import re
import sys
import traceback

import pytest

from loguru import logger
from loguru._better_exceptions import ExceptionFormatter


@pytest.fixture(autouse=True)
def _without_traceback_limit(monkeypatch):
    """Make the expected number of frames independent of the test environment."""
    monkeypatch.delattr(sys, "tracebacklimit", raising=False)


def _render_exception(error, *, diagnose=False):
    formatter = ExceptionFormatter(
        colorize=False,
        backtrace=False,
        diagnose=diagnose,
    )
    return "".join(
        formatter.format_exception(type(error), error, error.__traceback__)
    )


def _recursive_failure(depth):
    if depth == 0:
        raise ValueError("boom")
    _recursive_failure(depth - 1)


def _alternate_a(depth):
    if depth == 0:
        raise ValueError("boom")
    _alternate_b(depth - 1)


def _alternate_b(depth):
    _alternate_a(depth - 1)


def test_logger_exception_compacts_recursion_error_frames():
    messages = []
    sink_id = logger.add(
        messages.append,
        format="{message}",
        colorize=False,
        backtrace=False,
        diagnose=True,
        catch=False,
    )

    try:
        def rec():
            rec()

        try:
            rec()
        except RecursionError as error:
            recursion_frame_count = sum(
                frame.name == "rec"
                for frame in traceback.extract_tb(error.__traceback__)
            )
            expected_hidden_count = recursion_frame_count - 3
            assert expected_hidden_count > 0

            logger.exception("Oups")
    finally:
        logger.remove(sink_id)

    assert len(messages) == 1
    output = messages[0]

    assert output.startswith("Oups\n")
    assert "Traceback (most recent call last):" in output

    # Only the first three frames of the recursive run should be rendered.
    recursive_locations = re.findall(
        r'^  File ".*", line \d+, in rec$', output, flags=re.MULTILINE
    )
    assert len(recursive_locations) == 3

    summary = (
        f"  [Previous line repeated {expected_hidden_count} more times]\n"
    )
    assert summary in output
    assert output.count("[Previous line repeated") == 1

    # The summary belongs after the displayed frames and before the exception.
    assert output.index(summary) > output.rindex("    rec()")
    assert output.index(summary) < output.index("RecursionError:")
    assert re.search(r"^RecursionError:", output, flags=re.MULTILINE)


@pytest.mark.parametrize(
    ("depth", "visible_recursive_calls", "hidden_count"),
    [
        (1, 1, None),
        (2, 2, None),
        (3, 3, None),  # Three repetitions are still displayed in full.
        (4, 3, 1),     # Compaction starts with the fourth repetition.
        (8, 3, 5),
    ],
)
def test_repeated_frame_compaction_threshold_and_count(
    depth, visible_recursive_calls, hidden_count
):
    try:
        _recursive_failure(depth)
    except ValueError as error:
        output = _render_exception(error)
    else:
        pytest.fail("_recursive_failure() did not raise")

    assert output.count(
        "    _recursive_failure(depth - 1)\n"
    ) == visible_recursive_calls

    if hidden_count is None:
        assert "[Previous line repeated" not in output
    else:
        assert (
            f"  [Previous line repeated {hidden_count} more times]\n" in output
        )
        assert output.count("[Previous line repeated") == 1

    # Frames surrounding the repeated run and the final exception are retained.
    assert "    raise ValueError(\"boom\")\n" in output
    assert output.endswith("ValueError: boom\n")


def test_non_consecutive_duplicate_frames_are_not_compacted():
    try:
        _alternate_a(8)
    except ValueError as error:
        output = _render_exception(error)
    else:
        pytest.fail("_alternate_a() did not raise")

    # Each source location occurs four times, but occurrences alternate rather
    # than forming a consecutive recursive run.
    assert output.count("    _alternate_b(depth - 1)\n") == 4
    assert output.count("    _alternate_a(depth - 1)\n") == 4
    assert "[Previous line repeated" not in output
    assert output.endswith("ValueError: boom\n")

"""Regression tests for suppressing C++-only diagnostics in C files."""

import pytest

import cpplint


_CXX_ONLY_CATEGORIES = {"readability/casting", "runtime/int"}

# This line normally produces both C++-only diagnostics.  Its trailing spaces
# also produce a language-independent diagnostic, allowing us to verify that C
# files are still linted rather than silently ignored.
_TRIGGER_LINES = [
    "// Copyright 2024 Example.",
    "long value = (int64_t) 65;  ",
    "",
]


class _ErrorCollector:
    """Collect errors using the same suppression logic as cpplint's tests."""

    def __init__(self):
        self.errors = []

    def __call__(self, filename, linenum, category, confidence, message):
        if cpplint._ShouldPrintError(category, confidence, filename, linenum):
            self.errors.append((category, message))

    @property
    def categories(self):
        return {category for category, _ in self.errors}


@pytest.fixture(autouse=True)
def _reset_global_suppressions():
    cpplint.ResetNolintSuppressions()
    yield
    cpplint.ResetNolintSuppressions()


def _lint(filename, lines):
    extension = filename.rsplit(".", 1)[1]
    collector = _ErrorCollector()
    cpplint.ProcessFileData(filename, extension, list(lines), collector)
    return collector


@pytest.mark.parametrize("extension", ["c", "C", "h", "H"])
def test_c_file_extensions_suppress_cpp_only_warnings(extension):
    collector = _lint(f"foo.{extension}", _TRIGGER_LINES)

    assert _CXX_ONLY_CATEGORIES.isdisjoint(collector.categories), collector.errors
    # Suppressing C++-only checks must not suppress ordinary C lint checks.
    assert "whitespace/end_of_line" in collector.categories


@pytest.mark.parametrize(
    "extension",
    ["cc", "cpp", "cxx", "c++", "cu", "hh", "hpp", "hxx", "h++", "cuh"],
)
def test_cpp_file_extensions_keep_cpp_only_warnings(extension):
    collector = _lint(f"foo.{extension}", _TRIGGER_LINES)

    assert _CXX_ONLY_CATEGORIES <= collector.categories, collector.errors


def test_c_suppressions_do_not_leak_into_the_next_cpp_file():
    c_collector = _lint("foo.c", _TRIGGER_LINES)
    assert _CXX_ONLY_CATEGORIES.isdisjoint(c_collector.categories)

    cpp_collector = _lint("foo.cc", _TRIGGER_LINES)
    assert _CXX_ONLY_CATEGORIES <= cpp_collector.categories, cpp_collector.errors


def test_explicit_c_file_marker_suppresses_all_cpp_only_warnings():
    # Use a C++ extension so this exercises the existing explicit C-file
    # mechanism independently of extension-based detection.
    lines = _TRIGGER_LINES[:-1] + ["//  LINT_C_FILE", ""]
    collector = _lint("foo.cc", lines)

    assert _CXX_ONLY_CATEGORIES.isdisjoint(collector.categories), collector.errors


def test_uppercase_c_extensions_are_enabled_by_default():
    assert {"c", "C", "h", "H"} <= cpplint.GetAllExtensions()
    assert {"h", "H"} <= cpplint.GetHeaderExtensions()

import io
import re
import sys
import traceback

import pytest

from loguru import logger


_SUMMARY_PATTERN = re.compile(r"  \[Previous line repeated ([0-9]+) more times?\]")


def _recurse_without_arguments():
    _recurse_without_arguments()


def _recurse_with_argument(value):
    _recurse_with_argument(value + 1)


def _repeat_then_raise(depth):
    if depth > 0:
        _repeat_then_raise(depth - 1)
    else:
        raise RuntimeError("repetition boundary")


def _outer_repeat(depth):
    if depth > 0:
        _outer_repeat(depth - 1)
    else:
        _inner_repeat(5)


def _inner_repeat(depth):
    if depth > 0:
        _inner_repeat(depth - 1)
    else:
        raise RuntimeError("separate repetitions")


def _alternate_a(depth):
    if depth == 0:
        raise RuntimeError("alternating frames")
    _alternate_b(depth - 1)


def _alternate_b(depth):
    if depth == 0:
        raise RuntimeError("alternating frames")
    _alternate_a(depth - 1)


def _make_recursion_error(function, *args):
    previous_limit = sys.getrecursionlimit()
    caught = None

    try:
        sys.setrecursionlimit(100)
        try:
            function(*args)
        except RecursionError as error:
            caught = error
    finally:
        sys.setrecursionlimit(previous_limit)

    if caught is None:
        pytest.fail("The recursive function did not raise RecursionError")

    return caught


def _catch_runtime_error(function, *args):
    try:
        function(*args)
    except RuntimeError as error:
        return error
    pytest.fail("The test function did not raise RuntimeError")


def _capture_exception_log(error, *, backtrace=False, diagnose=False):
    sink = io.StringIO()
    handler_id = logger.add(
        sink,
        format="{message}",
        colorize=False,
        backtrace=backtrace,
        diagnose=diagnose,
        catch=False,
    )

    try:
        logger.opt(
            exception=(type(error), error, error.__traceback__)
        ).error("Oups")
    finally:
        logger.remove(handler_id)

    return sink.getvalue()


def _named_frames(error, function_name):
    return [
        frame
        for frame in traceback.extract_tb(error.__traceback__)
        if frame.name == function_name
    ]


def _summary_counts(output):
    counts = []
    for line in output.splitlines():
        if "[Previous line repeated" not in line:
            continue
        match = _SUMMARY_PATTERN.fullmatch(line)
        assert match is not None, "Malformed repetition summary: {!r}".format(line)
        counts.append(int(match.group(1)))
    return counts


def _logged_linenos(output, function_name):
    pattern = re.compile(
        r'  File ".*", line ([0-9]+), in ' + re.escape(function_name)
    )
    linenos = []
    for line in output.splitlines():
        match = pattern.fullmatch(line)
        if match is not None:
            linenos.append(int(match.group(1)))
    return linenos


@pytest.mark.parametrize("backtrace", [False, True])
def test_recursion_error_compacts_consecutive_repeated_frames(backtrace):
    error = _make_recursion_error(_recurse_without_arguments)
    recursive_frames = _named_frames(error, "_recurse_without_arguments")

    assert len(recursive_frames) > 4
    assert len(
        {
            (frame.filename, frame.lineno, frame.name)
            for frame in recursive_frames
        }
    ) == 1

    output = _capture_exception_log(error, backtrace=backtrace)

    assert output.startswith("Oups\n")
    assert "Traceback (most recent call last):" in output
    assert "RecursionError: maximum recursion depth exceeded" in output
    assert len(_logged_linenos(output, "_recurse_without_arguments")) == 3
    assert _summary_counts(output) == [len(recursive_frames) - 3]

    # Loguru's repetition accounting should agree with the standard traceback
    # formatter for the same exception and traceback.
    standard_output = "".join(
        traceback.format_exception(type(error), error, error.__traceback__)
    )
    assert _summary_counts(standard_output) == [len(recursive_frames) - 3]


def test_recursion_compaction_does_not_depend_on_diagnostic_values():
    # Although every frame has the same location, diagnose=True renders a
    # different local value in each one. Frame repetition is determined by the
    # code location, not by those rendered values.
    error = _make_recursion_error(_recurse_with_argument, 0)
    recursive_frames = _named_frames(error, "_recurse_with_argument")

    assert len(recursive_frames) > 4
    assert len({frame.lineno for frame in recursive_frames}) == 1

    standard_output = "".join(
        traceback.format_exception(type(error), error, error.__traceback__)
    )
    assert _summary_counts(standard_output) == [len(recursive_frames) - 3]

    output = _capture_exception_log(error, diagnose=True)

    assert len(_logged_linenos(output, "_recurse_with_argument")) == 3
    assert output.count("_recurse_with_argument(value + 1)") == 3
    assert _summary_counts(output) == [len(recursive_frames) - 3]


@pytest.mark.parametrize("depth", [1, 2, 3, 4, 5, 8])
def test_only_frames_beyond_the_first_three_are_summarized(depth):
    error = _catch_runtime_error(_repeat_then_raise, depth)
    frames = _named_frames(error, "_repeat_then_raise")

    call_lineno = frames[0].lineno
    raising_lineno = frames[-1].lineno
    assert call_lineno != raising_lineno
    assert sum(frame.lineno == call_lineno for frame in frames) == depth

    output = _capture_exception_log(error)
    linenos = _logged_linenos(output, "_repeat_then_raise")

    visible_repetitions = min(depth, 3)
    assert linenos.count(call_lineno) == visible_repetitions
    assert linenos.count(raising_lineno) == 1
    assert len(linenos) == visible_repetitions + 1

    expected_summaries = [] if depth <= 3 else [depth - 3]
    assert _summary_counts(output) == expected_summaries
    assert "RuntimeError: repetition boundary" in output


def test_separate_runs_of_repeated_frames_are_compacted_independently():
    error = _catch_runtime_error(_outer_repeat, 5)
    output = _capture_exception_log(error)

    assert _summary_counts(output) == [2, 2]

    for function_name in ("_outer_repeat", "_inner_repeat"):
        frames = _named_frames(error, function_name)
        call_lineno = frames[0].lineno
        final_lineno = frames[-1].lineno
        linenos = _logged_linenos(output, function_name)

        assert sum(frame.lineno == call_lineno for frame in frames) == 5
        assert linenos.count(call_lineno) == 3
        assert linenos.count(final_lineno) == 1
        assert len(linenos) == 4


def test_non_consecutive_frames_are_not_compacted():
    error = _catch_runtime_error(_alternate_a, 6)
    output = _capture_exception_log(error)

    assert _summary_counts(output) == []

    expected_linenos = [
        (frame.name, frame.lineno)
        for frame in traceback.extract_tb(error.__traceback__)
        if frame.name in {"_alternate_a", "_alternate_b"}
    ]
    actual_linenos = [
        ("_alternate_a", lineno)
        for lineno in _logged_linenos(output, "_alternate_a")
    ] + [
        ("_alternate_b", lineno)
        for lineno in _logged_linenos(output, "_alternate_b")
    ]

    assert len(actual_linenos) == len(expected_linenos)
    assert "RuntimeError: alternating frames" in output

"""Regression tests for skipping C++-only diagnostics in C source files."""

from __future__ import annotations

import re
import subprocess
import sys
from pathlib import Path

import pytest


CPPLINT = Path(__file__).resolve().parent / "cpplint.py"
CPLUSPLUS_ONLY_CATEGORIES = {"readability/casting", "runtime/int"}
CATEGORY_RE = re.compile(r"\[([a-z]+/[^\]]+)\]\s+\[\d+\]")

# The long comment proves that cpplint actually processed the file even when
# both C++-only diagnostics are suppressed. It contains repeated words rather
# than one uninterrupted token, which cpplint may exempt from its line-length
# check. The cast and "long" declaration produce the two C++-only diagnostics.
SAMPLE_SOURCE = "\n".join(
    [
        "// Copyright 2024 Example.",
        "#pragma once",
        "long value = (int64_t) 65;",
        "// x" + (" x" * 100),
        "",
    ]
)


def write_sample(directory: Path, extension: str, stem: str = "sample") -> Path:
    path = directory / f"{stem}.{extension}"
    path.write_text(SAMPLE_SOURCE, encoding="utf-8")
    return path


def run_cpplint(*files: Path) -> str:
    completed = subprocess.run(
        [sys.executable, str(CPPLINT), *(str(path) for path in files)],
        cwd=files[0].parent,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True,
        check=False,
        timeout=30,
    )
    return completed.stdout + completed.stderr


def categories_in(output: str) -> set[str]:
    return {
        category
        for line in output.splitlines()
        for category in CATEGORY_RE.findall(line)
    }


def categories_for_file(output: str, path: Path) -> set[str]:
    """Extract diagnostics belonging to one file in a multi-file run."""
    prefix = f"{path}:"
    return {
        category
        for line in output.splitlines()
        if line.startswith(prefix)
        for category in CATEGORY_RE.findall(line)
    }


@pytest.mark.parametrize("extension", ["c", "C", "h", "H"])
def test_c_extensions_skip_cplusplus_only_warnings(tmp_path, extension):
    """Every extension in .[cChH] is linted as C, including uppercase forms."""
    source = write_sample(tmp_path, extension)

    output = run_cpplint(source)
    categories = categories_in(output)

    # This also prevents a false pass if an uppercase extension is merely
    # ignored instead of being linted.
    assert "whitespace/line_length" in categories, output
    assert CPLUSPLUS_ONLY_CATEGORIES.isdisjoint(categories), output


@pytest.mark.parametrize(
    "extension",
    ["cc", "cpp", "cxx", "c++", "hh", "hpp", "hxx", "h++", "cu", "cuh"],
)
def test_cplusplus_extensions_keep_cplusplus_warnings(tmp_path, extension):
    """The C exceptions must not disable these checks for C++ files."""
    source = write_sample(tmp_path, extension)

    output = run_cpplint(source)
    categories = categories_in(output)

    assert "whitespace/line_length" in categories, output
    assert CPLUSPLUS_ONLY_CATEGORIES <= categories, output


@pytest.mark.parametrize("extensions", [("c", "cc"), ("cc", "c")])
def test_c_suppressions_are_scoped_to_each_file(tmp_path, extensions):
    """Linting a C file must not suppress warnings in a later C++ file."""
    sources = [
        write_sample(tmp_path, extension, stem=f"file{index}")
        for index, extension in enumerate(extensions)
    ]

    output = run_cpplint(*sources)

    for source, extension in zip(sources, extensions):
        categories = categories_for_file(output, source)
        assert "whitespace/line_length" in categories, output
        if extension == "c":
            assert CPLUSPLUS_ONLY_CATEGORIES.isdisjoint(categories), output
        else:
            assert CPLUSPLUS_ONLY_CATEGORIES <= categories, output

import io
import re
import sys
from contextlib import contextmanager

import pytest

from loguru import logger


def _recurse_forever():
    _recurse_forever()


def _recurse_with_changing_value(remaining):
    _recurse_with_changing_value(remaining - 1)


def _repeat_then_raise(remaining):
    if remaining == 0:
        raise RuntimeError("limited recursion")
    _repeat_then_raise(remaining - 1)


def _alternate_a(remaining):
    if remaining == 0:
        raise RuntimeError("alternating recursion")
    _alternate_b(remaining - 1)


def _alternate_b(remaining):
    _alternate_a(remaining - 1)


@contextmanager
def _captured_logs(*, diagnose):
    stream = io.StringIO()
    sink_id = logger.add(
        stream,
        format="{message}",
        colorize=False,
        backtrace=False,
        diagnose=diagnose,
    )
    try:
        yield stream
    finally:
        logger.remove(sink_id)


@contextmanager
def _recursion_limit(limit):
    previous_limit = sys.getrecursionlimit()
    sys.setrecursionlimit(limit)
    try:
        yield
    finally:
        sys.setrecursionlimit(previous_limit)


def _frame_locations(output, function_name, lineno=None):
    line_pattern = r"\d+" if lineno is None else str(lineno)
    pattern = r'^  File "[^"]+", line {}, in {}$'.format(
        line_pattern, re.escape(function_name)
    )
    return re.findall(pattern, output, flags=re.MULTILINE)


def _repetition_summaries(output):
    return re.findall(
        r"^  \[Previous line repeated (\d+) more times?\]$",
        output,
        flags=re.MULTILINE,
    )


def _count_traceback_frames(tb, code):
    count = 0
    while tb is not None:
        if tb.tb_frame.f_code is code:
            count += 1
        tb = tb.tb_next
    return count


@pytest.mark.parametrize("diagnose", [False, True])
def test_recursion_error_compacts_repeated_frames(diagnose):
    """The issue's RecursionError example should not print every recursive call."""
    with _recursion_limit(120), _captured_logs(diagnose=diagnose) as stream:
        try:
            _recurse_forever()
        except RecursionError as error:
            repeated_frames = _count_traceback_frames(
                error.__traceback__, _recurse_forever.__code__
            )
            logger.exception("Oups")

    output = stream.getvalue()
    assert repeated_frames > 3
    assert output.startswith("Oups\n")
    assert "Traceback (most recent call last):" in output
    assert len(_frame_locations(output, "_recurse_forever")) == 3
    assert _repetition_summaries(output) == [str(repeated_frames - 3)]
    assert re.search(r"^RecursionError:", output, flags=re.MULTILINE)


@pytest.mark.parametrize("repeats", [1, 2, 3, 4, 9])
def test_repeated_frame_cutoff_and_count(repeats):
    """Up to three frames are shown; only additional repetitions are summarized."""
    with _captured_logs(diagnose=False) as stream:
        try:
            _repeat_then_raise(repeats)
        except RuntimeError as error:
            # The first traceback entry is this test function. The next one is
            # the recursive call site, excluding the distinct terminal raise.
            recursive_lineno = error.__traceback__.tb_next.tb_lineno
            logger.exception("Limited recursion")

    output = stream.getvalue()
    recursive_frames = _frame_locations(
        output, "_repeat_then_raise", recursive_lineno
    )
    assert len(recursive_frames) == min(repeats, 3)

    expected_summaries = [] if repeats <= 3 else [str(repeats - 3)]
    assert _repetition_summaries(output) == expected_summaries
    assert "RuntimeError: limited recursion" in output


def test_recursion_compacts_despite_different_diagnosed_values():
    """Frame identity depends on the call site, not on rendered local values."""
    with _recursion_limit(120), _captured_logs(diagnose=True) as stream:
        try:
            _recurse_with_changing_value(7)
        except RecursionError as error:
            repeated_frames = _count_traceback_frames(
                error.__traceback__, _recurse_with_changing_value.__code__
            )
            recursive_lineno = error.__traceback__.tb_next.tb_lineno
            logger.exception("Changing values")

    output = stream.getvalue()

    # Every recursive frame displays a different value of "remaining". They
    # are nevertheless repetitions of the same file, line and function, just
    # as they are for Python's standard traceback formatter.
    recursive_frames = _frame_locations(
        output, "_recurse_with_changing_value", recursive_lineno
    )
    assert repeated_frames > 3
    assert len(recursive_frames) == 3
    assert _repetition_summaries(output) == [str(repeated_frames - 3)]
    assert re.search(r"^RecursionError:", output, flags=re.MULTILINE)


def test_non_consecutive_repetitions_are_not_compacted():
    """Equal frames separated by another call must remain fully visible."""
    with _captured_logs(diagnose=False) as stream:
        try:
            _alternate_a(8)
        except RuntimeError as error:
            tb = error.__traceback__
            a_call_lineno = tb.tb_next.tb_lineno
            b_call_lineno = tb.tb_next.tb_next.tb_lineno
            logger.exception("Alternating recursion")

    output = stream.getvalue()
    assert _repetition_summaries(output) == []
    assert len(_frame_locations(output, "_alternate_a", a_call_lineno)) == 4
    assert len(_frame_locations(output, "_alternate_b", b_call_lineno)) == 4
    assert "RuntimeError: alternating recursion" in output

import io

import pytest

from loguru import logger


class TtyStream(io.StringIO):
    def isatty(self):
        return True


def emit_message(colorize):
    stream = TtyStream()
    handler_id = logger.add(
        stream,
        format="<green>{message}</green>",
        colorize=colorize,
    )
    try:
        logger.info("message")
    finally:
        logger.remove(handler_id)
    return stream.getvalue()


@pytest.mark.parametrize("value", ["1", "0", "false", "no", "off", " "])
def test_no_color_disables_automatic_colorization(monkeypatch, value):
    # Every non-empty value disables color, including values resembling false.
    monkeypatch.setenv("NO_COLOR", value)

    assert emit_message(colorize=None) == "message\n"


@pytest.mark.parametrize("value", [None, ""])
def test_no_color_unset_or_empty_preserves_automatic_colorization(monkeypatch, value):
    # The specification only applies when NO_COLOR is present and non-empty.
    if value is None:
        monkeypatch.delenv("NO_COLOR", raising=False)
    else:
        monkeypatch.setenv("NO_COLOR", value)

    assert emit_message(colorize=None) == "\x1b[32mmessage\x1b[0m\n"


