"""Regression tests for method lookup on dictionary expressions."""

import ast
from typing import Any, Iterable

import pytest

from func_adl import ObjectStream
from func_adl.type_based_replacement import remap_by_types


class Jet:
    def pt(self) -> float:
        ...

    def eta(self) -> float:
        ...


class Event:
    def Jets(self) -> Iterable[Jet]:
        ...


def _expression(expr: str) -> ast.AST:
    return ast.parse(expr).body[0].value


def _remap_event_expression(expr: str):
    objs = ObjectStream[Event](ast.Name(id="e", ctx=ast.Load()))
    return remap_by_types(objs, "e", Event, _expression(expr))


def test_zip_method_lookup_on_dictionary_returns_any():
    """Looking up Zip as a method must not be treated as a dict key lookup failure."""
    _, _, expr_type = _remap_event_expression("{'jets': e.Jets()}.Zip()")

    assert expr_type is Any


def test_zip_in_nested_query_does_not_abort_type_tracing():
    """Exercise the AGC pattern: Zip followed by Where and Count inside a lambda."""
    expr = (
        "ds.Where(lambda e: "
        "{'pt': e.Jets(), 'eta': e.Jets()}.Zip()"
        ".Where(lambda electron: electron.pt > 30).Count() == 1)"
    )
    objs = ObjectStream[Iterable[Event]](ast.Name(id="ds", ctx=ast.Load()))

    _, _, expr_type = remap_by_types(objs, "ds", Iterable[Event], _expression(expr))

    # Zip itself is unknown, but that must not destroy typing of the outer query.
    assert expr_type == Iterable[Event]


def test_valid_dictionary_key_still_preserves_type_information():
    """The Zip workaround must not weaken lookup of keys that actually exist."""
    _, _, expr_type = _remap_event_expression(
        "{'jets': e.Jets()}.jets.Select(lambda j: j.pt())"
    )

    assert expr_type == Iterable[float]


def test_misspelled_dictionary_key_still_raises():
    """Returning Any for an unknown method lookup must not hide key misspellings."""
    with pytest.raises(ValueError, match="jetsss"):
        _remap_event_expression("{'jets': e.Jets()}.jetsss")


def test_misspelled_generated_dataclass_attribute_still_raises():
    """Dictionaries carried through Select retain enough information to catch typos."""
    expr = (
        "e.Jets().Select(lambda j: {'pt': j.pt(), 'eta': j.eta()})"
        ".Select(lambda info: info.ptt)"
    )

    with pytest.raises(ValueError, match="ptt"):
        _remap_event_expression(expr)

