import re
import sys
from contextlib import contextmanager

import pytest

from loguru import logger


def _recurse_forever():
    _recurse_forever()


def _finite_recursion(depth):
    if depth == 0:
        raise ValueError("bottom")
    _finite_recursion(depth - 1)


def _outer_recursion(depth):
    if depth == 0:
        _inner_recursion(4)
    else:
        _outer_recursion(depth - 1)


def _inner_recursion(depth):
    if depth == 0:
        raise ValueError("bottom")
    _inner_recursion(depth - 1)


def _ping(depth):
    if depth == 0:
        raise ValueError("bottom")
    _pong(depth - 1)


def _pong(depth):
    _ping(depth - 1)


def _catch_exception(function, *args):
    try:
        function(*args)
    except Exception as error:
        return error
    raise AssertionError("The function did not raise an exception")


def _render_exception(error, *, backtrace=False, diagnose=False):
    """Render an exception through Loguru's public logging API."""
    messages = []
    handler_id = logger.add(
        messages.append,
        format="{message}",
        colorize=False,
        backtrace=backtrace,
        diagnose=diagnose,
    )
    try:
        exception = (type(error), error, error.__traceback__)
        logger.opt(exception=exception).error("Oups")
    finally:
        logger.remove(handler_id)
    return "".join(messages)


def _frame_headers(output, function_name):
    pattern = r'^  File ".*", line \d+, in {}$'.format(re.escape(function_name))
    return list(re.finditer(pattern, output, flags=re.MULTILINE))


def _repetition_lines(output):
    return [
        line
        for line in output.splitlines()
        if line.startswith("  [Previous line repeated ")
    ]


@contextmanager
def _limited_recursion():
    old_limit = sys.getrecursionlimit()
    sys.setrecursionlimit(200)
    try:
        yield
    finally:
        sys.setrecursionlimit(old_limit)


def test_recursion_error_compacts_repeated_frames_with_backtrace_and_diagnose():
    with _limited_recursion():
        error = _catch_exception(_recurse_forever)

    recursive_line_numbers = []
    traceback = error.__traceback__
    while traceback is not None:
        if traceback.tb_frame.f_code is _recurse_forever.__code__:
            recursive_line_numbers.append(traceback.tb_lineno)
        traceback = traceback.tb_next

    # The test must exercise a run longer than the standard three-frame cutoff.
    assert len(recursive_line_numbers) > 4
    assert len(set(recursive_line_numbers)) == 1

    output = _render_exception(error, backtrace=True, diagnose=True)
    repeated_count = len(recursive_line_numbers) - 3
    expected_summary = (
        "  [Previous line repeated {} more times]".format(repeated_count)
    )

    assert output.startswith("Oups\n")
    assert "Traceback (most recent call last):" in output
    assert expected_summary in output.splitlines()
    assert _repetition_lines(output) == [expected_summary]

    # Only the first three identical recursive frames should be displayed.
    headers = _frame_headers(output, "_recurse_forever")
    assert len(headers) == 3
    assert headers[-1].end() < output.index(expected_summary)
    assert output.index(expected_summary) < output.index("RecursionError:")
    assert "RecursionError: maximum recursion depth exceeded" in output


@pytest.mark.parametrize(
    ("depth", "expected_repetitions", "expected_visible_headers"),
    [
        (2, None, 3),  # Below the cutoff.
        (3, None, 4),  # Exactly three identical call frames, plus the raising frame.
        (4, 1, 4),     # Singular: "1 more time".
        (6, 3, 4),     # Plural: "3 more times".
    ],
)
def test_repeated_frame_cutoff_and_grammar(
    depth, expected_repetitions, expected_visible_headers
):
    error = _catch_exception(_finite_recursion, depth)
    output = _render_exception(error)
    summaries = _repetition_lines(output)

    if expected_repetitions is None:
        assert summaries == []
    else:
        suffix = "s" if expected_repetitions > 1 else ""
        assert summaries == [
            "  [Previous line repeated {} more time{}]".format(
                expected_repetitions, suffix
            )
        ]

    assert len(_frame_headers(output, "_finite_recursion")) == expected_visible_headers
    assert "ValueError: bottom" in output


def test_separate_runs_of_repeated_frames_each_get_a_summary():
    # Four identical outer frames are followed by a different outer frame, then
    # four identical inner frames. The first summary must be flushed before the
    # second run rather than only being handled at the end of the traceback.
    error = _catch_exception(_outer_recursion, 4)
    output = _render_exception(error)

    singular_summary = "  [Previous line repeated 1 more time]"
    assert _repetition_lines(output) == [singular_summary, singular_summary]
    assert len(_frame_headers(output, "_outer_recursion")) == 4
    assert len(_frame_headers(output, "_inner_recursion")) == 4


def test_non_consecutive_frames_are_not_treated_as_repetitions():
    error = _catch_exception(_ping, 6)
    output = _render_exception(error)

    assert _repetition_lines(output) == []
    assert len(_frame_headers(output, "_ping")) == 4
    assert len(_frame_headers(output, "_pong")) == 3
    assert "ValueError: bottom" in output

