@pytest.fixture(autouse=True)
def clear_no_color(monkeypatch):
    """Keep the host environment from changing the control cases."""
    monkeypatch.delenv("NO_COLOR", raising=False)


def render_message(colorize):
    stream = TTYStream()
    handler_id = logger.add(
        stream,
        format="<green>{message}</green>",
        colorize=colorize,
    )
    try:
        logger.info("message")
    finally:
        logger.remove(handler_id)
    return stream.getvalue()


def run_fresh_logger(extra_env):
    """Run logger.add() with defaults bound in a fresh interpreter."""
    code = """
        import io
        import sys
        from loguru import logger

        class TTYStream(io.StringIO):
            def isatty(self):
                return True

        stream = TTYStream()
        logger.add(stream, format="<green>{message}</green>", level="DEBUG")
        logger.info("message")
        sys.stdout.write(stream.getvalue())
    """
    env = os.environ.copy()
    env.pop("NO_COLOR", None)
    env.pop("LOGURU_COLORIZE", None)
    env.update(
        {
            "LOGURU_AUTOINIT": "false",
            "LOGURU_SERIALIZE": "false",
            "LOGURU_ENQUEUE": "false",
        }
    )
    env.update(extra_env)

    return subprocess.run(
        [sys.executable, "-c", textwrap.dedent(code)],
        env=env,
        capture_output=True,
        text=True,
        check=True,
    )


def test_tty_auto_detection_still_works_without_no_color():
    assert should_colorize(TTYStream()) is True
    assert render_message(colorize=None) == COLORED_MESSAGE


@pytest.mark.parametrize("value", ["", "0", "1", "false", "no", "arbitrary"])
