import ast
from dataclasses import dataclass
from typing import Any, Iterable

import pytest

from func_adl import ObjectStream
from func_adl.type_based_replacement import remap_by_types


class Jet:
    def pt(self) -> float:
        ...

    def eta(self) -> float:
        ...


class Event:
    def Jets(self) -> Iterable[Jet]:
        ...

    def Jet_pt(self) -> Iterable[float]:
        ...

    def Jet_eta(self) -> Iterable[float]:
        ...

    def Jet_jetId(self) -> Iterable[int]:
        ...


@dataclass
class TypedRecord:
    pt: float
    eta: float


def parse_expression(expression: str) -> ast.AST:
    return ast.parse(expression).body[0].value  # type: ignore


def remap_expression(expression: str, var_type: type = Event, var_name: str = "e"):
    stream = ObjectStream(ast.Name(id=var_name, ctx=ast.Load()), var_type)
    return remap_by_types(stream, var_name, var_type, parse_expression(expression))


def test_zip_on_dictionary_literal_returns_any():
    """An unknown method lookup must not be treated as a missing data key."""
    expression = "{'pt': e.Jet_pt(), 'eta': e.Jet_eta()}.Zip()"

    _, new_ast, expression_type = remap_expression(expression)

    assert expression_type == Any
    assert ast.dump(new_ast) == ast.dump(parse_expression(expression))


def test_zip_where_count_chain_from_issue_is_supported():
    """The AGC-style chain should trace through the surrounding expression."""
    expression = (
        "{'pt': e.Jet_pt(), 'eta': e.Jet_eta(), 'jetId': e.Jet_jetId()}"
        ".Zip()"
        ".Where(lambda jet: jet.pt > 25 and abs(jet.eta) < 2.4 "
        "and jet.jetId == 6)"
        ".Count() >= 4"
    )

    _, new_ast, expression_type = remap_expression(expression)

    assert expression_type == bool
    assert ast.dump(new_ast) == ast.dump(parse_expression(expression))


def test_zip_on_typed_dataclass_returns_any():
    """The dataclass form of a dictionary needs the same method fallback."""
    _, _, expression_type = remap_expression("r.Zip()", TypedRecord, "r")

    assert expression_type == Any


def test_valid_dictionary_key_still_uses_available_type_information():
    _, _, expression_type = remap_expression(
        "{'jets': e.Jets()}.jets.Select(lambda j: j.pt())"
    )

    assert expression_type == Iterable[float]


def test_misspelled_dictionary_key_still_raises():
    """The method fallback must not hide misspelled dictionary keys."""
    with pytest.raises(ValueError) as error:
        remap_expression("{'jets': e.Jets()}.jetsss.Select(lambda j: j.pt())")

    assert "jetsss" in str(error.value)


def test_misspelled_dataclass_field_still_raises():
    """Known field types should still allow misspelled fields to be diagnosed."""
    with pytest.raises(ValueError) as error:
        remap_expression("r.ppt", TypedRecord, "r")

    assert "ppt" in str(error.value)


def test_misspelled_field_on_dictionary_generated_type_still_raises():
    """Type information must survive Select and still diagnose bad fields."""
    expression = (
        "e.Jets().Select(lambda j: {'pt': j.pt(), 'eta': j.eta()})"
        ".Select(lambda item: item.ppt)"
    )

    with pytest.raises(ValueError) as error:
        remap_expression(expression)

    assert "ppt" in str(error.value)


def test_valid_dataclass_field_still_uses_available_type_information():
    _, _, expression_type = remap_expression("r.pt", TypedRecord, "r")

    assert expression_type == float

