class FakeSftpFile:
    def __init__(self, client, name):
        self.client = client
        self.name = name

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        self.close()

    def set_pipelined(self, enabled):
        pass

    def write(self, value):
        self.client.files[self.name] = value

    def close(self):
        pass


class FakeSftpClient:
    """Small in-memory SFTP substitute; no network or paramiko is required."""

    def __init__(self, *, directories=(), files=None):
        self.directories = {"."} | set(directories)
        self.files = dict(files or {})
        self.mkdir_calls = []

    @staticmethod
    def _parent(name):
        return str(PurePosixPath(name).parent)

    def mkdir(self, name):
        name = str(PurePosixPath(name))
        self.mkdir_calls.append(name)
        if self._parent(name) not in self.directories:
            raise FileNotFoundError(errno.ENOENT, "No such file or directory", name)
        if name in self.directories or name in self.files:
            raise OSError(errno.EEXIST, "File exists", name)
        self.directories.add(name)

    def open(self, name, mode="r"):
        name = str(PurePosixPath(name))
        if mode != "w":
            raise NotImplementedError("the fake only needs write mode")
        if self._parent(name) not in self.directories:
            raise FileNotFoundError(errno.ENOENT, "No such file or directory", name)
        return FakeSftpFile(self, name)

    def posix_rename(self, source, destination):
        source = str(PurePosixPath(source))
        destination = str(PurePosixPath(destination))
        if source not in self.files:
            raise FileNotFoundError(errno.ENOENT, "No such file or directory", source)
        if self._parent(destination) not in self.directories:
            raise FileNotFoundError(errno.ENOENT, "No such file or directory", destination)
        self.files[destination] = self.files.pop(source)

    def unlink(self, name):
        name = str(PurePosixPath(name))
        try:
            del self.files[name]
        except KeyError:
            raise FileNotFoundError(errno.ENOENT, "No such file or directory", name) from None


def make_sftp_backend(*, precreate_dirs, directories=(), files=None):
    # Avoid Sftp.__init__ so the tests also run when paramiko is not installed.
    backend = Sftp.__new__(Sftp)
    backend.opened = True
    backend.precreate_dirs = precreate_dirs
    backend.client = FakeSftpClient(directories=directories, files=files)
    return backend


@pytest.mark.parametrize("precreate_dirs", [False, True])
def test_sftp_store_creates_missing_nested_directory(precreate_dirs):
    """SFTP must use the same write-then-mkdir-and-retry fallback as PosixFS."""
    backend = make_sftp_backend(
        precreate_dirs=precreate_dirs,
        directories=("a", "a/b") if precreate_dirs else (),
    )
    if precreate_dirs:
        # The directories were pre-created, but were subsequently lost.
        backend.client.directories = {"."}

    backend.store("a/b/object", b"value")

    assert backend.client.files["a/b/object"] == b"value"
    assert "a" in backend.client.directories
    assert "a/b" in backend.client.directories


@pytest.mark.parametrize("precreate_dirs", [False, True])
def test_sftp_store_does_not_mkdir_when_parent_exists(precreate_dirs):
    backend = make_sftp_backend(
        precreate_dirs=precreate_dirs,
        directories=("a", "a/b"),
    )

    backend.store("a/b/object", b"value")

    assert backend.client.files["a/b/object"] == b"value"
    assert backend.client.mkdir_calls == []


@pytest.mark.parametrize("precreate_dirs", [False, True])
def test_sftp_move_creates_missing_destination_directory(precreate_dirs):
    backend = make_sftp_backend(
        precreate_dirs=precreate_dirs,
        directories=("a", "a/b") if precreate_dirs else (),
        files={"source": b"value"},
    )
    if precreate_dirs:
        backend.client.directories = {"."}

    backend.move("source", "a/b/destination")

    assert "source" not in backend.client.files
    assert backend.client.files["a/b/destination"] == b"value"


@pytest.mark.parametrize("precreate_dirs", [False, True])
def test_sftp_move_missing_source_raises_object_not_found(precreate_dirs):
    backend = make_sftp_backend(precreate_dirs=precreate_dirs)

    with pytest.raises(ObjectNotFound):
        backend.move("missing-source", "a/b/destination")

    assert "a/b/destination" not in backend.client.files

import io
import re
import sys
import traceback
from contextlib import contextmanager

import pytest

from loguru import logger


def _recurse_forever():
    _recurse_forever()


def _recursive_zero_division(depth):
    # Keeping both the recursive call and the exception on this line gives us a
    # precise number of identical traceback frames.
    return _recursive_zero_division(depth - 1) if depth else 1 / 0


def _fail_leaf():
    raise RuntimeError("bottom")


def _repeat_then_fail(depth):
    return _repeat_then_fail(depth - 1) if depth else _fail_leaf()


def _ping(depth):
    if depth == 0:
        raise RuntimeError("bottom")
    _pong(depth - 1)


def _pong(depth):
    if depth == 0:
        raise RuntimeError("bottom")
    _ping(depth - 1)


@contextmanager
def _captured_logs(*, backtrace=False, diagnose=False):
    output = io.StringIO()
    sink_id = logger.add(
        output,
        format="{message}",
        colorize=False,
        backtrace=backtrace,
        diagnose=diagnose,
    )
    try:
        yield output
    finally:
        logger.remove(sink_id)


def _frame_matches(output, function):
    return list(
        re.finditer(
            r'^  File ".*", line \d+, in ' + re.escape(function) + r"$",
            output,
            re.MULTILINE,
        )
    )


def _repetition_summaries(output):
    return re.findall(
        r"^  \[Previous line repeated \d+ more times?\]$",
        output,
        re.MULTILINE,
    )


def test_recursion_error_is_condensed_like_standard_traceback():
    # Use a smaller limit to keep the test quick. The expected count is taken
    # from the stdlib rather than hard-coded because it also depends on the
    # depth of the pytest call stack.
    previous_limit = sys.getrecursionlimit()
    sys.setrecursionlimit(200)
    try:
        with _captured_logs(backtrace=True, diagnose=True) as output:
            try:
                _recurse_forever()
            except RecursionError as error:
                standard = "".join(
                    traceback.format_exception(
                        type(error), error, error.__traceback__
                    )
                )
                logger.exception("Oups")
            else:
                pytest.fail("The recursive function did not raise RecursionError")
    finally:
        sys.setrecursionlimit(previous_limit)

    logged = output.getvalue()
    standard_summaries = _repetition_summaries(standard)

    assert len(standard_summaries) == 1, standard
    expected_summary = standard_summaries[0]

    # Loguru must show the same number of omitted frames as Python, and must
    # not emit one enormous frame for every recursive call.
    assert _repetition_summaries(logged) == [expected_summary]
    assert len(_frame_matches(standard, "_recurse_forever")) == 3
    assert len(_frame_matches(logged, "_recurse_forever")) == 3

    assert "Oups\n" in logged
    assert "Traceback (most recent call last):" in logged
    assert "RecursionError: maximum recursion depth exceeded" in logged


@pytest.mark.parametrize(
    ("depth", "total_frames", "expected_summary"),
    [
        (2, 3, None),  # Exactly at the cutoff: nothing should be hidden.
        (3, 4, "  [Previous line repeated 1 more time]"),
        (5, 6, "  [Previous line repeated 3 more times]"),
    ],
)
def test_repetition_cutoff_and_singular_plural(
    depth, total_frames, expected_summary
):
    with _captured_logs() as output:
        try:
            _recursive_zero_division(depth)
        except ZeroDivisionError as error:
            standard = "".join(
                traceback.format_exception(type(error), error, error.__traceback__)
            )
            logger.exception("Finite recursion")
        else:
            pytest.fail("The recursive function did not raise")

    logged = output.getvalue()
    summaries = _repetition_summaries(logged)

    assert len(_frame_matches(logged, "_recursive_zero_division")) == min(
        total_frames, 3
    )

    if expected_summary is None:
        assert _repetition_summaries(standard) == []
        assert summaries == []
    else:
        # Confirm that the constructed traceback exercises the intended stdlib
        # boundary, then require Loguru to format it identically.
        assert _repetition_summaries(standard) == [expected_summary]
        assert summaries == [expected_summary]


def test_repetition_summary_is_emitted_before_following_different_frame():
    with _captured_logs() as output:
        try:
            _repeat_then_fail(5)
        except RuntimeError as error:
            standard = "".join(
                traceback.format_exception(type(error), error, error.__traceback__)
            )
            logger.exception("Repeated frames in the middle")
        else:
            pytest.fail("The recursive function did not raise")

    logged = output.getvalue()
    expected_summary = "  [Previous line repeated 3 more times]"

    assert _repetition_summaries(standard) == [expected_summary]
    assert _repetition_summaries(logged) == [expected_summary]

    repeated_frames = _frame_matches(logged, "_repeat_then_fail")
    leaf_frames = _frame_matches(logged, "_fail_leaf")
    assert len(repeated_frames) == 3
    assert len(leaf_frames) == 1

    summary_position = logged.index(expected_summary)
    assert repeated_frames[-1].start() < summary_position < leaf_frames[0].start()


def test_non_consecutive_recursive_frames_are_not_collapsed():
    with _captured_logs() as output:
        try:
            _ping(7)
        except RuntimeError as error:
            standard = "".join(
                traceback.format_exception(type(error), error, error.__traceback__)
            )
            logger.exception("Alternating recursion")
        else:
            pytest.fail("The recursive functions did not raise")

    logged = output.getvalue()

    # ping/pong repeat as a cycle, but no individual frame occurs three times
    # consecutively. A formatter must not globally deduplicate these frames.
    assert _repetition_summaries(standard) == []
    assert _repetition_summaries(logged) == []
    assert len(_frame_matches(logged, "_ping")) == 4
    assert len(_frame_matches(logged, "_pong")) == 4
    assert "RuntimeError: bottom" in logged

