import io
import sys

import pytest

from loguru import logger
from loguru._colorama import should_colorize


class TtyStream(io.StringIO):
    def isatty(self):
        return True


class NonTtyStream(io.StringIO):
    def isatty(self):
        return False


@pytest.fixture(autouse=True)
def isolate_color_environment(monkeypatch):
    """Prevent the host terminal/CI environment from affecting color detection."""
    for variable in (
        "NO_COLOR",
        "CI",
        "TRAVIS",
        "CIRCLECI",
        "APPVEYOR",
        "GITLAB_CI",
        "GITHUB_ACTIONS",
        "PYCHARM_HOSTED",
        "TERM",
    ):
        monkeypatch.delenv(variable, raising=False)


def log_to_stream(stream, **sink_options):
    sink_id = logger.add(stream, format="<red>{message}</red>", **sink_options)
    try:
        logger.info("colored-message")
    finally:
        logger.remove(sink_id)
    return stream.getvalue()


@pytest.mark.parametrize("value", ["1", "0", "false", "no", " ", "arbitrary"])
def test_any_nonempty_no_color_value_disables_automatic_color(monkeypatch, value):
    # The specification explicitly says that the value itself is irrelevant.
    monkeypatch.setenv("NO_COLOR", value)
    assert should_colorize(TtyStream()) is False


@pytest.mark.parametrize("value", [None, ""])
def test_absent_or_empty_no_color_preserves_normal_detection(monkeypatch, value):
    if value is None:
        monkeypatch.delenv("NO_COLOR", raising=False)
    else:
        monkeypatch.setenv("NO_COLOR", value)

    assert should_colorize(TtyStream()) is True
    assert should_colorize(NonTtyStream()) is False


@pytest.mark.parametrize("stream_attribute", ["__stdout__", "__stderr__"])
@pytest.mark.parametrize(
    "environment",
    [
        {"CI": "1", "GITHUB_ACTIONS": "1"},
        {"PYCHARM_HOSTED": "1"},
    ],
    ids=["ci", "pycharm"],
)
def test_no_color_takes_precedence_over_terminal_specific_detection(
    monkeypatch, stream_attribute, environment
):
    stream = NonTtyStream()
    monkeypatch.setattr(sys, stream_attribute, stream)
    for variable, value in environment.items():
        monkeypatch.setenv(variable, value)

    # These environments normally force color even for a non-TTY stream.
    assert should_colorize(stream) is True

    monkeypatch.setenv("NO_COLOR", "1")
    assert should_colorize(stream) is False


@pytest.mark.parametrize(
    ("value", "expect_color"),
    [
        (None, True),
        ("", True),
        ("1", False),
        ("0", False),
        ("false", False),
    ],
)
def test_logger_honors_no_color_when_colorize_is_automatic(
    monkeypatch, value, expect_color
):
    if value is None:
        monkeypatch.delenv("NO_COLOR", raising=False)
    else:
        monkeypatch.setenv("NO_COLOR", value)

    output = log_to_stream(TtyStream())

    assert "colored-message" in output
    assert ("\x1b[" in output) is expect_color
    if not expect_color:
        assert "\x1b" not in output


def test_explicit_colorize_true_overrides_no_color(monkeypatch):
    # NO_COLOR controls default behavior; an explicit per-sink request for color
    # remains authoritative, just like an explicit command-line color option.
    monkeypatch.setenv("NO_COLOR", "1")

    output = log_to_stream(NonTtyStream(), colorize=True)

    assert "colored-message" in output
    assert "\x1b[" in output

