import io
import re
import sys
import traceback
from contextlib import contextmanager

import pytest

from loguru import logger


def _recurse():
    _recurse()


def _diagnose_recursion():
    _diagnose_recursion()


def _finite_recursion(depth):
    if depth <= 0:
        raise ValueError("Reached bottom")
    _finite_recursion(depth - 1)


def _mutual_a():
    _mutual_b()


def _mutual_b():
    _mutual_a()


def _alternating_recursion(depth):
    # The function name and filename stay constant, but consecutive frames come
    # from different lines and therefore must not be treated as identical.
    if depth % 2:
        _alternating_recursion(depth - 1)
    else:
        _alternating_recursion(depth - 1)


def _catch_exception(function, *args, recursion_limit=None):
    old_limit = sys.getrecursionlimit()
    try:
        if recursion_limit is not None:
            sys.setrecursionlimit(recursion_limit)
        try:
            function(*args)
        except Exception:
            return sys.exc_info()
    finally:
        if recursion_limit is not None:
            sys.setrecursionlimit(old_limit)
    raise AssertionError("The function did not raise an exception")


@contextmanager
def _log_sink(*, backtrace=False, diagnose=False):
    stream = io.StringIO()
    sink_id = logger.add(
        stream,
        format="{message}",
        colorize=False,
        backtrace=backtrace,
        diagnose=diagnose,
    )
    try:
        yield stream
    finally:
        logger.remove(sink_id)


def _render_exception(exc_info, *, backtrace=False, diagnose=False):
    with _log_sink(backtrace=backtrace, diagnose=diagnose) as stream:
        logger.opt(exception=exc_info).error("Oups")
    return stream.getvalue()


def _traceback_structure(text):
    """Return frame headers and repetition summaries, ignoring source lines."""
    return [
        line
        for line in text.splitlines()
        if line.startswith('  File "') or line.startswith("  [Previous line repeated ")
    ]


def _repetition_lines(text):
    return [
        line for line in text.splitlines() if line.startswith("  [Previous line repeated ")
    ]


def _repetition_line(count):
    return "  [Previous line repeated {} more time{}]".format(
        count, "s" if count > 1 else ""
    )


def _count_traceback_frames(exc_info, code):
    count = 0
    tb = exc_info[2]
    while tb is not None:
        if tb.tb_frame.f_code is code:
            count += 1
        tb = tb.tb_next
    return count


def test_recursion_error_collapses_repeated_frames_like_stdlib():
    exc_info = _catch_exception(_recurse, recursion_limit=120)
    assert exc_info[0] is RecursionError

    output = _render_exception(exc_info)
    standard = "".join(traceback.format_exception(*exc_info))

    # The standard traceback is the oracle for both the retained frames and the
    # repetition count. Comparing headers avoids depending on Python-version-
    # specific source annotations such as caret markers.
    assert _traceback_structure(output) == _traceback_structure(standard)

    repeated_frames = _count_traceback_frames(exc_info, _recurse.__code__)
    assert repeated_frames > 4
    assert _repetition_lines(output) == [_repetition_line(repeated_frames - 3)]

    recursive_headers = [
        line for line in _traceback_structure(output) if line.endswith(", in _recurse")
    ]
    assert len(recursive_headers) == 3
    assert output.startswith("Oups\nTraceback (most recent call last):\n")
    assert output.rstrip().endswith("RecursionError: " + str(exc_info[1]))


@pytest.mark.parametrize("depth", range(6))
def test_repetition_cutoff_and_singular_plural(depth):
    exc_info = _catch_exception(_finite_recursion, depth)
    assert exc_info[0] is ValueError

    output = _render_exception(exc_info)
    standard = "".join(traceback.format_exception(*exc_info))

    assert _traceback_structure(output) == _traceback_structure(standard)

    # Three identical frames are always shown. Only subsequent frames are
    # summarized, including the singular "1 more time" case.
    repeated = max(0, depth - 3)
    expected = [] if repeated == 0 else [_repetition_line(repeated)]
    assert _repetition_lines(output) == expected


@pytest.mark.parametrize(
    ("function", "args"),
    [
        pytest.param(_mutual_a, (), id="mutual-recursion"),
        pytest.param(
            _alternating_recursion, (0,), id="same-function-at-different-lines"
        ),
    ],
)
def test_non_identical_consecutive_frames_are_not_collapsed(function, args):
    exc_info = _catch_exception(function, *args, recursion_limit=120)
    assert exc_info[0] is RecursionError

    output = _render_exception(exc_info)
    standard = "".join(traceback.format_exception(*exc_info))

    # Ensure this is a deep traceback, so an over-eager implementation would
    # have ample opportunity to collapse it incorrectly.
    assert len(_traceback_structure(output)) > 8
    assert _repetition_lines(output) == []
    assert _traceback_structure(output) == _traceback_structure(standard)


def test_recursion_summary_with_backtrace_and_diagnose():
    exc_info = _catch_exception(_diagnose_recursion, recursion_limit=120)
    assert exc_info[0] is RecursionError

    output = _render_exception(exc_info, backtrace=True, diagnose=True)

    repeated_frames = _count_traceback_frames(exc_info, _diagnose_recursion.__code__)
    assert repeated_frames > 4
    assert _repetition_line(repeated_frames - 3) in _repetition_lines(output)

    recursive_headers = re.findall(
        r'^  File "[^"]+", line \d+, in _diagnose_recursion$',
        output,
        flags=re.MULTILINE,
    )
    assert len(recursive_headers) == 3

    # Collapsing frames must not disable Loguru's source and variable output
    # for the three frames that remain visible.
    diagnosed_frames = re.findall(
        r"    _diagnose_recursion\(\)\n"
        r"    (?:└|->) <function _diagnose_recursion at 0x[0-9a-fA-F]+>",
        output,
    )
    assert len(diagnosed_frames) == 3
    assert output.rstrip().endswith("RecursionError: " + str(exc_info[1]))

import ast
from dataclasses import dataclass
from typing import Any, Iterable

import pytest

from func_adl import ObjectStream
from func_adl.type_based_replacement import remap_by_types


class Jet:
    def pt(self) -> float:
        ...

    def eta(self) -> float:
        ...


class Event:
    def Jets(self) -> Iterable[Jet]:
        ...


@dataclass
class Row:
    pt: float
    eta: float


def ast_expression(expression: str) -> ast.AST:
    return ast.parse(expression).body[0].value  # type: ignore


def remap(expression: str, var_name: str = "e", var_type: Any = Event):
    stream = ObjectStream(ast.Name(id=var_name, ctx=ast.Load()), var_type)
    return remap_by_types(stream, var_name, var_type, ast_expression(expression))


@pytest.mark.parametrize("method_name", ["Zip", "unknown_method"])
def test_unknown_method_on_dict_expression_returns_any(method_name):
    """An unknown method call must not be treated as a dictionary key lookup."""
    _, _, expr_type = remap(f"{{'jets': e.Jets()}}.{method_name}()")

    assert expr_type == Any


def test_zip_in_agc_style_chain_does_not_abort_type_tracing():
    expression = (
        "{'pt': e.Jets(), 'eta': e.Jets()}.Zip()"
        ".Where(lambda jet: jet.pt > 25 and abs(jet.eta) < 2.4).Count()"
    )

    _, transformed, _ = remap(expression)

    assert isinstance(transformed, ast.Call)


def test_known_dictionary_key_still_uses_available_type_information():
    _, _, expr_type = remap("{'jets': e.Jets()}.jets")

