def test_unknown_method_on_dataclass_returns_any():
    """Dictionaries propagated through Select are represented by dataclasses."""
    _, _, expr_type = remap("row.Zip()", var_name="row", var_type=Row)

    assert expr_type == Any


def test_known_dataclass_field_still_uses_available_type_information():
