"""
Tests for on-demand creation of nesting directories.

Pre-creating directories may be used as an optimization, but it must not be
required for correct operation. These tests use a local, filesystem-backed
SFTP client double so that both backends can be exercised without network
access.
"""

import shutil
from pathlib import Path

import pytest

from borgstore.backends.errors import ObjectNotFound
from borgstore.backends.posixfs import PosixFS
from borgstore.backends.sftp import Sftp


class FakeSftpFile:
    def __init__(self, path, mode):
        local_mode = "wb" if mode in ("w", "wb") else "rb"
        self._file = open(path, local_mode)

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        self._file.close()

    def set_pipelined(self, pipelined):
        pass

    def write(self, value):
        return self._file.write(value)

    def seek(self, offset):
        return self._file.seek(offset)

    def prefetch(self, size=None):
        pass

    def read(self, size=None):
        if size is None:
            return self._file.read()
        return self._file.read(size)


class FakeSftpClient:
    """Small SFTP client double with real filesystem error semantics."""

    def __init__(self, root):
        self.root = root

    def _path(self, name):
        return self.root / name

    def open(self, name, mode="r"):
        return FakeSftpFile(self._path(name), mode)

    def posix_rename(self, curr_name, new_name):
        self._path(curr_name).replace(self._path(new_name))

    def mkdir(self, name):
        self._path(name).mkdir()

    def unlink(self, name):
        self._path(name).unlink()

    def stat(self, name):
        return self._path(name).stat()


def make_backend(backend_kind, tmp_path, precreate_dirs):
    root = tmp_path / "store"
    root.mkdir()

    if backend_kind == "posixfs":
        backend = PosixFS(root)
        backend.precreate_dirs = precreate_dirs
        backend.open()
    else:
        # Avoid Sftp.__init__/_connect: no paramiko or network is needed for
        # exercising the public store/load/move operations with this client.
        backend = Sftp.__new__(Sftp)
        backend.opened = True
        backend.client = FakeSftpClient(root)
        backend.precreate_dirs = precreate_dirs

    return backend, root


@pytest.mark.parametrize("backend_kind", ["posixfs", "sftp"])
@pytest.mark.parametrize("precreate_dirs", [False, True])
def test_store_creates_missing_nesting_dirs_on_demand(
    backend_kind, precreate_dirs, tmp_path
):
    """Precreation is optional, including when precreate_dirs is True."""
    backend, _ = make_backend(backend_kind, tmp_path, precreate_dirs)
    name = "data/12/34/key"
    value = b"value stored without precreated directories"

    backend.store(name, value)

    assert backend.load(name) == value
    assert backend.info(name).exists


@pytest.mark.parametrize("backend_kind", ["posixfs", "sftp"])
def test_store_recreates_a_lost_nesting_directory(backend_kind, tmp_path):
    """A directory removed after store creation must not make stores fail."""
    backend, root = make_backend(backend_kind, tmp_path, precreate_dirs=True)
    first_name = "data/12/34/first"
    second_name = "data/12/34/second"
    (root / "data/12/34").mkdir(parents=True)
    backend.store(first_name, b"first")

    # Simulate losing part of the previously created directory hierarchy.
    shutil.rmtree(root / "data")
    backend.store(second_name, b"second")

    assert backend.load(second_name) == b"second"


@pytest.mark.parametrize("backend_kind", ["posixfs", "sftp"])
def test_store_to_existing_directory_uses_fast_path(
    backend_kind, tmp_path, monkeypatch
):
    """An existing nesting directory must not trigger an unnecessary mkdir."""
    backend, root = make_backend(backend_kind, tmp_path, precreate_dirs=False)
    name = "data/12/34/key"
    (root / "data/12/34").mkdir(parents=True)

    def unexpected_mkdir(*args, **kwargs):
        raise AssertionError("mkdir called although the nesting directory exists")

    if backend_kind == "posixfs":
        monkeypatch.setattr(Path, "mkdir", unexpected_mkdir)
    else:
        monkeypatch.setattr(backend.client, "mkdir", unexpected_mkdir)

    backend.store(name, b"value")

    assert backend.load(name) == b"value"


@pytest.mark.parametrize("backend_kind", ["posixfs", "sftp"])
@pytest.mark.parametrize("precreate_dirs", [False, True])
def test_move_creates_missing_destination_nesting_dirs(
    backend_kind, precreate_dirs, tmp_path
):
    """Moving to a nesting level also works without precreated destinations."""
    backend, root = make_backend(backend_kind, tmp_path, precreate_dirs)
    source = "data/12/34/source"
    destination = "data/ab/cd/destination"
    (root / "data/12/34").mkdir(parents=True)
    backend.store(source, b"value")

    backend.move(source, destination)

    assert not backend.info(source).exists
    assert backend.load(destination) == b"value"


@pytest.mark.parametrize("backend_kind", ["posixfs", "sftp"])
@pytest.mark.parametrize("precreate_dirs", [False, True])
def test_move_missing_source_raises_object_not_found(
    backend_kind, precreate_dirs, tmp_path
):
    """Retrying after FileNotFoundError must preserve the backend API error."""
    backend, root = make_backend(backend_kind, tmp_path, precreate_dirs)
    (root / "data").mkdir()

    with pytest.raises(ObjectNotFound):
        backend.move("data/missing", "other/nested/destination")

