import textwrap

import cpplint
import pytest


_TRAILING_SEMICOLON_MESSAGE = "You don't need a ; after a }"


def _trailing_semicolon_warnings(source):
    """Run cpplint normally and return only redundant-semicolon warnings."""
    lines = textwrap.dedent(source).strip("\n").splitlines()
    warnings = []

    def collect_error(filename, linenum, category, confidence, message):
        if (
            category == "readability/braces"
            and _TRAILING_SEMICOLON_MESSAGE in message
        ):
            warnings.append((linenum, message))

    cpplint.ProcessFileData(
        "concept_test.cc", "cc", lines, collect_error
    )
    return warnings


@pytest.mark.parametrize(
    "source",
    [
        # The example from the issue.
        """
        template <typename T>
        concept IndexableToChar = requires(T t) {
          { t[0] } -> std::convertible_to<char>;
        };
        """,
        # Splitting the concept-definition and requires-expression across lines
        # does not change the fact that the final semicolon is required.
        """
        template <typename T>
        concept IndexableToChar =
            requires(T t) {
              { t[0] } -> std::convertible_to<char>;
            };
        """,
        # Also allow the opening brace to be placed on its own line.
        """
        template <typename T>
        concept IndexableToChar = requires(T t)
        {
          { t[0] } -> std::convertible_to<char>;
        };
        """,
    ],
)
def test_concept_requires_expression_semicolon_is_not_redundant(source):
    assert _trailing_semicolon_warnings(source) == []


def test_concept_requires_expression_with_wrapped_parameter_list():
    source = """
    template <typename T>
    concept IndexableToChar =
        requires(
            T t) {
          { t[0] } -> std::convertible_to<char>;
        };
    """

    assert _trailing_semicolon_warnings(source) == []


def test_concept_requires_expression_semicolon_is_allowed_for_long_body():
    # Recognition must depend on the C++ construct, not on an arbitrary limit
    # on the number of lines between its opening and closing braces.
    requirements = "\n".join(
        f"  t.requirement_{index}();" for index in range(12)
    )
    source = (
        "template <typename T>\n"
        "concept LargeConcept = requires(T t) {\n"
        f"{requirements}\n"
        "};\n"
    )

    assert _trailing_semicolon_warnings(source) == []


def test_redundant_semicolon_after_function_body_is_still_reported():
    source = """
    void RegularFunction() {
    };
    """

    warnings = _trailing_semicolon_warnings(source)
    assert len(warnings) == 1


def test_concept_does_not_suppress_later_function_semicolon_warning():
    source = """
    template <typename T>
    concept IndexableToChar = requires(T t) {
      { t[0] } -> std::convertible_to<char>;
    };

    void RegularFunction() {
    };
    """

    # Exactly one warning should remain: the concept's semicolon is required,
    # while the function body's semicolon is redundant.
    warnings = _trailing_semicolon_warnings(source)
    assert len(warnings) == 1

from __future__ import annotations

from decimal import Decimal
from fractions import Fraction

import pytest

from pint import UnitRegistry


_OMITTED = object()


@pytest.fixture(scope="module")
def ureg():
    return UnitRegistry()


def assert_round_matches_builtin(ureg, value, ndigits=_OMITTED):
    """Rounding a quantity should round its magnitude like the bare value."""
    quantity = ureg.Quantity(value, "kilogram")
    original_type = type(quantity.magnitude)

    if ndigits is _OMITTED:
        expected = round(value)
        result = round(quantity)
    else:
        expected = round(value, ndigits)
        result = round(quantity, ndigits)

    assert isinstance(result, ureg.Quantity)
    assert result.magnitude == expected
    assert type(result.magnitude) is type(expected)
    assert result.units == ureg.kilogram

    # Rounding must not mutate or replace the input quantity's magnitude.
    assert quantity.magnitude == value
    assert type(quantity.magnitude) is original_type


def test_reported_round_example_returns_integer_magnitude(ureg):
    result = round(1.1 * ureg.kg)

    assert result.magnitude == 1
    assert type(result.magnitude) is int
    assert result.units == ureg.kg


@pytest.mark.parametrize(
    "value",
    [1.1, 2.5, 3.5, -1.6, -2.5, 0.0, 1234.567],
)
@pytest.mark.parametrize(
    "ndigits",
    [_OMITTED, None],
    ids=["ndigits-omitted", "ndigits-none"],
)
def test_round_without_digits_returns_int_and_uses_builtin_rounding(
    ureg, value, ndigits
):
    # In particular, ties must use Python's rounding rather than truncation or
    # conversion through int().
    assert_round_matches_builtin(ureg, value, ndigits)


@pytest.mark.parametrize("value", [1.2345, 1234.567, -2.5])
@pytest.mark.parametrize("ndigits", [0, 1, 2, -1, -2])
def test_round_with_explicit_ndigits_preserves_builtin_result_type(
    ureg, value, ndigits
):
    # Supplying zero explicitly is different from omitting ndigits:
    # round(1.1) is an int, while round(1.1, 0) is a float.
    assert_round_matches_builtin(ureg, value, ndigits)


@pytest.mark.parametrize(
    "value",
    [7, Decimal("2.5"), Fraction(5, 2)],
    ids=["integer", "decimal", "fraction"],
)
@pytest.mark.parametrize(
    "ndigits",
    [_OMITTED, None, 0, 1, -1],
    ids=["omitted", "none", "zero", "positive", "negative"],
)
def test_round_delegates_for_other_supported_scalar_magnitudes(
    ureg, value, ndigits
):
    assert_round_matches_builtin(ureg, value, ndigits)


@pytest.mark.parametrize("ndigits", [0.0, 1.5, "0"])
def test_round_rejects_invalid_ndigits_like_builtin(ureg, ndigits):
    quantity = ureg.Quantity(1.1, "kilogram")

    with pytest.raises(TypeError):
        round(quantity, ndigits)

