import yaml
import pytest

from nomenclature.codelist import RegionCodeList


def _write_region_file(path, regions):
    """Write a list of region definitions under the countries hierarchy."""
    path.write_text(
        yaml.safe_dump([{"countries": regions}], sort_keys=False),
        encoding="utf-8",
    )


def test_region_country_validation_collects_all_errors_in_a_file(tmp_path):
    """Parsing must continue after an invalid region and report every problem."""
    _write_region_file(
        tmp_path / "regions.yaml",
        [
            {"Valid aggregate": {"countries": ["Austria"]}},
            {
                "First invalid aggregate": {
                    "countries": [
                        "Austria",
                        "Invalid Country One",
                        "Invalid Country Two",
                    ]
                }
            },
            {"Another valid aggregate": {"countries": ["France"]}},
            {
                "Second invalid aggregate": {
                    "countries": ["Invalid Country Three"]
                }
            },
        ],
    )

    with pytest.raises(ValueError) as exc_info:
        RegionCodeList.from_directory("region", tmp_path)

    message = str(exc_info.value)

    # There are two invalid regions, not merely one error for the first region.
    assert "2 errors" in message
    for expected in (
        "First invalid aggregate",
        "Invalid Country One",
        "Invalid Country Two",
        "Second invalid aggregate",
        "Invalid Country Three",
    ):
        assert expected in message


def test_region_country_validation_collects_errors_across_files(tmp_path):
    """An invalid region in one YAML file must not hide errors in later files."""
    _write_region_file(
        tmp_path / "a.yaml",
        [
            {
                "Invalid region in first file": {
                    "countries": ["First Unknown Country"]
                }
            }
        ],
    )
    _write_region_file(
        tmp_path / "b.yaml",
        [
            {
                "Invalid region in second file": {
                    "countries": ["Second Unknown Country"]
                }
            }
        ],
    )

    with pytest.raises(ValueError) as exc_info:
        RegionCodeList.from_directory("region", tmp_path)

    message = str(exc_info.value)
    assert "2 errors" in message
    for expected in (
        "Invalid region in first file",
        "First Unknown Country",
        "Invalid region in second file",
        "Second Unknown Country",
    ):
        assert expected in message


def test_valid_region_country_definitions_still_load(tmp_path):
    """Error collection must not change successful region parsing."""
    _write_region_file(
        tmp_path / "valid.yaml",
        [
            {
                "European aggregate": {
                    "description": "A valid aggregate",
                    "countries": ["Austria", "France"],
                }
            },
            {"Single country aggregate": {"countries": ["Austria"]}},
        ],
    )

    codelist = RegionCodeList.from_directory("region", tmp_path)

    assert codelist["European aggregate"].countries == ["Austria", "France"]
    assert codelist["European aggregate"].hierarchy == "countries"
    assert codelist["European aggregate"].file.endswith("valid.yaml")
    assert codelist["Single country aggregate"].countries == ["Austria"]

import textwrap

import pytest

import cpplint


TRAILING_SEMICOLON_MESSAGE = "You don't need a ; after a }"


def trailing_semicolon_warnings(source):
    """Return line numbers reported for redundant-semicolon warnings."""
    errors = []

    def collect_error(filename, linenum, category, confidence, message):
        if (category == "readability/braces" and
                message == TRAILING_SEMICOLON_MESSAGE):
            errors.append(linenum)

    cpplint.ProcessFileData(
        "concept_test.cc", "cc", source.splitlines(), collect_error)
    return errors


@pytest.mark.parametrize(
    "source",
    [
        # The example from the issue: the semicolon is part of the concept
        # definition, not a redundant semicolon after a block.
        """
        template <typename T>
        concept IndexableToChar = requires(T t) {
          { t[0] } -> std::convertible_to<char>;
        };
        """,
        # A requires-expression need not have a parameter list.
        """
        template <typename T>
        concept HasValueType = requires {
          typename T::value_type;
        };
        """,
        # The constraint expression may be wrapped after the equals sign.
        """
        template <typename T>
        concept Incrementable =
            requires(T value) {
          ++value;
        };
        """,
        # The opening brace may be on a separate line.
        """
        template <typename T>
        concept Incrementable = requires(T value)
        {
          ++value;
        };
        """,
        # Newlines are also permitted within the requires parameter list.
        """
        template <typename T>
        concept Incrementable = requires(
            T value) {
          ++value;
        };
        """,
    ],
    ids=[
        "issue-example",
        "without-parameter-list",
        "requires-on-next-line",
        "brace-on-own-line",
        "wrapped-parameter-list",
    ],
)
def test_concept_requires_expression_semicolon_is_not_flagged(source):
    source = textwrap.dedent(source).strip("\n")
    assert trailing_semicolon_warnings(source) == []


def test_long_concept_requires_expression_semicolon_is_not_flagged():
    # Recognition must not depend on an arbitrary maximum body length.
    requirements = "\n".join(
        f"  value.operation_{number}();" for number in range(12)
    )
    source = (
        "template <typename T>\n"
        "concept ManyRequirements = requires(T value) {\n"
        f"{requirements}\n"
        "};\n"
    )

    assert trailing_semicolon_warnings(source) == []


def test_multiple_concepts_do_not_hide_redundant_function_semicolons():
    source = textwrap.dedent(
        """\
        template <typename T>
        concept First = requires(T value) {
          value.first();
        };

        template <typename T>
        concept Second = requires(T value) {
          value.second();
        };

        void regular_function() {};

        struct Example {
          void method() {};
        };
        """
    )

    # Only the function and inline member function have redundant semicolons.
    assert trailing_semicolon_warnings(source) == [11, 14]


