"""Regression tests for counts of mid-circuit measurements with dynamic one-shot."""

import numpy as np
import pytest

import pennylane as qml


def _assert_integer_keys(result):
    """Counts of a single mid-circuit measurement use integer outcome keys."""
    assert all(
        isinstance(key, (int, np.integer))
        and not isinstance(key, (bool, np.bool_))
        for key in result
    )


def _assert_complete_single_mcm_counts(result, shots, observed_outcome):
    assert len(result) == 2
    assert set(result) == {0, 1}
    _assert_integer_keys(result)

    assert int(result[observed_outcome]) == shots
    assert int(result[1 - observed_outcome]) == 0
    assert sum(int(count) for count in result.values()) == shots


@pytest.mark.parametrize("mcm_method", ["deferred", "one-shot"])
@pytest.mark.parametrize("observed_outcome", [0, 1])
def test_single_mcm_counts_include_all_outcomes(mcm_method, observed_outcome):
    """All outcomes are present, including when one of them was never sampled."""
    shots = 10
    dev = qml.device("default.qubit", wires=1, shots=shots)

    @qml.qnode(dev, mcm_method=mcm_method)
    def circuit():
        if observed_outcome:
            qml.X(0)
        m = qml.measure(0)
        return qml.counts(m, all_outcomes=True)

    result = circuit()

    _assert_complete_single_mcm_counts(result, shots, observed_outcome)


@pytest.mark.parametrize("observed_outcome", [0, 1])
def test_one_shot_single_mcm_counts_without_all_outcomes(observed_outcome):
    """Requesting only observed outcomes must not change their integer key type."""
    shots = 10
    dev = qml.device("default.qubit", wires=1, shots=shots)

    @qml.qnode(dev, mcm_method="one-shot")
    def circuit():
        if observed_outcome:
            qml.X(0)
        m = qml.measure(0)
        return qml.counts(m, all_outcomes=False)

    result = circuit()

    assert len(result) == 1
    _assert_integer_keys(result)
    assert observed_outcome in result
    assert int(result[observed_outcome]) == shots


@pytest.mark.parametrize("mcm_method", ["deferred", "one-shot"])
def test_counts_of_multiple_mcms_include_every_joint_outcome(mcm_method):
    """The all_outcomes guarantee also applies to counts of several MCMs."""
    shots = 12
    dev = qml.device("default.qubit", wires=2, shots=shots)

    @qml.qnode(dev, mcm_method=mcm_method)
    def circuit():
        m0 = qml.measure(0)
        m1 = qml.measure(1)
        return qml.counts([m0, m1], all_outcomes=True)

    result = circuit()
    expected = {"00": shots, "01": 0, "10": 0, "11": 0}

    assert len(result) == 4
    assert set(result) == set(expected)
    assert all(isinstance(key, str) for key in result)
    for outcome, count in expected.items():
        assert int(result[outcome]) == count
    assert sum(int(count) for count in result.values()) == shots


def test_one_shot_single_mcm_counts_with_shot_vector():
    """Every shot-vector partition independently contains all outcomes."""
    shot_partitions = (3, 7)
    dev = qml.device("default.qubit", wires=1, shots=shot_partitions)

    @qml.qnode(dev, mcm_method="one-shot")
    def circuit():
        m = qml.measure(0)
        return qml.counts(m, all_outcomes=True)

    results = circuit()

    assert isinstance(results, tuple)
    assert len(results) == len(shot_partitions)
    for result, shots in zip(results, shot_partitions):
        _assert_complete_single_mcm_counts(result, shots, observed_outcome=0)

