import re
import subprocess
import sys
import textwrap
from pathlib import Path

import pytest


CPPLINT = Path(__file__).resolve().with_name("cpplint.py")
SEMICOLON_WARNING = "You don't need a ; after a }"


def semicolon_warnings(tmp_path, source):
    """Run cpplint's public CLI and return lines with redundant-semicolon warnings."""
    source_file = tmp_path / "case.cc"
    source = textwrap.dedent(source).strip("\n") + "\n"
    source_file.write_text(source, encoding="utf-8")

    result = subprocess.run(
        [
            sys.executable,
            str(CPPLINT),
            "--filter=-,+readability/braces",
            "--quiet",
            str(source_file),
        ],
        cwd=tmp_path,
        capture_output=True,
        text=True,
        timeout=30,
        check=False,
    )
    output = result.stdout + result.stderr
    assert result.returncode in (0, 1), output

    warning_pattern = re.compile(
        r":(\d+):[^\n]*" + re.escape(SEMICOLON_WARNING)
    )
    return [int(match.group(1)) for match in warning_pattern.finditer(output)]


def test_reported_concept_requires_expression_is_not_flagged(tmp_path):
    source = """\
        template <typename T>
        concept IndexableToChar = requires(T t) {
          { t[0] } -> std::convertible_to<char>;
        };
    """

    assert semicolon_warnings(tmp_path, source) == []


@pytest.mark.parametrize(
    "source",
    [
        pytest.param(
            """\
                template <typename T>
                concept Parameterless = requires {
                  true;
                };
            """,
            id="parameterless-requires-expression",
        ),
        pytest.param(
            """\
                template <typename T>
                concept RequiresOnNextLine =
                    requires(T t) {
                  t;
                };
            """,
            id="requires-on-next-line",
        ),
        pytest.param(
            """\
                template <typename T>
                concept SplitEquals
                    = requires(T t) {
                  t;
                };
            """,
            id="equals-on-line-after-concept-name",
        ),
        pytest.param(
            """\
                template <typename T>
                concept SplitRequires = requires
                    (T t) {
                  t;
                };
            """,
            id="requires-parameters-on-next-line",
        ),
        pytest.param(
            """\
                template <typename T>
                concept BraceOnOwnLine = requires(T t)
                {
                  t;
                };
            """,
            id="opening-brace-on-own-line",
        ),
    ],
)
def test_concept_formatting_variations_are_not_flagged(tmp_path, source):
    assert semicolon_warnings(tmp_path, source) == []


def test_concept_with_long_requires_body_is_not_flagged(tmp_path):
    # Recognition must not depend on an arbitrary small opening/closing-brace
    # distance. Repeated simple requirements are valid C++20.
    requirements = "\n".join("  t;" for _ in range(12))
    source = (
        "template <typename T>\n"
        "concept LongConcept = requires(T t) {\n"
        f"{requirements}\n"
        "};\n"
    )

    assert semicolon_warnings(tmp_path, source) == []


