"""Tests for on-demand creation of nested backend directories.

The SFTP tests use an in-memory client double; they never open a network
connection.
"""

import shutil
import stat
from pathlib import Path
from types import SimpleNamespace

import pytest

from borgstore.backends.errors import ObjectNotFound
from borgstore.backends.posixfs import PosixFS
from borgstore.backends.sftp import Sftp
from borgstore.store import Store


@pytest.fixture
def posix_backend(tmp_path):
    backend = PosixFS(str(tmp_path / "store"))
    backend.create()
    backend.open()
    try:
        yield backend
    finally:
        backend.close()


def _track_posix_mkdir(monkeypatch):
    """Return a list recording Path.mkdir calls made after this is installed."""
    calls = []
    original_mkdir = Path.mkdir

    def recording_mkdir(self, *args, **kwargs):
        calls.append(self)
        return original_mkdir(self, *args, **kwargs)

    monkeypatch.setattr(Path, "mkdir", recording_mkdir)
    return calls


def test_store_creation_can_skip_precreating_levels_and_still_store(tmp_path):
    """A newly created, nested store must be usable without precreated dirs."""
    base_path = tmp_path / "store"
    store = Store(f"file://{base_path}", levels={"": [1]})
    key = "0123456789abcdef" * 4
    value = b"value written without precreated nesting directories"

    store.create()
    try:
        # Interactive creation should not have to populate the nesting tree.
        assert list(base_path.iterdir()) == []

        with store:
            store.store(key, value)
            assert store.load(key) == value
    finally:
        store.destroy()


@pytest.mark.parametrize("precreate_dirs", [False, True])
