class _FakeRemoteFile:
    def __init__(self, client, name):
        self.client = client
        self.name = name
        self.chunks = []
        self.closed = False
        self.pipelined = False

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        self.close()
        return False

    def set_pipelined(self, enabled):
        self.pipelined = enabled

    def write(self, data):
        data = bytes(data)
        self.chunks.append(data)
        return len(data)

    def close(self):
        if not self.closed:
            self.client.files[self.name] = b"".join(self.chunks)
            self.closed = True


class _FakeSftpClient:
    """Small in-memory SFTP double implementing operations used by Sftp."""

    def __init__(self):
        self.files = {}
        self.dirs = {"."}
        self.open_calls = []
        self.mkdir_calls = []
        self.rename_calls = []

    @staticmethod
    def _parent(name):
        return str(Path(name).parent)

    def open(self, name, mode="r"):
        name = str(name)
        self.open_calls.append(name)
        if mode not in ("w", "wb"):
            raise AssertionError(f"unexpected mode in SFTP test double: {mode}")
        if self._parent(name) not in self.dirs:
            raise FileNotFoundError(name)
        return _FakeRemoteFile(self, name)

    def mkdir(self, name):
        name = str(name)
        self.mkdir_calls.append(name)
        if name in self.dirs or name in self.files:
            raise OSError("already exists")
        if self._parent(name) not in self.dirs:
            raise FileNotFoundError(name)
        self.dirs.add(name)

    def posix_rename(self, curr_name, new_name):
        curr_name = str(curr_name)
        new_name = str(new_name)
        self.rename_calls.append((curr_name, new_name))
        if curr_name not in self.files:
            raise FileNotFoundError(curr_name)
        if self._parent(new_name) not in self.dirs:
            raise FileNotFoundError(new_name)
        self.files[new_name] = self.files.pop(curr_name)

    def stat(self, name):
        name = str(name)
        if name in self.files:
            return SimpleNamespace(
                st_mode=stat.S_IFREG | 0o644,
                st_size=len(self.files[name]),
            )
        if name in self.dirs:
            return SimpleNamespace(st_mode=stat.S_IFDIR | 0o755, st_size=0)
        raise FileNotFoundError(name)

    def unlink(self, name):
        name = str(name)
        if name not in self.files:
            raise FileNotFoundError(name)
        del self.files[name]


def _sftp_backend(client, precreate_dirs=False):
    # Avoid Sftp.__init__/_connect: these tests must never use the network.
    backend = object.__new__(Sftp)
    backend.client = client
    backend.opened = True
    backend.precreate_dirs = precreate_dirs
    return backend


@pytest.mark.parametrize("precreate_dirs", [False, True])
def test_sftp_store_tries_write_then_creates_missing_directories(precreate_dirs):
    client = _FakeSftpClient()
    backend = _sftp_backend(client, precreate_dirs=precreate_dirs)
    value = b"\x00sftp value\xff"

    backend.store("aa/bb/cc/object", value)

    assert client.files == {"aa/bb/cc/object": value}
    # The first write fails, then mkdir and exactly one retry are performed.
    assert len(client.open_calls) == 2
    assert client.mkdir_calls


def test_sftp_store_existing_parent_does_not_call_mkdir():
    client = _FakeSftpClient()
    client.dirs.update({"aa", "aa/bb"})
    backend = _sftp_backend(client, precreate_dirs=False)

    backend.store("aa/bb/object", b"value")

    assert client.files["aa/bb/object"] == b"value"
    assert client.mkdir_calls == []
    assert len(client.open_calls) == 1


@pytest.mark.parametrize("precreate_dirs", [False, True])
def test_sftp_move_tries_rename_then_creates_missing_directories(precreate_dirs):
    client = _FakeSftpClient()
    client.files["source"] = b"move me"
    backend = _sftp_backend(client, precreate_dirs=precreate_dirs)

    backend.move("source", "aa/bb/cc/target")

    assert client.files == {"aa/bb/cc/target": b"move me"}
    # The direct rename is attempted before the fallback and its retry.
    assert len(client.rename_calls) == 2
    assert client.mkdir_calls


def test_sftp_move_existing_target_parent_does_not_call_mkdir():
    client = _FakeSftpClient()
    client.files["source"] = b"move me"
    client.dirs.update({"aa", "aa/bb"})
    backend = _sftp_backend(client, precreate_dirs=False)

    backend.move("source", "aa/bb/target")

