"""Regression tests for counts of mid-circuit measurements in one-shot mode."""

import itertools

import numpy as np
import pytest

import pennylane as qml


def _assert_integer_counts(result, expected):
    """Check exact counts and ensure that outcomes are represented by integer keys."""
    assert isinstance(result, dict)
    assert set(result) == set(expected)

    for key in result:
        assert isinstance(key, (int, np.integer))
        assert not isinstance(key, (float, np.floating))

    for outcome, count in expected.items():
        assert int(result[outcome]) == count


@pytest.mark.parametrize("shots", [1, 10])
@pytest.mark.parametrize("flip", [False, True])
def test_one_shot_mcm_counts_all_outcomes_deterministic(shots, flip):
    """All binary outcomes must be returned, including outcomes with zero counts."""
    dev = qml.device("default.qubit", wires=1, shots=shots)

    @qml.qnode(dev, mcm_method="one-shot")
    def circuit():
        if flip:
            qml.X(0)
        m = qml.measure(0)
        return qml.counts(m, all_outcomes=True)

    observed = int(flip)
    expected = {0: 0, 1: 0}
    expected[observed] = shots

    _assert_integer_counts(circuit(), expected)


@pytest.mark.parametrize("flip", [False, True])
def test_one_shot_mcm_counts_observed_outcomes_only(flip):
    """Requesting only observed outcomes must still omit zero-count outcomes."""
    shots = 10
    dev = qml.device("default.qubit", wires=1, shots=shots)

    @qml.qnode(dev, mcm_method="one-shot")
    def circuit():
        if flip:
            qml.X(0)
        m = qml.measure(0)
        return qml.counts(m, all_outcomes=False)

    _assert_integer_counts(circuit(), {int(flip): shots})


def test_one_shot_mcm_counts_all_outcomes_superposition():
    """Adding all outcomes must not discard or fabricate the sampled counts."""
    shots = 128
    dev = qml.device("default.qubit", wires=1, shots=shots, seed=123)

    @qml.qnode(dev, mcm_method="one-shot")
    def circuit():
        qml.Hadamard(0)
        m = qml.measure(0)
        return qml.counts(m, all_outcomes=True)

    result = circuit()

    assert set(result) == {0, 1}
    assert all(isinstance(key, (int, np.integer)) for key in result)
    counts = {key: int(value) for key, value in result.items()}
    assert sum(counts.values()) == shots
    assert counts[0] > 0
    assert counts[1] > 0


def test_one_shot_mcm_counts_all_outcomes_with_shot_vector():
    """Each shot-vector bin must independently contain every possible outcome."""
    shot_bins = [3, 7]
    dev = qml.device("default.qubit", wires=1, shots=shot_bins)

    @qml.qnode(dev, mcm_method="one-shot")
    def circuit():
        m = qml.measure(0)
        return qml.counts(m, all_outcomes=True)

    results = circuit()

    assert len(results) == len(shot_bins)
    for result, shots in zip(results, shot_bins):
        _assert_integer_counts(result, {0: shots, 1: 0})


@pytest.mark.parametrize("prepared_state", ["00", "01", "10", "11"])
def test_one_shot_multiple_mcm_counts_all_outcomes(prepared_state):
    """Multiple MCMs must return all bit strings without mixing key types."""
    shots = 8
    dev = qml.device("default.qubit", wires=2, shots=shots)

    @qml.qnode(dev, mcm_method="one-shot")
    def circuit():
        for wire, bit in enumerate(prepared_state):
            if bit == "1":
                qml.X(wire)
        m0 = qml.measure(0)
        m1 = qml.measure(1)
        return qml.counts([m0, m1], all_outcomes=True)

    result = circuit()
    all_outcomes = ["".join(bits) for bits in itertools.product("01", repeat=2)]
    expected = {outcome: 0 for outcome in all_outcomes}
    expected[prepared_state] = shots

    assert isinstance(result, dict)
    assert set(result) == set(all_outcomes)
    assert all(isinstance(key, str) for key in result)
    for outcome, count in expected.items():
        assert int(result[outcome]) == count

import textwrap

import cpplint
import pytest


_SEMICOLON_WARNING = "You don't need a ; after a }"


def _trailing_semicolon_warnings(source):
    """Return 1-based line numbers of redundant-semicolon warnings."""
    source = textwrap.dedent(source).strip("\n")

    cpplint._cpplint_state.ResetErrorCounts()
    cpplint._cpplint_state.SetFilters("-,+readability/braces")
    cpplint._cpplint_state.SetVerboseLevel(5)

    warning_lines = []

    def collect_error(filename, linenum, category, confidence, message):
        if category == "readability/braces" and message == _SEMICOLON_WARNING:
            warning_lines.append(linenum + 1)

    cpplint.ProcessFileData(
        "concept_test.cc", "cc", source.splitlines(), collect_error
    )
    return warning_lines


def test_reported_concept_requires_expression_allows_semicolon():
    source = """
        template <typename T>
        concept IndexableToChar = requires(T t) {
          { t[0] } -> std::convertible_to<char>;
        };
    """

    assert _trailing_semicolon_warnings(source) == []


@pytest.mark.parametrize(
    "source",
    [
        pytest.param(
            """
            template <typename T>
            concept Indexable = requires(T t) { t[0]; };
            """,
            id="single-line-requires-expression",
        ),
        pytest.param(
            """
            template <typename T>
            concept Indexable = requires(T t)
            {
              t[0];
            };
            """,
            id="opening-brace-on-next-line",
        ),
        pytest.param(
            """
            template <typename T>
            concept Indexable =
                requires(T t) {
              t[0];
            };
            """,
            id="requires-on-line-after-concept",
        ),
        pytest.param(
            """
            template <typename T>
            concept DefaultConstructible = requires {
              T{};
            };
            """,
            id="requires-expression-without-parameter-list",
        ),
    ],
)
def test_concept_requires_expression_formatting_variations(source):
    assert _trailing_semicolon_warnings(source) == []


def test_concept_requires_expression_with_multiline_parameter_list():
    source = """
        template <typename T, typename U>
        concept BinaryConcept =
            requires(T t,
                     U u)
        {
          { t + u } -> std::convertible_to<bool>;
        };
    """

    assert _trailing_semicolon_warnings(source) == []


def test_concept_requires_expression_body_can_be_long():
    requirements = "\n".join(
        f"  t.requirement_{number}();" for number in range(12)
    )
    source = (
        "template <typename T>\n"
        "concept LongConcept = requires(T t) {\n"
        f"{requirements}\n"
        "};\n"
    )

    # The C++ grammar does not impose a maximum requires-expression length.
    assert _trailing_semicolon_warnings(source) == []


def test_redundant_semicolons_near_concept_are_still_reported():
    source = """
        template <typename T>
        concept SimpleConcept = requires(T t) {
          t.method();
        };

        void free_function() {};

        struct Widget {
          void method() {};
        };
    """

    # Only the two function bodies have redundant semicolons.
    assert _trailing_semicolon_warnings(source) == [7, 10]


def test_function_with_trailing_requires_clause_is_not_a_concept():
    # First establish that this function-body formatting is normally checked.
    function_source = """
        template <typename T>
        void f(T t) requires C<T>
        {
        };
    """
    assert len(_trailing_semicolon_warnings(function_source)) == 1

    source = """
        template <typename T>
        concept C = requires(T t) { t.foo(); };

        template <typename T>
        void f(T t) requires C<T>
        {
        };
    """

    warnings = _trailing_semicolon_warnings(source)

    # The nearby concept must not suppress the warning for the function body.
    # The concept itself is independently checked above to produce no warning.
    assert len(warnings) == 1
    assert warnings[0] > 2

