"""Regression tests for counts of mid-circuit measurements in one-shot mode."""

import numpy as np
import pytest

import pennylane as qml


def _assert_integer_outcomes(counts, outcomes):
    """Check the outcome set without letting int/float equality hide bad key types."""
    assert set(counts) == set(outcomes)
    assert all(isinstance(key, (int, np.integer)) for key in counts)


@pytest.mark.parametrize("flip", [False, True])
def test_one_shot_single_mcm_counts_all_outcomes(flip):
    """All binary outcomes should be present, including unobserved ones, with integer keys."""
    shots = 10
    dev = qml.device("default.qubit", wires=1, shots=shots)

    @qml.qnode(dev, mcm_method="one-shot")
    def circuit():
        if flip:
            qml.X(0)
        m = qml.measure(0)
        return qml.counts(m, all_outcomes=True)

    result = circuit()

    _assert_integer_outcomes(result, {0, 1})
    observed = int(flip)
    unobserved = 1 - observed
    assert int(result[observed]) == shots
    assert int(result[unobserved]) == 0
    assert sum(int(value) for value in result.values()) == shots


def test_one_shot_single_mcm_counts_observed_outcomes_only():
    """Requesting only observed outcomes must not add zero-count outcomes."""
    shots = 10
    dev = qml.device("default.qubit", wires=1, shots=shots)

    @qml.qnode(dev, mcm_method="one-shot")
    def circuit():
        m = qml.measure(0)
        return qml.counts(m, all_outcomes=False)

    result = circuit()

    _assert_integer_outcomes(result, {0})
    assert int(result[0]) == shots


def test_one_shot_single_mcm_counts_all_outcomes_with_shot_vector():
    """Every shot-vector partition should independently contain all outcomes."""
    shots = [4, 6]
    dev = qml.device("default.qubit", wires=1, shots=shots)

    @qml.qnode(dev, mcm_method="one-shot")
    def circuit():
        m = qml.measure(0)
        return qml.counts(m, all_outcomes=True)

    results = circuit()

    assert isinstance(results, tuple)
    assert len(results) == len(shots)
    for result, shot_count in zip(results, shots):
        _assert_integer_outcomes(result, {0, 1})
        assert int(result[0]) == shot_count
        assert int(result[1]) == 0


def test_one_shot_composite_mcm_counts_uses_its_actual_outcomes():
    """The zero-count outcomes should come from the measurement, not a hardcoded {0, 1}."""
    shots = 8
    dev = qml.device("default.qubit", wires=1, shots=shots)

    @qml.qnode(dev, mcm_method="one-shot")
    def circuit():
        qml.X(0)
        m = qml.measure(0)
        return qml.counts(2 * m, all_outcomes=True)

    result = circuit()

    _assert_integer_outcomes(result, {0, 2})
    assert int(result[0]) == 0
    assert int(result[2]) == shots


def test_one_shot_multiple_mcm_counts_all_outcomes():
    """Counts of several MCMs should retain bit-string keys and include every bit string."""
    shots = 12
    dev = qml.device("default.qubit", wires=2, shots=shots)

    @qml.qnode(dev, mcm_method="one-shot")
    def circuit():
        m0 = qml.measure(0)
        m1 = qml.measure(1)
        return qml.counts(op=[m0, m1], all_outcomes=True)

    result = circuit()

    expected_outcomes = {"00", "01", "10", "11"}
    assert set(result) == expected_outcomes
    assert all(isinstance(key, str) for key in result)
    assert int(result["00"]) == shots
    for outcome in expected_outcomes - {"00"}:
        assert int(result[outcome]) == 0
    assert sum(int(value) for value in result.values()) == shots

import numpy as np
import pytest
from astropy import units as u
from astropy.modeling import models

from specutils import Spectrum1D
from specutils.fitting import fit_lines


class RecordingFitter:
    """Fitter double that records the data actually supplied to the fit."""

    def __call__(self, model, x, y, weights=None, **kwargs):
        self.x = x.copy()
        self.y = y.copy()
        self.weights = None if weights is None else weights.copy()
        return model


def _to_values(values, unit):
    if isinstance(values, u.Quantity):
        return values.to_value(unit)
    return np.asarray(values)


def _make_spectrum():
    # Avoid samples exactly at 6553 or 6573 Angstrom so that the scalar-window
    # and explicit-bounds forms select the same pixels despite their different
    # upper-bound comparisons.
    dispersion = (6540.13 + 0.61 * np.arange(70)) * u.AA
    flux = (0.25 + np.arange(dispersion.size)) * u.Jy
    return Spectrum1D(spectral_axis=dispersion, flux=flux)


def _make_model(compound):
    gaussian = models.Gaussian1D(
        amplitude=2000 * u.Jy,
        mean=6563 * u.AA,
        stddev=3 * u.AA,
    )
    if compound:
        # This is the model form used in the issue. A compound model exposes
        # the Gaussian center as mean_0 rather than mean.
        return gaussian + models.Const1D(0 * u.Jy)
    return gaussian


@pytest.mark.parametrize(
    "compound", [False, True], ids=["gaussian", "gaussian-plus-continuum"]
)
@pytest.mark.parametrize(
    "window", [10 * u.AA, 1 * u.nm], ids=["angstrom", "equivalent-unit"]
)
def test_scalar_quantity_window_restricts_fit_around_gaussian_center(
    window, compound
):
    spectrum = _make_spectrum()
    fitter = RecordingFitter()

    fit_lines(spectrum, _make_model(compound), fitter=fitter, window=window)

    wavelength = spectrum.spectral_axis.to_value(u.AA)
    expected = (wavelength >= 6553) & (wavelength <= 6573)
    assert 0 < expected.sum() < wavelength.size

    fitted_wavelength = _to_values(fitter.x, u.AA)
    fitted_flux = _to_values(fitter.y, u.Jy)

    np.testing.assert_allclose(fitted_wavelength, wavelength[expected])
    np.testing.assert_allclose(
        fitted_flux, spectrum.flux.to_value(u.Jy)[expected]
    )


def test_scalar_quantity_window_matches_explicit_window_for_issue_model():
    spectrum = _make_spectrum()
    automatic_fitter = RecordingFitter()
    explicit_fitter = RecordingFitter()

    fit_lines(
        spectrum,
        _make_model(compound=True),
        fitter=automatic_fitter,
        window=10 * u.AA,
    )
    fit_lines(
        spectrum,
        _make_model(compound=True),
        fitter=explicit_fitter,
        window=(6553 * u.AA, 6573 * u.AA),
    )

    np.testing.assert_allclose(
        _to_values(automatic_fitter.x, u.AA),
        _to_values(explicit_fitter.x, u.AA),
    )
    np.testing.assert_allclose(
        _to_values(automatic_fitter.y, u.Jy),
        _to_values(explicit_fitter.y, u.Jy),
    )

"""Regression tests for C++20 concept requires-expression semicolons."""

from contextlib import redirect_stderr, redirect_stdout
import io
from pathlib import Path

import pytest

import cpplint


SEMICOLON_WARNING = "You don't need a ; after a }"


def _trailing_semicolon_warnings(tmp_path, source):
    """Run cpplint on source and return redundant-semicolon diagnostics."""
    source_file = Path(tmp_path) / "concept_test.cc"
    source_file.write_text(source, encoding="utf-8")

    # Restrict output to the check involved in this issue so unrelated style
    # diagnostics cannot affect the assertions.
    state = cpplint._cpplint_state
    state.SetFilters("-,+readability/braces")
    state.SetOutputFormat("emacs")
    state.SetCountingStyle("total")
    state.quiet = True

    stdout = io.StringIO()
    stderr = io.StringIO()
    with redirect_stdout(stdout), redirect_stderr(stderr):
        cpplint.ProcessFile(str(source_file), 0)

    output = stdout.getvalue() + stderr.getvalue()
    return [line for line in output.splitlines() if SEMICOLON_WARNING in line]


def test_issue_example_does_not_report_redundant_semicolon(tmp_path):
    source = """\
template <typename T>
concept IndexableToChar = requires(T t) {
  { t[0] } -> std::convertible_to<char>;
};
"""

    assert _trailing_semicolon_warnings(tmp_path, source) == []


@pytest.mark.parametrize(
    "source",
    [
        # The opening brace may be on the line following the requires clause.
        """\
template <typename T>
concept Indexable = requires(T t)
{
  t[0];
};
""",
        # The requires-expression may start on the line after the equals sign.
        """\
template <typename T>
concept Indexable =
    requires(T t) {
  t[0];
};
""",
        # A requires-expression need not have a parameter list.
        """\
template <typename T>
concept DefaultConstructible = requires {
  T{};
};
""",
    ],
)
def test_concept_semicolon_is_accepted_across_common_layouts(tmp_path, source):
    assert _trailing_semicolon_warnings(tmp_path, source) == []


def test_concept_body_length_does_not_change_semicolon_requirement(tmp_path):
    # C++ does not impose a length limit after which the concept definition's
    # semicolon becomes optional.
    requirements = "\n".join(f"  t[{index}];" for index in range(12))
    source = (
        "template <typename T>\n"
        "concept LongConcept = requires(T t) {\n"
        f"{requirements}\n"
        "};\n"
    )

    assert _trailing_semicolon_warnings(tmp_path, source) == []


def test_ordinary_redundant_semicolon_is_still_reported(tmp_path):
    source = """\
struct RequiredSemicolon {};
void FunctionWithRedundantSemicolon() {};
"""

    warnings = _trailing_semicolon_warnings(tmp_path, source)
    assert len(warnings) == 1
    assert ":2:" in warnings[0]


def test_requires_clause_on_function_is_not_a_concept_requires_expression(tmp_path):
    # A concept declaration nearby must not suppress diagnostics for later,
    # unrelated blocks. The semicolon after this function body is redundant;
    # unlike a concept definition, a function definition does not require it.
    source = """\
template <typename T>
concept C = requires(T t) {
  t[0];
};

template <typename T>
void F() requires C<T>
{
};
"""

    warnings = _trailing_semicolon_warnings(tmp_path, source)
    assert len(warnings) == 1
    assert ":8:" in warnings[0]

import numpy as np
import pytest

import pennylane as qml


def _plain_counts(counts):
    """Convert NumPy scalar keys/values to Python scalars for exact comparisons."""
    plain = {}
    for key, value in counts.items():
        if isinstance(key, np.generic):
            key = key.item()
        plain[key] = int(value)
    return plain


def _assert_integer_outcomes(counts):
    assert all(isinstance(key, (int, np.integer)) for key in counts)


@pytest.mark.parametrize("measured_state", [0, 1])
@pytest.mark.parametrize("shots", [1, 10])
def test_one_shot_single_mcm_counts_all_outcomes(measured_state, shots):
    """All binary outcomes must be present, including outcomes never sampled."""
    dev = qml.device("default.qubit", wires=1, shots=shots)

    @qml.qnode(dev, mcm_method="one-shot")
    def circuit():
        if measured_state:
            qml.X(0)
        m = qml.measure(0)
        return qml.counts(m, all_outcomes=True)

    result = circuit()

    _assert_integer_outcomes(result)
    expected = {0: 0, 1: 0}
    expected[measured_state] = shots
    assert _plain_counts(result) == expected


def test_one_shot_single_mcm_counts_without_all_outcomes():
    """Requesting only observed outcomes should still use integer outcome keys."""
    shots = 6
    dev = qml.device("default.qubit", wires=1, shots=shots)

    @qml.qnode(dev, mcm_method="one-shot")
    def circuit():
        m = qml.measure(0)
        return qml.counts(m, all_outcomes=False)

    result = circuit()

    _assert_integer_outcomes(result)
    assert _plain_counts(result) == {0: shots}


def test_one_shot_single_mcm_counts_preserves_shot_totals():
    """Sampling a non-deterministic MCM should retain every valid shot."""
    shots = 128
    dev = qml.device("default.qubit", wires=1, shots=shots, seed=1234)

    @qml.qnode(dev, mcm_method="one-shot")
    def circuit():
        qml.Hadamard(0)
        m = qml.measure(0)
        return qml.counts(m, all_outcomes=True)

    result = circuit()
    plain_result = _plain_counts(result)

    _assert_integer_outcomes(result)
    assert set(plain_result) == {0, 1}
    assert sum(plain_result.values()) == shots
    assert plain_result[0] > 0
    assert plain_result[1] > 0


def test_one_shot_single_mcm_counts_all_outcomes_with_shot_vector():
    """Each shot-vector bin should independently contain both outcomes."""
    shot_bins = (3, 5)
    dev = qml.device("default.qubit", wires=1, shots=list(shot_bins))

    @qml.qnode(dev, mcm_method="one-shot")
    def circuit():
        m = qml.measure(0)
        return qml.counts(m, all_outcomes=True)

    results = circuit()

    assert isinstance(results, tuple)
    assert len(results) == len(shot_bins)
    for result, shots in zip(results, shot_bins):
        _assert_integer_outcomes(result)
        assert _plain_counts(result) == {0: shots, 1: 0}


def test_one_shot_multiple_mcm_counts_all_outcomes():
    """Counts over a sequence of MCMs should include every bit-string outcome."""
    shots = 6
    dev = qml.device("default.qubit", wires=2, shots=shots)

    @qml.qnode(dev, mcm_method="one-shot")
    def circuit():
        qml.X(1)
        m0 = qml.measure(0)
        m1 = qml.measure(1)
        return qml.counts(op=[m0, m1], all_outcomes=True)

    result = circuit()

    assert _plain_counts(result) == {
        "00": 0,
        "01": shots,
        "10": 0,
        "11": 0,
    }


def test_one_shot_composite_mcm_counts_all_outcomes():
    """All branches of an arithmetic measurement value should be represented."""
    shots = 6
    dev = qml.device("default.qubit", wires=2, shots=shots)

    @qml.qnode(dev, mcm_method="one-shot")
    def circuit():
        qml.X(1)
        m0 = qml.measure(0)
        m1 = qml.measure(1)
        return qml.counts(m0 + 2 * m1, all_outcomes=True)

    result = circuit()

    _assert_integer_outcomes(result)
    assert _plain_counts(result) == {0: 0, 1: 0, 2: shots, 3: 0}

import io
import json
from urllib.parse import parse_qs, urlsplit

import pytest

from nix_auto_follow.cli import Node, start


GIT_URL = "https://github.com/SuperSandro2000/nixpkgs.git"
GIT_FLAKE_URL = f"git+{GIT_URL}"
REV = "c3392ad349a5227f4a3464dce87bcc5046692fce"


def make_git_node(**attributes: object) -> Node:
    original = {"type": "git", "url": GIT_URL}
    original.update(attributes)
    return Node.from_dict({"original": original})


@pytest.mark.parametrize(
    ("attributes", "expected_url"),
    [
        ({}, GIT_FLAKE_URL),
        (
            {"ref": "nixos-unstable"},
            f"{GIT_FLAKE_URL}?ref=nixos-unstable",
        ),
        (
            {"rev": REV},
            f"{GIT_FLAKE_URL}?rev={REV}",
        ),
    ],
)
def test_git_get_url_reconstructs_a_valid_flake_url(
    attributes: dict[str, object], expected_url: str
) -> None:
    """Git refs and revisions are query parameters, not repository path parts."""
    assert make_git_node(**attributes).get_url() == expected_url


def test_git_get_url_accepts_the_shallow_input_from_the_issue() -> None:
    # A lockfile produced from
    # git+https://github.com/SuperSandro2000/nixpkgs.git?shallow=1&ref=nixos-unstable
    # contains structured `shallow` and `ref` attributes in `original`.
    url = make_git_node(ref="nixos-unstable", shallow=True).get_url()
    parts = urlsplit(url)

    assert parts.scheme == "git+https"
    assert parts.netloc == "github.com"
    assert parts.path == "/SuperSandro2000/nixpkgs.git"
    assert parts.fragment == ""

    query = parse_qs(parts.query, keep_blank_values=True)
    assert query["ref"] == ["nixos-unstable"]
    # Retaining `shallow` is optional, but a retained boolean must use Nix's
    # query-parameter representation rather than Python's string "True".
    if "shallow" in query:
        assert query["shallow"] == ["1"]


def test_check_mode_reports_a_valid_git_url_instead_of_raising(
    capsys: pytest.CaptureFixture[str],
) -> None:
    """Exercise the start -> check_lock_file -> get_url path from the issue."""
    flake_lock = {
        "nodes": {
            "root": {"inputs": {"a": "a", "b": "b"}},
            "a": {"inputs": {"nixpkgs": "git_nixpkgs"}},
            "b": {"inputs": {"nixpkgs": "github_nixpkgs"}},
            "git_nixpkgs": {
                "locked": {
                    "rev": REV,
                    "type": "git",
                    "url": GIT_URL,
                },
                "original": {
                    "ref": "nixos-unstable",
                    "type": "git",
                    "url": GIT_URL,
                },
            },
            "github_nixpkgs": {
                "locked": {
                    "owner": "NixOS",
                    "repo": "nixpkgs",
                    "rev": REV,
                    "type": "github",
                },
                "original": {
                    "owner": "NixOS",
                    "repo": "nixpkgs",
                    "type": "github",
                },
            },
        },
        "root": "root",
        "version": 7,
    }

    with pytest.raises(SystemExit) as exc_info:
        start(
            args=["--check", "-"],
            stdin=io.StringIO(json.dumps(flake_lock)),
            stdout=io.StringIO(),
        )

    assert exc_info.value.code == 1
    output = capsys.readouterr().out
    assert (
        'nixpkgs.url = "git+https://github.com/SuperSandro2000/'
        'nixpkgs.git?ref=nixos-unstable"'
    ) in output
    assert "nixpkgs.git/nixos-unstable" not in output

"""Regression tests for semicolons terminating C++20 concept definitions."""

import copy
import textwrap
import unittest

import cpplint
import pytest


_TRAILING_SEMICOLON_WARNING = "You don't need a ; after a }"


@pytest.fixture(autouse=True)
def preserve_cpplint_state():
    """Prevent lint configuration from leaking into the repository tests."""
    state = cpplint._cpplint_state
    saved_state = copy.deepcopy(state.__dict__)
    yield
    state.__dict__.clear()
    state.__dict__.update(saved_state)


def _trailing_semicolon_errors(source):
    """Lint source and return only redundant-semicolon readability errors."""
    state = cpplint._cpplint_state
    state.ResetErrorCounts()
    state.SetVerboseLevel(0)
    state.SetFilters("-,+readability/braces")

    errors = []

    def collect_error(filename, linenum, category, confidence, message):
        if (
            category == "readability/braces"
            and _TRAILING_SEMICOLON_WARNING in message
        ):
            errors.append((linenum, message))

    lines = textwrap.dedent(source).strip("\n").splitlines()
    cpplint.ProcessFileData("concept_test.cc", "cc", lines, collect_error)
    return errors


@pytest.mark.parametrize(
    "source",
    [
        # The example from the issue.
        """
        template <typename T>
        concept IndexableToChar = requires(T t) {
          { t[0] } -> std::convertible_to<char>;
        };
        """,
        # The complete definition may also be written on one line.
        """
        template <typename T> concept IndexableToChar = requires(T t) { { t[0] } -> std::convertible_to<char>; };
        """,
        # A requires-expression need not have a parameter list.
        """
        template <typename T>
        concept HasValueType = requires {
          typename T::value_type;
        };
        """,
        # Newlines are whitespace in C++, including between concept and its name.
        """
        template <typename T>
        concept
        IndexableToChar = requires(T t) {
          { t[0] } -> std::convertible_to<char>;
        };
        """,
        # Likewise, the equals sign may be on a continuation line.
        """
        template <typename T>
        concept IndexableToChar
            = requires(T t) {
          { t[0] } -> std::convertible_to<char>;
        };
        """,
        # Putting the opening brace on its own line must not change the result.
        """
        template <typename T>
        concept IndexableToChar = requires(T t)
        {
          { t[0] } -> std::convertible_to<char>;
        };
        """,
    ],
    ids=[
        "issue-example",
        "single-line",
        "without-requires-parameters",
        "newline-after-concept-keyword",
        "equals-on-continuation-line",
        "brace-on-next-line",
    ],
)
def test_concept_definition_semicolon_is_not_redundant(source):
    assert _trailing_semicolon_errors(source) == []


def test_long_concept_body_still_requires_terminating_semicolon():
    requirements = "\n".join(f"  t[{index}];" for index in range(16))
    source = (
        "template <typename T>\n"
        "concept ManyRequirements = requires(T t) {\n"
        f"{requirements}\n"
        "};\n"
    )

    assert _trailing_semicolon_errors(source) == []


def test_ordinary_function_still_rejects_redundant_semicolon():
    source = """
    void FunctionWithRedundantSemicolon() {
    };
    """

    assert len(_trailing_semicolon_errors(source)) == 1


def test_nearby_concept_does_not_exempt_unrelated_braces():
    """Only the concept's own closing brace is exempt, not nearby blocks."""
    source = """
    void BeforeConcept() {
    };
    template <typename T> concept NearbyConcept = requires(T t) {
      { t[0] } -> std::convertible_to<char>;
    };
    void AfterConcept() {
    };
    """

    # Both function definitions have redundant semicolons. The concept between
    # them has exactly one required semicolon and must not suppress either error.
    assert len(_trailing_semicolon_errors(source)) == 2


def test_existing_cpplint_regression_suite():
    """Retain the repository's general regression and coverage checks."""
    import cpplint_unittest

    suite = unittest.defaultTestLoader.loadTestsFromModule(cpplint_unittest)
    result = unittest.TestResult()
    suite.run(result)

    assert result.testsRun > 0
    problems = "\n\n".join(
        f"{test}\n{traceback}"
        for test, traceback in result.failures + result.errors
    )
    assert result.wasSuccessful(), problems

"""Regression tests for counts of mid-circuit measurements in one-shot mode."""

import numpy as np
import pytest

import pennylane as qml


def _counts_with_python_int_values(counts):
    """Convert scalar/array count values to Python ints without changing the keys."""
    return {outcome: int(count) for outcome, count in counts.items()}


def _assert_integer_outcome_keys(counts):
    """MCM outcomes should use integer keys, as they do with deferred measurements."""
    assert all(
        isinstance(outcome, (int, np.integer))
        and not isinstance(outcome, (bool, np.bool_))
        for outcome in counts
    )


@pytest.mark.parametrize("mcm_method", ["deferred", "one-shot"])
@pytest.mark.parametrize("start_in_one", [False, True])
def test_single_mcm_counts_include_all_outcomes(mcm_method, start_in_one):
    """all_outcomes=True must include unobserved outcomes and use integer keys."""
    shots = 10
    dev = qml.device("default.qubit", wires=1, shots=shots)

    @qml.qnode(dev, mcm_method=mcm_method)
    def circuit():
        if start_in_one:
            qml.X(0)
        m = qml.measure(0)
        return qml.counts(m, all_outcomes=True)

    result = circuit()

    _assert_integer_outcome_keys(result)
    expected = {0: 0, 1: shots} if start_in_one else {0: shots, 1: 0}
    assert _counts_with_python_int_values(result) == expected


@pytest.mark.parametrize("start_in_one", [False, True])
def test_one_shot_single_mcm_counts_without_all_outcomes(start_in_one):
    """Requesting only observed outcomes must still omit the zero-count outcome."""
    shots = 10
    dev = qml.device("default.qubit", wires=1, shots=shots)

    @qml.qnode(dev, mcm_method="one-shot")
    def circuit():
        if start_in_one:
            qml.X(0)
        m = qml.measure(0)
        return qml.counts(m, all_outcomes=False)

    result = circuit()

    _assert_integer_outcome_keys(result)
    observed = int(start_in_one)
    assert _counts_with_python_int_values(result) == {observed: shots}


@pytest.mark.parametrize("mcm_method", ["deferred", "one-shot"])
def test_counts_of_mcm_sequence_include_all_bitstrings(mcm_method):
    """A sequence of MCMs has bitstring outcomes, all of which must be returned."""
    shots = 8
    dev = qml.device("default.qubit", wires=2, shots=shots)

    @qml.qnode(dev, mcm_method=mcm_method)
    def circuit():
        qml.X(1)
        m0 = qml.measure(0)
        m1 = qml.measure(1)
        return qml.counts([m0, m1], all_outcomes=True)

    result = circuit()

    assert all(isinstance(outcome, str) for outcome in result)
    assert _counts_with_python_int_values(result) == {
        "00": 0,
        "01": shots,
        "10": 0,
        "11": 0,
    }


def test_one_shot_counts_of_arithmetic_mcm_include_all_outcomes():
    """All outcomes of a processed MeasurementValue, not just 0 and 1, are included."""
    shots = 6
    dev = qml.device("default.qubit", wires=1, shots=shots)

    @qml.qnode(dev, mcm_method="one-shot")
    def circuit():
        m = qml.measure(0)
        return qml.counts(2 * m, all_outcomes=True)

    result = circuit()

    _assert_integer_outcome_keys(result)
    assert _counts_with_python_int_values(result) == {0: shots, 2: 0}


def test_one_shot_mcm_counts_all_outcomes_with_shot_vector():
    """Every shot-vector partition independently contains the complete outcome set."""
    shot_partitions = (3, 5)
    dev = qml.device("default.qubit", wires=1, shots=list(shot_partitions))

    @qml.qnode(dev, mcm_method="one-shot")
    def circuit():
        m = qml.measure(0)
        return qml.counts(m, all_outcomes=True)

    results = circuit()

    assert isinstance(results, tuple)
    assert len(results) == len(shot_partitions)
    for shots, result in zip(shot_partitions, results):
        _assert_integer_outcome_keys(result)
        assert _counts_with_python_int_values(result) == {0: shots, 1: 0}


def test_one_shot_mcm_counts_all_outcomes_with_postselection():
    """Adding unobserved outcomes must not alter counts from valid postselected shots."""
    shots = 6
    dev = qml.device("default.qubit", wires=1, shots=shots)

    @qml.qnode(dev, mcm_method="one-shot")
    def circuit():
        qml.X(0)
        m = qml.measure(0, postselect=1)
        return qml.counts(m, all_outcomes=True)

    result = circuit()

    _assert_integer_outcome_keys(result)
    assert _counts_with_python_int_values(result) == {0: 0, 1: shots}


def test_one_shot_terminal_wire_counts_are_unchanged():
    """MCM outcome handling must not add numeric outcomes to wire-based counts."""
    shots = 7
    dev = qml.device("default.qubit", wires=1, shots=shots)

    @qml.qnode(dev, mcm_method="one-shot")
    def circuit():
        _ = qml.measure(0)
        return qml.counts(wires=0, all_outcomes=True)

    result = circuit()

    assert _counts_with_python_int_values(result) == {"0": shots, "1": 0}

import re

import pytest
import yaml

from nomenclature.codelist import RegionCodeList


def _write_regions(path, regions, hierarchy="common"):
    """Write regions using the hierarchy-based region-codelist YAML format."""
    path.write_text(
        yaml.safe_dump([{hierarchy: regions}], sort_keys=False),
        encoding="utf-8",
    )


def test_region_codelist_collects_validation_errors_within_one_file(tmp_path):
    """One invalid region must not hide validation problems in later regions."""
    _write_regions(
        tmp_path / "regions.yaml",
        [
            {
                "Region with invalid countries": {
                    "countries": ["Austria", "Not a standard country"]
                }
            },
            {
                "Region with invalid ISO3 codes": {
                    "iso3_codes": ["AUT", "AUTT", "ZZZ"]
                }
            },
        ],
    )

    with pytest.raises(ValueError) as exc_info:
        RegionCodeList.from_directory("region", tmp_path)

    message = str(exc_info.value)

    # Both region-validation failures are reported through ErrorCollector.
    assert re.search(r"Collected 2 errors\b", message)
    assert (
        "Region 'Region with invalid countries' uses non-standard country name(s):"
        in message
    )
    assert "Not a standard country" in message
    assert (
        "Region 'Region with invalid ISO3 codes' has invalid ISO3 country code(s):"
        in message
    )
    # All invalid codes in the second region remain part of its error report.
    assert "AUTT" in message
    assert "ZZZ" in message


def test_region_codelist_collects_validation_errors_across_files(tmp_path):
    """Parsing continues after an invalid region file so other errors are visible."""
    _write_regions(
        tmp_path / "first.yaml",
        [
            {
                "First broken region": {
                    "countries": ["Another non-standard country"]
                }
            }
        ],
    )
    _write_regions(
        tmp_path / "second.yaml",
        [{"Second broken region": {"iso3_codes": "NOPE"}}],
    )

    with pytest.raises(ValueError) as exc_info:
        RegionCodeList.from_directory("region", tmp_path)

    message = str(exc_info.value)
    assert re.search(r"Collected 2 errors\b", message)
    assert "First broken region" in message
    assert "Another non-standard country" in message
    assert "Second broken region" in message
    assert "invalid ISO3 country code(s): NOPE" in message


def test_region_codelist_single_validation_error_uses_error_collection(tmp_path):
    """A single failure retains its descriptive message in the collection."""
    _write_regions(
        tmp_path / "regions.yaml",
        [{"Austria": {"iso3_codes": "AUTT"}}],
    )

    with pytest.raises(ValueError) as exc_info:
        RegionCodeList.from_directory("region", tmp_path)

    message = str(exc_info.value)
    assert re.search(r"Collected 1 error\b", message)
    assert "Region 'Austria' has invalid ISO3 country code(s): AUTT" in message


def test_region_codelist_accepts_valid_countries_and_iso3_codes(tmp_path):
    """Error collection must not reject valid country names or ISO3 codes."""
    _write_regions(
        tmp_path / "regions.yaml",
        [
            {"Austria": {"countries": ["Austria"], "iso3_codes": "AUT"}},
            {
                "Scandinavia": {
                    "countries": ["Norway", "Sweden"],
                    "iso3_codes": ["NOR", "SWE"],
                }
            },
        ],
    )

    codelist = RegionCodeList.from_directory("region", tmp_path)

    assert set(codelist.mapping) == {"Austria", "Scandinavia"}
    assert codelist["Austria"].countries == ["Austria"]
    assert codelist["Austria"].iso3_codes == "AUT"
    assert codelist["Scandinavia"].iso3_codes == ["NOR", "SWE"]

