"""Regression tests for required semicolons after C++20 concept definitions."""

import cpplint


REDUNDANT_SEMICOLON_MESSAGE = "You don't need a ; after a }"


def _lint(source):
    """Return line numbers for redundant-semicolon readability/braces errors."""
    error_lines = []

    def collect_error(filename, linenum, category, confidence, message):
        if (
            category == "readability/braces"
            and message == REDUNDANT_SEMICOLON_MESSAGE
        ):
            error_lines.append(linenum)

    cpplint.ProcessFileData(
        "concept_test.cc", "cc", source.splitlines(), collect_error
    )
    return error_lines


def test_reported_concept_definition_does_not_warn():
    source = """\
template <typename T>
concept IndexableToChar = requires(T t) {
  { t[0] } -> std::convertible_to<char>;
};
"""
    assert _lint(source) == []


def test_single_line_concept_definition_does_not_warn():
    source = """\
template <typename T>
concept HasFoo = requires(T t) { t.foo(); };
"""
    assert _lint(source) == []


def test_multiline_requires_parameter_list_does_not_warn():
    # A requires-expression's opening brace may be arbitrarily far from the
    # concept declaration. Recognition must not use a fixed-size line window.
    parameters = [f"    T t{i}," for i in range(12)]
    parameters.append("    T t12) {")
    source = "\n".join(
        [
            "template <typename T>",
            "concept HasFoo = requires(",
            *parameters,
            "  t0.foo();",
            "};",
            "",
        ]
    )
    assert _lint(source) == []


def test_nearby_concept_does_not_hide_redundant_function_semicolon():
    source = """\
template <typename T>
concept HasFoo = requires(T t) {
  t.foo();
};

void FunctionWithRedundantSemicolon() {
};
"""
    # Only the function's unnecessary semicolon on line 7 should be reported.
    assert _lint(source) == [7]


def test_redundant_function_semicolon_is_still_reported():
    source = """\
void FunctionWithRedundantSemicolon() {
};
"""
    assert _lint(source) == [2]

import pytest

from markdownify import markdownify as md


NEWLINE = chr(10)
BACKTICK = chr(96)
FENCE = BACKTICK * 3


def inline_code(text):
    return BACKTICK + text + BACKTICK


def fenced(text):
    return NEWLINE.join(("", FENCE, text, FENCE, ""))


@pytest.mark.parametrize("tag", ["code", "kbd", "samp"])
def test_anchor_inside_inline_code_like_tag_renders_only_its_text(tag):
    html = "<{0}><a href='http://foo.com/'>foo.com</a></{0}>".format(tag)

    assert md(html) == inline_code("foo.com")


def test_anchor_inside_pre_renders_only_its_text():
    html = "<pre><a href='http://foo.com/'>foo.com</a></pre>"

    assert md(html) == fenced("foo.com")


def test_anchor_inside_code_nested_in_pre_renders_only_its_text():
    html = "<pre><code><a href='http://foo.com/'>foo.com</a></code></pre>"

    assert md(html) == fenced("foo.com")


@pytest.mark.parametrize(
    "wrapper, expected",
    [
        ("code", inline_code("Visit Example now")),
        ("pre", fenced("Visit Example now")),
    ],
)
def test_anchor_text_is_inlined_without_html_or_markdown_link_syntax(
    wrapper, expected
):
    html = (
        "<{0}>Visit <a href='https://example.com/' title='Example site'>"
        "Example</a> now</{0}>"
    ).format(wrapper)

    result = md(html)

    assert result == expected
    assert "<a" not in result
    assert "](https://example.com/)" not in result


def test_anchor_without_href_inside_code_is_also_plain_text():
    assert md("<code><a>foo.com</a></code>") == inline_code("foo.com")


def test_nested_formatting_inside_anchor_in_code_remains_literal_text():
    html = (
        "<code><a href='https://example.com/'>"
        "<strong>Example</strong></a></code>"
    )

    assert md(html) == inline_code("Example")


@pytest.mark.parametrize(
    "options",
    [
        {"autolinks": False},
        {"default_title": True},
    ],
)
def test_link_options_do_not_create_links_inside_code(options):
    html = "<code><a href='http://foo.com/'>foo.com</a></code>"

    assert md(html, **options) == inline_code("foo.com")


def test_anchors_outside_preformatted_content_keep_normal_conversion():
    html = (
        "<code><a href='https://example.com/'>inside</a></code> and "
        "<a href='https://example.com/' title='Example'>outside</a>"
    )

    assert md(html) == (
        inline_code("inside")
        + ' and [outside](https://example.com/ "Example")'
    )

