from __future__ import annotations

import ast
import os
import subprocess
import sys
from pathlib import Path

import pytest


ROOT = Path(__file__).resolve().parents[1]
FIXTURES = ROOT / "tests" / "fixtures"


def _generate_wsdl(tmp_path: Path, wsdl: Path) -> dict[str, str]:
    """Generate kw-only models and return their sources by filename."""
    env = os.environ.copy()
    env["PYTHONPATH"] = os.pathsep.join(
        filter(None, [str(ROOT), env.get("PYTHONPATH")])
    )
    result = subprocess.run(
        [
            sys.executable,
            "-m",
            "xsdata",
            str(wsdl),
            "--package",
            "generated",
            "--kw-only",
        ],
        cwd=tmp_path,
        env=env,
        capture_output=True,
        text=True,
        timeout=60,
    )
    assert result.returncode == 0, result.stdout + result.stderr

    package = tmp_path / "generated"
    return {
        path.name: path.read_text(encoding="utf-8")
        for path in package.glob("*.py")
    }


def _field(class_def: ast.ClassDef, name: str) -> ast.AnnAssign | None:
    for statement in class_def.body:
        if (
            isinstance(statement, ast.AnnAssign)
            and isinstance(statement.target, ast.Name)
            and statement.target.id == name
        ):
            return statement
    return None


def _soap_fault_fields(source: str) -> list[tuple[ast.ClassDef, ast.AnnAssign]]:
    tree = ast.parse(source)
    result = []
    for node in ast.walk(tree):
        if isinstance(node, ast.ClassDef) and node.name == "Body":
            fault = _field(node, "fault")
            if fault is not None:
                result.append((node, fault))
    return result


def _is_optional(annotation: ast.AST) -> bool:
    if (
        isinstance(annotation, ast.Subscript)
        and isinstance(annotation.value, ast.Name)
        and annotation.value.id == "Optional"
    ):
        return True

    if isinstance(annotation, ast.BinOp) and isinstance(annotation.op, ast.BitOr):
        return any(
            isinstance(side, ast.Constant) and side.value is None
            for side in (annotation.left, annotation.right)
        )

    return False


def _has_none_default(field: ast.AnnAssign) -> bool:
    return (
        isinstance(field.value, ast.Call)
        and any(
            keyword.arg == "default"
            and isinstance(keyword.value, ast.Constant)
            and keyword.value.value is None
            for keyword in field.value.keywords
        )
    )


def _is_kw_only(class_def: ast.ClassDef) -> bool:
    for decorator in class_def.decorator_list:
        if isinstance(decorator, ast.Call) and any(
            keyword.arg == "kw_only"
            and isinstance(keyword.value, ast.Constant)
            and keyword.value.value is True
            for keyword in decorator.keywords
        ):
            return True
    return False


def _contains_kw_only_class(source: str) -> bool:
    return any(
        isinstance(node, ast.ClassDef) and _is_kw_only(node)
        for node in ast.walk(ast.parse(source))
    )


@pytest.mark.parametrize(
    ("wsdl", "module"),
    [
        (FIXTURES / "calculator" / "services.wsdl", "services.py"),
        # This service declares operation-specific faults in addition to the
        # generic SOAP fault, covering the other envelope-generation path.
        (FIXTURES / "hello" / "hello.wsdl", "hello.py"),
    ],
    ids=["generic-soap-fault", "declared-operation-faults"],
)
def test_kw_only_soap_body_fault_is_optional(tmp_path, wsdl, module):
    sources = _generate_wsdl(tmp_path, wsdl)
    assert module in sources

    source = sources[module]
    # Ensure this test cannot pass merely because kw-only generation was
    # disabled or ignored. Nested envelope classes do not necessarily repeat
    # every decorator argument used by their containing classes.
    assert _contains_kw_only_class(source)

    fault_fields = _soap_fault_fields(source)
    assert fault_fields, "The fixture did not generate any SOAP Body fault fields"

    for _body, fault in fault_fields:
        assert _is_optional(fault.annotation), ast.get_source_segment(source, fault)
        assert _has_none_default(fault), ast.get_source_segment(source, fault)


def test_kw_only_generation_still_keeps_required_schema_fields_required(tmp_path):
    sources = _generate_wsdl(
        tmp_path, FIXTURES / "calculator" / "services.wsdl"
    )

    add_response = next(
        (
            node
            for source in sources.values()
            for node in ast.walk(ast.parse(source))
            if isinstance(node, ast.ClassDef) and node.name == "AddResponse"
        ),
        None,
    )
    assert add_response is not None

    add_result = _field(add_response, "add_result")
    assert add_result is not None

    # Making every attribute optional would hide the SOAP fault regression,
    # but would also incorrectly weaken ordinary schema-required fields.
    assert not _is_optional(add_result.annotation)
    assert not _has_none_default(add_result)

"""Regression tests for counts of mid-circuit measurements in one-shot mode."""

from numbers import Integral

import numpy as np
import pytest

import pennylane as qml


def _counts_with_python_int_values(counts):
    """Convert scalar count values to Python ints without changing the outcome keys."""
    return {key: int(np.asarray(value)) for key, value in counts.items()}


def _assert_integer_keys(counts):
    """MCM outcomes are integers, not their floating-point representations."""
    assert all(isinstance(key, Integral) for key in counts)


@pytest.mark.parametrize("shots", [1, 10])
@pytest.mark.parametrize(
    "flip, expected_observed_outcome",
    [(False, 0), (True, 1)],
)
def test_one_shot_single_mcm_returns_all_outcomes(shots, flip, expected_observed_outcome):
    """All binary outcomes must be present, including an outcome with zero counts."""
    dev = qml.device("default.qubit", wires=1, shots=shots, seed=123)

    @qml.qnode(dev, mcm_method="one-shot")
    def circuit():
        if flip:
            qml.X(0)
        m = qml.measure(0)
        return qml.counts(m, all_outcomes=True)

    result = circuit()

    assert set(result) == {0, 1}
    _assert_integer_keys(result)

    expected = {0: 0, 1: 0}
    expected[expected_observed_outcome] = shots
    assert _counts_with_python_int_values(result) == expected


@pytest.mark.parametrize(
    "flip, expected",
    [(False, {0: 10}), (True, {1: 10})],
)
def test_one_shot_single_mcm_without_all_outcomes(flip, expected):
    """Requesting only observed outcomes must not add zero-count outcomes."""
    dev = qml.device("default.qubit", wires=1, shots=10, seed=123)

    @qml.qnode(dev, mcm_method="one-shot")
    def circuit():
        if flip:
            qml.X(0)
        m = qml.measure(0)
        return qml.counts(m, all_outcomes=False)

    result = circuit()

    assert set(result) == set(expected)
    _assert_integer_keys(result)
    assert _counts_with_python_int_values(result) == expected


def test_one_shot_single_mcm_superposition_counts():
    """Observed counts must be preserved when both binary outcomes occur."""
    shots = 256
    dev = qml.device("default.qubit", wires=1, shots=shots, seed=42)

    @qml.qnode(dev, mcm_method="one-shot")
    def circuit():
        qml.Hadamard(0)
        m = qml.measure(0)
        return qml.counts(m, all_outcomes=True)

    result = circuit()

    assert set(result) == {0, 1}
    _assert_integer_keys(result)
    counts = _counts_with_python_int_values(result)
    assert sum(counts.values()) == shots
    assert counts[0] > 0
    assert counts[1] > 0


def test_one_shot_single_mcm_all_outcomes_with_shot_vector():
    """Each shot-vector bin must independently contain all outcomes."""
    shots = [5, 7]
    dev = qml.device("default.qubit", wires=1, shots=shots, seed=123)

    @qml.qnode(dev, mcm_method="one-shot")
    def circuit():
        m = qml.measure(0)
        return qml.counts(m, all_outcomes=True)

    results = circuit()

    assert isinstance(results, tuple)
    assert len(results) == len(shots)
    for result, shot_bin in zip(results, shots):
        assert set(result) == {0, 1}
        _assert_integer_keys(result)
        assert _counts_with_python_int_values(result) == {0: shot_bin, 1: 0}


def test_one_shot_multiple_mcms_returns_all_bitstring_outcomes():
    """Sequences of MCMs must return every bitstring without mixing key types."""
    shots = 12
    dev = qml.device("default.qubit", wires=2, shots=shots, seed=123)

    @qml.qnode(dev, mcm_method="one-shot")
    def circuit():
        m0 = qml.measure(0)
        m1 = qml.measure(1)
        return qml.counts([m0, m1], all_outcomes=True)

    result = circuit()

    expected = {"00": shots, "01": 0, "10": 0, "11": 0}
    assert set(result) == set(expected)
    assert all(isinstance(key, str) for key in result)
    assert _counts_with_python_int_values(result) == expected


def test_one_shot_composite_mcm_returns_all_outcomes():
    """All outcomes of an arithmetic measurement value must be included."""
    shots = 12
    dev = qml.device("default.qubit", wires=2, shots=shots, seed=123)

    @qml.qnode(dev, mcm_method="one-shot")
    def circuit():
        m0 = qml.measure(0)
        m1 = qml.measure(1)
        return qml.counts(m0 + 2 * m1, all_outcomes=True)

    result = circuit()

    assert set(result) == {0, 1, 2, 3}
    _assert_integer_keys(result)
    assert _counts_with_python_int_values(result) == {0: shots, 1: 0, 2: 0, 3: 0}

import io
import json
import re
from urllib.parse import parse_qs

import pytest

from nix_auto_follow.cli import Node, start


def assert_git_url(actual: str, original_url: str, expected_query: dict) -> None:
    """Compare git flake URLs without depending on query-parameter ordering."""
    base, separator, query = actual.partition("?")
    assert base == f"git+{original_url}"
    assert parse_qs(query, keep_blank_values=True) == expected_query
    assert bool(separator) == bool(expected_query)


@pytest.mark.parametrize(
    "original, original_url, expected_query",
    [
        pytest.param(
            {
                "type": "git",
                "url": "https://github.com/SuperSandro2000/nixpkgs.git",
                "ref": "nixos-unstable",
                "shallow": True,
            },
            "https://github.com/SuperSandro2000/nixpkgs.git",
            {"ref": ["nixos-unstable"], "shallow": ["1"]},
            id="issue-example",
        ),
        pytest.param(
            {
                "type": "git",
                "url": "https://github.com/NixOS/patchelf",
                "ref": "master",
                "rev": "f34751b88bd07d7f44f5cd3200fb4122bf916c7e",
            },
            "https://github.com/NixOS/patchelf",
            {
                "ref": ["master"],
                "rev": ["f34751b88bd07d7f44f5cd3200fb4122bf916c7e"],
            },
            id="ref-and-rev",
        ),
        pytest.param(
            {
                "type": "git",
                "url": "ssh://git@github.com/NixOS/nixpkgs.git",
                "rev": "0123456789abcdef0123456789abcdef01234567",
            },
            "ssh://git@github.com/NixOS/nixpkgs.git",
            {"rev": ["0123456789abcdef0123456789abcdef01234567"]},
            id="ssh-rev-only",
        ),
        pytest.param(
            {
                "type": "git",
                "url": "https://github.com/example/repo.git",
            },
            "https://github.com/example/repo.git",
            {},
            id="no-options",
        ),
        pytest.param(
            {
                "type": "git",
                "url": "https://example.org/repo.git",
                "ref": "feature/nix-support",
                "shallow": True,
                "submodules": True,
                "allRefs": True,
            },
            "https://example.org/repo.git",
            {
                "ref": ["feature/nix-support"],
                "shallow": ["1"],
                "submodules": ["1"],
                "allRefs": ["1"],
            },
            id="git-boolean-options",
        ),
    ],
)
def test_get_url_supports_git_flakes(
    original: dict, original_url: str, expected_query: dict
) -> None:
    node = Node.from_dict({"original": original})

    assert_git_url(node.get_url(), original_url, expected_query)


def test_check_mode_reports_git_urls_instead_of_raising(capsys) -> None:
    """Exercise the conflicting-input path from the issue through the CLI."""
    unstable_url = "https://github.com/SuperSandro2000/nixpkgs.git"
    lock_data = {
        "root": "root",
        "version": 7,
        "nodes": {
            "root": {"inputs": {"a": "a", "b": "b"}},
            "a": {"inputs": {"nixpkgs": "nixpkgs_unstable"}},
            "b": {"inputs": {"nixpkgs": "nixpkgs_stable"}},
            "nixpkgs_unstable": {
                "original": {
                    "type": "git",
                    "url": unstable_url,
                    "ref": "nixos-unstable",
                    "shallow": True,
                },
                "locked": {
                    "type": "git",
                    "url": unstable_url,
                    "ref": "nixos-unstable",
                    "rev": "0123456789abcdef0123456789abcdef01234567",
                    "shallow": True,
                },
            },
            "nixpkgs_stable": {
                "original": {
                    "type": "git",
                    "url": unstable_url,
                    "ref": "nixos-24.05",
                },
                "locked": {
                    "type": "git",
                    "url": unstable_url,
                    "ref": "nixos-24.05",
                    "rev": "fedcba9876543210fedcba9876543210fedcba98",
                },
            },
        },
    }

    with pytest.raises(SystemExit) as exc_info:
        start(
            args=["--check", "-"],
            stdin=io.StringIO(json.dumps(lock_data)),
            stdout=io.StringIO(),
        )

    assert exc_info.value.code == 1
    output = capsys.readouterr().out
    assert "Node a has input nixpkgs" in output

    suggested_urls = re.findall(r"nixpkgs[.]url = \"([^\"']+)", output)
    assert len(suggested_urls) == 2
    assert_git_url(
        suggested_urls[0],
        unstable_url,
        {"ref": ["nixos-unstable"], "shallow": ["1"]},
    )
    assert_git_url(
        suggested_urls[1],
        unstable_url,
        {"ref": ["nixos-24.05"]},
    )

import pytest

from markdownify import markdownify as md


NEWLINE = chr(10)
FENCE = chr(96) * 3


def fenced(text):
    return NEWLINE + FENCE + NEWLINE + text + NEWLINE + FENCE + NEWLINE


def test_link_inside_code_is_rendered_as_plain_text():
    html = "<code><a href='http://foo.com/'>foo.com</a></code>"
    assert md(html) == "`foo.com`"


def test_link_inside_pre_is_rendered_as_plain_text():
    html = "<pre><a href='http://foo.com/'>foo.com</a></pre>"
    assert md(html) == fenced("foo.com")


@pytest.mark.parametrize("tag", ["code", "kbd", "samp"])
def test_links_inside_inline_code_elements_keep_only_their_text(tag):
    html = (
        "<{tag}>before <a href='https://example.com/' title='Example'>"
        "linked text</a> after</{tag}>"
    ).format(tag=tag)
    assert md(html) == "`before linked text after`"


def test_link_inside_nested_pre_and_code_is_plain_text():
    html = (
        "<pre><code><a href='https://example.com/' title='Example'>"
        "example</a></code></pre>"
    )
    assert md(html) == fenced("example")


def test_multiple_and_hrefless_links_inside_code_are_plain_text():
    html = (
        "<code>one <a href='/two'>two</a> three "
        "<a>four</a> <a href='/five'>five</a></code>"
    )
    assert md(html) == "`one two three four five`"


@pytest.mark.parametrize(
    "options",
    [
        {},
        {"autolinks": False},
        {"default_title": True},
    ],
)
def test_code_link_text_is_plain_regardless_of_link_options(options):
    html = "<code><a href='https://example.com/'>https://example.com/</a></code>"
    assert md(html, **options) == "`https://example.com/`"


def test_empty_link_inside_code_does_not_emit_html_or_markdown():
    html = "<code><a href='https://example.com/'></a></code>"
    assert md(html) == ""


def test_link_contents_inside_code_remain_literal_text():
    html = "<code><a href='https://example.com/'>*literal* _text_</a></code>"
    assert md(html) == "`*literal* _text_`"


def test_normal_link_conversion_outside_code_is_unchanged():
    assert md("<a href='http://foo.com/'>foo.com</a>") == (
        "[foo.com](http://foo.com/)"
    )
    assert md("<a href='https://example.com/'>https://example.com/</a>") == (
        "<https://example.com/>"
    )
    assert md(
        "<a href='https://example.com/' title='Example'>label</a>"
    ) == '[label](https://example.com/ "Example")'

import subprocess
import sys
import textwrap
from pathlib import Path

import pytest


ROOT = Path(__file__).resolve().parent
CPPLINT = ROOT / "cpplint.py"
SEMICOLON_WARNING = "You don't need a ; after a }"


def lint_braces(source, tmp_path):
    """Run cpplint through its CLI, keeping only readability/braces output."""
    source_file = tmp_path / "concept_test.cc"
    source_file.write_text(
        "// Copyright 2025 Example\n"
        + textwrap.dedent(source).strip()
        + "\n",
        encoding="utf-8",
    )

    result = subprocess.run(
        [
            sys.executable,
            str(CPPLINT),
            "--filter=-,+readability/braces",
            str(source_file),
        ],
        cwd=ROOT,
        capture_output=True,
        text=True,
        check=False,
    )
    output = result.stdout + result.stderr
    assert result.returncode in (0, 1), output
    return output


def test_reported_concept_requires_expression_keeps_required_semicolon(tmp_path):
    output = lint_braces(
        """
        template <typename T>
        concept IndexableToChar = requires(T t) {
          { t[0] } -> std::convertible_to<char>;
        };
        """,
        tmp_path,
    )

    assert SEMICOLON_WARNING not in output, output


@pytest.mark.parametrize(
    "source",
    [
        pytest.param(
            """
            template <typename T>
            concept IndexableToChar
                = requires(T t) {
              { t[0] } -> std::convertible_to<char>;
            };
            """,
            id="equals-on-next-line",
        ),
        pytest.param(
            """
            template <typename T>
            concept IndexableToChar = requires(T t)
            {
              { t[0] } -> std::convertible_to<char>;
            };
            """,
            id="brace-on-next-line",
        ),
    ],
)
def test_concept_layout_does_not_change_semicolon_requirement(source, tmp_path):
    # Splitting the concept-definition before its equals sign is valid C++ and
    # must not make the required trailing semicolon look redundant.
    output = lint_braces(source, tmp_path)
    assert SEMICOLON_WARNING not in output, output


def test_concept_with_long_multiline_header_keeps_required_semicolon(tmp_path):
    # Whitespace and comments are permitted between the requires-parameter-list
    # and the requires-expression body. Detection must not depend on the concept
    # keyword being only a few lines away from the opening brace.
    explanatory_comments = "\n".join(
        f"    // Requirement explanation {number}" for number in range(12)
    )
    source = (
        "template <typename T>\n"
        "concept IndexableToChar =\n"
        "    requires(T t)\n"
        f"{explanatory_comments}\n"
        "{\n"
        "  { t[0] } -> std::convertible_to<char>;\n"
        "};\n"
    )

    output = lint_braces(source, tmp_path)
    assert SEMICOLON_WARNING not in output, output


def test_concept_with_long_body_keeps_required_semicolon(tmp_path):
    requirements = "\n".join(
        "  { t[0] } -> std::convertible_to<char>;" for _ in range(15)
    )
    source = (
        "template <typename T>\n"
        "concept IndexableToChar = requires(T t) {\n"
        f"{requirements}\n"
        "};\n"
    )

    output = lint_braces(source, tmp_path)
    assert SEMICOLON_WARNING not in output, output


def test_ordinary_redundant_semicolon_is_still_reported(tmp_path):
    output = lint_braces(
        """
        void Function() {
        };
        """,
        tmp_path,
    )

    assert output.count(SEMICOLON_WARNING) == 1, output


@pytest.mark.parametrize(
    "source",
    [
        pytest.param(
            """
            void Function() {
            };
            concept AlwaysTrue = true;
            """,
            id="concept-after-function",
        ),
        pytest.param(
            """
            template <typename T>
            concept IndexableToChar = requires(T t) {
              { t[0] } -> std::convertible_to<char>;
            };

            void Function() {
            };
            """,
            id="concept-before-function",
        ),
    ],
)
def test_nearby_concept_does_not_hide_unrelated_redundant_semicolon(
    source, tmp_path
):
    # Only the function's semicolon is redundant. A concept elsewhere in the
    # file must not disable the check for unrelated braces. The multiline
    # function form is used because this check does not diagnose `{};` when
    # the entire function definition is on one line.
    output = lint_braces(source, tmp_path)
    assert output.count(SEMICOLON_WARNING) == 1, output

"""Regression tests for nullable nested schemas in OpenAPI 3.0."""

import pytest
from apispec import APISpec
from apispec.ext.marshmallow import MarshmallowPlugin
from marshmallow import Schema, fields


class NullableRefTargetSchema(Schema):
    bar = fields.Integer(required=True)


class NullableRefContainerSchema(Schema):
    foo = fields.Nested(NullableRefTargetSchema, allow_none=True)


class DescribedNullableRefContainerSchema(Schema):
    foo = fields.Nested(
        NullableRefTargetSchema,
        allow_none=True,
        metadata={"description": "A nullable foo"},
    )


class NullableManyRefContainerSchema(Schema):
    foo = fields.Nested(NullableRefTargetSchema, many=True, allow_none=True)


class NullableScalarContainerSchema(Schema):
    foo = fields.String(allow_none=True)


class ListOfNullableRefContainerSchema(Schema):
    foo = fields.List(fields.Nested(NullableRefTargetSchema, allow_none=True))


def _build_property(openapi_version, container_schema, field_name="foo"):
    spec = APISpec(
        title="Nullable nested schema test",
        version="1.0.0",
        openapi_version=openapi_version,
        plugins=[MarshmallowPlugin()],
    )
    spec.components.schema("NullableRefTarget", schema=NullableRefTargetSchema)
    spec.components.schema("Container", schema=container_schema)

    document = spec.to_dict()
    if "components" in document:
        schemas = document["components"]["schemas"]
    else:
        schemas = document["definitions"]
    return schemas["Container"]["properties"][field_name]


def _reference(openapi_version):
    if openapi_version.startswith("2."):
        return "#/definitions/NullableRefTarget"
    return "#/components/schemas/NullableRefTarget"


def _assert_openapi_30_nullable_reference(prop, reference):
    """Check the OpenAPI 3.0-compatible nullable reference representation.

    OpenAPI 3.0 does not support {"type": "null"}. The null alternative must
    instead have a type assertion alongside nullable: true.
    """
    assert "nullable" not in prop
    assert "allOf" not in prop
    assert "$ref" not in prop

    alternatives = prop["anyOf"]
    assert len(alternatives) == 2
    assert {"$ref": reference} in alternatives
    assert {"type": "object", "nullable": True} in alternatives
    assert {"type": "null"} not in alternatives


@pytest.mark.parametrize("openapi_version", ["3.0.0", "3.0.3"])
def test_nested_allow_none_uses_openapi_30_nullable_anyof(openapi_version):
    prop = _build_property(openapi_version, NullableRefContainerSchema)

    assert set(prop) == {"anyOf"}
    _assert_openapi_30_nullable_reference(prop, _reference(openapi_version))


def test_nested_allow_none_with_metadata_does_not_leave_nullable_allof():
    prop = _build_property("3.0.3", DescribedNullableRefContainerSchema)

    assert set(prop) == {"anyOf", "description"}
    assert prop["description"] == "A nullable foo"
    _assert_openapi_30_nullable_reference(prop, _reference("3.0.3"))


def test_nullable_nested_schema_inside_list_uses_same_representation():
    prop = _build_property("3.0.3", ListOfNullableRefContainerSchema)

    assert set(prop) == {"type", "items"}
    assert prop["type"] == "array"
    assert set(prop["items"]) == {"anyOf"}
    _assert_openapi_30_nullable_reference(prop["items"], _reference("3.0.3"))


def test_nullable_nested_many_field_keeps_nullable_array_type():
    """A many=True nested field already has a type in the same schema object."""
    prop = _build_property("3.0.3", NullableManyRefContainerSchema)

    assert prop == {
        "type": "array",
        "items": {"$ref": _reference("3.0.3")},
        "nullable": True,
    }


def test_nullable_scalar_field_keeps_regular_openapi_30_nullable():
    """The reference workaround must not change ordinary nullable fields."""
    prop = _build_property("3.0.3", NullableScalarContainerSchema)

    assert prop == {"type": "string", "nullable": True}


def test_openapi_31_nullable_nested_representation_is_unchanged():
    """The null type is valid in OpenAPI 3.1, unlike OpenAPI 3.0."""
    prop = _build_property("3.1.0", NullableRefContainerSchema)

    assert set(prop) == {"anyOf"}
    assert len(prop["anyOf"]) == 2
    assert {"$ref": _reference("3.1.0")} in prop["anyOf"]
    assert {"type": "null"} in prop["anyOf"]


def test_openapi_20_nullable_nested_representation_is_unchanged():
    prop = _build_property("2.0", NullableRefContainerSchema)

    assert prop == {
        "$ref": _reference("2.0"),
        "x-nullable": True,
    }

"""Regression tests for counts of mid-circuit measurements in one-shot mode."""

import numpy as np
import pytest

import pennylane as qml


def _assert_integer_outcome_keys(counts):
    """MCM outcomes are integers, not numerically equivalent float keys."""
    assert all(isinstance(key, (int, np.integer)) for key in counts)
    assert not any(isinstance(key, (float, np.floating)) for key in counts)


@pytest.mark.parametrize("mcm_method", ["deferred", "one-shot"])
@pytest.mark.parametrize("measured_value", [0, 1])
def test_single_mcm_counts_all_outcomes(mcm_method, measured_value):
    """All binary outcomes are returned, including outcomes with zero counts."""
    shots = 10
    dev = qml.device("default.qubit", wires=2, shots=shots)

    @qml.qnode(dev, mcm_method=mcm_method)
    def circuit():
        if measured_value:
            qml.PauliX(0)
        m = qml.measure(0)
        return qml.counts(m, all_outcomes=True)

    result = circuit()

    expected = {0: 0, 1: 0}
    expected[measured_value] = shots
    assert result == expected
    assert set(result) == {0, 1}
    assert sum(result.values()) == shots
    _assert_integer_outcome_keys(result)


def test_one_shot_single_mcm_counts_without_all_outcomes():
    """Requesting only observed outcomes must not add zero-count outcomes."""
    shots = 10
    dev = qml.device("default.qubit", wires=2, shots=shots)

    @qml.qnode(dev, mcm_method="one-shot")
    def circuit():
        m = qml.measure(0)
        return qml.counts(m)

    result = circuit()

    assert result == {0: shots}
    assert len(result) == 1
    _assert_integer_outcome_keys(result)


def test_one_shot_counts_sequence_containing_one_mcm():
    """A length-one MCM sequence has string outcomes and includes both outcomes."""
    shots = 6
    dev = qml.device("default.qubit", wires=2, shots=shots)

    @qml.qnode(dev, mcm_method="one-shot")
    def circuit():
        m = qml.measure(0)
        return qml.counts([m], all_outcomes=True)

    result = circuit()

    assert result == {"0": shots, "1": 0}
    assert all(isinstance(key, str) for key in result)


def test_one_shot_composite_mcm_counts_all_outcomes():
    """Counts of several MCMs include every bit string, in measurement order."""
    shots = 8
    dev = qml.device("default.qubit", wires=2, shots=shots)

    @qml.qnode(dev, mcm_method="one-shot")
    def circuit():
        # The ordered pair (m0, m1) therefore always has the outcome "01".
        qml.PauliX(1)
        m0 = qml.measure(0)
        m1 = qml.measure(1)
        return qml.counts([m0, m1], all_outcomes=True)

    result = circuit()

    assert result == {"00": 0, "01": shots, "10": 0, "11": 0}
    assert sum(result.values()) == shots
    assert all(isinstance(key, str) for key in result)


def test_one_shot_composite_mcm_counts_without_all_outcomes():
    """Composite MCM counts still omit unobserved bit strings by default."""
    shots = 8
    dev = qml.device("default.qubit", wires=2, shots=shots)

    @qml.qnode(dev, mcm_method="one-shot")
    def circuit():
        m0 = qml.measure(0)
        m1 = qml.measure(1)
        return qml.counts([m0, m1])

    result = circuit()

    assert result == {"00": shots}


def test_one_shot_mcm_counts_all_outcomes_with_shot_vector():
    """Every shot-vector partition independently receives the full outcome set."""
    dev = qml.device("default.qubit", wires=2, shots=[3, 5])

    @qml.qnode(dev, mcm_method="one-shot")
    def circuit():
        m = qml.measure(0)
        return qml.counts(m, all_outcomes=True)

    results = circuit()

    assert len(results) == 2
    for result, shots in zip(results, [3, 5]):
        assert result == {0: shots, 1: 0}
        _assert_integer_outcome_keys(result)


def test_regular_counts_all_outcomes_remain_unchanged():
    """The MCM fix must not alter ordinary computational-basis counts."""
    shots = 5
    dev = qml.device("default.qubit", wires=2, shots=shots)

    @qml.qnode(dev, mcm_method="one-shot")
    def circuit():
        return qml.counts(wires=[0, 1], all_outcomes=True)

    result = circuit()

    assert result == {"00": shots, "01": 0, "10": 0, "11": 0}
    assert all(isinstance(key, str) for key in result)

