def test_check_mode_reports_git_url_suggestions(capsys):
    """Exercise the check-mode path from the issue, not just URL formatting."""
    flake_lock = {
        "root": "root",
        "version": 7,
        "nodes": {
            "root": {"inputs": {"first": "first", "second": "second"}},
            "first": {"inputs": {"nixpkgs": "nixpkgs_git"}},
            "second": {"inputs": {"nixpkgs": "nixpkgs_other"}},
            "nixpkgs_git": {
                "original": {
                    "type": "git",
                    "url": "https://github.com/SuperSandro2000/nixpkgs.git",
                    "ref": "nixos-unstable",
                    "shallow": True,
                }
            },
            "nixpkgs_other": {
                "original": {
                    "type": "git",
                    "url": "https://github.com/NixOS/nixpkgs.git",
                    "ref": "nixos-24.05",
                }
            },
        },
    }

    with pytest.raises(SystemExit) as exc_info:
        start(
            args=["-", "--check"],
            stdin=io.StringIO(json.dumps(flake_lock)),
            stdout=io.StringIO(),
        )

    assert exc_info.value.code == 1
    output = capsys.readouterr().out

    # The suggested override must be a usable git flake URL and retain the
    # attributes from the original input, including shallow=1 from the issue.
    assert (
        'nixpkgs.url = "git+https://github.com/SuperSandro2000/'
        'nixpkgs.git?'
    ) in output
    assert "ref=nixos-unstable" in output
    assert "shallow=1" in output
    assert (
        "git+https://github.com/NixOS/nixpkgs.git?ref=nixos-24.05" in output
    )

import pytest

from markdownify import markdownify as md


CODE_FENCE = "`" * 3


def code_block(text):
    return "\n%s\n%s\n%s\n" % (CODE_FENCE, text, CODE_FENCE)


@pytest.mark.parametrize(
    "html, expected",
    [
        # The two examples from the issue: only the anchor's text should remain.
        (
            "<code><a href='http://foo.com/'>foo.com</a></code>",
            "`foo.com`",
        ),
        (
            "<pre><a href='http://foo.com/'>foo.com</a></pre>",
            code_block("foo.com"),
        ),
        # The anchor may be nested more deeply in the preformatted element.
        (
            "<pre><code><a href='http://foo.com/'>foo.com</a></code></pre>",
            code_block("foo.com"),
        ),
        # These elements use the same inline-code conversion as <code>.
        (
            "<kbd><a href='http://foo.com/'>foo.com</a></kbd>",
            "`foo.com`",
        ),
        (
            "<samp><a href='http://foo.com/'>foo.com</a></samp>",
            "`foo.com`",
        ),
    ],
)
def test_anchor_inside_preformatted_element_is_plain_text(html, expected):
    assert md(html) == expected


def test_nested_anchor_attributes_do_not_produce_html_or_markdown_in_code():
    html = (
        '<code>before <span><a href="https://example.com" '
        'title="Example">link text</a></span> after</code>'
    )
    assert md(html) == "`before link text after`"


@pytest.mark.parametrize(
    "options",
    [
        {},
        {"autolinks": False},
        {"default_title": True},
    ],
)
def test_autolink_options_do_not_change_anchor_text_inside_code(options):
    html = '<code><a href="https://example.com">https://example.com</a></code>'
    assert md(html, **options) == "`https://example.com`"


def test_preformatted_text_around_anchor_is_preserved():
    html = (
        '<pre>first line\n'
        '<a href="https://example.com">second line</a> tail</pre>'
    )
    assert md(html) == code_block("first line\nsecond line tail")


def test_anchor_without_href_inside_code_is_also_plain_text():
    assert md("<code><a>plain text</a></code>") == "`plain text`"


def test_only_anchors_inside_preformatted_elements_are_affected():
    html = (
        '<code><a href="https://one.example">one</a></code> '
        '<a href="https://two.example" title="Two">two</a>'
    )
    assert md(html) == '`one` [two](https://two.example "Two")'

    # Ordinary autolink behavior must remain intact as well.
    assert (
        md('<a href="https://example.com">https://example.com</a>')
        == "<https://example.com>"
    )

