import pytest
from apispec import APISpec
from apispec.ext.marshmallow import MarshmallowPlugin
from marshmallow import Schema, fields


class FooSchema(Schema):
    bar = fields.Integer(required=True)


class MySchema(Schema):
    foo = fields.Nested(FooSchema, allow_none=True)


class NullableNestedMetadataSchema(Schema):
    foo = fields.Nested(
        FooSchema,
        allow_none=True,
        metadata={"description": "An optional Foo"},
    )


class NullableNestedListSchema(Schema):
    foo = fields.List(fields.Nested(FooSchema, allow_none=True))


class NullableNestedManySchema(Schema):
    foo = fields.Nested(FooSchema, many=True, allow_none=True)


class ScalarAndNonNullableNestedSchema(Schema):
    name = fields.String(allow_none=True)
    foo = fields.Nested(FooSchema)


def make_spec(openapi_version):
    plugin = MarshmallowPlugin()
    spec = APISpec(
        title="Nullable nested schema test",
        version="1.0.0",
        openapi_version=openapi_version,
        plugins=[plugin],
    )
    return spec, plugin


def register_with_foo(spec, name, schema):
    spec.components.schema("Foo", schema=FooSchema)
    spec.components.schema(name, schema=schema)
    return spec.to_dict()["components"]["schemas"]


def assert_nullable_object_reference(schema, ref):
    """Check the OpenAPI 3.0 representation proposed in the issue.

    The order of anyOf alternatives is not semantically significant. The null
    alternative must nevertheless have a type assertion in the same Schema
    Object; OpenAPI 3.0 does not support {"type": "null"}.
    """
    alternatives = schema["anyOf"]
    assert len(alternatives) == 2
    assert {"$ref": ref} in alternatives
    assert {"type": "object", "nullable": True} in alternatives
    assert "nullable" not in schema
    assert "allOf" not in schema
    assert "$ref" not in schema


@pytest.mark.parametrize("openapi_version", ["3.0.0", "3.0.3"])
def test_issue_example_uses_openapi_30_compliant_nullable_nested_schema(
    openapi_version,
):
    spec, _ = make_spec(openapi_version)
    schemas = register_with_foo(spec, "MySchema", MySchema)

    assert schemas["Foo"] == {
        "type": "object",
        "properties": {"bar": {"type": "integer"}},
        "required": ["bar"],
    }

    my_schema = schemas["MySchema"]
    assert my_schema["type"] == "object"
    assert set(my_schema["properties"]) == {"foo"}

    foo = my_schema["properties"]["foo"]
    assert set(foo) == {"anyOf"}
    assert_nullable_object_reference(foo, "#/components/schemas/Foo")


def test_openapi_30_nullable_nested_schema_with_metadata_does_not_use_allof():
    """Metadata makes nested conversion produce allOf before nullable handling."""
    spec, _ = make_spec("3.0.3")
    schemas = register_with_foo(
        spec, "NullableNestedMetadata", NullableNestedMetadataSchema
    )

    foo = schemas["NullableNestedMetadata"]["properties"]["foo"]
    assert set(foo) == {"anyOf", "description"}
    assert foo["description"] == "An optional Foo"
    assert_nullable_object_reference(foo, "#/components/schemas/Foo")


def test_openapi_30_nullable_nested_schema_inside_list():
    spec, _ = make_spec("3.0.3")
    schemas = register_with_foo(spec, "NullableNestedList", NullableNestedListSchema)

    foo = schemas["NullableNestedList"]["properties"]["foo"]
    assert set(foo) == {"type", "items"}
    assert foo["type"] == "array"
    assert set(foo["items"]) == {"anyOf"}
    assert_nullable_object_reference(foo["items"], "#/components/schemas/Foo")


def test_openapi_30_nullable_nested_many_makes_the_array_nullable():
    """For many=True, allow_none applies to the array, not to each item."""
    spec, _ = make_spec("3.0.3")
    schemas = register_with_foo(spec, "NullableNestedMany", NullableNestedManySchema)

    assert schemas["NullableNestedMany"]["properties"]["foo"] == {
        "type": "array",
        "items": {"$ref": "#/components/schemas/Foo"},
        "nullable": True,
    }


def test_openapi_30_scalar_and_non_nullable_nested_fields_are_unchanged():
    spec, _ = make_spec("3.0.3")
    schemas = register_with_foo(
        spec, "ScalarAndNonNullableNested", ScalarAndNonNullableNestedSchema
    )

    properties = schemas["ScalarAndNonNullableNested"]["properties"]
    assert properties["name"] == {"type": "string", "nullable": True}
    assert properties["foo"] == {"$ref": "#/components/schemas/Foo"}


@pytest.mark.parametrize(
    ("openapi_version", "expected"),
    [
        (
            "2.0",
            {"$ref": "#/definitions/Foo", "x-nullable": True},
        ),
        (
            "3.1.0",
            {
                "anyOf": [
                    {"$ref": "#/components/schemas/Foo"},
                    {"type": "null"},
                ]
            },
        ),
    ],
)
def test_nullable_nested_behavior_for_other_openapi_versions_is_unchanged(
    openapi_version, expected
):
    _, plugin = make_spec(openapi_version)

    result = plugin.converter.field2property(
        fields.Nested(FooSchema, allow_none=True)
    )

    assert result == expected


def test_openapi_30_inline_nullable_nested_schema_keeps_nullable_with_its_type():
    """An inline object already has a type assertion, so it needs no anyOf."""
    plugin = MarshmallowPlugin(schema_name_resolver=lambda schema: None)
    APISpec(
        title="Inline nullable nested schema test",
        version="1.0.0",
        openapi_version="3.0.3",
        plugins=[plugin],
    )

    result = plugin.converter.field2property(
        fields.Nested(FooSchema, allow_none=True)
    )

    assert result["type"] == "object"
    assert result["nullable"] is True
    assert result["properties"] == {"bar": {"type": "integer"}}
    assert result["required"] == ["bar"]
    assert "anyOf" not in result
    assert "allOf" not in result

from __future__ import annotations

import tomlkit
import pytest

from pdm.project.core import Project


RUFF_REQUIREMENT = "ruff>=0.9.6"


def _read_pyproject(project: Project) -> dict:
    pyproject = project.root / "pyproject.toml"
    return tomlkit.parse(pyproject.read_text(encoding="utf-8")).unwrap()


def _set_legacy_dev_dependencies(project: Project, groups: dict[str, list[str]]) -> None:
    project.pyproject.settings["dev-dependencies"] = groups
    project.pyproject.write()


def _add_to_dev_group(project: Project, group: str, requirement: str = RUFF_REQUIREMENT) -> None:
    dependencies, setter = project.use_pyproject_dependencies(group, dev=True)
    updated = tomlkit.array()
    for dependency in dependencies:
        updated.append(dependency)
    updated.append(requirement)
    setter(updated)
    project.pyproject.write()


@pytest.mark.parametrize("target_group", ["dev", "lint"])
def test_add_uses_requested_dev_group_when_legacy_editable_group_exists(
    project: Project, target_group: str
) -> None:
    """Both `pdm add -d` and `pdm add -dG lint` must use their requested group."""
    legacy_groups = {
        "workspaces": [
            "-e ./packages/pkg-app",
            "-e ./packages/pkg-core",
        ]
    }
    _set_legacy_dev_dependencies(project, legacy_groups)

    _add_to_dev_group(project, target_group)

    data = _read_pyproject(project)
    assert data["dependency-groups"] == {target_group: [RUFF_REQUIREMENT]}
    assert "workspaces" not in data["dependency-groups"]
    # Adding an unrelated dependency must not migrate or modify the legacy table.
    assert data["tool"]["pdm"]["dev-dependencies"] == legacy_groups


def test_add_preserves_existing_dependency_groups_without_copying_legacy_editables(
    project: Project,
) -> None:
    legacy_groups = {"workspaces": ["-e ./packages/pkg-app"]}
    existing_groups = {
        "lint": ["black>=24.0"],
        "test": ["pytest>=8.0"],
    }

    # Create both tables together, as they would appear in an existing project's
    # pyproject.toml, and verify the setup itself did not duplicate the legacy group.
    project.pyproject.settings["dev-dependencies"] = legacy_groups
    project.pyproject._data["dependency-groups"] = tomlkit.item(existing_groups)
    project.pyproject.write()
    before = _read_pyproject(project)
    assert before["dependency-groups"] == existing_groups
    assert before["tool"]["pdm"]["dev-dependencies"] == legacy_groups

    dependencies, setter = project.use_pyproject_dependencies("lint", dev=True)
    assert list(dependencies) == ["black>=24.0"]
    updated = tomlkit.array()
    updated.extend(dependencies)
    updated.append(RUFF_REQUIREMENT)
    setter(updated)
    project.pyproject.write()

    data = _read_pyproject(project)
    assert data["dependency-groups"] == {
        "lint": ["black>=24.0", RUFF_REQUIREMENT],
        "test": ["pytest>=8.0"],
    }
    assert "workspaces" not in data["dependency-groups"]
    assert data["tool"]["pdm"]["dev-dependencies"] == legacy_groups


def test_legacy_group_containing_editables_is_not_partially_duplicated(
    project: Project,
) -> None:
    """A group is not PEP 735-compatible merely because its editable items are removed."""
    legacy_groups = {
        "workspaces": [
            "-e ./packages/pkg-app",
            "pytest>=8.0",
        ]
    }
    _set_legacy_dev_dependencies(project, legacy_groups)

    _add_to_dev_group(project, "dev")

    data = _read_pyproject(project)
    assert data["dependency-groups"] == {"dev": [RUFF_REQUIREMENT]}
    assert "workspaces" not in data["dependency-groups"]
    # In particular, pytest must remain with its original group rather than being
    # silently moved into a partially migrated dependency-groups entry.
    assert data["tool"]["pdm"]["dev-dependencies"] == legacy_groups


def test_multiple_legacy_editable_groups_do_not_affect_target_selection(
    project: Project,
) -> None:
    legacy_groups = {
        "docs-tools": ["-e ./tools/docs"],
        "workspaces": [
            "-e ./packages/pkg-app",
            "-e ./packages/pkg-core",
        ],
    }
    _set_legacy_dev_dependencies(project, legacy_groups)

    _add_to_dev_group(project, "dev")

    data = _read_pyproject(project)
    assert data["dependency-groups"] == {"dev": [RUFF_REQUIREMENT]}
    assert data["tool"]["pdm"]["dev-dependencies"] == legacy_groups

"""Regression tests for variadic parameters in model initialization."""

import pytest

from mesa.visualization.solara_viz import _check_model_params


def test_var_keyword_parameter_is_not_required():
    """A **kwargs parameter should not itself have to appear in model_params."""

    class KwargsOnlyModel:
        def __init__(self, **options):
            pass

    # Use a name other than "kwargs" to ensure the parameter kind, not its
    # name, determines how it is handled.
    _check_model_params(KwargsOnlyModel.__init__, {})

    class MixedModel:
        def __init__(self, required_param, optional_param=10, **kwargs):
            pass

    _check_model_params(MixedModel.__init__, {"required_param": 1})
    _check_model_params(
        MixedModel.__init__, {"required_param": 1, "optional_param": 5}
    )


def test_var_positional_parameter_is_not_required():
    """An *args parameter is also optional when calling the initializer."""

    class ArgsOnlyModel:
        def __init__(self, *args):
            pass

    _check_model_params(ArgsOnlyModel.__init__, {})

    class CombinedModel:
        def __init__(self, required_param, *args, **kwargs):
            pass

    _check_model_params(CombinedModel.__init__, {"required_param": 1})


def test_variadic_parameters_do_not_hide_missing_required_parameters():
    """Required named parameters must still be validated."""

    class ModelWithKwargs:
        def __init__(self, required_param, **kwargs):
            pass

    with pytest.raises(
        ValueError, match="Missing required model parameter: required_param"
    ):
        _check_model_params(ModelWithKwargs.__init__, {})

    class ModelWithRequiredKeywordOnlyParam:
        def __init__(self, *args, required_param, **kwargs):
            pass

    with pytest.raises(
        ValueError, match="Missing required model parameter: required_param"
    ):
        _check_model_params(ModelWithRequiredKeywordOnlyParam.__init__, {})

    _check_model_params(
        ModelWithRequiredKeywordOnlyParam.__init__, {"required_param": 1}
    )


def test_regular_parameters_named_args_or_kwargs_are_still_required():
    """Only variadic parameters receive special treatment, not their names."""

    class RegularKwargsParameterModel:
        def __init__(self, kwargs):
            pass

    with pytest.raises(ValueError, match="Missing required model parameter: kwargs"):
        _check_model_params(RegularKwargsParameterModel.__init__, {})

    class RegularArgsParameterModel:
        def __init__(self, args):
            pass

    with pytest.raises(ValueError, match="Missing required model parameter: args"):
        _check_model_params(RegularArgsParameterModel.__init__, {})


def test_invalid_parameter_validation_is_preserved_without_var_kwargs():
    """The variadic-parameter fix must not disable other parameter checks."""

    class ModelWithoutVariadicParams:
        def __init__(self, required_param):
            pass

    with pytest.raises(ValueError, match="Invalid model parameter: unexpected"):
        _check_model_params(
            ModelWithoutVariadicParams.__init__,
            {"required_param": 1, "unexpected": 2},
        )

