    assert md(html) == "`foo.com`"


def test_link_inside_pre_is_rendered_as_plain_text():
    html = "<pre><a href='http://foo.com/'>foo.com</a></pre>"
    assert md(html) == fenced("foo.com")


def test_link_inside_nested_pre_and_code_is_rendered_as_plain_text():
    html = "<pre><code>before <a href='/target'>link</a> after</code></pre>"
    assert md(html) == fenced("before link after")


def test_code_links_do_not_use_autolink_or_title_markup():
    autolink = (
        "<code><a href='https://example.com/'>"
        "https://example.com/</a></code>"
    )
    assert md(autolink) == "`https://example.com/`"

    titled = "<code><a href='/docs' title='Documentation'>docs</a></code>"
    assert md(titled) == "`docs`"
    assert md("<code><a href='/docs'>docs</a></code>", default_title=True) == "`docs`"


def test_link_without_href_inside_code_is_rendered_as_plain_text():
    assert md("<code><a>label</a></code>") == "`label`"


def test_only_links_inside_preformatted_content_are_suppressed():
    html = (
        "<a href='/outside'>outside</a> "
        "<code><a href='/inside'>inside</a></code>"
    )
    assert md(html) == "[outside](/outside) `inside`"

