"""Regression tests for counts of mid-circuit measurements with one-shot execution."""

import numbers

import numpy as np
import pytest

import pennylane as qml


SHOTS = 10


def _assert_integer_keys(counts):
    """MCM outcomes are integer measurement values, not floating-point samples."""
    assert all(isinstance(key, numbers.Integral) for key in counts), counts


@pytest.mark.parametrize("mcm_method", ["deferred", "one-shot"])
@pytest.mark.parametrize("prepare_one", [False, True])
def test_counts_single_mcm_all_outcomes(mcm_method, prepare_one):
    """All possible MCM outcomes are returned, including zero-count outcomes."""
    dev = qml.device("default.qubit", wires=1, shots=SHOTS)

    @qml.qnode(dev, mcm_method=mcm_method)
    def circuit():
        if prepare_one:
            qml.PauliX(0)
        m = qml.measure(0)
        return qml.counts(m, all_outcomes=True)

    result = circuit()
    expected = {0: 0, 1: SHOTS} if prepare_one else {0: SHOTS, 1: 0}

    assert result == expected
    _assert_integer_keys(result)
    assert sum(result.values()) == SHOTS


@pytest.mark.parametrize("prepare_one", [False, True])
def test_one_shot_counts_without_all_outcomes_only_returns_observed(prepare_one):
    """Requesting all outcomes must not change the default observed-only behaviour."""
    dev = qml.device("default.qubit", wires=1, shots=SHOTS)

    @qml.qnode(dev, mcm_method="one-shot")
    def circuit():
        if prepare_one:
            qml.PauliX(0)
        m = qml.measure(0)
        return qml.counts(m)

    result = circuit()
    observed = int(prepare_one)

    assert result == {observed: SHOTS}
    assert len(result) == 1
    _assert_integer_keys(result)


@pytest.mark.parametrize("mcm_method", ["deferred", "one-shot"])
def test_counts_multiple_mcms_all_outcomes(mcm_method):
    """Counts of a sequence of MCMs include every bit-string outcome."""
    dev = qml.device("default.qubit", wires=2, shots=SHOTS)

    @qml.qnode(dev, mcm_method=mcm_method)
    def circuit():
        m0 = qml.measure(0)
        m1 = qml.measure(1)
        return qml.counts([m0, m1], all_outcomes=True)

    result = circuit()

    assert result == {"00": SHOTS, "01": 0, "10": 0, "11": 0}
    assert sum(result.values()) == SHOTS


@pytest.mark.parametrize("mcm_method", ["deferred", "one-shot"])
def test_counts_all_outcomes_uses_transformed_mcm_branches(mcm_method):
    """The outcomes come from the MeasurementValue, rather than always being 0 and 1."""
    dev = qml.device("default.qubit", wires=1, shots=SHOTS)

    @qml.qnode(dev, mcm_method=mcm_method)
    def circuit():
        m = qml.measure(0)
        return qml.counts(2 * m, all_outcomes=True)

    result = circuit()

    # In particular, outcome 1 is impossible and must not be added spuriously.
    assert result == {0: SHOTS, 2: 0}
    _assert_integer_keys(result)


@pytest.mark.parametrize("mcm_method", ["deferred", "one-shot"])
def test_counts_all_outcomes_for_arithmetic_composite_mcm(mcm_method):
    """Arithmetic over several MCMs retains every possible composite value."""
    dev = qml.device("default.qubit", wires=2, shots=SHOTS)

    @qml.qnode(dev, mcm_method=mcm_method)
    def circuit():
        m0 = qml.measure(0)
        m1 = qml.measure(1)
        return qml.counts(m0 + 2 * m1, all_outcomes=True)

    result = circuit()

    assert result == {0: SHOTS, 1: 0, 2: 0, 3: 0}
    _assert_integer_keys(result)
    assert sum(result.values()) == SHOTS


def test_one_shot_counts_all_outcomes_with_shot_vector():
    """Each shot partition independently contains all MCM outcomes."""
    shots = [7, 11]
    dev = qml.device("default.qubit", wires=1, shots=shots)

    @qml.qnode(dev, mcm_method="one-shot")
    def circuit():
        m = qml.measure(0)
        return qml.counts(m, all_outcomes=True)

    results = circuit()

    assert len(results) == len(shots)
    for result, shot_count in zip(results, shots):
        assert result == {0: shot_count, 1: 0}
        _assert_integer_keys(result)


@pytest.mark.parametrize("mcm_method", ["deferred", "one-shot"])
def test_non_mcm_observable_count_keys_are_not_coerced_to_int(mcm_method):
    """Fixing MCM key types must not truncate eigenvalues of ordinary observables."""
    dev = qml.device("default.qubit", wires=2, shots=SHOTS)
    observable = qml.Hermitian(np.diag([0.25, 1.75]), wires=1)

    @qml.qnode(dev, mcm_method=mcm_method)
    def circuit():
        # Ensure that one-shot execution uses its counts-gathering path even
        # though the returned counts are for an ordinary observable.
        _ = qml.measure(0)
        return qml.counts(observable, all_outcomes=True)

    result = circuit()

    assert result == {0.25: SHOTS, 1.75: 0}
    assert sum(result.values()) == SHOTS

import pytest

import sqlglot
from sqlglot.errors import ParseError


def transpile_one(sql: str, read: str, write: str) -> str:
    return sqlglot.transpile(sql, read=read, write=write)[0]


@pytest.mark.parametrize(
    ("source", "expected"),
    [
        (
            "SELECT 'hello' || 'world' FROM t",
            "SELECT 'hello' + 'world' FROM t",
        ),
        (
            "SELECT first_name || last_name FROM users",
            "SELECT first_name + last_name FROM users",
        ),
        (
            "SELECT a || b || c FROM t",
            "SELECT a + b + c FROM t",
        ),
        (
            "SELECT UPPER(first_name || ' ' || last_name) FROM users",
            "SELECT UPPER(first_name + ' ' + last_name) FROM users",
        ),
        (
            "SELECT a || b AS ab, c || d AS cd FROM t",
            "SELECT a + b AS ab, c + d AS cd FROM t",
        ),
    ],
)
def test_string_concatenation_uses_plus_for_tsql(source, expected):
    """A DPipe coming from another dialect must not be emitted as T-SQL ||."""
    assert transpile_one(source, read="postgres", write="tsql") == expected


def test_tsql_double_pipe_is_not_accepted_as_string_concatenation():
    """SQL Server uses OR for logical disjunction; || is not a T-SQL OR operator."""
    with pytest.raises(ParseError):
        sqlglot.parse_one("SELECT a || b FROM t", read="tsql")


@pytest.mark.parametrize("write", ["tsql", "postgres"])
def test_existing_plus_operator_is_not_rewritten(write):
    """TSQL + is an Add expression and should remain distinct from DPipe."""
    assert (
        transpile_one("SELECT a + b FROM t", read="tsql", write=write)
        == "SELECT a + b FROM t"
    )


def test_tsql_concat_function_is_unchanged():
    assert (
        transpile_one("SELECT CONCAT(a, b) FROM t", read="tsql", write="tsql")
        == "SELECT CONCAT(a, b) FROM t"
    )


def test_tsql_change_does_not_alter_other_dialect_concatenation():
    source = "SELECT a || b FROM t"

    assert transpile_one(source, read="postgres", write="postgres") == source
    assert (
        transpile_one(source, read="postgres", write="mysql")
        == "SELECT CONCAT(a, b) FROM t"
    )

import sys
import textwrap
from pathlib import Path

import pytest


ROOT = Path(__file__).resolve().parent
if str(ROOT) not in sys.path:
    sys.path.insert(0, str(ROOT))

import cpplint


TRAILING_SEMICOLON_WARNING = "You don't need a ; after a }"


class ErrorCollector:
    """Collect cpplint diagnostics using its public error callback interface."""

    def __init__(self):
        self.errors = []

    def __call__(self, filename, linenum, category, confidence, message):
        self.errors.append(
            (filename, linenum, category, confidence, message)
        )


def lint_readability_braces(tmp_path, source):
    """Lint C++ source in-process, as cpplint's own multiline tests do."""
    filename = str(tmp_path / "concept_test.cc")
    lines = textwrap.dedent(source).lstrip("\n").splitlines()
    collector = ErrorCollector()

    previous_filters = list(cpplint._cpplint_state.filters)
    cpplint._cpplint_state.SetFilters("-,+readability/braces")
    try:
        cpplint.ProcessFileData(filename, "cc", lines, collector)
    finally:
        cpplint._cpplint_state.SetFilters(previous_filters)

    return collector.errors


def trailing_semicolon_warnings(errors):
    return [
        error
        for error in errors
        if error[2] == "readability/braces"
        and error[4] == TRAILING_SEMICOLON_WARNING
    ]


@pytest.mark.parametrize(
    "source",
    [
        # The example from the issue: this semicolon terminates the concept
        # definition and is required by C++20.
        """
        template <typename T>
        concept IndexableToChar = requires(T t) {
          { t[0] } -> std::convertible_to<char>;
        };
        """,
        # Newlines are whitespace in a concept-definition; splitting before
        # the equals sign must not make the required semicolon look redundant.
        """
        template <typename T>
        concept IndexableToChar
            = requires(T t) {
          { t[0] } -> std::convertible_to<char>;
        };
        """,
        # The requires-expression's braces may also start on the next line.
        """
        template <typename T>
        concept IndexableToChar = requires(T t)
        {
          { t[0] } -> std::convertible_to<char>;
        };
        """,
    ],
    ids=("issue_example", "split_before_equals", "brace_on_next_line"),
)
def test_required_semicolon_after_concept_is_not_flagged(tmp_path, source):
    errors = lint_readability_braces(tmp_path, source)
    assert not trailing_semicolon_warnings(errors), errors


def test_multiline_concept_detection_has_no_arbitrary_line_limit(tmp_path):
    parameters = ",\n".join(f"    T t{i}" for i in range(12))
    source = (
        "template <typename T>\n"
        "concept IndexableToChar = requires(\n"
        f"{parameters}\n"
        ") {\n"
        "  { t0[0] } -> std::convertible_to<char>;\n"
        "};\n"
    )

    errors = lint_readability_braces(tmp_path, source)
    assert not trailing_semicolon_warnings(errors), errors


def test_redundant_semicolon_after_function_still_warns(tmp_path):
    errors = lint_readability_braces(
        tmp_path,
        """
        void Function() {
        };
        """,
    )
    assert len(trailing_semicolon_warnings(errors)) == 1, errors


def test_concept_does_not_suppress_warnings_for_nearby_unrelated_blocks(tmp_path):
    # Only the concept's own closing brace is part of its definition. The
    # semicolon after Function's body remains redundant even though a concept
    # appears shortly beforehand.
    errors = lint_readability_braces(
        tmp_path,
        """
        template <typename T>
        concept IndexableToChar = requires(T t) {
          { t[0] } -> std::convertible_to<char>;
        };

        void Function() {
        };
        """,
    )
    assert len(trailing_semicolon_warnings(errors)) == 1, errors

"""Regression tests for expanding Python versions with multi-digit minors."""

import pytest

import hashin


@pytest.mark.parametrize(
    "version",
    [
        "2.7",
        "3.5",
        "3.9",
        "3.10",
        "3.11",
        "3.12",
        "3.100",
    ],
)
def test_expand_python_version_supports_multi_digit_minor_versions(version):
    """Every major.minor version should produce all PyPI identifier forms."""
    major, minor = version.split(".")

    assert hashin.expand_python_version(version) == {
        version,
        "cp{}{}".format(major, minor),
        "py{}".format(major),
        "py{}.{}".format(major, minor),
        "py{}{}".format(major, minor),
        "source",
        "py2.py3",
    }


@pytest.mark.parametrize(
    "version",
    [
        "cp310",
        "py3",
        "py310",
        "source",
        "3.10.1",
        "3.",
        ".10",
        "3",
        "3.x",
        "",
    ],
)
def test_expand_python_version_passes_other_identifiers_through(version):
    """Inputs that are not a major.minor version retain the old behavior."""
    assert hashin.expand_python_version(version) == [version]


@pytest.mark.parametrize(
    ("version", "tag", "expected_hash"),
    [
        ("3.10", "cp310", "a" * 64),
        ("3.11", "cp311", "b" * 64),
    ],
)
def test_get_package_hashes_finds_wheels_for_multi_digit_python_versions(
    version, tag, expected_hash
):
    """A matching wheel must not result in PackageError('No releases...')."""
    unrelated_hash = "f" * 64
    package_data = {
        "info": {"name": "demo", "version": "1.0"},
        "releases": {
            "1.0": [
                {
                    "url": (
                        "https://files.pythonhosted.org/packages/"
                        "demo-1.0-cp39-cp39-manylinux1_x86_64.whl"
                    ),
                    "digests": {"sha256": unrelated_hash},
                },
                {
                    "url": (
                        "https://files.pythonhosted.org/packages/"
                        "demo-1.0-{0}-{0}-manylinux1_x86_64.whl".format(tag)
                    ),
                    "digests": {"sha256": expected_hash},
                },
            ]
        },
    }

    # lookup_memory maps package names to their locally supplied PyPI responses,
    # so this exercises the public package-hashing workflow without networking.
    result = hashin.get_package_hashes(
        "demo",
        version="1.0",
        python_versions=[version],
        lookup_memory={"demo": package_data},
    )

    assert result == {
        "package": "demo",
        "version": "1.0",
        "hashes": [{"hash": expected_hash}],
    }

"""Regression tests for nullable nested schemas in OpenAPI 3.0."""

import pytest
from apispec import APISpec
from apispec.ext.marshmallow import MarshmallowPlugin
from marshmallow import Schema, fields


class FooSchema(Schema):
    bar = fields.Integer(required=True)


class MySchema(Schema):
    foo = fields.Nested(FooSchema, allow_none=True)


def make_spec(openapi_version):
    return APISpec(
        title="My API Spec",
        version="1.0.0",
        openapi_version=openapi_version,
        plugins=[MarshmallowPlugin()],
    )


def register_foo_and_schema(spec, name, schema):
    spec.components.schema("Foo", schema=FooSchema)
    spec.components.schema(name, schema=schema)


def assert_nullable_nested_reference(prop, reference):
    """Check the OpenAPI 3.0-compatible representation proposed in the issue.

    In particular, {"type": "null"} is not a valid OpenAPI 3.0 schema, and a
    sibling "nullable" cannot modify a type inherited through allOf or $ref.
    """
    assert "$ref" not in prop
    assert "allOf" not in prop
    assert "nullable" not in prop

    alternatives = prop["anyOf"]
    assert len(alternatives) == 2
    assert {"$ref": reference} in alternatives
    assert {"type": "object", "nullable": True} in alternatives
    assert {"type": "null"} not in alternatives


@pytest.mark.parametrize("openapi_version", ["3.0.0", "3.0.3"])
def test_issue_example_nested_allow_none(openapi_version):
    spec = make_spec(openapi_version)
    register_foo_and_schema(spec, "MySchema", MySchema)

    schemas = spec.to_dict()["components"]["schemas"]

    assert schemas["Foo"] == {
        "type": "object",
        "properties": {"bar": {"type": "integer"}},
        "required": ["bar"],
    }
    assert schemas["MySchema"]["type"] == "object"
    assert_nullable_nested_reference(
        schemas["MySchema"]["properties"]["foo"],
        "#/components/schemas/Foo",
    )


def test_nullable_nested_reference_with_metadata_uses_valid_anyof():
    class DocumentedSchema(Schema):
        foo = fields.Nested(
            FooSchema,
            allow_none=True,
            metadata={"description": "An optional foo"},
        )

    spec = make_spec("3.0.3")
    register_foo_and_schema(spec, "Documented", DocumentedSchema)

    # Metadata causes nested2properties to use allOf internally. The nullable
    # conversion must handle that path as well as the bare-$ref path.
    prop = spec.to_dict()["components"]["schemas"]["Documented"]["properties"][
        "foo"
    ]
    assert prop["description"] == "An optional foo"
    assert_nullable_nested_reference(prop, "#/components/schemas/Foo")


def test_openapi30_scalar_nullable_and_nonnullable_nested_are_unchanged():
    class ScalarSchema(Schema):
        name = fields.String(allow_none=True)

    class PlainNestedSchema(Schema):
        foo = fields.Nested(FooSchema)

    spec = make_spec("3.0.3")
    spec.components.schema("Scalar", schema=ScalarSchema)
    register_foo_and_schema(spec, "PlainNested", PlainNestedSchema)

    schemas = spec.to_dict()["components"]["schemas"]
    assert schemas["Scalar"]["properties"]["name"] == {
        "type": "string",
        "nullable": True,
    }
    assert schemas["PlainNested"]["properties"]["foo"] == {
        "$ref": "#/components/schemas/Foo"
    }


def test_openapi30_nullable_nested_many_nullable_is_on_array():
    class NullableManySchema(Schema):
        foos = fields.Nested(FooSchema, many=True, allow_none=True)

    spec = make_spec("3.0.3")
    register_foo_and_schema(spec, "NullableMany", NullableManySchema)

    prop = spec.to_dict()["components"]["schemas"]["NullableMany"]["properties"][
        "foos"
    ]
    assert prop == {
        "type": "array",
        "items": {"$ref": "#/components/schemas/Foo"},
        "nullable": True,
    }


def test_openapi30_list_of_nullable_nested_schemas():
    class ListOfNullableSchema(Schema):
        foos = fields.List(fields.Nested(FooSchema, allow_none=True))

    spec = make_spec("3.0.3")
    register_foo_and_schema(spec, "ListOfNullable", ListOfNullableSchema)

    prop = spec.to_dict()["components"]["schemas"]["ListOfNullable"]["properties"][
        "foos"
    ]
    assert prop["type"] == "array"
    assert "nullable" not in prop
    assert_nullable_nested_reference(
        prop["items"], "#/components/schemas/Foo"
    )


@pytest.mark.parametrize(
    ("openapi_version", "definitions_key", "expected"),
    [
        (
            "2.0",
            "definitions",
            {"$ref": "#/definitions/Foo", "x-nullable": True},
        ),
        (
            "3.1.0",
            "components",
            {
                "anyOf": [
                    {"$ref": "#/components/schemas/Foo"},
                    {"type": "null"},
                ]
            },
        ),
    ],
)
def test_nullable_nested_behavior_outside_openapi30_is_unchanged(
    openapi_version, definitions_key, expected
):
    spec = make_spec(openapi_version)
    register_foo_and_schema(spec, "MySchema", MySchema)
    document = spec.to_dict()

    if definitions_key == "components":
        prop = document["components"]["schemas"]["MySchema"]["properties"]["foo"]
    else:
        prop = document["definitions"]["MySchema"]["properties"]["foo"]

    assert prop == expected

import pytest

import sqlglot
from sqlglot import exp


@pytest.mark.parametrize(
    ("source_sql", "expected_tsql"),
    [
        (
            "SELECT 'hello' || 'world' FROM t",
            "SELECT 'hello' + 'world' FROM t",
        ),
        (
            "SELECT first_name || last_name FROM users",
            "SELECT first_name + last_name FROM users",
        ),
        (
            "SELECT a || b || c FROM t",
            "SELECT a + b + c FROM t",
        ),
        (
            "SELECT UPPER(first_name || ' ' || last_name) FROM users",
            "SELECT UPPER(first_name + ' ' + last_name) FROM users",
        ),
        (
            "SELECT * FROM users WHERE first_name || last_name = 'ab'",
            "SELECT * FROM users WHERE first_name + last_name = 'ab'",
        ),
    ],
)
def test_double_pipe_transpiles_to_plus_for_tsql(source_sql, expected_tsql):
    """T-SQL output must use the broadly supported SQL Server concat operator."""
    assert sqlglot.transpile(source_sql, read="postgres", write="tsql") == [expected_tsql]


def test_parsed_double_pipe_is_not_emitted_as_double_pipe_for_tsql():
    # Parse the concatenation with SQLGlot's default dialect, which supports ||,
    # and verify that T-SQL generation uses + instead.
    expression = sqlglot.parse_one("SELECT a || b FROM t")

    assert expression.sql(dialect="tsql") == "SELECT a + b FROM t"


def test_dpipe_expression_generates_plus_in_tsql():
    expression = exp.DPipe(this=exp.column("a"), expression=exp.column("b"))

    assert expression.sql(dialect="tsql") == "a + b"


@pytest.mark.parametrize("target_dialect", ["tsql", "postgres"])
def test_native_tsql_plus_is_not_changed(target_dialect):
    # In particular, arithmetic addition must not be turned into || merely
    # because the source dialect is T-SQL.
    assert sqlglot.transpile("SELECT a + b FROM t", read="tsql", write=target_dialect) == [
        "SELECT a + b FROM t"
    ]


def test_tsql_concat_function_is_preserved():
    assert sqlglot.transpile(
        "SELECT CONCAT(column1, column2)", read="tsql", write="tsql"
    ) == ["SELECT CONCAT(column1, column2)"]


@pytest.mark.parametrize(
    ("target_dialect", "expected_sql"),
    [
        ("postgres", "SELECT a || b FROM t"),
        ("mysql", "SELECT CONCAT(a, b) FROM t"),
    ],
)
def test_other_dialect_concatenation_behavior_is_unchanged(target_dialect, expected_sql):
    assert sqlglot.transpile("SELECT a || b FROM t", read="postgres", write=target_dialect) == [
        expected_sql
    ]

import pytest

from yarl import URL


class _PortLike:
    """A custom invalid port type with a distinctive name."""


@pytest.mark.parametrize("encoded", [False, True])
@pytest.mark.parametrize(
    "port",
    [
        pytest.param(8080.0, id="float"),
        pytest.param("8080", id="str"),
        pytest.param([], id="list"),
        pytest.param(object(), id="object"),
        pytest.param(_PortLike(), id="custom-type"),
    ],
)
def test_build_invalid_port_error_reports_actual_type(port, encoded):
    """The TypeError should identify the offending type, not just repeat the rule."""
    with pytest.raises(TypeError) as exc_info:
        URL.build(
            scheme="http",
            host="example.com",
            port=port,
            encoded=encoded,
        )

    port_type = type(port)
    # Both the type's name (as suggested in the issue) and its repr provide
    # the requested diagnostic information.
    expected_messages = {
