import textwrap

import cpplint
import pytest


_TRAILING_SEMICOLON_MESSAGE = "You don't need a ; after a }"


def _trailing_semicolon_errors(source):
    """Return one-based line numbers for redundant-semicolon diagnostics."""
    lines = textwrap.dedent(source).strip("\n").split("\n")
    errors = []

    def collect_error(_filename, linenum, category, _confidence, message):
        if (category == "readability/braces"
                and _TRAILING_SEMICOLON_MESSAGE in message):
            errors.append(linenum)

    cpplint._cpplint_state.ResetErrorCounts()
    cpplint.ProcessFileData("test.cc", "cc", lines, collect_error)
    return errors


@pytest.mark.parametrize(
    "source",
    [
        # The example from the issue: this semicolon is required by C++20.
        """
        template <typename T>
        concept IndexableToChar = requires(T t) {
          { t[0] } -> std::convertible_to<char>;
        };
        """,
        # A template-head is not required for a concept definition.
        """
        concept AlwaysTrue = requires {
          { true };
        };
        """,
        # Whitespace and newlines may separate the concept name from '='.
        """
        template <typename T>
        concept IndexableToChar
            = requires(T t) {
          { t[0] } -> std::convertible_to<char>;
        };
        """,
    ],
    ids=["issue-example", "without-template", "split-before-equals"],
)
def test_concept_definition_semicolon_is_not_flagged(source):
    assert _trailing_semicolon_errors(source) == []


def test_redundant_semicolon_after_function_is_still_flagged():
    # ProcessFileData reports one-based source line numbers.
    assert _trailing_semicolon_errors("void f() {};\n") == [1]


def test_preceding_concept_does_not_hide_unrelated_redundant_semicolon():
    source = """
    template <typename T>
    concept IndexableToChar = requires(T t) {
      { t[0] } -> std::convertible_to<char>;
    };

    void f() {};
    """
    # Only the function's semicolon on source line 6 is redundant; it must
    # not be suppressed merely because a concept appears nearby.
    assert _trailing_semicolon_errors(source) == [6]


def test_following_concept_does_not_hide_unrelated_redundant_semicolon():
    source = """
    void f() {};
    template <typename T>
    concept IndexableToChar = requires(T t) {
      { t[0] } -> std::convertible_to<char>;
    };
    """
    assert _trailing_semicolon_errors(source) == [1]

import pytest

import sqlglot
from sqlglot import exp, parse_one


def transpile_one(sql: str, *, read: str, write: str) -> str:
    return sqlglot.transpile(sql, read=read, write=write)[0]


@pytest.mark.parametrize(
    ("source", "expected"),
    [
        (
            "SELECT 'hello' || 'world' FROM t",
            "SELECT 'hello' + 'world' FROM t",
        ),
        (
            "SELECT first_name || last_name FROM users",
            "SELECT first_name + last_name FROM users",
        ),
        (
            "SELECT a || b || c FROM t",
            "SELECT a + b + c FROM t",
        ),
        (
            "SELECT UPPER(first_name || ' ' || last_name) FROM users",
            "SELECT UPPER(first_name + ' ' + last_name) FROM users",
        ),
        (
            "SELECT * FROM users WHERE first_name || ' ' || last_name = 'Ada Lovelace'",
            "SELECT * FROM users WHERE first_name + ' ' + last_name = 'Ada Lovelace'",
        ),
        (
            "SELECT 'a||b' || 'c'",
            "SELECT 'a||b' + 'c'",
        ),
    ],
)
def test_tsql_generates_plus_for_double_pipe_concatenation(source, expected):
    """T-SQL output must use the concatenation operator supported by SQL Server."""
    assert transpile_one(source, read="postgres", write="tsql") == expected


def test_tsql_generates_plus_for_a_dpipe_expression():
    """Exercise generation directly, independently of the source SQL text."""
    expression = parse_one("a || b", read="postgres")
    assert isinstance(expression, exp.DPipe)
    assert expression.sql("tsql") == "a + b"


def test_tsql_plus_concatenation_is_preserved():
    sql = "SELECT first_name + last_name FROM users"
    assert transpile_one(sql, read="tsql", write="tsql") == sql
    assert transpile_one(sql, read="tsql", write="postgres") == sql


def test_tsql_concat_function_is_preserved():
    sql = "SELECT CONCAT(first_name, last_name) FROM users"
    assert transpile_one(sql, read="tsql", write="tsql") == sql


@pytest.mark.parametrize(
    ("write", "expected"),
    [
        ("postgres", "SELECT a || b FROM t"),
        ("sqlite", "SELECT a || b FROM t"),
        ("mysql", "SELECT CONCAT(a, b) FROM t"),
    ],
)
def test_tsql_change_does_not_alter_other_dialects(write, expected):
    assert transpile_one("SELECT a || b FROM t", read="postgres", write=write) == expected

"""Regression tests for scalar Quantity windows in :func:`fit_lines`."""

import numpy as np
import pytest
from astropy import units as u
from astropy.modeling import models

from specutils import Spectrum1D
from specutils.fitting import fit_lines


LINE_CENTER = 6563 * u.AA
HALF_WINDOW = 10 * u.AA


class RecordingFitter:
    """Fitter double that records the data actually supplied to the fit."""

    def __init__(self):
        self.calls = []

    def __call__(self, model, x, y, weights=None, **kwargs):
        self.calls.append(
            {
                "x": x.copy(),
                "y": y.copy(),
                "weights": None if weights is None else weights.copy(),
            }
        )
        return model


def make_spectrum():
    # Offset the pixels from the window boundaries so this test does not
    # depend on the inclusive/exclusive boundary convention.
    wavelength = np.arange(6540.25, 6586.25, 1.0) * u.AA

    line = 2000 * np.exp(-0.5 * ((wavelength.value - 6563.0) / 3.0) ** 2)
    # A strong feature outside the requested window makes using the whole
    # spectrum observably different from fitting only the requested region.
    contaminant = 15000 * np.exp(
        -0.5 * ((wavelength.value - 6581.0) / 1.5) ** 2
    )
    flux = (7 + line + contaminant) * u.Jy

    return Spectrum1D(spectral_axis=wavelength, flux=flux)


def make_gaussian():
    return models.Gaussian1D(
        amplitude=2000,
        mean=LINE_CENTER,
        stddev=3 * u.AA,
    )


def make_compound_model():
    # This is the model form used in the issue: the compound model has no
    # top-level ``mean`` attribute; the Gaussian center is ``mean_0``.
    return make_gaussian() + models.Const1D(0)


def dispersion_in_angstrom(values):
    if isinstance(values, u.Quantity):
        return values.to_value(u.AA)
    return np.asarray(values, dtype=float)


def flux_in_jansky(values):
    if isinstance(values, u.Quantity):
        return values.to_value(u.Jy)
    return np.asarray(values, dtype=float)


@pytest.mark.parametrize("model_factory", [make_gaussian, make_compound_model])
@pytest.mark.parametrize(
    "window",
    [10 * u.AA, 0.001 * u.um],
    ids=["angstroms", "equivalent-unit"],
)
def test_scalar_quantity_window_is_centered_on_model_mean(model_factory, window):
    """A scalar Quantity window is a half-width around the line center."""
    spectrum = make_spectrum()
    fitter = RecordingFitter()
    weights = np.linspace(1.0, 2.0, spectrum.flux.size)

    fit_lines(
        spectrum,
        model_factory(),
        fitter=fitter,
        weights=weights,
        window=window,
    )

    expected_mask = (
        (spectrum.spectral_axis >= LINE_CENTER - HALF_WINDOW)
        & (spectrum.spectral_axis < LINE_CENTER + HALF_WINDOW)
    )
    expected_dispersion = spectrum.spectral_axis[expected_mask]
    expected_flux = spectrum.flux[expected_mask]

    # Ensure the test really distinguishes a windowed fit from a full fit.
    assert 0 < expected_dispersion.size < spectrum.spectral_axis.size
    assert len(fitter.calls) == 1

    call = fitter.calls[0]
    np.testing.assert_allclose(
        dispersion_in_angstrom(call["x"]),
        expected_dispersion.to_value(u.AA),
    )
    np.testing.assert_allclose(
        flux_in_jansky(call["y"]),
        expected_flux.to_value(u.Jy),
    )
    np.testing.assert_allclose(call["weights"], weights[expected_mask])


def test_scalar_quantity_window_matches_explicit_bounds_for_compound_model():
    """The issue's automatic window must select the same data as its bounds."""
    spectrum = make_spectrum()
    automatic_fitter = RecordingFitter()
    explicit_fitter = RecordingFitter()

    fit_lines(
        spectrum,
        make_compound_model(),
        fitter=automatic_fitter,
        window=10 * u.AA,
    )
    fit_lines(
        spectrum,
        make_compound_model(),
        fitter=explicit_fitter,
        window=(6553 * u.AA, 6573 * u.AA),
    )

    automatic = automatic_fitter.calls[0]
    explicit = explicit_fitter.calls[0]

    np.testing.assert_allclose(
        dispersion_in_angstrom(automatic["x"]),
        dispersion_in_angstrom(explicit["x"]),
    )
    np.testing.assert_allclose(
        flux_in_jansky(automatic["y"]),
        flux_in_jansky(explicit["y"]),
    )

"""Regression tests for nullable nested schemas in OpenAPI 3.0.

OpenAPI 3.0 does not support ``type: null``. A nullable nested schema must
instead put a schema with its own ``type`` and ``nullable: true`` alongside
the reference in ``anyOf``.
"""

import pytest
from apispec import APISpec
from apispec.ext.marshmallow import MarshmallowPlugin
from marshmallow import Schema, fields


class FooSchema(Schema):
    bar = fields.Integer(required=True)


class MySchema(Schema):
    foo = fields.Nested(FooSchema, allow_none=True)


def make_spec(openapi_version):
    return APISpec(
        title="My API Spec",
        version="1.0.0",
        openapi_version=openapi_version,
        plugins=[MarshmallowPlugin()],
    )


def register_issue_schemas(spec):
    spec.components.schema("Foo", schema=FooSchema)
    spec.components.schema("MySchema", schema=MySchema)


def assert_nullable_nested_reference(prop, ref):
    """Check the OpenAPI 3.0 representation without constraining anyOf order."""
    assert set(prop) == {"anyOf"}
    assert len(prop["anyOf"]) == 2
    assert {"$ref": ref} in prop["anyOf"]
    assert {"type": "object", "nullable": True} in prop["anyOf"]


@pytest.mark.parametrize("openapi_version", ["3.0.0", "3.0.3"])
def test_issue_example_uses_openapi_30_compliant_nullable_anyof(openapi_version):
    spec = make_spec(openapi_version)
    register_issue_schemas(spec)

    schemas = spec.to_dict()["components"]["schemas"]

    assert schemas["Foo"] == {
        "type": "object",
        "properties": {"bar": {"type": "integer"}},
        "required": ["bar"],
    }
    assert schemas["MySchema"]["type"] == "object"
    assert set(schemas["MySchema"]["properties"]) == {"foo"}
    assert_nullable_nested_reference(
        schemas["MySchema"]["properties"]["foo"],
        "#/components/schemas/Foo",
    )


def test_openapi_30_nullable_nested_schema_with_metadata():
    """Metadata makes nested conversion use allOf, which must also be fixed."""

    class DescribedSchema(Schema):
        foo = fields.Nested(
            FooSchema,
            allow_none=True,
            metadata={"description": "An optional foo"},
        )

    spec = make_spec("3.0.3")
    spec.components.schema("Foo", schema=FooSchema)
    spec.components.schema("Described", schema=DescribedSchema)

    prop = spec.to_dict()["components"]["schemas"]["Described"]["properties"][
        "foo"
    ]

    assert prop["description"] == "An optional foo"
    assert "allOf" not in prop
    assert "nullable" not in prop
    assert_nullable_nested_reference(
        {key: value for key, value in prop.items() if key != "description"},
        "#/components/schemas/Foo",
    )


def test_openapi_30_nullable_fields_with_own_type_keep_using_nullable():
    """Only references need anyOf; nullable can modify a local type directly."""

    class NullableTypesSchema(Schema):
        name = fields.String(allow_none=True)
        foo_list = fields.List(fields.Nested(FooSchema), allow_none=True)
        many_foos = fields.Nested(FooSchema, many=True, allow_none=True)

    spec = make_spec("3.0.3")
    spec.components.schema("Foo", schema=FooSchema)
    spec.components.schema("NullableTypes", schema=NullableTypesSchema)

    properties = spec.to_dict()["components"]["schemas"]["NullableTypes"][
        "properties"
    ]

    assert properties["name"] == {"type": "string", "nullable": True}

    expected_array = {
        "type": "array",
        "items": {"$ref": "#/components/schemas/Foo"},
        "nullable": True,
    }
    assert properties["foo_list"] == expected_array
    assert properties["many_foos"] == expected_array


def test_openapi_30_non_nullable_nested_schemas_are_unchanged():
    class NonNullableSchema(Schema):
        foo = fields.Nested(FooSchema)
        described_foo = fields.Nested(
            FooSchema, metadata={"description": "A foo"}
        )

    spec = make_spec("3.0.3")
    spec.components.schema("Foo", schema=FooSchema)
    spec.components.schema("NonNullable", schema=NonNullableSchema)

    properties = spec.to_dict()["components"]["schemas"]["NonNullable"][
        "properties"
    ]

    assert properties["foo"] == {"$ref": "#/components/schemas/Foo"}
    assert properties["described_foo"] == {
        "description": "A foo",
        "allOf": [{"$ref": "#/components/schemas/Foo"}],
    }


@pytest.mark.parametrize(
    ("openapi_version", "expected"),
    [
        (
            "2.0",
            {"$ref": "#/definitions/Foo", "x-nullable": True},
        ),
        (
            "3.1.0",
            {
                "anyOf": [
                    {"$ref": "#/components/schemas/Foo"},
                    {"type": "null"},
                ]
            },
        ),
    ],
)
def test_nullable_nested_behavior_outside_openapi_30_is_unchanged(
    openapi_version, expected
):
    spec = make_spec(openapi_version)
    register_issue_schemas(spec)

    document = spec.to_dict()
    schemas = (
        document["definitions"]
        if openapi_version == "2.0"
        else document["components"]["schemas"]
    )

    assert schemas["MySchema"]["properties"]["foo"] == expected

"""Regression tests for variadic parameters in model initialization."""

import pytest

from mesa.visualization.solara_viz import _check_model_params


def test_kwargs_is_not_a_required_model_param():
    """The issue scenario should not require a value for **kwargs."""

    class ModelWithKwargs:
        def __init__(self, width, height, **kwargs):
            pass

    _check_model_params(
        ModelWithKwargs.__init__, {"width": 10, "height": 10}
    )


def test_model_with_only_kwargs_needs_no_model_params():
    """A signature containing only **kwargs should accept an empty mapping."""

    class ModelWithOnlyKwargs:
        def __init__(self, **kwargs):
            pass

    _check_model_params(ModelWithOnlyKwargs.__init__, {})


def test_args_and_kwargs_are_not_required_model_params():
    """Both variadic parameter kinds should be ignored by required checks."""

    class ModelWithVariadicParams:
        def __init__(
            self, width, height, optional_param=10, *args, **kwargs
        ):
            pass

    _check_model_params(
        ModelWithVariadicParams.__init__, {"width": 10, "height": 10}
    )


def test_required_params_are_still_checked_when_kwargs_is_present():
    """Ignoring **kwargs must not disable validation of regular parameters."""

    class ModelWithKwargs:
        def __init__(self, width, height, **kwargs):
            pass

    with pytest.raises(
