"""Regression tests for counts of mid-circuit measurements with one-shot execution."""

import numpy as np
import pytest

import pennylane as qml


def _assert_integer_outcome_keys(counts):
    """MCM bit outcomes should be integer keys, not float keys such as 0.0."""
    assert all(isinstance(key, (int, np.integer)) for key in counts), counts


@pytest.mark.parametrize("mcm_method", ["deferred", "one-shot"])
@pytest.mark.parametrize("measured_outcome", [0, 1])
def test_single_mcm_counts_all_outcomes(mcm_method, measured_outcome):
    """All binary outcomes are returned, including an outcome with zero counts."""
    shots = 10
    dev = qml.device("default.qubit", wires=1, shots=shots)

    @qml.qnode(dev, mcm_method=mcm_method)
    def circuit():
        if measured_outcome:
            qml.PauliX(0)
        m = qml.measure(0)
        return qml.counts(m, all_outcomes=True)

    result = circuit()

    expected = {0: 0, 1: shots} if measured_outcome else {0: shots, 1: 0}
    assert result == expected
    assert set(result) == {0, 1}
    assert sum(result.values()) == shots
    _assert_integer_outcome_keys(result)


@pytest.mark.parametrize("measured_outcome", [0, 1])
def test_single_mcm_counts_without_all_outcomes(measured_outcome):
    """Requesting only observed outcomes must not introduce zero-count entries."""
    shots = 10
    dev = qml.device("default.qubit", wires=1, shots=shots)

    @qml.qnode(dev, mcm_method="one-shot")
    def circuit():
        if measured_outcome:
            qml.PauliX(0)
        m = qml.measure(0)
        return qml.counts(m)

    result = circuit()

    assert result == {measured_outcome: shots}
    assert sum(result.values()) == shots
    _assert_integer_outcome_keys(result)


@pytest.mark.parametrize("all_outcomes", [False, True])
def test_multiple_mcm_counts_all_outcomes(all_outcomes):
    """Counts of a sequence of MCMs include every bit string when requested."""
    shots = 7
    dev = qml.device("default.qubit", wires=2, shots=shots)

    @qml.qnode(dev, mcm_method="one-shot")
    def circuit():
        qml.PauliX(1)
        m0 = qml.measure(0)
        m1 = qml.measure(1)
        return qml.counts([m0, m1], all_outcomes=all_outcomes)

    result = circuit()

    if all_outcomes:
        expected = {"00": 0, "01": shots, "10": 0, "11": 0}
    else:
        expected = {"01": shots}

    assert result == expected
    assert sum(result.values()) == shots
    assert all(isinstance(key, str) for key in result)


def test_single_mcm_counts_all_outcomes_with_shot_vector():
    """All outcomes are supplied independently for every shot-vector bin."""
    shot_bins = [3, 4]
    dev = qml.device("default.qubit", wires=1, shots=shot_bins)

    @qml.qnode(dev, mcm_method="one-shot")
    def circuit():
        m = qml.measure(0)
        return qml.counts(m, all_outcomes=True)

    results = circuit()

    assert len(results) == len(shot_bins)
    for shots, result in zip(shot_bins, results):
        assert result == {0: shots, 1: 0}
        assert sum(result.values()) == shots
        _assert_integer_outcome_keys(result)


@pytest.mark.parametrize("measured_outcome", [0, 1])
def test_transformed_mcm_counts_use_actual_measurement_value_outcomes(measured_outcome):
    """All-outcomes handling must use the MeasurementValue's outcomes, not just 0 and 1."""
    shots = 10
    dev = qml.device("default.qubit", wires=1, shots=shots)

    @qml.qnode(dev, mcm_method="one-shot")
    def circuit():
        if measured_outcome:
            qml.PauliX(0)
        m = qml.measure(0)
        return qml.counts(op=2 * m, all_outcomes=True)

    result = circuit()

    expected = {0: 0, 2: shots} if measured_outcome else {0: shots, 2: 0}
    assert result == expected
    assert set(result) == {0, 2}
    assert sum(result.values()) == shots
    _assert_integer_outcome_keys(result)


def test_composite_transformed_mcm_counts_include_every_outcome():
    """Arithmetic over several MCMs can have more than the two raw bit outcomes."""
    shots = 9
    dev = qml.device("default.qubit", wires=2, shots=shots)

    @qml.qnode(dev, mcm_method="one-shot")
    def circuit():
        qml.PauliX(1)
        m0 = qml.measure(0)
        m1 = qml.measure(1)
        return qml.counts(op=m0 + 2 * m1, all_outcomes=True)

    result = circuit()

    # The observed values are m0=0 and m1=1, whose transformed value is 2.
    assert result == {0: 0, 1: 0, 2: shots, 3: 0}
    assert sum(result.values()) == shots
    _assert_integer_outcome_keys(result)


def test_one_shot_preserves_non_mcm_observable_count_keys():
    """Fixing MCM bit keys must not truncate eigenvalue keys of ordinary counts."""
    shots = 6
    eigenvalues = (-0.5, 1.5)
    observable = np.diag(eigenvalues)
    dev = qml.device("default.qubit", wires=2, shots=shots)

    @qml.qnode(dev, mcm_method="one-shot")
    def circuit():
        qml.measure(0)
        return qml.counts(op=qml.Hermitian(observable, wires=1), all_outcomes=True)

    result = circuit()

    # Wire 1 remains in |0>, so only the first eigenvalue is observed.
    assert result == {eigenvalues[0]: shots, eigenvalues[1]: 0}
    assert set(result) == set(eigenvalues)
    assert sum(result.values()) == shots

import pytest

from sqlglot import exp, parse_one


DIALECT = "duckdb"


def _round_trip(sql):
    """Parse DuckDB SQL and ensure its generated form preserves the same AST."""
    expression = parse_one(sql, read=DIALECT)
    rendered = expression.sql(DIALECT)
    assert parse_one(rendered, read=DIALECT) == expression
    return expression, rendered


def _compact(sql):
    return "".join(sql.upper().split())


def test_struct_pack_unpacks_columns_from_issue():
    expression, rendered = _round_trip(
        r"""SELECT id, struct_pack(*COLUMNS('m\d')) AS measurements
FROM many_measurements"""
    )

    assert expression.named_selects == ["id", "measurements"]
    assert _compact(rendered).count("*COLUMNS") == 1
    assert any(
        literal.is_string and literal.this == r"m\d"
        for literal in expression.find_all(exp.Literal)
    )


@pytest.mark.parametrize(
    "sql",
    [
        "SELECT *COLUMNS('m[0-9]') FROM many_measurements",
        "SELECT id, *COLUMNS('m[0-9]') FROM many_measurements",
        "SELECT *COLUMNS('m[0-9]'), id FROM many_measurements",
    ],
)
def test_unpack_columns_in_select_list(sql):
    _, rendered = _round_trip(sql)
    assert _compact(rendered) == _compact(sql)


@pytest.mark.parametrize(
    ("sql", "unpack_count"),
    [
        (
            r"SELECT struct_pack(id, *COLUMNS('m\d')) AS measurements "
            "FROM many_measurements",
            1,
        ),
        (
            r"SELECT struct_pack(*COLUMNS('m\d'), *COLUMNS('s\d')) "
            "AS measurements FROM many_measurements",
            2,
        ),
        (r"SELECT list_value(*COLUMNS('m\d')) FROM many_measurements", 1),
        (r"SELECT list_value( * columns('m\d') ) FROM many_measurements", 1),
    ],
)
def test_unpack_columns_in_function_arguments(sql, unpack_count):
    _, rendered = _round_trip(sql)
    assert _compact(rendered).count("*COLUMNS") == unpack_count


@pytest.mark.parametrize(
    "sql",
    [
        "SELECT * FROM tbl",
        "SELECT tbl.* FROM tbl",
        "SELECT COUNT(*) FROM tbl",
        "SELECT a * b FROM tbl",
    ],
)
def test_existing_star_syntax_is_unchanged(sql):
    assert parse_one(sql, read=DIALECT).sql(DIALECT) == sql


def test_plain_star_function_argument_is_not_unpacking():
    _, rendered = _round_trip("SELECT struct_pack(*) FROM tbl")
    assert "*" in rendered
    assert "COLUMNS" not in rendered.upper()

"""Regression tests for variadic parameters in model initialization."""

import pytest

from mesa.visualization.solara_viz import _check_model_params


def test_kwargs_only_signature_does_not_require_kwargs_parameter():
    """A **kwargs declaration is not itself a required model parameter."""

    class ModelWithKwargs:
        def __init__(self, **kwargs):
            pass

    # This is the reported failure: it used to raise
    # "Missing required model parameter: kwargs".
    _check_model_params(ModelWithKwargs.__init__, {})


def test_args_and_kwargs_are_ignored_when_checking_required_params():
    """Variadic parameters remain optional alongside ordinary parameters."""

    class ModelWithVariadicParams:
        def __init__(self, required_param, optional_param=10, *args, **kwargs):
            pass

    _check_model_params(
        ModelWithVariadicParams.__init__,
        {"required_param": 1},
    )


def test_required_params_are_still_checked_when_kwargs_is_present():
    """Ignoring **kwargs must not disable validation of real parameters."""

    class ModelWithKwargs:
        def __init__(self, required_param, optional_param=10, **kwargs):
            pass

    with pytest.raises(
        ValueError, match="Missing required model parameter: required_param"
    ):
        _check_model_params(ModelWithKwargs.__init__, {})


def test_required_keyword_only_param_is_still_checked_with_kwargs():
    """Keyword-only required parameters retain their normal validation."""

    class ModelWithKeywordOnlyParam:
        def __init__(self, *, required_param, optional_param=10, **kwargs):
            pass

    _check_model_params(
        ModelWithKeywordOnlyParam.__init__,
        {"required_param": 1},
    )

    with pytest.raises(
        ValueError, match="Missing required model parameter: required_param"
    ):
        _check_model_params(ModelWithKeywordOnlyParam.__init__, {})


def test_regular_parameter_named_kwargs_is_still_required():
    """Only the **kwargs parameter kind is special, not the name 'kwargs'."""

    class ModelWithRegularKwargsName:
        def __init__(self, kwargs):
            pass

    _check_model_params(ModelWithRegularKwargsName.__init__, {"kwargs": 1})

    with pytest.raises(ValueError, match="Missing required model parameter: kwargs"):
        _check_model_params(ModelWithRegularKwargsName.__init__, {})

