import pytest
from apispec import APISpec
from apispec.ext.marshmallow import MarshmallowPlugin
from marshmallow import Schema, fields


class FooSchema(Schema):
    bar = fields.Integer(required=True)


class MySchema(Schema):
    foo = fields.Nested(FooSchema, allow_none=True)


def make_spec(openapi_version="3.0.3", **plugin_kwargs):
    plugin = MarshmallowPlugin(**plugin_kwargs)
    spec = APISpec(
        title="Nullable nested schema test",
        version="1.0.0",
        openapi_version=openapi_version,
        plugins=[plugin],
    )
    return spec, plugin


def assert_openapi_30_nullable_ref(prop, ref, **extra_attributes):
    """Check the OpenAPI 3.0 representation proposed in the issue.

    OpenAPI 3.0 does not support {"type": "null"}, and "nullable" cannot
    be placed next to allOf to modify the referenced schema.
    """
    assert set(prop) == {"anyOf"} | set(extra_attributes)
    for key, value in extra_attributes.items():
        assert prop[key] == value

    alternatives = prop["anyOf"]
    assert len(alternatives) == 2
    assert {"type": "object", "nullable": True} in alternatives
    assert ref in alternatives

    # Reject both the original invalid form and an invalid JSON Schema 3.1
    # null-type branch used in an OpenAPI 3.0 document.
    assert {"type": "null"} not in alternatives
    assert "nullable" not in prop
    assert "allOf" not in prop
    assert "$ref" not in prop


@pytest.mark.parametrize("openapi_version", ["3.0.0", "3.0.3"])
def test_issue_example_generates_openapi_30_compliant_nullable_nested_schema(
    openapi_version,
):
    spec, _ = make_spec(openapi_version)
    spec.components.schema("MySchema", schema=MySchema)

    schemas = spec.to_dict()["components"]["schemas"]

    assert schemas["Foo"] == {
        "type": "object",
        "properties": {"bar": {"type": "integer"}},
        "required": ["bar"],
    }
    assert schemas["MySchema"]["type"] == "object"
    assert set(schemas["MySchema"]["properties"]) == {"foo"}
    assert_openapi_30_nullable_ref(
        schemas["MySchema"]["properties"]["foo"],
        {"$ref": "#/components/schemas/Foo"},
    )


def test_openapi_30_nullable_nested_schema_with_other_attributes():
    """Exercise the allOf path produced when a nested field has attributes."""

    class Child(Schema):
        name = fields.String()

    _, plugin = make_spec("3.0.3")
    prop = plugin.converter.field2property(
        fields.Nested(
            Child,
            allow_none=True,
            dump_only=True,
            metadata={"description": "An optional child"},
        )
    )

    assert_openapi_30_nullable_ref(
        prop,
        {"$ref": "#/components/schemas/Child"},
        description="An optional child",
        readOnly=True,
    )


def test_openapi_30_nullable_nested_schema_inside_list_items():
    class Child(Schema):
        name = fields.String()

    _, plugin = make_spec("3.0.3")
    prop = plugin.converter.field2property(
        fields.List(fields.Nested(Child, allow_none=True))
    )

    assert prop["type"] == "array"
    assert set(prop) == {"type", "items"}
    assert_openapi_30_nullable_ref(
        prop["items"], {"$ref": "#/components/schemas/Child"}
    )


def test_openapi_30_nullable_nested_many_retains_array_type():
    """allow_none on a many=True Nested field applies to the array itself."""

    class Child(Schema):
        name = fields.String()

    _, plugin = make_spec("3.0.3")
    prop = plugin.converter.field2property(
        fields.Nested(Child, many=True, allow_none=True)
    )

    assert prop == {
        "type": "array",
        "items": {"$ref": "#/components/schemas/Child"},
        "nullable": True,
    }


def test_openapi_30_nullable_non_nested_field_is_unchanged():
    _, plugin = make_spec("3.0.3")

    assert plugin.converter.field2property(fields.String(allow_none=True)) == {
        "type": "string",
        "nullable": True,
    }


def test_openapi_30_inline_nested_schema_uses_nullable_with_its_type():
    """Without a $ref, nullable already has a type assertion to modify."""

    class Child(Schema):
        name = fields.String()

    _, plugin = make_spec("3.0.3", schema_name_resolver=lambda schema: None)
    prop = plugin.converter.field2property(fields.Nested(Child, allow_none=True))

    assert prop == {
        "type": "object",
        "properties": {"name": {"type": "string"}},
        "nullable": True,
    }


@pytest.mark.parametrize(
    ("openapi_version", "expected"),
    [
        (
            "2.0",
            {"$ref": "#/definitions/Child", "x-nullable": True},
        ),
        (
            "3.1.0",
            {
                "anyOf": [
                    {"$ref": "#/components/schemas/Child"},
                    {"type": "null"},
                ]
            },
        ),
    ],
)
def test_nullable_nested_schema_other_openapi_versions_are_unchanged(
    openapi_version, expected
):
    class Child(Schema):
        name = fields.String()

    _, plugin = make_spec(openapi_version)

    assert plugin.converter.field2property(
        fields.Nested(Child, allow_none=True)
    ) == expected

