        ),
        (
            '<pre>before <code><a href="http://foo.com/">foo.com</a></code> after</pre>',
            fenced_code('before foo.com after'),
        ),
        (
            '<code><a href="http://one.example/">one</a> and '
            '<a href="http://two.example/">two</a></code>',
            '`one and two`',
        ),
    ],
)
def test_nested_and_multiple_links_inside_preformatted_tags(html, expected):
    assert md(html) == expected


def test_autolink_and_title_forms_are_also_suppressed_inside_code():
    autolink = '<code><a href="http://foo.com/">http://foo.com/</a></code>'
    titled_link = (
        '<pre><a href="http://foo.com/" title="Example">foo.com</a></pre>'
    )

    assert md(autolink) == '`http://foo.com/`'
    assert md(titled_link) == fenced_code('foo.com')
    assert md(
        "<code><a href='http://foo.com/'>foo.com</a></code>",
        default_title=True,
    ) == '`foo.com`'


def test_link_text_whitespace_is_preserved_inside_pre():
    html = "<pre><a href='http://foo.com/'> foo.com </a></pre>"
    assert md(html) == fenced_code(' foo.com ')


def test_links_outside_preformatted_tags_are_unchanged():
    assert md("<a href='http://foo.com/'>foo.com</a>") == (
        '[foo.com](http://foo.com/)'
    )
    assert md("<a href='http://foo.com/'>http://foo.com/</a>") == (
        '<http://foo.com/>'
    )

    # A code span contained by a link is different from a link contained by
    # a code span: the former should remain a linked code span.
    assert md("<a href='http://foo.com/'><code>foo.com</code></a>") == (
        '[`foo.com`](http://foo.com/)'
    )

