import hashin


@pytest.mark.parametrize("version", ["3.10", "3.11", "3.12", "3.100"])
def test_expand_python_version_supports_multi_digit_minor_versions(version):
    major, minor = version.split(".")

    expanded = hashin.expand_python_version(version)

    assert set(expanded) == {
