)
def test_expand_python_version_passes_non_major_minor_identifiers_through(version):
    assert hashin.expand_python_version(version) == [version]


def _release(filename, digest):
    return {
        "url": "https://files.pythonhosted.org/packages/example/{}".format(filename),
        "digests": {"sha256": digest},
    }


def _releases():
    return [
        _release(
            "example-1.0-cp310-cp310-manylinux2014_x86_64.whl",
            "a" * 64,
        ),
        _release(
            "example-1.0-cp39-cp39-manylinux2014_x86_64.whl",
            "b" * 64,
        ),
        _release("example-1.0-py3-none-any.whl", "c" * 64),
        _release("example-1.0-py2.py3-none-any.whl", "d" * 64),
        _release("example-1.0.tar.gz", "e" * 64),
    ]


def test_filter_releases_recognizes_python_310_wheel_identifiers():
    filtered = hashin.filter_releases(_releases(), ["3.10"])

    filenames = [release["url"].rsplit("/", 1)[-1] for release in filtered]
    assert filenames == [
        "example-1.0-cp310-cp310-manylinux2014_x86_64.whl",
        "example-1.0-py3-none-any.whl",
        "example-1.0-py2.py3-none-any.whl",
        "example-1.0.tar.gz",
    ]


def test_get_package_hashes_finds_python_310_releases_without_network():
    # Supplying lookup_memory and all digests keeps this regression test
    # entirely offline while exercising the public operation from the issue.
    data = {"info": {"name": "example"}, "releases": {"1.0": _releases()}}

    result = hashin.get_package_hashes(
        package="example",
        version="1.0",
        algorithm="sha256",
        python_versions=("3.10",),
        lookup_memory={"example": data},
    )

    assert result["package"] == "example"
    assert result["version"] == "1.0"
    assert {release["hash"] for release in result["hashes"]} == {
        "a" * 64,
        "c" * 64,
        "d" * 64,
        "e" * 64,
    }


def test_python_310_filter_still_rejects_releases_for_other_versions():
    data = {
        "info": {"name": "example"},
        "releases": {
            "1.0": [
                _release(
                    "example-1.0-cp39-cp39-manylinux2014_x86_64.whl",
                    "b" * 64,
                )
            ]
        },
    }

    with pytest.raises(hashin.PackageError, match="No releases could be found"):
        hashin.get_package_hashes(
            package="example",
            version="1.0",
            algorithm="sha256",
            python_versions=("3.10",),
            lookup_memory={"example": data},
        )

"""Regression tests for variable parameters in model initialization."""

import pytest
import solara

import mesa
from mesa.visualization.solara_viz import SolaraViz, _check_model_params


def test_kwargs_only_model_does_not_require_kwargs_parameter():
    """A **kwargs parameter is optional and must not need a literal kwargs entry."""

    class ModelWithKwargs:
        def __init__(self, **configuration):
            self.configuration = configuration

    _check_model_params(ModelWithKwargs.__init__, {})


def test_kwargs_model_still_accepts_required_and_optional_parameters():
    """Normal parameters retain their behavior when **kwargs is present."""

    class ModelWithKwargs:
        def __init__(self, required_param, optional_param=10, **kwargs):
            pass

    _check_model_params(ModelWithKwargs.__init__, {"required_param": 1})
    _check_model_params(
        ModelWithKwargs.__init__, {"required_param": 1, "optional_param": 5}
    )


def test_args_and_kwargs_are_not_required_parameters():
    """Neither variadic positional nor variadic keyword parameters are required."""

    class ModelWithVariableParameters:
        def __init__(self, required_param, *args, **kwargs):
            pass

    _check_model_params(ModelWithVariableParameters.__init__, {"required_param": 1})


def test_required_parameters_are_still_checked_when_kwargs_is_present():
    """Ignoring **kwargs must not disable validation of actual required parameters."""

    class ModelWithKwargs:
        def __init__(self, required_param, *, required_option, **kwargs):
            pass

    with pytest.raises(
        ValueError, match="^Missing required model parameter: required_param$"
    ):
        _check_model_params(ModelWithKwargs.__init__, {})

    with pytest.raises(
        ValueError, match="^Missing required model parameter: required_option$"
    ):
        _check_model_params(ModelWithKwargs.__init__, {"required_param": 1})

    _check_model_params(
        ModelWithKwargs.__init__, {"required_param": 1, "required_option": 2}
    )


def test_regular_parameter_named_kwargs_is_still_required():
    """The exemption is based on parameter kind, not merely the name ``kwargs``."""

    class ModelWithRegularKwargsName:
        def __init__(self, kwargs):
            self.kwargs = kwargs

    with pytest.raises(
        ValueError, match="^Missing required model parameter: kwargs$"
    ):
        _check_model_params(ModelWithRegularKwargsName.__init__, {})

    _check_model_params(ModelWithRegularKwargsName.__init__, {"kwargs": 1})


def test_solara_viz_renders_model_whose_init_has_kwargs():
    """Exercise the visualization path that previously reported missing kwargs."""

    class ModelWithKwargs(mesa.Model):
        def __init__(self, required_param, optional_param=10, **kwargs):
            super().__init__()
            self.required_param = required_param
            self.optional_param = optional_param
            self.configuration = kwargs

    model = ModelWithKwargs(1)

    solara.render(
        SolaraViz(
            model,
            components=[],
            model_params={"required_param": 1},
        ),
        handle_error=False,
    )

from __future__ import annotations

import shutil

import pytest
import tomlkit

from pdm.project.core import Project
from tests import FIXTURES

pytestmark = pytest.mark.usefixtures("local_finder")


def read_pyproject(project: Project) -> tomlkit.TOMLDocument:
    return tomlkit.parse(project.root.joinpath("pyproject.toml").read_text(encoding="utf-8"))


def table_of_lists(table) -> dict[str, list[str]]:
    return {name: list(dependencies) for name, dependencies in table.items()}


def add_requirement_through_setter(project: Project, group: str, requirement: str) -> None:
    """Update a group in the same way as the add command, without resolving packages."""
    dependencies, setter = project.use_pyproject_dependencies(group, dev=True)
    setter([*dependencies, requirement])
    project.pyproject.write()


@pytest.mark.parametrize("target_group", ["dev", "lint"])
def test_add_uses_requested_group_and_does_not_duplicate_legacy_editable_groups(
    project: Project, target_group: str
) -> None:
    legacy_groups = {
        "docs": ["-e ./packages/docs-tools"],
        "workspaces": [
            "-e ./packages/pkg-app",
            "-e ./packages/pkg-core",
        ],
    }
    project.pyproject.settings["dev-dependencies"] = legacy_groups
    project.pyproject.write()

    add_requirement_through_setter(project, target_group, "ruff>=0.9.6")

    document = read_pyproject(project)
    dependency_groups = document.get("dependency-groups", {})

    # The requested group, rather than the last legacy group visited by the
    # implementation, receives the new dependency.
    assert set(dependency_groups) == {target_group}
    assert list(dependency_groups[target_group]) == ["ruff>=0.9.6"]

    # Looking up the merged development dependencies must not migrate or copy
    # editable-only legacy groups into the PEP 735 table.
    assert table_of_lists(document["tool"]["pdm"]["dev-dependencies"]) == legacy_groups
    assert "workspaces" not in dependency_groups
    assert "docs" not in dependency_groups


@pytest.mark.parametrize(
    ("add_options", "target_group"),
    [
        (["-d"], "dev"),
        (["-d", "-G", "lint"], "lint"),
    ],
)
def test_pdm_add_with_legacy_editable_dependencies(
    project: Project, pdm, add_options: list[str], target_group: str
) -> None:
    editable_package = project.root / "packages" / "demo"
    shutil.copytree(FIXTURES / "projects" / "demo", editable_package)
    legacy_groups = {"workspaces": ["-e ./packages/demo"]}
    project.pyproject.settings["dev-dependencies"] = legacy_groups
    project.pyproject.write()

    # future-fstrings is supplied by the local package fixtures, so this
    # exercises the real add/lock command without requiring network access.
    pdm(
        ["add", *add_options, "--no-sync", "future-fstrings"],
        obj=project,
        strict=True,
    )

    document = read_pyproject(project)
    dependency_groups = document.get("dependency-groups", {})

    assert set(dependency_groups) == {target_group}
    added = list(dependency_groups[target_group])
    assert len(added) == 1
    assert added[0].startswith("future-fstrings")
    assert table_of_lists(document["tool"]["pdm"]["dev-dependencies"]) == legacy_groups


def test_add_to_existing_pep735_group_preserves_unrelated_legacy_groups(project: Project) -> None:
    legacy_groups = {"workspaces": ["-e ./packages/pkg-app"]}
    project.pyproject._data["dependency-groups"] = {"lint": ["pytest>=7.0"]}
    project.pyproject.settings["dev-dependencies"] = legacy_groups
    project.pyproject.write()

    add_requirement_through_setter(project, "lint", "ruff>=0.9.6")

    document = read_pyproject(project)
    dependency_groups = document["dependency-groups"]
    assert table_of_lists(dependency_groups) == {
        "lint": ["pytest>=7.0", "ruff>=0.9.6"]
    }
    assert table_of_lists(document["tool"]["pdm"]["dev-dependencies"]) == legacy_groups


def test_add_normal_requirement_to_legacy_editable_group_preserves_editable(
    project: Project,
) -> None:
    """A fix must not avoid duplication by dropping editables from the target group."""
    editable = "-e ./packages/pkg-app"
    project.pyproject.settings["dev-dependencies"] = {"dev": [editable]}
    project.pyproject.write()

    dependencies, setter = project.use_pyproject_dependencies("dev", dev=True)
    # The add command writes the returned dependencies back together with the
    # new requirement, so the existing editable must still be exposed here.
    assert list(dependencies) == [editable]
    setter([*dependencies, "ruff>=0.9.6"])
    project.pyproject.write()

    document = read_pyproject(project)
    assert table_of_lists(document["tool"]["pdm"]["dev-dependencies"]) == {
        "dev": [editable]
    }
    assert table_of_lists(document["dependency-groups"]) == {
        "dev": ["ruff>=0.9.6"]
    }

import pytest
from apispec import APISpec
from apispec.ext.marshmallow import MarshmallowPlugin
from marshmallow import Schema, fields


class FooSchema(Schema):
    bar = fields.Integer(required=True)


def render_foo_property(openapi_version, field):
    """Render a schema containing ``foo`` through the public APISpec API."""
    spec = APISpec(
        title="My API Spec",
        version="1.0.0",
        openapi_version=openapi_version,
        plugins=[MarshmallowPlugin()],
    )

    class MySchema(Schema):
        foo = field

    spec.components.schema("Foo", schema=FooSchema)
    spec.components.schema("MySchema", schema=MySchema)

    document = spec.to_dict()
    schemas = (
        document["definitions"]
        if openapi_version == "2.0"
        else document["components"]["schemas"]
    )
    return schemas["MySchema"]["properties"]["foo"]


@pytest.mark.parametrize("openapi_version", ["3.0.0", "3.0.3"])
def test_openapi_30_nullable_nested_ref_uses_anyof(openapi_version):
    """A nullable modifier must not be placed next to an allOf reference."""
    prop = render_foo_property(
        openapi_version,
        fields.Nested(FooSchema, allow_none=True),
    )

    assert prop == {
        "anyOf": [
            {"type": "object", "nullable": True},
            {"$ref": "#/components/schemas/Foo"},
        ]
    }


@pytest.mark.parametrize(
    ("field_kwargs", "expected_extra"),
    [
        (
            {"metadata": {"description": "An optional Foo"}},
            {"description": "An optional Foo"},
        ),
        ({"dump_only": True}, {"readOnly": True}),
    ],
)
def test_openapi_30_nullable_nested_ref_with_sibling_attributes(
    field_kwargs, expected_extra
):
    """Metadata makes Nested use allOf internally, but must not bypass the fix."""
    prop = render_foo_property(
        "3.0.3",
        fields.Nested(FooSchema, allow_none=True, **field_kwargs),
    )

    assert prop == {
        **expected_extra,
        "anyOf": [
            {"type": "object", "nullable": True},
            {"$ref": "#/components/schemas/Foo"},
        ],
    }
    assert "nullable" not in prop
    assert "allOf" not in prop


@pytest.mark.parametrize("allow_none", [None, False])
def test_openapi_30_non_nullable_nested_ref_is_unchanged(allow_none):
    kwargs = {} if allow_none is None else {"allow_none": allow_none}
    prop = render_foo_property(
        "3.0.3",
        fields.Nested(FooSchema, **kwargs),
    )

    assert prop == {"$ref": "#/components/schemas/Foo"}


def test_openapi_30_nullable_nested_many_remains_a_nullable_array():
    """For many=True, nullable modifies the array type in the same object."""
    prop = render_foo_property(
        "3.0.3",
        fields.Nested(FooSchema, many=True, allow_none=True),
    )

    assert prop == {
        "type": "array",
        "items": {"$ref": "#/components/schemas/Foo"},
        "nullable": True,
    }


def test_openapi_30_regular_nullable_field_is_unchanged():
    """nullable remains valid when a type assertion is in the same object."""
    prop = render_foo_property(
        "3.0.3",
        fields.String(allow_none=True),
    )

    assert prop == {"type": "string", "nullable": True}


@pytest.mark.parametrize(
    ("openapi_version", "expected"),
    [
        (
            "2.0",
            {"$ref": "#/definitions/Foo", "x-nullable": True},
        ),
        (
            "3.1.0",
            {
                "anyOf": [
                    {"$ref": "#/components/schemas/Foo"},
                    {"type": "null"},
                ]
            },
        ),
    ],
)
def test_nullable_nested_ref_other_openapi_versions_are_unchanged(
    openapi_version, expected
):
    prop = render_foo_property(
        openapi_version,
        fields.Nested(FooSchema, allow_none=True),
    )

    assert prop == expected

