import pytest

from markdownify import markdownify as md


NEWLINE = chr(10)
CODE_FENCE = chr(96) * 3
PREFORMATTED_FOO = NEWLINE.join(
    ["", CODE_FENCE, "foo.com", CODE_FENCE, ""]
)


@pytest.mark.parametrize(
    "html, expected",
    [
        (
            "<code><a href='http://foo.com/'>foo.com</a></code>",
            "`foo.com`",
        ),
        (
            "<pre><a href='http://foo.com/'>foo.com</a></pre>",
            PREFORMATTED_FOO,
        ),
        (
            "<pre><code><a href='http://foo.com/'>foo.com</a></code></pre>",
            PREFORMATTED_FOO,
        ),
    ],
)
def test_links_inside_preformatted_tags_are_rendered_as_text(html, expected):
    assert md(html) == expected


def test_deeply_nested_link_inside_code_is_rendered_as_text():
    html = (
        "<code>before <span><a href='http://foo.com/'>foo.com</a></span>"
        " after</code>"
    )
    assert md(html) == "`before foo.com after`"


@pytest.mark.parametrize("tag", ["kbd", "samp"])
def test_links_inside_other_code_elements_are_rendered_as_text(tag):
    html = "<{0}><a href='http://foo.com/'>foo.com</a></{0}>".format(tag)
    assert md(html) == "`foo.com`"


@pytest.mark.parametrize(
    "options",
    [
        {},
        {"autolinks": False},
        {"default_title": True},
    ],
)
def test_link_options_do_not_create_links_inside_code(options):
    html = "<code><a href='http://foo.com/'>foo.com</a></code>"
    assert md(html, **options) == "`foo.com`"


def test_link_title_is_not_emitted_inside_preformatted_text():
    html = (
        "<pre><a href='http://foo.com/' title='Example'>foo.com</a></pre>"
    )
    assert md(html) == PREFORMATTED_FOO


def test_link_text_remains_literal_inside_code():
    html = "<code><a href='http://foo.com/'>foo_bar *baz*</a></code>"
    assert md(html) == "`foo_bar *baz*`"


def test_links_outside_preformatted_tags_are_still_converted():
    html = (
        "before <code><a href='http://foo.com/'>foo.com</a></code> "
        "after <a href='http://bar.com/'>bar</a>"
    )
    assert md(html) == "before `foo.com` after [bar](http://bar.com/)"

    # The ordinary autolink shortcut must also remain available.
    assert md("<a href='http://foo.com/'>http://foo.com/</a>") == (
        "<http://foo.com/>"
    )

import pytest

import sqlglot
from sqlglot.errors import ParseError


@pytest.mark.parametrize(
    ("source_sql", "expected_tsql"),
    [
        (
            "SELECT 'hello' || 'world' FROM t",
            "SELECT 'hello' + 'world' FROM t",
        ),
        (
            "SELECT first_name || last_name FROM users",
            "SELECT first_name + last_name FROM users",
        ),
        (
            "SELECT a || b || c FROM t",
            "SELECT a + b + c FROM t",
        ),
        (
            "SELECT UPPER(first_name || ' ' || last_name) FROM users",
            "SELECT UPPER(first_name + ' ' + last_name) FROM users",
        ),
        (
            "SELECT * FROM users WHERE first_name || last_name = 'AdaLovelace'",
            "SELECT * FROM users WHERE first_name + last_name = 'AdaLovelace'",
        ),
    ],
)
def test_tsql_generates_plus_for_string_concatenation(source_sql, expected_tsql):
    """TSQL output must not rely on the Azure-only || concatenation operator."""
    assert sqlglot.transpile(source_sql, read="postgres", write="tsql") == [expected_tsql]


def test_tsql_double_pipe_is_not_accepted_as_string_concatenation():
    """SQL Server uses neither || for concatenation nor for logical OR."""
    with pytest.raises(ParseError):
        sqlglot.parse_one("SELECT a || b FROM t", dialect="tsql")


def test_tsql_plus_operator_is_preserved_when_transpiling():
    source_sql = "SELECT a + b FROM t"

    assert sqlglot.transpile(source_sql, read="tsql", write="tsql") == [source_sql]
    assert sqlglot.transpile(source_sql, read="tsql", write="postgres") == [source_sql]


@pytest.mark.parametrize(
    ("write_dialect", "expected_sql"),
    [
        ("postgres", "SELECT a || b FROM t"),
        ("sqlite", "SELECT a || b FROM t"),
        ("mysql", "SELECT CONCAT(a, b) FROM t"),
    ],
)
def test_string_concatenation_in_other_dialects_is_unchanged(write_dialect, expected_sql):
    """The TSQL compatibility fix must not change other dialects' generators."""
    assert sqlglot.transpile(
        "SELECT a || b FROM t", read="postgres", write=write_dialect
    ) == [expected_sql]

"""Regression tests for variadic parameters in Solara model initialization."""

import pytest

from mesa.visualization.solara_viz import _check_model_params


def test_kwargs_only_model_does_not_require_kwargs_parameter():
    """A model accepting only **kwargs can be created without model params."""

    class ModelWithKwargs:
        def __init__(self, **kwargs):
            pass

    _check_model_params(ModelWithKwargs.__init__, {})


def test_kwargs_is_ignored_alongside_required_and_optional_params():
    """The presence of **kwargs must not change normal parameter handling."""

    class ModelWithKwargs:
        def __init__(self, required_param, optional_param=10, **kwargs):
            pass

    # Optional parameters may still be omitted or explicitly supplied.
    _check_model_params(ModelWithKwargs.__init__, {"required_param": 1})
    _check_model_params(
        ModelWithKwargs.__init__, {"required_param": 1, "optional_param": 5}
    )

    # Ignoring **kwargs must not suppress validation of actual required params.
    with pytest.raises(
        ValueError, match="Missing required model parameter: required_param"
    ):
        _check_model_params(ModelWithKwargs.__init__, {})


def test_args_is_not_treated_as_a_required_model_parameter():
    """Variadic positional parameters also need no value in model_params."""

    class ModelWithArgs:
        def __init__(self, required_param, *args):
            pass

    _check_model_params(ModelWithArgs.__init__, {"required_param": 1})

    with pytest.raises(
        ValueError, match="Missing required model parameter: required_param"
    ):
        _check_model_params(ModelWithArgs.__init__, {})


def test_variadic_parameters_are_detected_by_kind_not_by_name():
    """Custom names for *args and **kwargs must work as well."""

    class ModelWithCustomVariadicNames:
        def __init__(self, required_param, *values, **options):
            pass

    _check_model_params(
        ModelWithCustomVariadicNames.__init__, {"required_param": 1}
    )


def test_regular_required_parameter_named_kwargs_is_still_required():
    """Only the special **kwargs parameter should be ignored."""

    class ModelWithRequiredKwargsParameter:
        def __init__(self, kwargs):
            pass

    with pytest.raises(ValueError, match="Missing required model parameter: kwargs"):
        _check_model_params(ModelWithRequiredKwargsParameter.__init__, {})


def test_required_keyword_only_parameter_is_still_checked_with_kwargs():
    """A catch-all **kwargs does not make required keyword-only params optional."""

    class ModelWithRequiredKeywordOnlyParameter:
        def __init__(self, *, required_param, **kwargs):
            pass

    _check_model_params(
        ModelWithRequiredKeywordOnlyParameter.__init__, {"required_param": 1}
    )

    with pytest.raises(
        ValueError, match="Missing required model parameter: required_param"
    ):
        _check_model_params(ModelWithRequiredKeywordOnlyParameter.__init__, {})

"""Tests for counts of mid-circuit measurements with dynamic one-shot execution."""

from numbers import Integral

import pennylane as qml
import pytest


def _assert_counts_equal(result, expected, integer_keys=True):
    """Compare counts while also checking the public outcome-key types."""
    assert len(result) == len(expected)
    assert set(result) == set(expected)

    for outcome, count in expected.items():
        assert int(result[outcome]) == count

    if integer_keys:
        # In particular, float keys such as 0.0 must not be used for MCM outcomes.
        assert all(isinstance(outcome, Integral) for outcome in result)


@pytest.mark.parametrize("mcm_method", ["deferred", "one-shot"])
@pytest.mark.parametrize("flip_qubit", [False, True])
def test_single_mcm_counts_all_outcomes(mcm_method, flip_qubit):
    """All binary outcomes are returned, including an outcome with zero counts."""
    shots = 10
    dev = qml.device("default.qubit", wires=1, shots=shots)

    @qml.qnode(dev, mcm_method=mcm_method)
    def circuit():
        if flip_qubit:
            qml.PauliX(0)
        m = qml.measure(0)
        return qml.counts(m, all_outcomes=True)

    result = circuit()
    observed_outcome = int(flip_qubit)
    expected = {0: 0, 1: 0}
    expected[observed_outcome] = shots

    _assert_counts_equal(result, expected)


@pytest.mark.parametrize("explicit_false", [False, True])
def test_single_mcm_counts_without_all_outcomes(explicit_false):
    """Requesting all outcomes must not change the default observed-only behavior."""
    shots = 10
    dev = qml.device("default.qubit", wires=1, shots=shots)

    @qml.qnode(dev, mcm_method="one-shot")
    def circuit():
        m = qml.measure(0)
        if explicit_false:
            return qml.counts(m, all_outcomes=False)
        return qml.counts(m)

    result = circuit()
    _assert_counts_equal(result, {0: shots})


@pytest.mark.parametrize("mcm_method", ["deferred", "one-shot"])
def test_multiple_mcm_counts_all_outcomes(mcm_method):
    """Counts of a list of MCMs include every possible bit-string outcome."""
    shots = 8
    dev = qml.device("default.qubit", wires=2, shots=shots)

    @qml.qnode(dev, mcm_method=mcm_method)
    def circuit():
        m0 = qml.measure(0)
        m1 = qml.measure(1)
        return qml.counts([m0, m1], all_outcomes=True)

    result = circuit()
    expected = {"00": shots, "01": 0, "10": 0, "11": 0}

    _assert_counts_equal(result, expected, integer_keys=False)
    assert all(isinstance(outcome, str) for outcome in result)


@pytest.mark.parametrize("mcm_method", ["deferred", "one-shot"])
def test_transformed_mcm_counts_all_outcomes(mcm_method):
    """All outcomes means all branches of the measurement value, not just 0 and 1."""
    shots = 6
    dev = qml.device("default.qubit", wires=1, shots=shots)

    @qml.qnode(dev, mcm_method=mcm_method)
    def circuit():
        m = qml.measure(0)
        return qml.counts(2 * m, all_outcomes=True)

    result = circuit()

    # The possible values of 2 * m are 0 and 2. An outcome of 1 is impossible.
    # One-shot execution must use these measurement-value branches just as
    # deferred execution does, rather than assuming the outcomes are 0 and 1.
    _assert_counts_equal(result, {0: shots, 2: 0})


def test_single_mcm_counts_all_outcomes_with_shot_vector():
    """Each shot-vector bin independently contains all outcomes."""
    shot_bins = [3, 5]
    dev = qml.device("default.qubit", wires=1, shots=shot_bins)

    @qml.qnode(dev, mcm_method="one-shot")
    def circuit():
        m = qml.measure(0)
        return qml.counts(m, all_outcomes=True)

    results = circuit()

    assert isinstance(results, tuple)
    assert len(results) == len(shot_bins)
    for result, shots in zip(results, shot_bins):
        _assert_counts_equal(result, {0: shots, 1: 0})

import pytest

import sqlglot
from sqlglot import exp


def _transpile(sql: str, read: str = "postgres", write: str = "tsql") -> str:
    return sqlglot.transpile(sql, read=read, write=write)[0]


@pytest.mark.parametrize("source_dialect", ["postgres", "oracle", "sqlite"])
def test_double_pipe_is_generated_as_plus_for_tsql(source_dialect):
    sql = "SELECT 'hello' || 'world'"

    assert _transpile(sql, read=source_dialect) == "SELECT 'hello' + 'world'"


def test_chained_string_concatenation_uses_plus():
    sql = "SELECT first_name || ' ' || last_name FROM users"

    assert _transpile(sql) == "SELECT first_name + ' ' + last_name FROM users"


@pytest.mark.parametrize(
    "sql",
    [
        "SELECT 'a' || 'b' || 'c' || 'd'",
        "SELECT UPPER(first_name) || '_' || LOWER(last_name) FROM users",
        "SELECT ('prefix_' || category) || ('_' || id) FROM items",
        "SELECT * FROM users WHERE full_name = first_name || ' ' || last_name",
        "SELECT 'ID: ' || CAST(id AS VARCHAR) || ' Name: ' || name FROM users",
    ],
)
def test_every_double_pipe_is_converted_in_complex_expressions(sql):
    expression = sqlglot.parse_one(sql, read="postgres")
    concatenation_count = len(list(expression.find_all(exp.DPipe)))

    generated = expression.sql(dialect="tsql")

    assert concatenation_count > 0
    assert "||" not in generated
    assert generated.count("+") == concatenation_count


def test_dpipe_expression_generates_tsql_plus_directly():
    expression = exp.DPipe(
        this=exp.Literal.string("hello"),
        expression=exp.Literal.string("world"),
    )

    assert expression.sql(dialect="tsql") == "'hello' + 'world'"


@pytest.mark.parametrize("target_dialect", ["postgres", "oracle", "sqlite"])
def test_double_pipe_generation_is_unchanged_for_other_dialects(target_dialect):
    sql = "SELECT 'hello' || 'world'"

    assert _transpile(sql, write=target_dialect) == "SELECT 'hello' || 'world'"


@pytest.mark.parametrize(
    "sql",
    [
        "SELECT 'hello' + 'world'",
        "SELECT first_name + ' ' + last_name FROM users",
        "SELECT price + tax FROM orders",
    ],
)
def test_native_tsql_plus_expressions_are_preserved(sql):
    assert _transpile(sql, read="tsql") == sql

import pytest
from apispec import APISpec
from apispec.ext.marshmallow import MarshmallowPlugin
from marshmallow import Schema, fields


class FooSchema(Schema):
    bar = fields.Integer(required=True)


def build_foo_property(
    field,
    openapi_version="3.0.3",
    plugin=None,
    register_foo=True,
):
    spec = APISpec(
        title="My API Spec",
        version="1.0.0",
        openapi_version=openapi_version,
        plugins=[plugin or MarshmallowPlugin()],
    )

    class MySchema(Schema):
        foo = field

    if register_foo:
        spec.components.schema("Foo", schema=FooSchema)
    spec.components.schema("MySchema", schema=MySchema)

    document = spec.to_dict()
    if openapi_version.startswith("2."):
        schemas = document["definitions"]
    else:
        schemas = document["components"]["schemas"]
    return schemas["MySchema"]["properties"]["foo"]


@pytest.mark.parametrize("openapi_version", ["3.0.0", "3.0.3"])
def test_nullable_nested_schema_uses_anyof(openapi_version):
    foo = build_foo_property(
        fields.Nested(FooSchema, allow_none=True), openapi_version
    )

    assert foo == {
        "anyOf": [
            {"type": "object", "nullable": True},
            {"$ref": "#/components/schemas/Foo"},
        ]
    }


def test_nullable_nested_schema_with_metadata_does_not_use_nullable_allof():
    # Metadata causes apispec to represent the nested reference with allOf.
    # nullable must not simply be added alongside that allOf.
    foo = build_foo_property(
        fields.Nested(
            FooSchema,
            allow_none=True,
            metadata={"description": "A nullable foo"},
        )
    )

    assert foo["description"] == "A nullable foo"
    assert set(foo) == {"description", "anyOf"}
    assert len(foo["anyOf"]) == 2
    assert {"type": "object", "nullable": True} in foo["anyOf"]
    assert {"$ref": "#/components/schemas/Foo"} in foo["anyOf"]


@pytest.mark.parametrize("field_kwargs", [{}, {"allow_none": False}])
def test_non_nullable_nested_schema_remains_a_plain_reference(field_kwargs):
    foo = build_foo_property(fields.Nested(FooSchema, **field_kwargs))

    assert foo == {"$ref": "#/components/schemas/Foo"}


def test_nullable_nested_collection_keeps_array_type():
    foo = build_foo_property(fields.Nested(FooSchema, many=True, allow_none=True))

    # The array type is asserted in the same Schema Object, so nullable is
    # sufficient here; the object-reference anyOf form would be incorrect.
    assert foo == {
        "type": "array",
        "items": {"$ref": "#/components/schemas/Foo"},
        "nullable": True,
    }


def test_nullable_scalar_field_is_unchanged():
    foo = build_foo_property(fields.String(allow_none=True))

    assert foo == {"type": "string", "nullable": True}


def test_nullable_inline_nested_schema_keeps_object_type():
    plugin = MarshmallowPlugin(schema_name_resolver=lambda schema: None)
    foo = build_foo_property(
        fields.Nested(FooSchema, allow_none=True),
        plugin=plugin,
        # Registering Foo first would make the converter reuse its reference
        # even with a name resolver that otherwise requests inline schemas.
        register_foo=False,
    )

    assert foo["type"] == "object"
    assert foo["nullable"] is True
    assert foo["properties"] == {"bar": {"type": "integer"}}
    assert foo["required"] == ["bar"]
    assert "$ref" not in foo
    assert "allOf" not in foo
    assert "anyOf" not in foo


def test_openapi_2_nullable_nested_schema_is_unchanged():
    foo = build_foo_property(
        fields.Nested(FooSchema, allow_none=True), openapi_version="2.0"
    )

    assert foo == {"$ref": "#/definitions/Foo", "x-nullable": True}


def test_openapi_31_nullable_nested_schema_is_unchanged():
    foo = build_foo_property(
        fields.Nested(FooSchema, allow_none=True), openapi_version="3.1.0"
    )

    assert foo == {
        "anyOf": [
            {"$ref": "#/components/schemas/Foo"},
            {"type": "null"},
        ]
    }

import pytest

from markdownify import markdownify as md


NEWLINE = chr(10)
CODE_FENCE = chr(96) * 3


def fenced_code(text):
    return NEWLINE + CODE_FENCE + NEWLINE + text + NEWLINE + CODE_FENCE + NEWLINE


def test_anchor_inside_code_is_rendered_as_plaintext():
    html = "<code><a href='http://foo.com/'>foo.com</a></code>"
    assert md(html) == "`foo.com`"


def test_anchor_inside_pre_is_rendered_as_plaintext():
    html = "<pre><a href='http://foo.com/'>foo.com</a></pre>"
    assert md(html) == fenced_code("foo.com")


@pytest.mark.parametrize("tag", ["kbd", "samp"])
def test_anchor_inside_other_preformatted_inline_tags_is_plaintext(tag):
    html = "<{0}><a href='http://foo.com/'>foo.com</a></{0}>".format(tag)
    assert md(html) == "`foo.com`"


def test_deeply_nested_anchor_inside_preformatted_content_is_plaintext():
    html = (
        "<pre><code>Before <span><a href='http://foo.com/' "
        "title='Foo'>foo.com</a></span> after</code></pre>"
    )
    assert md(html) == fenced_code("Before foo.com after")


def test_all_anchors_and_surrounding_text_are_preserved():
    assert md(
        "<code><a href='http://foo.com/'>foo.com</a> and "
        "<a href='http://bar.com/'>bar.com</a></code>"
    ) == "`foo.com and bar.com`"

    assert md(
        "<pre>Visit <a href='http://foo.com/'>foo.com</a> for details</pre>"
    ) == fenced_code("Visit foo.com for details")


def test_link_options_do_not_create_markup_inside_code():
    # The automatic-link shortcut must not be used inside a code span.
    assert md(
        "<code><a href='http://foo.com/'>http://foo.com/</a></code>"
    ) == "`http://foo.com/`"

    # A generated title must not cause full link syntax to be emitted either.
    assert md(
        "<code><a href='http://foo.com/'>foo.com</a></code>",
        default_title=True,
    ) == "`foo.com`"


def test_links_outside_preformatted_content_are_still_converted():
    assert md(
        "<a href='http://foo.com/'>foo.com</a>"
    ) == "[foo.com](http://foo.com/)"

    assert md(
        "<a href='http://foo.com/'>http://foo.com/</a>"
    ) == "<http://foo.com/>"

    assert md(
        "<a href='http://foo.com/' title='Foo'>foo.com</a>"
    ) == '[foo.com](http://foo.com/ "Foo")'


def test_link_suppression_is_limited_to_preformatted_ancestors():
    html = (
        "<p><a href='http://outside.com/'>outside</a> "
        "<code><a href='http://inside.com/'>inside</a></code></p>"
    )
    expected = (
        NEWLINE + NEWLINE
        + "[outside](http://outside.com/) `inside`"
        + NEWLINE + NEWLINE
    )
    assert md(html) == expected


def test_code_inside_an_anchor_does_not_suppress_the_link():
    # The reverse nesting is valid Markdown and must remain a link.
    assert md(
        "<a href='http://foo.com/'><code>foo.com</code></a>"
    ) == "[`foo.com`](http://foo.com/)"

import pytest

import hashin


@pytest.mark.parametrize("version", ["3.5", "3.9", "3.10", "3.11", "3.100"])
def test_expand_python_version_supports_multi_digit_minor_versions(version):
    # Expansion is based on the version's syntax, not on whether that Python
    # release currently exists. In particular, the issue's proposed regex puts
    # no two-digit limit on the minor version.
    major, minor = version.split(".")

    assert hashin.expand_python_version(version) == {
        version,
        "cp{}{}".format(major, minor),
        "py{}".format(major),
        "py{}.{}".format(major, minor),
        "py{}{}".format(major, minor),
        "source",
        "py2.py3",
    }


@pytest.mark.parametrize("version", ["py3", "py310", "cp310", "3", "3.10.1", "3.10a"])
def test_expand_python_version_leaves_other_identifiers_unchanged(version):
    assert hashin.expand_python_version(version) == [version]


@pytest.mark.parametrize(
    ("python_version", "wheel_tag"),
    [
        ("3.10", "cp310"),
        ("3.11", "cp311"),
        ("3.100", "cp3100"),
    ],
)
def test_get_package_hashes_finds_wheels_for_multi_digit_python_versions(
    python_version, wheel_tag
):
    expected_hash = "a" * 64
    data = {
        "info": {"name": "example", "version": "1.0"},
        "releases": {
            "1.0": [
                {
                    "url": (
                        "https://files.pythonhosted.org/packages/"
                        "example-1.0-{}-none-any.whl".format(wheel_tag)
                    ),
                    "digests": {"sha256": expected_hash},
                },
                {
                    "url": (
                        "https://files.pythonhosted.org/packages/"
                        "example-1.0-cp39-none-any.whl"
                    ),
                    "digests": {"sha256": "b" * 64},
                },
            ]
        },
    }

    result = hashin.get_package_hashes(
        "example",
        version="1.0",
        python_versions=[python_version],
        lookup_memory={"example": data},
    )

    assert result == {
        "package": "example",
        "version": "1.0",
        "hashes": [{"hash": expected_hash}],
    }

from typing import Optional

import pytest

