import pytest
import tomlkit


def _read_pyproject(project):
    return tomlkit.parse((project.root / "pyproject.toml").read_text(encoding="utf-8"))


def _add_requirement_to_group(project, group, requirement):
    """Use the same Project API as the add command, without resolving packages."""
    dependencies, setter = project.use_pyproject_dependencies(group, dev=True)
    original_dependencies = list(dependencies)
    setter([*original_dependencies, requirement])
    project.pyproject.write()
    return original_dependencies


@pytest.mark.parametrize("target_group", ["dev", "lint"])
def test_add_dev_dependency_uses_target_group_without_copying_editable_groups(project, target_group):
    legacy_groups = {
        "workspaces": [
            "-e ./packages/pkg-app",
            "-e ./packages/pkg-core",
        ],
        "docs": ["-e ./packages/pkg-docs"],
    }
    project.pyproject.settings["dev-dependencies"] = legacy_groups

    original_dependencies = _add_requirement_to_group(project, target_group, "ruff>=0.9.6")

    assert original_dependencies == []
    document = _read_pyproject(project)
    assert document["dependency-groups"].unwrap() == {target_group: ["ruff>=0.9.6"]}
    assert document["tool"]["pdm"]["dev-dependencies"].unwrap() == legacy_groups


def test_add_to_existing_group_does_not_duplicate_mixed_legacy_editable_group(project):
    """A legacy group containing an editable must remain only in the legacy table."""
    legacy_groups = {
        "workspaces": [
            "-e ./packages/pkg-app",
            "pytest>=6.0",
        ],
        "docs": ["-e ./packages/pkg-docs"],
    }
    existing_groups = {
        "lint": ["black>=24.0"],
        "test": ["pytest-cov>=5.0"],
    }
    project.pyproject.settings["dev-dependencies"] = legacy_groups
    project.pyproject._data["dependency-groups"] = existing_groups

    original_dependencies = _add_requirement_to_group(project, "lint", "ruff>=0.9.6")

    assert original_dependencies == ["black>=24.0"]
    document = _read_pyproject(project)

    # Both legacy groups contain editables. Neither group may be duplicated in
    # dependency-groups, including the mixed group's non-editable requirement.
    assert document["dependency-groups"].unwrap() == {
        "lint": ["black>=24.0", "ruff>=0.9.6"],
        "test": ["pytest-cov>=5.0"],
    }
    assert document["tool"]["pdm"]["dev-dependencies"].unwrap() == legacy_groups


@pytest.mark.parametrize(
    "options,target_group",
    [
        (["-d"], "dev"),
        (["-dG", "lint"], "lint"),
    ],
)
def test_pdm_add_dev_dependency_with_legacy_dev_dependencies(
    project, working_set, pdm, options, target_group
):
    # Exercise the complete CLI workflow using the local package fixtures.
    project.pyproject.settings["dev-dependencies"] = {"workspaces": ["idna"]}
    project.pyproject.write()

    pdm(["add", *options, "requests"], obj=project, strict=True)

    document = _read_pyproject(project)
    dependency_groups = document.get("dependency-groups", {})
    assert target_group in dependency_groups
    assert any(requirement.startswith("requests") for requirement in dependency_groups[target_group])
    assert not any(
        requirement.startswith("requests") for requirement in dependency_groups.get("workspaces", [])
    )
    assert document["tool"]["pdm"]["dev-dependencies"].unwrap() == {"workspaces": ["idna"]}

import pytest

from markdownify import markdownify as md


NEWLINE = chr(10)
FENCE = chr(96) * 3


def fenced_code_block(text):
    return NEWLINE + FENCE + NEWLINE + text + NEWLINE + FENCE + NEWLINE


def test_link_inside_code_is_rendered_as_plain_text():
    html = "<code><a href='http://foo.com/'>foo.com</a></code>"
    assert md(html) == "`foo.com`"


def test_link_inside_pre_is_rendered_as_plain_text():
    html = "<pre><a href='http://foo.com/'>foo.com</a></pre>"
    assert md(html) == fenced_code_block("foo.com")


def test_link_inside_nested_pre_code_is_rendered_as_plain_text():
    html = "<pre><code><a href='http://foo.com/'>foo.com</a></code></pre>"
    assert md(html) == fenced_code_block("foo.com")


@pytest.mark.parametrize("tag", ["code", "kbd", "samp"])
def test_links_inside_inline_preformatted_tags_are_plain_text(tag):
    html = "<{0}><a href='http://foo.com/'>foo.com</a></{0}>".format(tag)
    assert md(html) == "`foo.com`"


def test_preformatted_ancestor_need_not_be_direct_parent():
    html = (
        "<code><span><a href='http://foo.com/' title='Foo'>"
        "foo.com</a></span></code>"
    )
    assert md(html) == "`foo.com`"


def test_autolink_syntax_is_not_created_inside_code():
    html = "<code><a href='http://foo.com/'>http://foo.com/</a></code>"
    assert md(html) == "`http://foo.com/`"

    # The corresponding link outside code still uses the normal autolink form.
    assert md("<a href='http://foo.com/'>http://foo.com/</a>") == (
        "<http://foo.com/>"
    )


def test_default_title_does_not_reintroduce_links_inside_code():
    html = "<code><a href='http://foo.com/'>foo.com</a></code>"
    assert md(html, default_title=True) == "`foo.com`"


def test_all_links_in_preformatted_content_are_plain_text():
    html = (
        "<pre>before <a href='http://foo.com/'>foo.com</a> and "
        "<a href='http://bar.com/' title='Bar'>bar.com</a> after</pre>"
    )
    assert md(html) == fenced_code_block("before foo.com and bar.com after")


def test_links_outside_preformatted_tags_are_unchanged():
    html = (
        "Outside <a href='http://foo.com/'>foo.com</a>; inside "
        "<code><a href='http://bar.com/'>bar.com</a></code>"
    )
    assert md(html) == "Outside [foo.com](http://foo.com/); inside `bar.com`"


def test_link_containing_code_is_still_a_link():
    # Suppression depends on the anchor's ancestors, not on code in its content.
    html = "<a href='http://foo.com/'><code>foo.com</code></a>"
    assert md(html) == "[`foo.com`](http://foo.com/)"

from sqlglot import parse_one
from tests.dialects.test_dialect import Validator


class TestTSQLDoublePipeConcatenation(Validator):
    dialect = "tsql"

    def test_double_pipe_is_generated_as_plus(self):
        source_sql = "SELECT 'hello' || 'world'"
        self.validate_all(
            "SELECT 'hello' + 'world'",
            read={
                "postgres": source_sql,
                "oracle": source_sql,
                "sqlite": source_sql,
                "tsql": source_sql,
            },
        )

    def test_chained_concatenation_with_columns(self):
        source_sql = (
            "SELECT first_name || ' ' || last_name AS full_name FROM users"
        )
        self.validate_all(
            "SELECT first_name + ' ' + last_name AS full_name FROM users",
            read={
                "postgres": source_sql,
                "oracle": source_sql,
                "sqlite": source_sql,
            },
        )

    def test_concatenation_in_where_clause(self):
        self.validate_all(
            "SELECT * FROM users WHERE full_name = first_name + ' ' + last_name",
            read={
                "postgres": (
                    "SELECT * FROM users "
                    "WHERE full_name = first_name || ' ' || last_name"
                )
            },
        )

    def test_concatenation_with_functions(self):
        self.validate_all(
            "SELECT UPPER(first_name) + '_' + LOWER(last_name)",
            read={
                "postgres": "SELECT UPPER(first_name) || '_' || LOWER(last_name)"
            },
        )

    def test_parenthesized_concatenation(self):
        self.validate_all(
            "SELECT ('prefix_' + category) + ('_' + id) FROM items",
            read={
                "postgres": (
                    "SELECT ('prefix_' || category) || ('_' || id) FROM items"
                )
            },
        )

    def test_double_pipe_inside_string_literals_is_not_an_operator(self):
        self.validate_identity("SELECT 'a||b'")
        self.validate_all(
            "SELECT 'a' + '||'",
            read={"postgres": "SELECT 'a' || '||'"},
        )

    def test_native_tsql_addition_is_unchanged(self):
        self.validate_identity("SELECT 'hello' + 'world'")
        self.validate_identity("SELECT first_name + ' ' + last_name FROM users")
        self.validate_identity("SELECT price + tax FROM orders")

    def test_other_dialects_still_generate_double_pipe(self):
        for dialect in ("postgres", "oracle", "sqlite"):
            with self.subTest(dialect=dialect):
                expression = parse_one(
                    "SELECT 'hello' || 'world'", read="postgres"
                )
                self.assertEqual(
                    expression.sql(dialect),
                    "SELECT 'hello' || 'world'",
                )

"""Regression tests for model initialization with variable keyword arguments."""

import pytest

from mesa.visualization.solara_viz import _check_model_params


def test_kwargs_is_not_treated_as_a_required_parameter():
    """A model using **kwargs should not need a literal ``kwargs`` value."""

    class ModelWithKwargs:
        def __init__(self, required_param, optional_param=10, **kwargs):
            pass

    _check_model_params(ModelWithKwargs.__init__, {"required_param": 1})


def test_kwargs_allows_additional_model_configuration():
    """Additional configuration should be valid when the model accepts **kwargs."""

    class ModelWithKwargs:
        def __init__(self, required_param, optional_param=10, **kwargs):
            pass

    _check_model_params(
        ModelWithKwargs.__init__,
        {
            "required_param": 1,
            "optional_param": 5,
            "custom_option": "custom value",
            "another_option": 42,
        },
    )


def test_kwargs_only_model_accepts_empty_and_arbitrary_params():
    """The variable-keyword parameter is optional regardless of its name."""

    class ModelWithOnlyKwargs:
        def __init__(self, **options):
            pass

    _check_model_params(ModelWithOnlyKwargs.__init__, {})
    _check_model_params(
        ModelWithOnlyKwargs.__init__,
        {"width": 10, "height": 20, "seed": 123},
    )


def test_required_parameters_are_still_checked_when_kwargs_is_present():
    """Accepting **kwargs must not disable validation of required parameters."""

    class ModelWithKwargs:
        def __init__(self, required_param, optional_param=10, **kwargs):
            pass

    with pytest.raises(
        ValueError, match=r"^Missing required model parameter: required_param$"
    ):
        _check_model_params(ModelWithKwargs.__init__, {})

    # Supplying arbitrary keyword configuration does not satisfy a named requirement.
    with pytest.raises(
        ValueError, match=r"^Missing required model parameter: required_param$"
    ):
        _check_model_params(ModelWithKwargs.__init__, {"custom_option": 1})


def test_required_keyword_only_parameter_is_checked_with_kwargs():
    """Required keyword-only parameters remain required alongside **kwargs."""

    class ModelWithKeywordOnlyParameter:
        def __init__(self, *, required_param, optional_param=10, **kwargs):
            pass

    with pytest.raises(
        ValueError, match=r"^Missing required model parameter: required_param$"
    ):
        _check_model_params(ModelWithKeywordOnlyParameter.__init__, {})

    _check_model_params(
        ModelWithKeywordOnlyParameter.__init__,
        {"required_param": 1, "custom_option": 2},
    )


def test_unknown_parameters_are_still_rejected_without_kwargs():
    """Models without **kwargs should retain strict parameter-name validation."""

    class ModelWithoutKwargs:
        def __init__(self, required_param, optional_param=10):
            pass

    with pytest.raises(ValueError, match=r"^Invalid model parameter: custom_option$"):
        _check_model_params(
            ModelWithoutKwargs.__init__,
            {"required_param": 1, "custom_option": 2},
        )


def test_regular_parameter_named_kwargs_is_not_special():
    """Only a VAR_KEYWORD parameter is special, not a parameter's spelling."""

    class ModelWithExplicitKwargsParameter:
        def __init__(self, kwargs):
            pass

    with pytest.raises(ValueError, match=r"^Missing required model parameter: kwargs$"):
        _check_model_params(ModelWithExplicitKwargsParameter.__init__, {})

    _check_model_params(ModelWithExplicitKwargsParameter.__init__, {"kwargs": {}})

import pytest
from apispec import APISpec
from apispec.ext.marshmallow import MarshmallowPlugin
from marshmallow import Schema, fields


class FooSchema(Schema):
    bar = fields.Integer(required=True)


def make_spec(openapi_version="3.0.3", plugin=None):
    return APISpec(
        title="My API Spec",
        version="1.0.0",
        openapi_version=openapi_version,
        plugins=[plugin or MarshmallowPlugin()],
    )


def nullable_nested_property(openapi_version="3.0.3"):
    return {
        "anyOf": [
            {"type": "object", "nullable": True},
            {
                "$ref": (
                    "#/definitions/Foo"
                    if openapi_version == "2.0"
                    else "#/components/schemas/Foo"
                )
            },
        ]
    }


def property_for_field(field, openapi_version="3.0.3"):
    """Generate a property through schema registration and spec serialization."""
    spec = make_spec(openapi_version)
    MySchema = type("MySchema", (Schema,), {"foo": field})

    spec.components.schema("Foo", schema=FooSchema)
    spec.components.schema("MySchema", schema=MySchema)
    document = spec.to_dict()

    schemas = (
        document["definitions"]
        if openapi_version == "2.0"
        else document["components"]["schemas"]
    )
    return schemas["MySchema"]["properties"]["foo"]


def test_issue_example_generates_openapi_30_compliant_schema():
    spec = make_spec("3.0.3")

    class MySchema(Schema):
        foo = fields.Nested(FooSchema, allow_none=True)

    spec.components.schema("Foo", schema=FooSchema)
    spec.components.schema("MySchema", schema=MySchema)

    assert spec.to_dict()["components"]["schemas"] == {
        "Foo": {
            "type": "object",
            "properties": {"bar": {"type": "integer"}},
            "required": ["bar"],
        },
        "MySchema": {
            "type": "object",
            "properties": {"foo": nullable_nested_property()},
        },
    }


@pytest.mark.parametrize("openapi_version", ["2.0", "3.0.0", "3.0.3", "3.1.0"])
def test_nullable_nested_ref_per_openapi_version(openapi_version):
    result = property_for_field(
        fields.Nested(FooSchema, allow_none=True), openapi_version
    )

    if openapi_version == "2.0":
        assert result == {"$ref": "#/definitions/Foo", "x-nullable": True}
    elif openapi_version.startswith("3.0"):
        expected = nullable_nested_property(openapi_version)
        assert result == expected
        # nullable must not be applied to a schema whose type comes from allOf.
        assert "nullable" not in result
        assert "allOf" not in result
    else:
        # OpenAPI 3.1 represents null as a JSON Schema type instead.
        assert result == {
            "anyOf": [
                {"$ref": "#/components/schemas/Foo"},
                {"type": "null"},
            ]
        }


@pytest.mark.parametrize(
    ("field_kwargs", "expected_attributes"),
    [
        (
            {"metadata": {"description": "A nullable Foo"}},
            {"description": "A nullable Foo"},
        ),
        ({"dump_only": True}, {"readOnly": True}),
    ],
)
def test_nullable_nested_ref_with_other_attributes_is_also_compliant(
    field_kwargs, expected_attributes
):
    """Metadata/readOnly cause Nested conversion to use allOf internally.

    That must not reintroduce the invalid top-level nullable + allOf combination.
    OpenAPI 3.0 nullable only modifies a type asserted in the same Schema Object;
    it cannot modify the type inherited through allOf.
    """
    result = property_for_field(
        fields.Nested(FooSchema, allow_none=True, **field_kwargs)
    )

    assert result == {
        **expected_attributes,
        **nullable_nested_property(),
    }


@pytest.mark.parametrize("field_kwargs", [{}, {"allow_none": False}])
def test_non_nullable_nested_ref_is_unchanged(field_kwargs):
    assert property_for_field(fields.Nested(FooSchema, **field_kwargs)) == {
        "$ref": "#/components/schemas/Foo"
    }


@pytest.mark.parametrize(
    "field_factory",
    [
        lambda: fields.Nested(FooSchema, many=True, allow_none=True),
        lambda: fields.List(fields.Nested(FooSchema), allow_none=True),
    ],
)
def test_nullable_array_of_nested_schemas_uses_array_nullable(field_factory):
    # Here nullable has a type assertion in the same Schema Object, so it is
    # valid OpenAPI 3.0 and does not need the anyOf representation.
    assert property_for_field(field_factory()) == {
        "type": "array",
        "items": {"$ref": "#/components/schemas/Foo"},
        "nullable": True,
    }


def test_nullable_nested_schema_inside_list_is_converted_recursively():
    result = property_for_field(
        fields.List(fields.Nested(FooSchema, allow_none=True))
    )

    assert result == {
        "type": "array",
        "items": nullable_nested_property(),
    }


def test_nullable_non_nested_field_is_unchanged():
    assert property_for_field(fields.String(allow_none=True)) == {
        "type": "string",
        "nullable": True,
    }


def test_nullable_inline_nested_schema_keeps_nullable_with_its_type():
    # Without a $ref/allOf, nullable already operates on a type declared in the
    # same Schema Object and therefore should not be wrapped in anyOf.
    spec = make_spec(
        "3.0.3", MarshmallowPlugin(schema_name_resolver=lambda schema: None)
    )

    class MySchema(Schema):
        foo = fields.Nested(FooSchema, allow_none=True)

    spec.components.schema("MySchema", schema=MySchema)
    result = spec.to_dict()["components"]["schemas"]["MySchema"]["properties"][
        "foo"
    ]

    assert result["type"] == "object"
    assert result["nullable"] is True
    assert result["properties"] == {"bar": {"type": "integer"}}
    assert result["required"] == ["bar"]
    assert "$ref" not in result
    assert "allOf" not in result
    assert "anyOf" not in result

import pytest

import sqlglot
from sqlglot import exp


def _transpile(sql: str, read: str, write: str) -> str:
    return sqlglot.transpile(sql, read=read, write=write)[0]


def _to_tsql(sql: str, read: str = "postgres") -> str:
    return _transpile(sql, read=read, write="tsql")


@pytest.mark.parametrize("source_dialect", ["postgres", "oracle", "sqlite", "tsql"])
def test_double_pipe_is_generated_as_plus_for_tsql(source_dialect):
    assert (
        _to_tsql("SELECT 'hello' || 'world'", read=source_dialect)
        == "SELECT 'hello' + 'world'"
    )


@pytest.mark.parametrize(
    ("sql", "expected"),
    [
        (
            "SELECT 'a' || 'b' || 'c' || 'd'",
            "SELECT 'a' + 'b' + 'c' + 'd'",
        ),
        (
            "SELECT first_name || ' ' || last_name FROM users",
            "SELECT first_name + ' ' + last_name FROM users",
        ),
        (
            "SELECT UPPER(first_name) || '_' || LOWER(last_name)",
            "SELECT UPPER(first_name) + '_' + LOWER(last_name)",
        ),
        (
            "SELECT * FROM users WHERE full_name = first_name || ' ' || last_name",
            "SELECT * FROM users WHERE full_name = first_name + ' ' + last_name",
        ),
    ],
)
def test_concatenation_is_converted_in_chains_and_query_expressions(sql, expected):
    assert _to_tsql(sql) == expected


def test_nested_concatenation_is_converted_recursively():
    result = _to_tsql(
        "SELECT ('prefix_' || category) || ('_' || id) FROM items"
    )

    assert "||" not in result
    assert result.count("+") == 3
    for fragment in ("'prefix_'", "category", "'_'", "id"):
        assert fragment in result


def test_double_pipe_inside_a_string_literal_is_not_an_operator():
    assert (
        _to_tsql("SELECT 'a||b' AS combined, 'x' || 'y'")
        == "SELECT 'a||b' AS combined, 'x' + 'y'"
    )


def test_programmatically_built_dpipe_uses_tsql_concatenation_operator():
    expression = exp.DPipe(
        this=exp.Literal.string("hello"),
        expression=exp.Literal.string("world"),
    )

    assert expression.sql(dialect="tsql") == "'hello' + 'world'"


@pytest.mark.parametrize(
    "sql",
    [
        "SELECT 'hello' + 'world'",
        "SELECT first_name + ' ' + last_name FROM users",
        "SELECT 1 + 2, price + tax FROM orders",
    ],
)
def test_native_tsql_plus_expressions_are_unchanged(sql):
    assert _to_tsql(sql, read="tsql") == sql


@pytest.mark.parametrize("target_dialect", ["postgres", "oracle", "sqlite"])
def test_other_dialects_keep_double_pipe_concatenation(target_dialect):
    assert (
        _transpile(
            "SELECT 'hello' || 'world'",
            read="postgres",
            write=target_dialect,
        )
        == "SELECT 'hello' || 'world'"
    )

from unittest import mock

import pytest

import hashin


def _expected_expansion(version):
    major, minor = version.split(".")
    return {
        version,
        "cp{0}{1}".format(major, minor),
        "py{0}".format(major),
        "py{0}.{1}".format(major, minor),
        "py{0}{1}".format(major, minor),
        "py2.py3",
        "source",
    }


def _release(filename, digest="a" * 64):
    return {
        "url": "https://pypi.org/packages/ab/cd/{0}".format(filename),
        "digests": {"sha256": digest},
    }


@pytest.mark.parametrize(
    "version", ["2.7", "3.9", "3.10", "3.11", "3.12", "3.99"]
)
def test_expand_python_version_for_major_minor_versions(version):
    """Single- and multi-digit minor versions get the same complete expansion."""
    assert set(hashin.expand_python_version(version)) == _expected_expansion(version)


@pytest.mark.parametrize(
    "version",
    ["", "3", "3.", ".10", "3.x", "3.10.1", "py3", "cp310", "source"],
)
def test_expand_python_version_leaves_other_values_unchanged(version):
    assert hashin.expand_python_version(version) == [version]


def test_filter_releases_for_python_310():
    releases = [
        _release("example-1.2.3-cp310-cp310-manylinux2014_x86_64.whl"),
        _release("example-1.2.3-cp39-cp39-manylinux2014_x86_64.whl"),
        _release("example-1.2.3-py3-none-any.whl"),
        _release("example-1.2.3-py2.py3-none-any.whl"),
        _release("example-1.2.3-py2-none-any.whl"),
        _release("example-1.2.3.tar.gz"),
    ]

    filtered = hashin.filter_releases(releases, ["3.10"])

    assert filtered == [
        releases[0],  # cp310
        releases[2],  # py3
        releases[3],  # py2.py3
        releases[5],  # source
    ]


@pytest.mark.parametrize(
    ("python_version", "wheel_tag"),
    [("3.10", "cp310"), ("3.11", "cp311"), ("3.12", "cp312")],
)
def test_run_finds_hashes_for_multi_digit_python_minor_versions(
    tmp_path, python_version, wheel_tag
):
    """A version-specific wheel must not result in PackageError."""
    digest = "b" * 64
    package_data = {
        "info": {"name": "example", "version": "1.2.3"},
        "releases": {
            "1.2.3": [
                _release(
                    "example-1.2.3-{0}-{0}-manylinux2014_x86_64.whl".format(
                        wheel_tag
                    ),
                    digest,
                )
            ]
        },
    }
    requirements_file = tmp_path / "requirements.txt"
    requirements_file.write_text("")

    with mock.patch("hashin.get_package_data", return_value=package_data):
        result = hashin.run(
            "example==1.2.3",
            str(requirements_file),
            "sha256",
            python_versions=[python_version],
        )

    assert result == 0
    requirements = requirements_file.read_text()
    assert "example==1.2.3" in requirements
    assert "--hash=sha256:{0}".format(digest) in requirements

"""Tests for counts of mid-circuit measurements with dynamic one-shot execution."""

import numpy as np
import pytest

import pennylane as qml


def _assert_integer_outcome_keys(counts):
    """MCM outcomes should be integers, not numerically equivalent floats."""
    assert all(isinstance(key, (int, np.integer)) for key in counts)


def _assert_counts_equal(actual, expected):
    assert isinstance(actual, dict)
    assert set(actual) == set(expected)
    for outcome, count in expected.items():
        assert int(actual[outcome]) == count


@pytest.mark.parametrize("mcm_method", ["deferred", "one-shot"])
@pytest.mark.parametrize("measured_outcome", [0, 1])
def test_counts_mcm_all_outcomes(mcm_method, measured_outcome):
    """All binary outcomes are returned, including deterministic zero-count outcomes."""
    shots = 10
    dev = qml.device("default.qubit", wires=1, shots=shots)

    @qml.qnode(dev, mcm_method=mcm_method)
    def circuit():
        if measured_outcome:
            qml.PauliX(0)
        m = qml.measure(0)
        return qml.counts(m, all_outcomes=True)

    result = circuit()

    _assert_integer_outcome_keys(result)
    _assert_counts_equal(
        result,
        {measured_outcome: shots, 1 - measured_outcome: 0},
    )


def test_counts_mcm_without_all_outcomes_only_returns_observed():
    """Requesting all outcomes must not change the default observed-only behaviour."""
    shots = 10
    dev = qml.device("default.qubit", wires=1, shots=shots)

    @qml.qnode(dev, mcm_method="one-shot")
    def circuit():
        m = qml.measure(0)
        return qml.counts(m)

    result = circuit()

    _assert_integer_outcome_keys(result)
    _assert_counts_equal(result, {0: shots})


@pytest.mark.parametrize(
    "all_outcomes, expected",
    [
        (False, {"00": 10}),
        (True, {"00": 10, "01": 0, "10": 0, "11": 0}),
    ],
)
def test_counts_mcm_list_all_outcomes(all_outcomes, expected):
    """Counts of a list of MCMs include every bit string only when requested."""
    dev = qml.device("default.qubit", wires=2, shots=10)

    @qml.qnode(dev, mcm_method="one-shot")
    def circuit():
        m0 = qml.measure(0)
        m1 = qml.measure(1)
        return qml.counts([m0, m1], all_outcomes=all_outcomes)

    _assert_counts_equal(circuit(), expected)


def test_counts_all_outcomes_for_transformed_single_mcm():
    """The possible outcomes come from the measurement value, not just binary 0 and 1."""
    shots = 10
    dev = qml.device("default.qubit", wires=1, shots=shots)

    @qml.qnode(dev, mcm_method="one-shot")
    def circuit():
        m = qml.measure(0)
        return qml.counts(m * 2, all_outcomes=True)

    result = circuit()

    _assert_integer_outcome_keys(result)
    _assert_counts_equal(result, {0: shots, 2: 0})


def test_counts_all_outcomes_for_composite_mcm_expression():
    """All values of an arithmetic composite measurement value are included."""
    shots = 10
    dev = qml.device("default.qubit", wires=2, shots=shots)

    @qml.qnode(dev, mcm_method="one-shot")
    def circuit():
        m0 = qml.measure(0)
        m1 = qml.measure(1)
        return qml.counts(m0 + 2 * m1, all_outcomes=True)

    result = circuit()

    _assert_integer_outcome_keys(result)
    _assert_counts_equal(result, {0: shots, 1: 0, 2: 0, 3: 0})


def test_mcm_counts_fix_does_not_truncate_observable_eigenvalues():
    """Integer MCM keys must not cause non-MCM observable outcomes to be cast to int."""
    shots = 10
    dev = qml.device("default.qubit", wires=1, shots=shots)
    observable = qml.Hermitian(np.diag([0.25, 1.5]), wires=0)

    @qml.qnode(dev, mcm_method="one-shot")
    def circuit():
        qml.measure(0)
        return qml.counts(op=observable)

    result = circuit()

    _assert_counts_equal(result, {0.25: shots})

"""Regression tests for model initialization with variable keyword arguments."""

import pytest

from mesa.visualization.solara_viz import _check_model_params


def test_kwargs_only_model_accepts_empty_and_arbitrary_params():
    """A **kwargs parameter is optional and permits additional configuration."""

    class ModelWithKwargs:
        def __init__(self, **kwargs):
            self.kwargs = kwargs

    _check_model_params(ModelWithKwargs.__init__, {})

    params = {"density": 0.8, "seed": 42}
    _check_model_params(ModelWithKwargs.__init__, params)

    model = ModelWithKwargs(**params)
    assert model.kwargs == params


def test_kwargs_allows_extras_alongside_named_parameters():
    """Named parameters retain their behavior while extras go to **kwargs."""

    class ModelWithNamedParamsAndKwargs:
        def __init__(self, required_param, optional_param=10, **kwargs):
            self.required_param = required_param
            self.optional_param = optional_param
            self.kwargs = kwargs

    _check_model_params(
        ModelWithNamedParamsAndKwargs.__init__, {"required_param": 1}
    )

    params = {
        "required_param": 1,
        "optional_param": 5,
        "density": 0.8,
        "seed": 42,
    }
    _check_model_params(ModelWithNamedParamsAndKwargs.__init__, params)

    model = ModelWithNamedParamsAndKwargs(**params)
    assert model.required_param == 1
    assert model.optional_param == 5
    assert model.kwargs == {"density": 0.8, "seed": 42}


def test_kwargs_does_not_make_required_parameters_optional():
    """Accepting arbitrary keywords must not bypass required-parameter checks."""

    class ModelWithRequiredParamAndKwargs:
        def __init__(self, required_param, **kwargs):
            pass

    with pytest.raises(
        ValueError, match="Missing required model parameter: required_param"
    ):
        _check_model_params(
            ModelWithRequiredParamAndKwargs.__init__, {"density": 0.8}
        )


def test_required_keyword_only_parameter_is_still_checked_with_kwargs():
    """Required keyword-only parameters remain required when **kwargs exists."""

    class ModelWithKeywordOnlyParam:
        def __init__(self, *, required_param, **kwargs):
            pass

    _check_model_params(
        ModelWithKeywordOnlyParam.__init__,
        {"required_param": 1, "extra_config": True},
    )

    with pytest.raises(
        ValueError, match="Missing required model parameter: required_param"
    ):
        _check_model_params(
            ModelWithKeywordOnlyParam.__init__, {"extra_config": True}
        )


def test_models_without_kwargs_still_reject_unknown_parameters():
    """The fix must not disable validation for ordinary model signatures."""

    class ModelWithoutKwargs:
        def __init__(self, required_param, optional_param=10):
            pass

    _check_model_params(ModelWithoutKwargs.__init__, {"required_param": 1})

    with pytest.raises(ValueError, match="Invalid model parameter: extra"):
        _check_model_params(
            ModelWithoutKwargs.__init__, {"required_param": 1, "extra": 2}
        )


def test_variable_positional_parameter_is_not_required():
    """*args, like **kwargs, does not require an entry in model_params."""

    class ModelWithVariableArgs:
        def __init__(self, required_param, *args, **kwargs):
            pass

    _check_model_params(
        ModelWithVariableArgs.__init__,
        {"required_param": 1, "extra_config": True},
    )

    with pytest.raises(
        ValueError, match="Missing required model parameter: required_param"
    ):
        _check_model_params(ModelWithVariableArgs.__init__, {})

