@pytest.mark.parametrize(
    "python_version, compatible_tag, incompatible_tag",
    [
        ("3.10", "cp310", "cp39"),
        ("3.11", "cp311", "cp310"),
    ],
)
def test_get_package_hashes_filters_releases_for_multi_digit_python_versions(
    python_version, compatible_tag, incompatible_tag
):
    """A two-digit minor version must not filter out every release."""
    package = "example"
    version = "1.0"

    compatible_hash = "a" * 64
    incompatible_hash = "b" * 64
    py3_hash = "c" * 64
    py2_py3_hash = "d" * 64
    source_hash = "e" * 64

    releases = [
        {
            "url": (
                "https://files.pythonhosted.org/packages/"
                f"example-{version}-{compatible_tag}-{compatible_tag}-"
                "manylinux2014_x86_64.whl"
            ),
            "digests": {"sha256": compatible_hash},
        },
        {
            "url": (
                "https://files.pythonhosted.org/packages/"
                f"example-{version}-{incompatible_tag}-{incompatible_tag}-"
                "manylinux2014_x86_64.whl"
            ),
            "digests": {"sha256": incompatible_hash},
        },
        {
            "url": (
                "https://files.pythonhosted.org/packages/"
                f"example-{version}-py3-none-any.whl"
            ),
            "digests": {"sha256": py3_hash},
        },
        {
            "url": (
                "https://files.pythonhosted.org/packages/"
                f"example-{version}-py2.py3-none-any.whl"
            ),
            "digests": {"sha256": py2_py3_hash},
        },
        {
            "url": (
                "https://files.pythonhosted.org/packages/"
                f"example-{version}.tar.gz"
            ),
            "digests": {"sha256": source_hash},
        },
    ]
    data = {
        "info": {"name": package, "version": version},
        "releases": {version: releases},
    }

    result = hashin.get_package_hashes(
        package=package,
        version=version,
        algorithm="sha256",
        python_versions=(python_version,),
        lookup_memory={package: data},
    )

    assert result["package"] == package
    assert result["version"] == version
    assert {release["hash"] for release in result["hashes"]} == {
        compatible_hash,
        py3_hash,
        py2_py3_hash,
        source_hash,
    }
    assert incompatible_hash not in {
        release["hash"] for release in result["hashes"]
    }

import pytest
from apispec import APISpec
from apispec.ext.marshmallow import MarshmallowPlugin
from marshmallow import Schema, fields


class FooSchema(Schema):
    bar = fields.Integer(required=True)


def generate_schemas(field, openapi_version):
    """Register Foo and a schema containing ``field`` and return their definitions."""
    spec = APISpec(
        title="My API Spec",
        version="1.0.0",
        openapi_version=openapi_version,
        plugins=[MarshmallowPlugin()],
    )

    class MySchema(Schema):
        foo = field

    spec.components.schema("Foo", schema=FooSchema)
    spec.components.schema("MySchema", schema=MySchema)
    document = spec.to_dict()
    if openapi_version.startswith("2."):
        return document["definitions"]
    return document["components"]["schemas"]


def foo_ref(openapi_version):
    prefix = (
        "#/definitions" if openapi_version.startswith("2.") else "#/components/schemas"
    )
    return {"$ref": f"{prefix}/Foo"}


@pytest.mark.parametrize("openapi_version", ["3.0.0", "3.0.3"])
def test_openapi_30_nullable_nested_schema_uses_anyof(openapi_version):
    schemas = generate_schemas(
        fields.Nested(FooSchema, allow_none=True), openapi_version
    )

    assert schemas == {
        "Foo": {
            "type": "object",
            "properties": {"bar": {"type": "integer"}},
            "required": ["bar"],
        },
        "MySchema": {
            "type": "object",
            "properties": {
                "foo": {
                    "anyOf": [
                        {"type": "object", "nullable": True},
                        foo_ref(openapi_version),
                    ]
                }
            },
        },
    }


@pytest.mark.parametrize(
    ("nested_kwargs", "expected_extra"),
    [
        pytest.param(
            {"metadata": {"description": "A nullable Foo"}},
            {"description": "A nullable Foo"},
            id="metadata",
        ),
        pytest.param({"dump_only": True}, {"readOnly": True}, id="read-only"),
    ],
)
def test_openapi_30_nullable_nested_schema_with_other_attributes(
    nested_kwargs, expected_extra
):
    """Existing attributes make Nested use allOf, which must also be converted."""
    schemas = generate_schemas(
        fields.Nested(FooSchema, allow_none=True, **nested_kwargs), "3.0.3"
    )

    assert schemas["MySchema"]["properties"]["foo"] == {
        **expected_extra,
        "anyOf": [
            {"type": "object", "nullable": True},
            {"$ref": "#/components/schemas/Foo"},
        ],
    }


@pytest.mark.parametrize("openapi_version", ["2.0", "3.1.0"])
def test_nullable_nested_schema_other_openapi_versions_unchanged(openapi_version):
    schemas = generate_schemas(
        fields.Nested(FooSchema, allow_none=True), openapi_version
    )
    foo = schemas["MySchema"]["properties"]["foo"]

    if openapi_version == "2.0":
        assert foo == {"$ref": "#/definitions/Foo", "x-nullable": True}
    else:
        assert foo == {
            "anyOf": [
                {"$ref": "#/components/schemas/Foo"},
                {"type": "null"},
            ]
        }


def test_openapi_30_nullable_nested_many_remains_a_nullable_array():
    schemas = generate_schemas(
        fields.Nested(FooSchema, many=True, allow_none=True), "3.0.3"
    )

    assert schemas["MySchema"]["properties"]["foo"] == {
        "type": "array",
        "items": {"$ref": "#/components/schemas/Foo"},
        "nullable": True,
    }


def test_openapi_30_list_of_nullable_nested_schemas_converts_the_items():
    schemas = generate_schemas(
        fields.List(fields.Nested(FooSchema, allow_none=True)), "3.0.3"
    )

    assert schemas["MySchema"]["properties"]["foo"] == {
        "type": "array",
        "items": {
            "anyOf": [
                {"type": "object", "nullable": True},
                {"$ref": "#/components/schemas/Foo"},
            ]
        },
    }


def test_openapi_30_nullable_scalar_behavior_is_unchanged():
    schemas = generate_schemas(fields.String(allow_none=True), "3.0.3")

    assert schemas["MySchema"]["properties"]["foo"] == {
        "type": "string",
        "nullable": True,
    }


@pytest.mark.parametrize("nested_kwargs", [{}, {"allow_none": False}])
def test_openapi_30_non_nullable_nested_schema_remains_a_plain_ref(nested_kwargs):
    schemas = generate_schemas(fields.Nested(FooSchema, **nested_kwargs), "3.0.3")

    assert schemas["MySchema"]["properties"]["foo"] == {
        "$ref": "#/components/schemas/Foo"
    }

import pytest

from sqlglot import exp, parse_one


def to_tsql(sql: str, read: str = "postgres") -> str:
    return parse_one(sql, read=read).sql(dialect="tsql")


@pytest.mark.parametrize("source_dialect", ["postgres", "oracle", "sqlite"])
def test_double_pipe_is_transpiled_to_tsql_plus(source_dialect):
    assert (
        to_tsql("SELECT 'hello' || 'world'", read=source_dialect)
        == "SELECT 'hello' + 'world'"
    )


@pytest.mark.parametrize(
    ("sql", "expected"),
    [
        (
            "SELECT first_name || ' ' || last_name FROM users",
            "SELECT first_name + ' ' + last_name FROM users",
        ),
        (
            "SELECT 'a' || 'b' || 'c' || 'd'",
            "SELECT 'a' + 'b' + 'c' + 'd'",
        ),
        (
            "SELECT UPPER(first_name) || '_' || LOWER(last_name)",
            "SELECT UPPER(first_name) + '_' + LOWER(last_name)",
        ),
        (
            "SELECT * FROM users WHERE full_name = first_name || ' ' || last_name",
            "SELECT * FROM users WHERE full_name = first_name + ' ' + last_name",
        ),
        (
            "SELECT 'ID_' || id FROM products",
            "SELECT 'ID_' + id FROM products",
        ),
        (
            "SELECT '' || 'value'",
            "SELECT '' + 'value'",
        ),
    ],
)
def test_double_pipe_conversion_in_chains_and_other_clauses(sql, expected):
    assert to_tsql(sql) == expected


def test_double_pipe_conversion_preserves_nested_arithmetic():
    assert (
        to_tsql("SELECT 'total: ' || (price + tax) FROM orders")
        == "SELECT 'total: ' + (price + tax) FROM orders"
    )


def test_double_pipe_inside_string_literal_is_not_an_operator():
    # Only the operator should change; pipes inside the literal must survive.
    assert to_tsql("SELECT 'a||b' || 'c'") == "SELECT 'a||b' + 'c'"


def test_programmatically_built_dpipe_uses_tsql_plus():
    expression = exp.DPipe(
        this=exp.DPipe(
            this=exp.column("first_name"),
            expression=exp.Literal.string(" "),
        ),
        expression=exp.column("last_name"),
    )

    assert expression.sql(dialect="tsql") == "first_name + ' ' + last_name"


@pytest.mark.parametrize("target_dialect", ["postgres", "oracle", "sqlite"])
def test_other_dialects_keep_double_pipe(target_dialect):
    expression = parse_one("SELECT 'hello' || 'world'", read="postgres")

    assert expression.sql(dialect=target_dialect) == "SELECT 'hello' || 'world'"


@pytest.mark.parametrize(
    "sql",
    [
        "SELECT 'hello' + 'world'",
        "SELECT first_name + ' ' + last_name FROM users",
        "SELECT price + tax FROM orders",
        "SELECT 1 + 2",
    ],
)
def test_existing_tsql_plus_expressions_are_unchanged(sql):
    assert parse_one(sql, read="tsql").sql(dialect="tsql") == sql

