"""Regression tests for model initializers with variable parameters."""

import pytest

from mesa.visualization.solara_viz import _check_model_params


def test_kwargs_only_initializer_accepts_empty_and_arbitrary_params():
    """A **kwargs parameter is optional and accepts additional configuration."""

    class ModelWithKwargs:
        def __init__(self, **kwargs):
            pass

    # This is the original failure: kwargs itself must not be reported missing.
    _check_model_params(ModelWithKwargs.__init__, {})

    # Arbitrary named options are valid because the initializer accepts them.
    _check_model_params(
        ModelWithKwargs.__init__,
        {"density": 0.8, "enable_feature": True, "label": "test"},
    )


def test_variable_keyword_parameter_is_detected_by_kind_not_name():
    """The special parameter need not literally be named kwargs."""

    class ModelWithOptions:
        def __init__(self, required_param, optional_param=10, **options):
            pass

    _check_model_params(ModelWithOptions.__init__, {"required_param": 1})
    _check_model_params(
        ModelWithOptions.__init__,
        {
            "required_param": 1,
            "optional_param": 5,
            "custom_option": "accepted through options",
        },
    )


def test_required_params_are_still_enforced_when_kwargs_is_present():
    """Accepting **kwargs must not disable checks for named required params."""

    class ModelWithRequiredAndKwargs:
        def __init__(self, required_param, optional_param=10, **kwargs):
            pass

    with pytest.raises(
        ValueError, match="Missing required model parameter: required_param"
    ):
        _check_model_params(ModelWithRequiredAndKwargs.__init__, {})

    # Supplying arbitrary keyword options does not satisfy the named parameter.
    with pytest.raises(
        ValueError, match="Missing required model parameter: required_param"
    ):
        _check_model_params(
            ModelWithRequiredAndKwargs.__init__, {"custom_option": 1}
        )


def test_required_keyword_only_param_is_still_enforced_with_kwargs():
    """Keyword-only required parameters retain their validation."""

    class ModelWithKeywordOnlyParam:
        def __init__(self, *, required_param, **kwargs):
            pass

    with pytest.raises(
        ValueError, match="Missing required model parameter: required_param"
    ):
        _check_model_params(
            ModelWithKeywordOnlyParam.__init__, {"other_option": 2}
        )

    _check_model_params(
        ModelWithKeywordOnlyParam.__init__,
        {"required_param": 1, "other_option": 2},
    )


def test_var_positional_parameter_is_not_required():
    """*args is also optional, but does not accept arbitrary keyword options."""

    class ModelWithVarArgs:
        def __init__(self, *args):
            pass

    _check_model_params(ModelWithVarArgs.__init__, {})

    with pytest.raises(ValueError, match="Invalid model parameter: unexpected"):
        _check_model_params(ModelWithVarArgs.__init__, {"unexpected": 1})


def test_initializers_without_kwargs_still_reject_unknown_params():
    """The relaxed handling of extra options applies only when **kwargs exists."""

    class StrictModel:
        def __init__(self, required_param, optional_param=10):
            pass

    _check_model_params(StrictModel.__init__, {"required_param": 1})

    with pytest.raises(ValueError, match="Invalid model parameter: extra"):
        _check_model_params(
            StrictModel.__init__, {"required_param": 1, "extra": 2}
        )

    with pytest.raises(
        ValueError, match="Missing required model parameter: required_param"
    ):
        _check_model_params(StrictModel.__init__, {})

import pytest

import sqlglot


DIALECT = "duckdb"


def round_trip(sql: str) -> str:
    """Generate DuckDB SQL and ensure the generated SQL is also parseable."""
    expression = sqlglot.parse_one(sql, dialect=DIALECT)
    generated = expression.sql(dialect=DIALECT)

    # Parsing can normalize expressions, so the reparsed AST need not be
    # identical to the original one. The generated SQL must, however, remain
    # valid DuckDB syntax.
    sqlglot.parse_one(generated, dialect=DIALECT)
    return generated


def test_issue_example_preserves_struct_pack_unpack():
    # Unpacking is valid in STRUCT_PACK, but not in DuckDB's inline struct
    # literal syntax, so this must not degrade to {'_0': *COLUMNS(...)}.
    sql = r"""SELECT id, struct_pack(*COLUMNS('m\d')) AS measurements
FROM many_measurements"""

    assert round_trip(sql) == (
        r"SELECT id, STRUCT_PACK(*COLUMNS('m\d')) AS measurements "
        "FROM many_measurements"
    )


@pytest.mark.parametrize(
    ("sql", "expected"),
    [
        (
            r"SELECT struct_pack(*COLUMNS('m\d'))",
            r"SELECT STRUCT_PACK(*COLUMNS('m\d'))",
        ),
        (
            "SELECT struct_pack(x := 10, *COLUMNS('y'), z := 20) AS s",
            "SELECT STRUCT_PACK(x := 10, *COLUMNS('y'), z := 20) AS s",
        ),
        (
            "SELECT struct_pack(*COLUMNS('a'), *COLUMNS('b'))",
            "SELECT STRUCT_PACK(*COLUMNS('a'), *COLUMNS('b'))",
        ),
        (
            "SELECT struct_pack(*COLUMNS('m'), id := 1)",
            "SELECT STRUCT_PACK(*COLUMNS('m'), id := 1)",
        ),
    ],
)
def test_struct_pack_unpack_variations(sql, expected):
    assert round_trip(sql) == expected


@pytest.mark.parametrize(
    "sql",
    [
        r"SELECT *COLUMNS('m\d') FROM many_measurements",
        r"SELECT id, *COLUMNS('m\d') FROM many_measurements",
    ],
)
def test_unpacked_columns_in_projection(sql):
    assert round_trip(sql) == sql


@pytest.mark.parametrize(
    ("sql", "expected"),
    [
        (
            "SELECT struct_pack(a := 1, b := 2) AS s",
            "SELECT {'a': 1, 'b': 2} AS s",
        ),
        (
            'SELECT STRUCT_PACK("a b" := 1)',
            "SELECT {'a b': 1}",
        ),
        (
            "SELECT struct_pack(1, 2)",
            "SELECT {'_0': 1, '_1': 2}",
        ),
    ],
)
def test_regular_struct_pack_behavior_is_unchanged(sql, expected):
    # Calls without unpacked arguments should retain SQLGlot's existing struct
    # normalization rather than being preserved as STRUCT_PACK indiscriminately.
    assert round_trip(sql) == expected


@pytest.mark.parametrize(
    "sql",
    [
        "SELECT * FROM t",
        "SELECT a * b FROM t",
        "SELECT 2 * 3",
        "SELECT COUNT(*) FROM t",
