"""Regression tests for nullable nested schemas in OpenAPI 3.0."""

import pytest
from marshmallow import Schema, fields

from apispec import APISpec
from apispec.ext.marshmallow import MarshmallowPlugin


class FooSchema(Schema):
    bar = fields.Integer(required=True)


def make_spec(openapi_version, **plugin_kwargs):
    return APISpec(
        title="My API Spec",
        version="1.0.0",
        openapi_version=openapi_version,
        plugins=[MarshmallowPlugin(**plugin_kwargs)],
    )


def expected_openapi_30_nullable_foo():
    return {
        "anyOf": [
            {"type": "object", "nullable": True},
            {"$ref": "#/components/schemas/Foo"},
        ]
    }


@pytest.mark.parametrize("openapi_version", ["3.0.0", "3.0.3"])
def test_openapi_30_nullable_nested_schema_matches_issue(openapi_version):
    """A nullable $ref must not be combined with an inherited allOf type."""

    class MySchema(Schema):
        foo = fields.Nested(FooSchema, allow_none=True)

    spec = make_spec(openapi_version)
    spec.components.schema("Foo", schema=FooSchema)
    spec.components.schema("MySchema", schema=MySchema)

    schemas = spec.to_dict()["components"]["schemas"]

    assert schemas == {
        "Foo": {
            "type": "object",
            "properties": {"bar": {"type": "integer"}},
            "required": ["bar"],
        },
        "MySchema": {
            "type": "object",
            "properties": {"foo": expected_openapi_30_nullable_foo()},
        },
    }


@pytest.mark.parametrize(
    ("field_kwargs", "expected_attributes"),
    [
        (
            {"metadata": {"description": "A nullable Foo"}},
            {"description": "A nullable Foo"},
        ),
        ({"dump_only": True}, {"readOnly": True}),
    ],
)
def test_openapi_30_nullable_nested_schema_with_other_attributes(
    field_kwargs, expected_attributes
):
    """Metadata and readOnly also force a nested reference through allOf.

    Those cases need the same nullable treatment as a bare nested reference,
    while retaining the other property attributes. In particular, nullable
    must not remain alongside an allOf that supplies the type constraint.
    """

    class Container(Schema):
        foo = fields.Nested(FooSchema, allow_none=True, **field_kwargs)

    spec = make_spec("3.0.3")
    spec.components.schema("Foo", schema=FooSchema)
    spec.components.schema("Container", schema=Container)

    prop = spec.to_dict()["components"]["schemas"]["Container"]["properties"][
        "foo"
    ]

    assert prop == {
        **expected_attributes,
        **expected_openapi_30_nullable_foo(),
    }
    assert "nullable" not in prop
    assert "allOf" not in prop


@pytest.mark.parametrize("field_kwargs", [{}, {"allow_none": False}])
def test_openapi_30_non_nullable_nested_schema_is_unchanged(field_kwargs):
    class Container(Schema):
        foo = fields.Nested(FooSchema, **field_kwargs)

    spec = make_spec("3.0.3")
    spec.components.schema("Foo", schema=FooSchema)
    spec.components.schema("Container", schema=Container)

    prop = spec.to_dict()["components"]["schemas"]["Container"]["properties"][
        "foo"
    ]
    assert prop == {"$ref": "#/components/schemas/Foo"}


def test_openapi_30_nullable_fields_with_a_local_type_remain_nullable():
    """nullable is valid alongside a type in the same Schema Object."""

    class Container(Schema):
        scalar = fields.String(allow_none=True)
        many_foos = fields.Nested(FooSchema, many=True, allow_none=True)
        foo_list = fields.List(fields.Nested(FooSchema), allow_none=True)

    spec = make_spec("3.0.3")
    spec.components.schema("Foo", schema=FooSchema)
    spec.components.schema("Container", schema=Container)

    properties = spec.to_dict()["components"]["schemas"]["Container"][
        "properties"
    ]

    assert properties["scalar"] == {"type": "string", "nullable": True}
    assert properties["many_foos"] == {
        "type": "array",
        "items": {"$ref": "#/components/schemas/Foo"},
        "nullable": True,
    }
    assert properties["foo_list"] == {
        "type": "array",
        "items": {"$ref": "#/components/schemas/Foo"},
        "nullable": True,
    }


def test_openapi_30_inline_nullable_nested_schema_keeps_local_type():
    """An inline nested object already has a type assertion to modify."""

    class Container(Schema):
        foo = fields.Nested(FooSchema, allow_none=True)

    spec = make_spec("3.0.3", schema_name_resolver=lambda schema: None)
    spec.components.schema("Container", schema=Container)

    prop = spec.to_dict()["components"]["schemas"]["Container"]["properties"][
        "foo"
    ]

    assert prop["type"] == "object"
    assert prop["nullable"] is True
    assert prop["properties"] == {"bar": {"type": "integer"}}
    assert prop["required"] == ["bar"]
    assert "anyOf" not in prop
    assert "allOf" not in prop
    assert "$ref" not in prop


def test_openapi_31_nullable_nested_schema_behavior_is_unchanged():
    class Container(Schema):
        foo = fields.Nested(FooSchema, allow_none=True)

    spec = make_spec("3.1.0")
    spec.components.schema("Foo", schema=FooSchema)
    spec.components.schema("Container", schema=Container)

    prop = spec.to_dict()["components"]["schemas"]["Container"]["properties"][
        "foo"
    ]
    assert prop == {
        "anyOf": [
            {"$ref": "#/components/schemas/Foo"},
            {"type": "null"},
        ]
    }


def test_openapi_2_nullable_nested_schema_behavior_is_unchanged():
    class Container(Schema):
        foo = fields.Nested(FooSchema, allow_none=True)

    spec = make_spec("2.0")
    spec.components.schema("Foo", schema=FooSchema)
    spec.components.schema("Container", schema=Container)

    prop = spec.to_dict()["definitions"]["Container"]["properties"]["foo"]
    assert prop == {
        "$ref": "#/definitions/Foo",
        "x-nullable": True,
    }

import pytest

import hashin


def _release(filename, digest="a" * 64):
    return {
        "url": "https://files.pythonhosted.org/packages/{}".format(filename),
        "digests": {"sha256": digest},
    }


@pytest.mark.parametrize("minor", ["9", "10", "11"])
def test_expand_python_version_supports_multi_digit_minor_versions(minor):
    """Single- and multi-digit minor versions should expand to PyPI identifiers."""
    version = "3.{}".format(minor)

    assert set(hashin.expand_python_version(version)) == {
        version,
        "cp3{}".format(minor),
        "py3",
        "py3.{}".format(minor),
        "py3{}".format(minor),
        "source",
        "py2.py3",
    }


@pytest.mark.parametrize("version", ["3", "3.10.1", "py310", "3.x"])
def test_expand_python_version_leaves_other_identifiers_unchanged(version):
    assert hashin.expand_python_version(version) == [version]


def test_filter_releases_for_python_310():
    cp310 = _release("demo-1.0-cp310-cp310-manylinux1_x86_64.whl")
    cp39 = _release("demo-1.0-cp39-cp39-manylinux1_x86_64.whl")
    py3 = _release("demo-1.0-py3-none-any.whl")
    universal = _release("demo-1.0-py2.py3-none-any.whl")
    source = _release("demo-1.0.tar.gz")
    releases = [cp310, cp39, py3, universal, source]

    assert hashin.filter_releases(releases, ["3.10"]) == [
        cp310,
        py3,
        universal,
        source,
    ]


def test_run_with_python_310_finds_cp310_wheel(monkeypatch, tmp_path):
    """Regression test for the PackageError reported when running hashin."""
    digest = "a" * 64
    data = {
        "info": {"name": "demo", "version": "1.0"},
        "releases": {
            "1.0": [
                _release(
                    "demo-1.0-cp310-cp310-manylinux1_x86_64.whl",
                    digest,
                ),
                _release(
                    "demo-1.0-cp39-cp39-manylinux1_x86_64.whl",
                    "b" * 64,
                ),
            ]
        },
    }
    monkeypatch.setattr(
        hashin, "get_package_data", lambda *args, **kwargs: data
    )
    requirements_file = tmp_path / "requirements.txt"
    requirements_file.write_text("")

    result = hashin.run(
        ["demo==1.0"],
        str(requirements_file),
        "sha256",
        python_versions=["3.10"],
        synchronous=True,
    )

    assert result == 0
    assert requirements_file.read_text() == (
        "demo==1.0 \\\n"
        "    --hash=sha256:{}\n".format(digest)
    )

from dataclasses import dataclass, field
from typing import Any

from xsdata.formats.dataclass.filters import Filters
from xsdata.models.config import GeneratorConfig
from xsdata.models.enums import DataType
from xsdata.utils.testing import AttrFactory, ClassFactory


def ignore_field_definition(filters: Filters, target: Any) -> str:
    attr = AttrFactory.native(DataType.STRING)
    attr.restrictions.max_occurs = 0
    return filters.field_definition(target, attr, None)


def test_ignore_field_definition_disables_repr():
    filters = Filters(GeneratorConfig())
    target = ClassFactory.create(qname="a")

    result = ignore_field_definition(filters, target)

    assert "init=False" in result
    assert '"type": "Ignore"' in result
    assert "repr=False" in result


def test_generated_models_with_ignore_fields_can_be_reprd():
    """Uninitialized Ignore fields must not break nested dataclass reprs."""
    filters = Filters(GeneratorConfig())
    target = ClassFactory.create(qname="a")
    ignored = ignore_field_definition(filters, target)

    namespace = {
        "__name__": __name__,
        "dataclass": dataclass,
        "field": field,
        "Any": Any,
    }
    exec(
        f"""
@dataclass
class AccessibilityLimitationVersionedChildStructure:
    wheelchair_access: str = "false"


@dataclass
class AccessibilityLimitation(AccessibilityLimitationVersionedChildStructure):
    validity_conditions_or_valid_between: Any = {ignored}
    alternative_texts: Any = {ignored}


@dataclass
class StopPlace:
    accessibility_limitation: AccessibilityLimitation = field(
        default_factory=AccessibilityLimitation
    )
""",
        namespace,
    )

    limitation = namespace["AccessibilityLimitation"]()
    stop_place = namespace["StopPlace"]()

    assert repr(limitation) == (
        "AccessibilityLimitation(wheelchair_access='false')"
    )
    assert repr(stop_place) == (
        "StopPlace(accessibility_limitation="
        "AccessibilityLimitation(wheelchair_access='false'))"
    )

"""Regression tests for model initializers accepting variable arguments."""

import pytest

from mesa.visualization.solara_viz import _check_model_params


def test_kwargs_only_initializer_does_not_require_kwargs_parameter():
    """A **kwargs declaration is optional, not a required model parameter."""

    class ModelWithKwargs:
        def __init__(self, **kwargs):
            pass

    _check_model_params(ModelWithKwargs.__init__, {})


def test_kwargs_initializer_accepts_additional_model_configuration():
    """Extra fixed model parameters should be forwarded through **kwargs."""

    class ModelWithKwargs:
        def __init__(self, width, height=10, **configuration):
            pass

    # Optional declared parameters and **configuration may both be omitted.
    _check_model_params(ModelWithKwargs.__init__, {"width": 20})

    # The variable-keyword parameter need not literally be named "kwargs".
    _check_model_params(
        ModelWithKwargs.__init__,
        {
            "width": 20,
            "height": 30,
            "density": 0.8,
            "seed": 42,
        },
    )


def test_kwargs_does_not_bypass_required_parameter_validation():
    """Declared required parameters remain required when **kwargs is present."""

    class ModelWithKwargs:
        def __init__(self, width, *, height, optional=10, **kwargs):
            pass

    with pytest.raises(
        ValueError, match=r"Missing required model parameter: height$"
    ):
        _check_model_params(
            ModelWithKwargs.__init__,
            {"width": 20, "density": 0.8},
        )

    _check_model_params(
        ModelWithKwargs.__init__,
        {"width": 20, "height": 30, "density": 0.8},
    )


def test_unknown_parameters_remain_invalid_without_kwargs():
    """Support for **kwargs must not weaken validation of strict signatures."""

    class ModelWithoutKwargs:
        def __init__(self, width, height=10):
            pass

    _check_model_params(ModelWithoutKwargs.__init__, {"width": 20})

    with pytest.raises(ValueError, match=r"Invalid model parameter: density$"):
        _check_model_params(
            ModelWithoutKwargs.__init__,
            {"width": 20, "density": 0.8},
        )


def test_regular_parameter_named_kwargs_is_still_required():
    """Only the variable-keyword syntax is special, not the name 'kwargs'."""

    class ModelWithRegularKwargsParameter:
        def __init__(self, kwargs):
            pass

    with pytest.raises(
        ValueError, match=r"Missing required model parameter: kwargs$"
    ):
        _check_model_params(ModelWithRegularKwargsParameter.__init__, {})

    _check_model_params(
        ModelWithRegularKwargsParameter.__init__, {"kwargs": {"density": 0.8}}
    )


def test_var_positional_parameter_is_not_required():
    """*args, like **kwargs, does not need an entry in model_params."""

    class ModelWithArgs:
        def __init__(self, width, *args):
            pass

    _check_model_params(ModelWithArgs.__init__, {"width": 20})

"""Regression tests for ``qml.counts`` of mid-circuit measurement values."""

import numpy as np
import pytest

import pennylane as qml


SHOTS = 10


def _assert_integer_outcomes(counts):
    """MCM outcomes are integers, not floating-point samples."""
    assert all(isinstance(outcome, (int, np.integer)) for outcome in counts)


@pytest.mark.parametrize("mcm_method", ["deferred", "one-shot"])
@pytest.mark.parametrize(
    "measured_one, expected",
    [
        (False, {0: SHOTS, 1: 0}),
        (True, {0: 0, 1: SHOTS}),
    ],
)
def test_single_mcm_counts_include_all_outcomes(mcm_method, measured_one, expected):
    """All binary outcomes are returned, including an unobserved outcome."""
    dev = qml.device("default.qubit", wires=1, shots=SHOTS, seed=1234)

    @qml.qnode(dev, mcm_method=mcm_method)
    def circuit():
        if measured_one:
            qml.PauliX(0)
        m = qml.measure(0)
        return qml.counts(m, all_outcomes=True)

    counts = circuit()

    assert counts == expected
    assert set(counts) == {0, 1}
    assert sum(counts.values()) == SHOTS
    _assert_integer_outcomes(counts)


@pytest.mark.parametrize(
    "measured_one, expected",
    [
        (False, {0: SHOTS}),
        (True, {1: SHOTS}),
    ],
)
def test_single_mcm_counts_without_all_outcomes(measured_one, expected):
    """Requesting only observed outcomes must not add zero-count outcomes."""
    dev = qml.device("default.qubit", wires=1, shots=SHOTS, seed=1234)

    @qml.qnode(dev, mcm_method="one-shot")
    def circuit():
        if measured_one:
            qml.PauliX(0)
        m = qml.measure(0)
        return qml.counts(m)

    counts = circuit()

    assert counts == expected
    assert len(counts) == 1
    assert sum(counts.values()) == SHOTS
    _assert_integer_outcomes(counts)


def test_multiple_mcm_counts_include_all_bitstrings():
    """A list of MCMs has four possible outcomes, even for a deterministic circuit."""
    dev = qml.device("default.qubit", wires=2, shots=SHOTS, seed=1234)

    @qml.qnode(dev, mcm_method="one-shot")
    def circuit():
        qml.PauliX(1)
        m0 = qml.measure(0)
        m1 = qml.measure(1)
        return qml.counts(op=[m0, m1], all_outcomes=True)

    counts = circuit()

    assert counts == {"00": 0, "01": SHOTS, "10": 0, "11": 0}
    assert sum(counts.values()) == SHOTS


@pytest.mark.parametrize(
    "measured_one, expected",
    [
        (False, {0: SHOTS, 2: 0}),
        (True, {0: 0, 2: SHOTS}),
    ],
)
def test_transformed_mcm_counts_use_its_actual_outcomes(measured_one, expected):
    """All-outcomes handling must use the MeasurementValue's possible values.

    In particular, a transformed MCM must not receive hard-coded outcomes ``0``
    and ``1`` when its actual outcomes are ``0`` and ``2``.
    """
    dev = qml.device("default.qubit", wires=1, shots=SHOTS, seed=1234)

    @qml.qnode(dev, mcm_method="one-shot")
    def circuit():
        if measured_one:
            qml.PauliX(0)
        m = qml.measure(0)
        return qml.counts(2 * m, all_outcomes=True)

    counts = circuit()

    assert counts == expected
    assert set(counts) == {0, 2}
    assert sum(counts.values()) == SHOTS
    _assert_integer_outcomes(counts)


def test_composite_mcm_counts_include_all_composite_outcomes():
    """Arithmetic over several MCMs includes every possible composite value."""
    dev = qml.device("default.qubit", wires=2, shots=SHOTS, seed=1234)

    @qml.qnode(dev, mcm_method="one-shot")
    def circuit():
        qml.PauliX(1)
        m0 = qml.measure(0)
        m1 = qml.measure(1)
        return qml.counts(m0 + 2 * m1, all_outcomes=True)

    counts = circuit()

    assert counts == {0: 0, 1: 0, 2: SHOTS, 3: 0}
    assert sum(counts.values()) == SHOTS
    _assert_integer_outcomes(counts)

from __future__ import annotations

import pytest
import tomlkit

from pdm.project.core import Project


EDITABLE_REQUIREMENTS = [
    "-e file:///${PROJECT_ROOT}/packages/pkg-app#egg=pkg-app",
    "-e file:///${PROJECT_ROOT}/packages/pkg-core#egg=pkg-core",
]


def _read_pyproject(project: Project) -> dict:
    pyproject = project.root / "pyproject.toml"
    return tomlkit.parse(pyproject.read_text(encoding="utf-8")).unwrap()


def _add_requirement(
    project: Project, group: str, requirement: str = "ruff", *, dev: bool = True
) -> dict:
    """Update a group through the same Project API used by the add command."""
    dependencies, setter = project.use_pyproject_dependencies(group, dev=dev)
    setter([*dependencies, requirement])
    project.pyproject.write()
    return _read_pyproject(project)


@pytest.mark.parametrize("group", ["dev", "lint"], ids=["default-dev-group", "explicit-dev-group"])
@pytest.mark.parametrize("has_dependency_groups", [False, True], ids=["new-table", "existing-table"])
def test_add_dev_dependency_uses_requested_group_without_duplicating_editable_groups(
    project: Project, group: str, has_dependency_groups: bool
):
    legacy_groups = {"workspaces": EDITABLE_REQUIREMENTS.copy()}
    project.pyproject.settings["dev-dependencies"] = legacy_groups
    existing_groups = {"test": ["pytest>=8"]} if has_dependency_groups else None
    if existing_groups is not None:
        project.pyproject._data["dependency-groups"] = existing_groups
    project.pyproject.write()

    data = _add_requirement(project, group)

    expected_groups = dict(existing_groups or {})
    expected_groups[group] = ["ruff"]
    assert data["dependency-groups"] == expected_groups
    assert data["tool"]["pdm"]["dev-dependencies"] == legacy_groups


def test_add_to_existing_dependency_group_appends_without_touching_legacy_editable_group(
    project: Project,
):
    legacy_groups = {"workspaces": EDITABLE_REQUIREMENTS.copy()}
    project.pyproject.settings["dev-dependencies"] = legacy_groups
    project.pyproject._data["dependency-groups"] = {
        "dev": ["pytest>=8"],
        "lint": ["black>=25"],
    }
    project.pyproject.write()

    data = _add_requirement(project, "dev")

    assert data["dependency-groups"] == {
        "dev": ["pytest>=8", "ruff"],
        "lint": ["black>=25"],
    }
    assert data["tool"]["pdm"]["dev-dependencies"] == legacy_groups


def test_group_containing_both_editable_and_regular_requirements_is_not_partially_duplicated(
    project: Project,
):
    """A mixed legacy group must not be migrated partially, losing its editables."""
    legacy_groups = {
        "workspaces": [
            "-e file:///${PROJECT_ROOT}/packages/pkg-app#egg=pkg-app",
            "pytest>=8",
        ],
        "editable-only": EDITABLE_REQUIREMENTS.copy(),
    }
    project.pyproject.settings["dev-dependencies"] = legacy_groups
    project.pyproject._data["dependency-groups"] = {"test": ["coverage>=7"]}
    project.pyproject.write()

    data = _add_requirement(project, "dev")

    assert data["dependency-groups"] == {
        "test": ["coverage>=7"],
        "dev": ["ruff"],
    }
    assert "workspaces" not in data["dependency-groups"]
    assert "editable-only" not in data["dependency-groups"]
    assert data["tool"]["pdm"]["dev-dependencies"] == legacy_groups


def test_legacy_dev_table_does_not_change_non_dev_target_group(project: Project):
    """The legacy-group loop must not shadow optional-dependency targets either."""
    legacy_groups = {"workspaces": EDITABLE_REQUIREMENTS.copy()}
    project.pyproject.settings["dev-dependencies"] = legacy_groups
    project.pyproject._data["dependency-groups"] = {"test": ["pytest>=8"]}
    project.pyproject.write()

    data = _add_requirement(project, "docs", "sphinx>=8", dev=False)

    assert data["project"]["optional-dependencies"]["docs"] == ["sphinx>=8"]
    assert data["dependency-groups"] == {"test": ["pytest>=8"]}
    assert data["tool"]["pdm"]["dev-dependencies"] == legacy_groups

import pytest

import sqlglot


def _parse_div0(expression: str):
    return sqlglot.parse_one(
        f"SELECT {expression}", read=sqlglot.Dialects.SNOWFLAKE
    )


def _generate_div0(expression: str) -> str:
    return _parse_div0(expression).sql()


def _false_branch_sql(expression: str) -> str:
    if_expression = _parse_div0(expression).selects[0]
    return if_expression.args["false"].sql()


def test_div0_parenthesizes_subtraction_in_dividend():
    parsed = _parse_div0("div0(2 - 1, 1)")

    assert parsed.selects[0].args["false"].sql() == "(2 - 1) / 1"

    # Pretty printing may put the parenthesized expression on separate lines.
    pretty_sql = " ".join(parsed.sql(pretty=True).split())
    pretty_sql = pretty_sql.replace("( ", "(").replace(" )", ")")
    assert "ELSE (2 - 1) / 1 END" in pretty_sql


@pytest.mark.parametrize(
    ("expression", "explicitly_parenthesized"),
    [
        pytest.param(
            "div0(a + b, c - d)",
            "div0((a + b), (c - d))",
            id="addition-in-both-operands",
        ),
        pytest.param(
            "div0(a - b, c * d + e)",
            "div0((a - b), (c * d + e))",
            id="nested-arithmetic-in-divisor",
        ),
        pytest.param(
            "div0(a, b * c)",
            "div0(a, (b * c))",
            id="multiplication-in-divisor",
        ),
        pytest.param(
            "div0(a, b / c)",
            "div0(a, (b / c))",
            id="division-in-divisor",
        ),
        pytest.param(
            "div0((a + b) * c, d - e)",
            "div0((a + b) * c, (d - e))",
            id="existing-parentheses-in-dividend",
        ),
    ],
)
def test_div0_matches_explicitly_parenthesized_arithmetic(
    expression, explicitly_parenthesized
):
    # Compare the division itself: optional parentheses in the CASE condition
    # do not change its meaning. Parentheses in the divisor are necessary even
    # for multiplication and division because / and * associate left-to-right.
    assert _false_branch_sql(expression) == _false_branch_sql(
        explicitly_parenthesized
    )


def test_div0_simple_operands_retain_guarded_division():
    assert (
        _generate_div0("div0(a, b)")
        == "SELECT CASE WHEN b = 0 AND NOT a IS NULL THEN 0 ELSE a / b END"
    )

"""Regression tests for model initialization with variable keyword arguments."""

import pytest

from mesa.visualization.solara_viz import _check_model_params


def test_kwargs_only_model_does_not_require_kwargs_model_param():
    """The synthetic **kwargs parameter itself must not be treated as required."""

    class ModelWithKwargs:
        def __init__(self, **kwargs):
            pass

    _check_model_params(ModelWithKwargs.__init__, {})


def test_kwargs_model_accepts_additional_optional_configuration():
    """Extra model parameters are valid when the initializer accepts **kwargs."""

    class ModelWithKwargs:
        def __init__(self, required_param, optional_param=10, **kwargs):
            pass

    _check_model_params(
        ModelWithKwargs.__init__,
        {
            "required_param": 1,
            "optional_param": 5,
            "custom_option": "custom",
            "another_option": 42,
        },
    )


def test_kwargs_model_still_requires_named_parameters():
    """Accepting arbitrary keywords must not disable required-parameter checks."""

    class ModelWithKwargs:
        def __init__(self, required_param, **kwargs):
            pass

    with pytest.raises(
        ValueError, match="Missing required model parameter: required_param"
    ):
        _check_model_params(ModelWithKwargs.__init__, {})

    with pytest.raises(
        ValueError, match="Missing required model parameter: required_param"
    ):
        _check_model_params(ModelWithKwargs.__init__, {"custom_option": 1})


def test_kwargs_model_still_requires_keyword_only_parameters():
    """Required keyword-only parameters remain mandatory alongside **kwargs."""

    class ModelWithKwargs:
        def __init__(self, *, required_option, **kwargs):
            pass

    with pytest.raises(
        ValueError, match="Missing required model parameter: required_option"
    ):
        _check_model_params(ModelWithKwargs.__init__, {"custom_option": 1})

    _check_model_params(
        ModelWithKwargs.__init__,
        {"required_option": 1, "custom_option": 2},
    )


def test_variable_keyword_parameter_is_detected_by_kind_not_name():
    """Any VAR_KEYWORD parameter should work, not only one named kwargs."""

    class ModelWithOptions:
        def __init__(self, **options):
            pass

    _check_model_params(ModelWithOptions.__init__, {})
    _check_model_params(ModelWithOptions.__init__, {"custom_option": 1})


def test_regular_parameter_named_kwargs_is_still_required():
    """A normal parameter called kwargs is distinct from a **kwargs parameter."""

    class ModelWithNamedKwargsParameter:
        def __init__(self, kwargs):
            pass

    with pytest.raises(ValueError, match="Missing required model parameter: kwargs"):
        _check_model_params(ModelWithNamedKwargsParameter.__init__, {})

    _check_model_params(ModelWithNamedKwargsParameter.__init__, {"kwargs": {}})


def test_models_without_kwargs_still_reject_invalid_parameters():
    """The fix must not weaken validation for initializers without **kwargs."""

    class ModelWithoutKwargs:
        def __init__(self, required_param, optional_param=10):
            pass

    with pytest.raises(ValueError, match="Invalid model parameter: custom_option"):
        _check_model_params(
            ModelWithoutKwargs.__init__,
            {"required_param": 1, "custom_option": 2},
        )

import pytest

from markdownify import markdownify as md


def markdown_lines(html, **options):
    """Return the meaningful output lines, ignoring surrounding newlines."""
    return md(html, **options).strip("\n").split("\n")


def test_list_item_paragraph_separator_has_no_indentation():
    html = """
    <ul>
      <li>
        <p>1</p>
        <p>2</p>
      </li>
    </ul>
    """

    assert markdown_lines(html) == [
        "* 1",
        "",
        "  2",
    ]


def test_blockquote_paragraph_separator_has_no_marker_or_trailing_space():
    html = """
    <blockquote>
      <p>1</p>
      <p>2</p>
    </blockquote>
    """

    assert markdown_lines(html) == [
        "> 1",
        "",
        "> 2",
    ]


@pytest.mark.parametrize(
    "html, expected",
    [
        (
            "<ul><li><p>first</p><p>second</p><p>third</p></li></ul>",
            ["* first", "", "  second", "", "  third"],
        ),
        (
            "<blockquote><p>first</p><p>second</p><p>third</p></blockquote>",
            ["> first", "", "> second", "", "> third"],
        ),
    ],
)
def test_every_separator_between_multiple_paragraphs_is_optimized(html, expected):
    assert markdown_lines(html) == expected


def test_ordered_list_blank_line_is_empty_with_a_wide_bullet():
    # Continuation lines still need four spaces to align with "10. ", but the
    # separator itself must not contain those spaces.
    html = '<ol start="10"><li><p>1</p><p>2</p></li></ol>'

    assert markdown_lines(html) == [
        "10. 1",
        "",
        "    2",
    ]


@pytest.mark.parametrize(
    "html, expected",
    [
        (
            "<blockquote><p>outer</p><blockquote>"
            "<p>inner 1</p><p>inner 2</p>"
            "</blockquote></blockquote>",
            ["> outer", "", "> > inner 1", "", "> > inner 2"],
        ),
        (
            "<ul><li><blockquote><p>one</p><p>two</p></blockquote></li></ul>",
            ["* > one", "", "  > two"],
        ),
        (
            "<blockquote><ul><li><p>one</p><p>two</p></li></ul></blockquote>",
            ["> * one", "", ">   two"],
        ),
    ],
)
def test_empty_lines_remain_unpadded_in_nested_structures(html, expected):
    assert markdown_lines(html) == expected


@pytest.mark.parametrize(
    "html, expected",
    [
        (
            "<ul><li><p>one<br>two</p><p>three</p></li></ul>",
            ["* one  ", "  two", "", "  three"],
        ),
        (
            "<blockquote><p>one<br>two</p><p>three</p></blockquote>",
            ["> one  ", "> two", "", "> three"],
        ),
    ],
)
def test_hard_break_spaces_on_nonempty_lines_are_preserved(html, expected):
    # The two spaces produced by <br> are meaningful Markdown and must not be
    # removed while optimizing genuinely empty separator lines.
    assert markdown_lines(html) == expected


@pytest.mark.parametrize(
    "html, expected",
    [
        ("<ul><li><p>only</p></li></ul>", ["* only"]),
        ("<blockquote><p>only</p></blockquote>", ["> only"]),
    ],
)
def test_single_paragraph_output_is_unchanged(html, expected):
    assert markdown_lines(html) == expected


def test_empty_containers_do_not_acquire_markers_or_indentation():
    assert md("<blockquote></blockquote>").strip() == ""
    assert md("<ul><li></li></ul>").strip() == ""

