import pytest
import tomlkit

from pdm.project.core import Project


def _editable_requirement(name: str) -> str:
    return f"-e file:///${{PROJECT_ROOT}}/packages/{name}#egg={name}"


def _read_pyproject(project: Project):
    return tomlkit.parse((project.root / "pyproject.toml").read_text(encoding="utf-8"))


@pytest.mark.parametrize("requested_group", ["dev", "lint"])
@pytest.mark.parametrize(
    "existing_dependencies",
    [
        pytest.param(None, id="new-group"),
        pytest.param(["pytest"], id="existing-dependency-group"),
    ],
)
def test_add_dev_dependency_uses_requested_group_and_preserves_legacy_groups(
    project: Project,
    requested_group: str,
    existing_dependencies: list[str] | None,
):
    """The pyproject update performed by ``pdm add -d[-G ...]`` must use its target group."""
    legacy_groups = {
        "docs": [_editable_requirement("pkg-docs")],
        "workspaces": [
            _editable_requirement("pkg-app"),
            _editable_requirement("pkg-core"),
        ],
    }
    project.pyproject.settings["dev-dependencies"] = legacy_groups
    project.pyproject._data["dependency-groups"] = (
        {} if existing_dependencies is None else {requested_group: list(existing_dependencies)}
    )

    project.add_dependencies(["ruff"], to_group=requested_group, dev=True)

    data = _read_pyproject(project)
    dependency_groups = data["dependency-groups"]
    expected = [*(existing_dependencies or []), "ruff"]

    assert set(dependency_groups) == {requested_group}
    assert list(dependency_groups[requested_group]) == expected

    # Legacy editable groups must neither be modified nor copied to PEP 735.
    saved_legacy_groups = data["tool"]["pdm"]["dev-dependencies"]
    assert set(saved_legacy_groups) == set(legacy_groups)
    for group, requirements in legacy_groups.items():
        assert list(saved_legacy_groups[group]) == requirements


@pytest.mark.parametrize(
    "existing_dependencies",
    [
        pytest.param(None, id="new-group"),
        pytest.param(["pytest"], id="existing-dependency-group"),
    ],
)
def test_add_to_group_with_legacy_editables_does_not_duplicate_them(
    project: Project,
    existing_dependencies: list[str] | None,
):
    """A target group present in both tables must not have its editables copied to PEP 735."""
    editable = _editable_requirement("pkg-app")
    project.pyproject.settings["dev-dependencies"] = {"dev": [editable]}
    project.pyproject._data["dependency-groups"] = (
        {} if existing_dependencies is None else {"dev": list(existing_dependencies)}
    )

    project.add_dependencies(["ruff"], to_group="dev", dev=True)

    data = _read_pyproject(project)
    dependency_groups = data["dependency-groups"]
    expected = [*(existing_dependencies or []), "ruff"]

    assert set(dependency_groups) == {"dev"}
    assert list(dependency_groups["dev"]) == expected
    assert editable not in dependency_groups["dev"]
    assert list(data["tool"]["pdm"]["dev-dependencies"]["dev"]) == [editable]

