from typing import Any

import pytest
import tomlkit

from pdm.project.core import Project


EDITABLE_APP = "-e file:///${PROJECT_ROOT}/packages/pkg-app#egg=pkg-app"
EDITABLE_CORE = "-e file:///${PROJECT_ROOT}/packages/pkg-core#egg=pkg-core"


def _set_legacy_dev_dependencies(project: Project, groups: dict[str, list[str]]) -> None:
    project.pyproject.settings["dev-dependencies"] = groups
    project.pyproject.write()


def _read_pyproject(project: Project) -> dict[str, Any]:
    document = tomlkit.parse((project.root / "pyproject.toml").read_text(encoding="utf-8"))
    return document.unwrap()


@pytest.mark.parametrize("group", ["dev", "lint"])
def test_add_normal_dev_dependency_uses_requested_pep735_group(project: Project, group: str) -> None:
    """Cover both ``pdm add -d`` and ``pdm add -dG <group>`` file updates."""
    legacy_groups = {
        "workspaces": [EDITABLE_APP, EDITABLE_CORE],
        "formatting": ["-e file:///${PROJECT_ROOT}/packages/formatter#egg=formatter"],
    }
    _set_legacy_dev_dependencies(project, legacy_groups)

    # dev=True selects the dependency-group behavior used by ``pdm add -d``.
    project.add_dependencies(["ruff"], to_group=group, dev=True, show_message=False)

    data = _read_pyproject(project)
    assert data["dependency-groups"] == {group: ["ruff"]}
    assert data["tool"]["pdm"]["dev-dependencies"] == legacy_groups


def test_add_does_not_copy_target_legacy_group_into_dependency_groups(project: Project) -> None:
    """A legacy group with the requested name must not be migrated implicitly."""
    legacy_groups = {
        "dev": [EDITABLE_APP],
        "workspaces": [EDITABLE_CORE],
    }
    _set_legacy_dev_dependencies(project, legacy_groups)

    project.add_dependencies(["ruff"], to_group="dev", dev=True, show_message=False)

    data = _read_pyproject(project)
    # The new normal dependency belongs in a new PEP 735 group. In particular,
    # the editable entry must not also be written to that group.
    assert data["dependency-groups"] == {"dev": ["ruff"]}
    assert data["tool"]["pdm"]["dev-dependencies"] == legacy_groups

    # Both sources still contribute to the combined view of the group.
    requirements = project.get_dependencies("dev")
    assert {requirement.name for requirement in requirements} == {"pkg-app", "ruff"}
    editable = next(requirement for requirement in requirements if requirement.name == "pkg-app")
    assert editable.editable


def test_add_preserves_existing_dependency_group_without_duplicating_legacy_groups(
    project: Project,
) -> None:
    legacy_groups = {"workspaces": [EDITABLE_APP, EDITABLE_CORE]}
    _set_legacy_dev_dependencies(project, legacy_groups)
    project.pyproject.dependency_groups["lint"] = ["pytest"]
    project.pyproject.write()

    project.add_dependencies(["ruff"], to_group="lint", dev=True, show_message=False)

    data = _read_pyproject(project)
    assert data["dependency-groups"] == {"lint": ["pytest", "ruff"]}
    assert data["tool"]["pdm"]["dev-dependencies"] == legacy_groups


def test_legacy_group_lookup_and_write_does_not_create_pep735_copy(project: Project) -> None:
    """Even a no-op update of a legacy editable group must not duplicate it."""
    legacy_groups = {"dev": [EDITABLE_APP]}
    _set_legacy_dev_dependencies(project, legacy_groups)

    dependencies, setter = project.use_pyproject_dependencies("dev", dev=True)
    assert list(dependencies) == legacy_groups["dev"]

    setter(dependencies)
    project.pyproject.write()

    data = _read_pyproject(project)
    assert data["tool"]["pdm"]["dev-dependencies"] == legacy_groups
    assert data.get("dependency-groups", {}) == {}

