import pytest
import tomlkit

from pdm.project.core import Project


EDITABLE_APP = "-e file:///${PROJECT_ROOT}/packages/pkg-app#egg=pkg-app"
EDITABLE_CORE = "-e file:///${PROJECT_ROOT}/packages/pkg-core#egg=pkg-core"


def _add_requirement(project: Project, group: str, requirement: str) -> None:
    """Add a requirement through the same pyproject API used by ``pdm add``."""
    dependencies, setter = project.use_pyproject_dependencies(group, dev=True)
