def _dependency_groups(document) -> dict[str, list[str]]:
    return {name: list(items) for name, items in document.get("dependency-groups", {}).items()}


def _legacy_dev_dependencies(document) -> dict[str, list[str]]:
    settings = document.get("tool", {}).get("pdm", {})
    return {name: list(items) for name, items in settings.get("dev-dependencies", {}).items()}


def _set_legacy_dev_dependencies(project: Project, groups: dict[str, list[str]]) -> None:
