    legacy_groups = {"workspaces": [EDITABLE_APP, EDITABLE_CORE]}
    _set_legacy_dev_dependencies(project, legacy_groups)

    _add_requirement(project, target_group, "ruff")

    document = _read_pyproject(project)
    assert _dependency_groups(document) == {target_group: ["ruff"]}
    assert _legacy_dev_dependencies(document) == legacy_groups


