        "lint": [EDITABLE_APP],
        "workspaces": [EDITABLE_CORE],
    }
    _set_legacy_dev_dependencies(project, legacy_groups)

    _add_requirement(project, "lint", "ruff")

    document = _read_pyproject(project)
    assert _dependency_groups(document) == {"lint": ["ruff"]}
    assert _legacy_dev_dependencies(document) == legacy_groups


