import re

import sqlglot
from sqlglot import exp


ISSUE_SQL = """
CREATE TABLE temp
(
    id SERIAL PRIMARY KEY
);
"""


def _transpile_one(sql: str, **kwargs) -> str:
    result = sqlglot.transpile(sql, read="mysql", write="mysql", **kwargs)
    assert len(result) == 1
    return result[0]


def _constraint_count(column: exp.ColumnDef, constraint_type: type) -> int:
    return sum(
        isinstance(constraint.args.get("kind"), constraint_type)
        for constraint in column.args.get("constraints", [])
    )


def _assert_mysql_serial_column(sql: str, column_name: str = "id", **kwargs):
    """SERIAL may be retained or expanded to its documented MySQL alias."""
    output = _transpile_one(sql, **kwargs)

    # The generated SQL must itself be accepted by the MySQL dialect.
    statement = sqlglot.parse_one(output, read="mysql")
    column = next(
        (
            candidate
            for candidate in statement.find_all(exp.ColumnDef)
            if candidate.name == column_name
        ),
        None,
    )
    assert column is not None, output

    # MySQL supports SERIAL natively, so preserving it is semantics-preserving.
    if re.search(r"\bSERIAL\b", output, flags=re.IGNORECASE):
        return output, column

    # If SERIAL is expanded, it must retain the full meaning of MySQL's alias:
    # BIGINT UNSIGNED NOT NULL AUTO_INCREMENT UNIQUE.
    assert isinstance(column.kind, exp.DataType)
    assert column.kind.this == exp.DataType.Type.UBIGINT, output
    for constraint_type in (
        exp.NotNullColumnConstraint,
        exp.AutoIncrementColumnConstraint,
        exp.UniqueColumnConstraint,
    ):
        assert _constraint_count(column, constraint_type) == 1, output

    return output, column


def test_mysql_serial_issue_reproduction():
    _, column = _assert_mysql_serial_column(
        ISSUE_SQL,
        pretty=True,
        comments=False,
    )

    # Expanding SERIAL must not discard the column's existing PRIMARY KEY.
    assert _constraint_count(column, exp.PrimaryKeyColumnConstraint) == 1


def test_mysql_serial_is_case_insensitive_without_other_constraints():
    # This also exercises SERIAL without PRIMARY KEY, where UNIQUE and the other
    # implicit attributes cannot be inferred from another supplied constraint.
    _assert_mysql_serial_column("CREATE TABLE t (id serial)")


def test_mysql_serial_does_not_duplicate_existing_constraints():
    _, column = _assert_mysql_serial_column(
        """
        CREATE TABLE t (
            id SERIAL NOT NULL AUTO_INCREMENT UNIQUE PRIMARY KEY
        )
        """
    )

    for constraint_type in (
        exp.NotNullColumnConstraint,
        exp.AutoIncrementColumnConstraint,
        exp.UniqueColumnConstraint,
        exp.PrimaryKeyColumnConstraint,
    ):
        assert _constraint_count(column, constraint_type) == 1


def test_mysql_serial_generated_sql_is_stable_on_round_trip():
