import ast
from collections import namedtuple
from textwrap import dedent

import pytest

from wemake_python_styleguide.options.config import Configuration
from wemake_python_styleguide.transformations.ast_tree import transform
from wemake_python_styleguide.violations.complexity import (
    TooManyLocalsViolation,
)
from wemake_python_styleguide.visitors.ast.complexity.function import (
    FunctionComplexityVisitor,
)


_ISSUE_EXAMPLE = '''
def querybuilder_form_data_factory(querybuilder_consts, faker_seed):
    """Create context-aware fixture for the form data."""
    consts = querybuilder_hh_consts

    def factory(field):
        return lambda: choice(list(field.keys()))

    class InnerFactory:
        __random_seed__ = faker_seed

        area = factory(consts.areas)
        country = factory(consts.countries)
        citizenship = factory(consts.countries)
        professional_role = factory(consts.professional_roles)
        gender = factory(consts.gender)
        employment = factory(consts.employment)
        schedule = factory(consts.schedule)

    return InnerFactory
'''


def _assignments(prefix: str, count: int, indentation: str) -> str:
    return '\n'.join(
        f'{indentation}{prefix}{index} = {index}'
        for index in range(count)
    )


def _create_options(**overrides):
    default_values = {
        option.long_option_name[2:].replace('-', '_'): option.default
        for option in Configuration._options  # noqa: WPS437
    }
    default_values.update(overrides)
    options_type = namedtuple('Options', default_values.keys())
    return options_type(**default_values)


def _run_visitor(code: str, max_local_variables: int = 5):
    tree = transform(ast.parse(dedent(code)))
    visitor = FunctionComplexityVisitor(
        _create_options(max_local_variables=max_local_variables),
        tree=tree,
    )
    visitor.run()
    return visitor


def _assert_single_locals_violation(visitor, count: int, limit: int) -> None:
    assert len(visitor.violations) == 1
    violation = visitor.violations[0]
    assert isinstance(violation, TooManyLocalsViolation)
    assert violation.message() == violation.error_template.format(
        str(count),
        baseline=limit,
    )


def test_issue_example_has_no_excess_locals():
    """Class attributes and nested-function locals belong to their scopes."""
    visitor = _run_visitor(_ISSUE_EXAMPLE)

    assert visitor.violations == []


def test_nested_class_does_not_affect_locals_at_the_limit():
    """An enclosing function at its local-variable limit remains valid."""
    limit = 5
    code = f'''
def outer():
{_assignments('outer_', limit, '    ')}
    class Nested:
{_assignments('attribute_', limit + 2, '        ')}
'''
    visitor = _run_visitor(code, max_local_variables=limit)

    assert visitor.violations == []


def test_enclosing_function_reports_only_its_own_locals():
    """Nested class attributes must not inflate the reported local count."""
    limit = 5
    code = f'''
def outer():
{_assignments('outer_', limit + 1, '    ')}
    class Nested:
{_assignments('attribute_', limit + 2, '        ')}
'''
    visitor = _run_visitor(code, max_local_variables=limit)

    _assert_single_locals_violation(visitor, limit + 1, limit)


@pytest.mark.parametrize('definition', ['def', 'async def'])
def test_nested_function_locals_are_checked_in_the_nested_function(definition):
    """Nested locals count toward the nested function, not its parent."""
    limit = 5
    code = f'''
{definition} outer():
    outer_variable = 0
    {definition} inner():
{_assignments('inner_', limit + 1, '        ')}
'''
    visitor = _run_visitor(code, max_local_variables=limit)

    _assert_single_locals_violation(visitor, limit + 1, limit)


def test_deeply_nested_function_has_an_independent_local_scope():
    """Scope isolation applies at every nesting depth."""
    limit = 5
    code = f'''
def outer():
    outer_variable = 0
    def middle():
        middle_variable = 0
        def inner():
{_assignments('inner_', limit + 1, '            ')}
'''
    visitor = _run_visitor(code, max_local_variables=limit)

    _assert_single_locals_violation(visitor, limit + 1, limit)


def test_method_of_nested_class_retains_its_own_locals():
    """A nested class hides method locals from outer, but not from method."""
    limit = 5
    code = f'''
def outer():
    class Nested:
        def method(self):
{_assignments('method_', limit + 1, '            ')}
'''
    visitor = _run_visitor(code, max_local_variables=limit)

    _assert_single_locals_violation(visitor, limit + 1, limit)

