import pytest

from pyopenapi3.schemas import ObjectsDTSchema, StringDTSchema


def assert_free_form(schema):
    """Check the semantics without requiring one particular serialization."""
    assert schema.type == "object"
    assert schema.properties is None or schema.properties == {}

    serialized = schema.dict()
    assert serialized["type"] == "object"
    assert serialized.get("properties", {}) == {}

    # Omitting additionalProperties is equivalent to true for a free-form
    # object. An empty schema is the other explicitly equivalent spelling.
    additional = serialized.get("additionalProperties", True)
    assert additional is True or additional == {}


@pytest.mark.parametrize(
    "properties_kwargs",
    [
        {},
        {"properties": None},
        {"properties": {}},
    ],
    ids=["omitted", "none", "empty"],
)
def test_object_without_named_properties_is_free_form(properties_kwargs):
    schema = ObjectsDTSchema(
        type="object",
        description="Custom tags",
        **properties_kwargs,
    )

    assert_free_form(schema)
    assert schema.dict()["description"] == "Custom tags"


@pytest.mark.parametrize("additional_properties", [True, {}])
def test_explicit_free_form_spellings_do_not_require_properties(
    additional_properties,
):
    schema = ObjectsDTSchema.parse_obj(
        {
            "type": "object",
            "description": "Custom tags",
            "additionalProperties": additional_properties,
        }
    )

    assert_free_form(schema)
    assert (
