    assert schema.dict()["additionalProperties"] is False


def test_free_form_object_can_be_nested_as_in_pet_tags_example():
    tags = ObjectsDTSchema(type="object", description="Custom tags")
    pet = ObjectsDTSchema(
        type="object",
        properties={"tags": tags},
    )

    assert_free_form(tags)

    serialized = pet.dict()
    serialized_tags = serialized["properties"]["tags"]
    assert serialized_tags["type"] == "object"
    assert serialized_tags["description"] == "Custom tags"
