    # properties. Explicitly serializing it as true or {} is equivalent.
    if "additionalProperties" in data:
        additional = data["additionalProperties"]
        assert additional is True or additional == {}


@pytest.mark.parametrize(
    "kwargs",
    [
        {},
        {"properties": None},
        {"properties": {}},
        {"additionalProperties": True},
        {"additionalProperties": {}},
        {"additional_properties": True},
        {"additional_properties": {}},
    ],
)
def test_free_form_object_variants_are_accepted(kwargs):
    schema = ObjectsDTSchema(description="Custom tags", **kwargs)

    serialized = schema.dict()
    assert serialized["description"] == "Custom tags"
    _assert_free_form_object(serialized)

    # The JSON representation must retain the same free-form semantics.
    _assert_free_form_object(json.loads(schema.json()))


def test_free_form_object_can_be_nested_as_in_the_issue():
    tags = ObjectsDTSchema(description="Custom tags")
    pet = ObjectsDTSchema(properties={"tags": tags})

    serialized = pet.dict()

    assert serialized["type"] == "object"
    tags_schema = serialized["properties"]["tags"]
    assert tags_schema["description"] == "Custom tags"
    _assert_free_form_object(tags_schema)


@pytest.mark.parametrize("keyword", ["additionalProperties", "additional_properties"])
@pytest.mark.parametrize(
    "properties",
    [
        None,
        {},
        {"name": {"type": "string"}},
    ],
)
def test_explicitly_disallowed_additional_properties_are_preserved(
    keyword, properties
):
    kwargs = {keyword: False}
    if properties is not None:
        kwargs["properties"] = properties

    schema = ObjectsDTSchema(**kwargs)
    serialized = schema.dict()

    assert serialized["type"] == "object"
    assert serialized["additionalProperties"] is False
    if properties:
        assert serialized["properties"] == {"name": {"type": "string"}}


def test_declared_properties_are_not_discarded():
    schema = ObjectsDTSchema(
        properties={
            "id": {"type": "integer", "format": "int64"},
            "name": {"type": "string"},
        }
    )

    serialized = schema.dict()

    assert serialized["type"] == "object"
    assert serialized["properties"] == {
        "id": {"type": "integer", "format": "int64"},
        "name": {"type": "string"},
    }

import pytest

from pyopenapi3.schemas import ObjectsDTSchema


def assert_free_form_object(document):
    """Check any of the OpenAPI-equivalent free-form object representations."""
    assert document["type"] == "object"
    assert not document.get("properties")

    # Omitting additionalProperties also permits arbitrary properties.
    additional = document.get("additionalProperties", True)
    assert additional is True or additional == {}


def test_object_without_properties_is_allowed_and_free_form():
    schema = ObjectsDTSchema(description="Custom tags")

    document = schema.dict()

    assert document["description"] == "Custom tags"
    assert_free_form_object(document)


def test_free_form_object_can_be_nested_as_a_component_property():
    tags = ObjectsDTSchema(description="Custom tags")
    pet = ObjectsDTSchema(properties={"tags": tags})

    document = pet.dict()

    assert set(document["properties"]) == {"tags"}
    tags_document = document["properties"]["tags"]
    assert tags_document["description"] == "Custom tags"
    assert_free_form_object(tags_document)

    # Declaring an ordinary property must not make the containing object
    # acquire an unrelated explicit additionalProperties setting.
    assert "additionalProperties" not in document


@pytest.mark.parametrize(
    "kwargs",
    [
        {},
        {"properties": None},
        {"properties": {}},
    ],
)
def test_object_schema_accepts_missing_or_empty_properties(kwargs):
    document = ObjectsDTSchema(**kwargs).dict()

    assert_free_form_object(document)


