"""Tests for isolating control planes on configurable message-queue topics."""

import pytest

from llama_deploy import ControlPlaneServer, SimpleMessageQueue, SimpleOrchestrator
from llama_deploy.control_plane.server import ControlPlaneConfig
from llama_deploy.message_consumers.callable import CallableMessageConsumer
from llama_deploy.message_consumers.remote import RemoteMessageConsumer


def make_control_plane(
    message_queue: SimpleMessageQueue, **kwargs
) -> ControlPlaneServer:
    return ControlPlaneServer(
        message_queue=message_queue,
        orchestrator=SimpleOrchestrator(),
        **kwargs,
    )


@pytest.mark.parametrize("remote", [False, True])
def test_default_topic_is_backward_compatible(remote: bool) -> None:
    """Existing deployments should continue using the original topic."""
    control_plane = make_control_plane(SimpleMessageQueue())

    consumer = control_plane.as_consumer(remote=remote)

    assert consumer.message_type == "control_plane"


@pytest.mark.parametrize("remote", [False, True])
@pytest.mark.parametrize(
    "topic_name",
    [
        "deployment_a_control_plane",
        "control-plane_123.special",
    ],
)
def test_custom_topic_is_used_by_both_consumer_types(
    remote: bool, topic_name: str
) -> None:
    """Manual deployments can select a topic for local or remote consumption."""
    control_plane = make_control_plane(
        SimpleMessageQueue(), control_plane_name=topic_name
    )

    consumer = control_plane.as_consumer(remote=remote)

    assert consumer.message_type == topic_name
    if remote:
        assert isinstance(consumer, RemoteMessageConsumer)
    else:
        assert isinstance(consumer, CallableMessageConsumer)


def test_topic_can_be_configured_through_control_plane_settings(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    """Settings-based deployments must propagate the topic to the server."""
    monkeypatch.setenv(
        "CONTROL_PLANE_CONTROL_PLANE_NAME", "api_server_deployment_control_plane"
    )
    config = ControlPlaneConfig()

    control_plane = make_control_plane(SimpleMessageQueue(), **config.model_dump())

    assert config.control_plane_name == "api_server_deployment_control_plane"
    assert (
        control_plane.as_consumer().message_type
        == "api_server_deployment_control_plane"
    )
    assert (
        control_plane.as_consumer(remote=True).message_type
        == "api_server_deployment_control_plane"
    )


@pytest.mark.asyncio
async def test_control_planes_register_independently_on_their_own_topics() -> None:
    """Two control planes sharing a queue must not share a consumer topic."""
    message_queue = SimpleMessageQueue()
    first = make_control_plane(
        message_queue, control_plane_name="first_deployment_control_plane"
    )
    second = make_control_plane(
        message_queue, control_plane_name="second_deployment_control_plane"
    )

    first_consumer = first.as_consumer()
    second_consumer = second.as_consumer()
    await message_queue.register_consumer(first_consumer)
    await message_queue.register_consumer(second_consumer)

    first_topic_consumers = await message_queue.get_consumers(
        "first_deployment_control_plane"
    )
    second_topic_consumers = await message_queue.get_consumers(
        "second_deployment_control_plane"
    )

    assert {consumer.id_ for consumer in first_topic_consumers} == {
        first.publisher_id
    }
    assert {consumer.id_ for consumer in second_topic_consumers} == {
        second.publisher_id
    }
    assert first.publisher_id != second.publisher_id


@pytest.mark.asyncio
async def test_register_to_message_queue_uses_custom_topic_for_remote_consumer() -> (
    None
):
    """The normal server registration path must also honor the configured topic."""
    message_queue = SimpleMessageQueue()
    control_plane = make_control_plane(
        message_queue, control_plane_name="remote_deployment_control_plane"
    )

    start_consuming = await control_plane.register_to_message_queue()

    assert callable(start_consuming)
    registered = await message_queue.get_consumers(
        "remote_deployment_control_plane"
    )
    assert len(registered) == 1
    assert isinstance(registered[0], RemoteMessageConsumer)
    assert registered[0].id_ == control_plane.publisher_id
    assert registered[0].message_type == "remote_deployment_control_plane"

import pytest

from vyper.exceptions import OverflowException, TypeMismatch


def _constant_return_source(expression: str, return_type: str = "uint256") -> str:
    return f"""
@external
def foo() -> {return_type}:
    return {expression}
"""


def test_nested_literal_exponentiation_issue_example(get_contract):
    # 10**36 is well below the uint256 maximum of 2**256 - 1.
    contract = get_contract(_constant_return_source("(10**18)**2"))
    assert contract.foo() == 10**36


@pytest.mark.parametrize(
    "expression,expected",
    [
        ("(2**127)**2", 2**254),
        ("(2**255)**1", 2**255),
        # This result is 2**256 - 2**129 + 1, so it still fits in uint256.
        ("(2**128 - 1)**2", (2**128 - 1) ** 2),
    ],
)
def test_nested_literal_exponentiation_valid_results(get_contract, expression, expected):
    contract = get_contract(_constant_return_source(expression))
    assert contract.foo() == expected


@pytest.mark.parametrize(
    "expression",
    [
        # Exactly one greater than the uint256 maximum.
        "(2**128)**2",
        "(2**255)**2",
        # The inner result fits in uint256, but the outer result does not.
        "(10**39)**2",
    ],
)
def test_nested_literal_exponentiation_real_overflows_still_fail(
    get_contract, assert_compile_failed, expression
):
    assert_compile_failed(
        lambda: get_contract(_constant_return_source(expression)), OverflowException
    )


def test_nested_literal_exponentiation_respects_narrow_integer_bounds(
    get_contract, assert_compile_failed
):
    contract = get_contract(_constant_return_source("(2**3)**2", "uint8"))
    assert contract.foo() == 64

    # The folded value 256 cannot be returned as uint8. Depending on whether
    # rejection happens during folding or return-type validation, the compiler
    # reports an overflow or a literal/type mismatch.
    assert_compile_failed(
        lambda: get_contract(_constant_return_source("(2**4)**2", "uint8")),
        (OverflowException, TypeMismatch),
    )

import numpy as np
import pytest

from unyt import cm, unyt_array, unyt_quantity


def take_via(interface, array, indices, **kwargs):
    if interface == "method":
        return array.take(indices, **kwargs)
    return np.take(array, indices, **kwargs)


@pytest.mark.parametrize("interface", ["method", "numpy"])
@pytest.mark.parametrize(
    "index, expected",
    [
        (0, 1),
        (-1, 3),
        (np.int64(1), 2),
        (np.array(2), 3),
    ],
)
def test_take_scalar_index_preserves_units(interface, index, expected):
    data = unyt_array([1, 2, 3], cm)

    result = take_via(interface, data, index)

    assert isinstance(result, unyt_quantity)
    assert result.shape == ()
    assert result.units == cm
    assert result.dtype == data.dtype
    assert result.to_value(cm) == expected


@pytest.mark.parametrize("interface", ["method", "numpy"])
@pytest.mark.parametrize(
    "indices, expected",
    [
        ([0], [1]),
        ([0, 2], [1, 3]),
        (np.array([2, 0]), [3, 1]),
    ],
)
def test_take_array_indices_still_returns_unyt_array(
    interface, indices, expected
):
    data = unyt_array([1, 2, 3], cm)

    result = take_via(interface, data, indices)

    assert isinstance(result, unyt_array)
    assert result.units == cm
    assert result.shape == (len(expected),)
    np.testing.assert_array_equal(result.to_value(cm), expected)


@pytest.mark.parametrize("interface", ["method", "numpy"])
@pytest.mark.parametrize(
    "axis, index, expected_shape, expected",
    [
        (0, 1, (3,), [4, 5, 6]),
        (1, -1, (2,), [3, 6]),
    ],
)
def test_take_scalar_index_along_axis_preserves_units(
    interface, axis, index, expected_shape, expected
):
    data = unyt_array([[1, 2, 3], [4, 5, 6]], cm)

    result = take_via(interface, data, index, axis=axis)

    assert isinstance(result, unyt_array)
    assert result.units == cm
    assert result.shape == expected_shape
    np.testing.assert_array_equal(result.to_value(cm), expected)


@pytest.mark.parametrize("interface", ["method", "numpy"])
def test_take_from_scalar_quantity_preserves_units(interface):
    data = unyt_quantity(2.5, cm)

    result = take_via(interface, data, 0)

    assert isinstance(result, unyt_quantity)
    assert result.shape == ()
    assert result.units == cm
    assert result.to_value(cm) == 2.5

