import pytest

from pyopenapi3.schemas import ArrayDTSchema, ObjectsDTSchema


def test_free_form_object_without_properties_is_valid():
    schema = ObjectsDTSchema.parse_obj(
        {
            "type": "object",
            "description": "Custom tags",
        }
    )

    assert schema.properties is None
    assert schema.dict() == {
        "type": "object",
        "description": "Custom tags",
    }


def test_issue_example_allows_nested_free_form_object():
    tags = ObjectsDTSchema.parse_obj(
        {
            "type": "object",
            "description": "Custom tags",
        }
    )
    pet = ObjectsDTSchema(
        type="object",
        properties={"tags": tags},
    )

    assert pet.dict() == {
