import pytest

from pyopenapi3.schemas import (
    ObjectsDTSchema,
    ReferenceObject,
    SchemaObject,
)


@pytest.mark.parametrize(
    "payload, expected",
    [
        ({}, {"type": "object"}),
        (
            {"description": "Custom tags"},
            {"type": "object", "description": "Custom tags"},
        ),
        (
            {"properties": None},
            {"type": "object"},
        ),
        (
            {"additionalProperties": True},
            {"type": "object", "additionalProperties": True},
        ),
        (
            {"additionalProperties": {}},
            {"type": "object", "additionalProperties": {}},
        ),
    ],
)
def test_free_form_object_does_not_require_properties(payload, expected):
    """All three OpenAPI spellings of a free-form object are valid."""
    schema = ObjectsDTSchema(**payload)

    assert schema.type == "object"
    assert schema.properties is None
    assert schema.dict() == expected


def test_free_form_object_can_be_used_as_a_nested_property():
    """The Pet/tags example from the issue should validate and round-trip."""
    pet = ObjectsDTSchema.parse_obj(
        {
            "type": "object",
            "properties": {
                "tags": {
                    "type": "object",
                    "description": "Custom tags",
                }
            },
        }
    )

    tags = pet.properties["tags"]
    assert isinstance(tags, SchemaObject)
    assert tags.type == "object"
    assert tags.properties is None

    assert pet.dict() == {
        "type": "object",
        "properties": {
            "tags": {
                "type": "object",
                "description": "Custom tags",
            }
        },
    }


def test_explicitly_empty_properties_mapping_is_preserved():
    schema = ObjectsDTSchema(properties={})

    assert schema.properties == {}
    assert schema.dict() == {"type": "object", "properties": {}}


def test_declared_properties_and_references_are_still_supported():
    """Making properties optional must not discard ordinary object schemas."""
    pet = ObjectsDTSchema(
        properties={
            "name": {"type": "string"},
            "owner": {"$ref": "#/components/schemas/Owner"},
        }
    )

    assert isinstance(pet.properties["name"], SchemaObject)
    assert isinstance(pet.properties["owner"], ReferenceObject)
    assert pet.dict() == {
        "type": "object",
        "properties": {
            "name": {"type": "string"},
            "owner": {"$ref": "#/components/schemas/Owner"},
        },
    }

