from pyopenapi3.schemas import ObjectsDTSchema


def test_issue_example_allows_free_form_tags_object():
    """A property declared only as ``type: object`` needs no properties map."""
    tags = ObjectsDTSchema(type="object", description="Custom tags")
    pet = ObjectsDTSchema(type="object", properties={"tags": tags})

    assert tags.properties is None
    assert pet.dict() == {
        "type": "object",
        "properties": {
            "tags": {
                "type": "object",
                "description": "Custom tags",
            }
        },
    }


