        {"type": "object"},
        {"type": "object", "additionalProperties": True},
        {"type": "object", "additionalProperties": {}},
    ],
    ids=["bare-object", "additional-properties-true", "additional-properties-empty"],
)
def test_free_form_object_equivalent_definitions(definition):
    schema = ObjectsDTSchema.parse_obj(definition)

    assert schema.type == "object"
    assert schema.properties is None
    # All three forms are valid; a bare object need not be rewritten to
    # include additionalProperties.
    assert schema.dict() == definition


def test_object_with_empty_properties_remains_valid_and_distinct():
    schema = ObjectsDTSchema.parse_obj({"type": "object", "properties": {}})

    assert schema.properties == {}
    assert schema.dict() == {"type": "object", "properties": {}}


