"""Regression tests for preserving units in numpy.take and unyt_array.take."""

import numpy as np
import pytest

from unyt import unyt_array, unyt_quantity


def _take(a, indices, dispatcher, **kwargs):
    if dispatcher == "method":
        return a.take(indices, **kwargs)
    return np.take(a, indices, **kwargs)


@pytest.mark.parametrize("dispatcher", ["method", "numpy"])
@pytest.mark.parametrize(
    "index",
    [0, 2, -1, np.int64(1), np.array(1)],
    ids=["first", "last", "negative", "numpy-scalar", "zero-dimensional-array"],
)
def test_take_scalar_index_preserves_units(dispatcher, index):
    a = unyt_array([1, 2, 3], "cm")

    result = _take(a, index, dispatcher)
    expected = np.take(np.asarray(a), index)

    assert isinstance(result, unyt_quantity)
    assert result.units == a.units
    assert result.shape == ()
    np.testing.assert_array_equal(np.asarray(result), np.asarray(expected))


@pytest.mark.parametrize("dispatcher", ["method", "numpy"])
@pytest.mark.parametrize(
    "indices",
    [[0], [2, 0], np.array([0, 2]), np.array([], dtype=int)],
    ids=["single-element-list", "list", "integer-array", "empty-array"],
)
def test_take_array_like_indices_preserve_units(dispatcher, indices):
    a = unyt_array([1, 2, 3], "cm")

    result = _take(a, indices, dispatcher)
    expected = np.take(np.asarray(a), indices)

    assert isinstance(result, unyt_array)
    assert result.units == a.units
    assert result.shape == expected.shape
    np.testing.assert_array_equal(np.asarray(result), expected)


@pytest.mark.parametrize("dispatcher", ["method", "numpy"])
@pytest.mark.parametrize(
    ("axis", "index"),
    [(None, 4), (0, 1), (1, -1), (0, np.int64(0))],
    ids=["flattened-scalar", "row", "negative-column", "numpy-scalar-row"],
)
def test_take_multidimensional_scalar_index(dispatcher, axis, index):
    a = unyt_array([[0, 1, 2], [3, 4, 5]], "cm")

    result = _take(a, index, dispatcher, axis=axis)
    expected = np.take(np.asarray(a), index, axis=axis)

    assert result.units == a.units
    assert result.shape == expected.shape
    if expected.ndim == 0:
        assert isinstance(result, unyt_quantity)
    else:
        assert isinstance(result, unyt_array)
    np.testing.assert_array_equal(np.asarray(result), expected)


@pytest.mark.parametrize("dispatcher", ["method", "numpy"])
@pytest.mark.parametrize(
    ("index", "mode"),
    [(99, "clip"), (-4, "wrap"), (np.int64(3), "wrap")],
)
def test_take_scalar_result_with_nondefault_mode(dispatcher, index, mode):
    a = unyt_array([1, 2, 3], "cm")

    result = _take(a, index, dispatcher, mode=mode)
    expected = np.take(np.asarray(a), index, mode=mode)

    assert isinstance(result, unyt_quantity)
    assert result.units == a.units
    np.testing.assert_array_equal(np.asarray(result), np.asarray(expected))


@pytest.mark.parametrize("dispatcher", ["method", "numpy"])
def test_take_from_unyt_quantity_preserves_units(dispatcher):
    q = unyt_quantity(5, "cm")

    result = _take(q, 0, dispatcher)

    assert isinstance(result, unyt_quantity)
    assert result.units == q.units
    assert result.shape == ()
    np.testing.assert_array_equal(np.asarray(result), np.asarray(5))

