"""Regression tests for multiple test-case entities in a single VHDL file."""

import os
import re

from plumbum import local

from tests.common import run_vhdeps


TESTS_DIR = os.path.dirname(os.path.abspath(__file__))
MULTI_TC_DIR = os.path.join(TESTS_DIR, "complex", "multi-tc-per-file")
FAKE_GHDL_DIR = os.path.join(TESTS_DIR, "ghdl", "fake-ghdl")
KNOWN_ENTITIES = ("foo_tc", "bar_tc", "baz")


def _run_ghdl(*extra_args):
    """Run the multi-testcase project using the repository's fake GHDL."""
    path = FAKE_GHDL_DIR + os.pathsep + local.env.get("PATH", "")
    with local.env(PATH=path):
        return run_vhdeps("ghdl", "-i", MULTI_TC_DIR, *extra_args)


def _elaborated_entities(stdout):
    """Return which entities from the fixture GHDL was asked to elaborate."""
    commands = re.findall(r"ghdl -e [^\n]*", stdout)
    return {
        entity
        for entity in KNOWN_ENTITIES
        if any(
            re.search(r"(?<![A-Za-z0-9_])%s(?![A-Za-z0-9_])" % entity, command)
            for command in commands
        )
    }


def _assert_success(code, stdout, stderr):
    assert code == 0, (
        "vhdeps failed with exit code %s\nstdout:\n%s\nstderr:\n%s"
        % (code, stdout, stderr)
    )


def test_ghdl_runs_all_default_testcases_from_one_file():
    code, stdout, stderr = _run_ghdl()

    _assert_success(code, stdout, stderr)
    assert _elaborated_entities(stdout) == {"foo_tc", "bar_tc"}

    # Elaborating both entities is not sufficient: both must also reach the
    # final result summary as independently executed test cases.
    for entity in ("foo_tc", "bar_tc"):
        assert re.search(r"PASSED[^\n]*\b%s\b" % entity, stdout), stdout


def test_vsim_tcl_contains_all_default_testcases_from_one_file():
    code, stdout, stderr = run_vhdeps("vsim", "--tcl", "-i", MULTI_TC_DIR)

    _assert_success(code, stdout, stderr)
    for entity in ("foo_tc", "bar_tc"):
        assert re.search(r"\bwork\s+%s\b" % entity, stdout), stdout

    # The non-testcase entity must not acquire a test entry merely because it
    # happens to share a source file with the two default test cases.
    assert not re.search(r"\bwork\s+baz\b", stdout), stdout


def test_entity_pattern_filters_entities_within_a_multi_testcase_file():
    code, stdout, stderr = _run_ghdl("-pfoo*")

    _assert_success(code, stdout, stderr)
    assert _elaborated_entities(stdout) == {"foo_tc"}


def test_explicit_entity_pattern_can_select_non_tc_entity():
    """An explicit pattern replaces the default *_tc pattern.

    The _tc suffix is only the default filter; it must not prevent an
    explicitly requested entity in a multi-entity file from being selected.
    """
    code, stdout, stderr = _run_ghdl("-pbaz")

    _assert_success(code, stdout, stderr)
    assert _elaborated_entities(stdout) == {"baz"}

