def test_folded_base_with_runtime_exponent(get_contract):
    # Folding the base must not cause a spurious compile-time overflow when
    # the exponent is not known until runtime.
    source = """
@external
def foo(x: uint256) -> uint256:
    return (10**18)**x
    """
    contract = get_contract(source)
    assert contract.foo(0) == 1
