from unyt import cm, unyt_array, unyt_quantity


def _method_take(a, indices, **kwargs):
    return a.take(indices, **kwargs)


def _function_take(a, indices, **kwargs):
    return np.take(a, indices, **kwargs)


TAKE_IMPLEMENTATIONS = [
    pytest.param(_method_take, id="method"),
    pytest.param(_function_take, id="numpy-function"),
]


@pytest.mark.parametrize("take", TAKE_IMPLEMENTATIONS)
@pytest.mark.parametrize(
