"""Regression tests for multiple test cases defined in one VHDL file."""

import os
import re
from pathlib import Path

import pytest
from plumbum import local

from tests.common import run_vhdeps


TESTS_DIR = Path(__file__).resolve().parent
FAKE_GHDL_BIN = TESTS_DIR / "ghdl" / "fake-ghdl"


def _write_entities(path, names):
    """Write several independent entities and architectures to one file."""
    blocks = []
    for name in names:
        blocks.append(
            f"""\
entity {name} is
end entity {name};

architecture sim of {name} is
begin
  process
  begin
    wait;
  end process;
end architecture sim;
"""
        )
    path.write_text("\n".join(blocks), encoding="utf-8")


@pytest.fixture
def multi_entity_project(tmp_path):
    # helper deliberately does not have the default test-case suffix. It must
    # nevertheless be selectable when the user supplies an explicit pattern.
    _write_entities(
        tmp_path / "multi.vhd", ["alpha_tc", "beta_tc", "helper"]
    )
    # Also retain a conventional one-entity-per-file test case to check that
    # supporting multiple entities does not drop ordinary test cases.
    _write_entities(tmp_path / "single.vhd", ["solo_tc"])
    return tmp_path


def _run_backend(backend, project, *patterns):
    args = [backend]
    if backend == "vsim":
        # Generating the Tcl script exercises test-case discovery and vsim's
        # use of library/entity names without requiring Modelsim to be installed.
        args.append("--tcl")
    args.extend(["-i", str(project)])
    for pattern in patterns:
        args.extend(["-p", pattern])

    if backend == "ghdl":
        path = str(FAKE_GHDL_BIN) + os.pathsep + os.environ.get("PATH", "")
        with local.env(PATH=path):
            code, out, err = run_vhdeps(*args)
    else:
        code, out, err = run_vhdeps(*args)

    assert code == 0, (
        f"{backend} failed for patterns {patterns!r}\n"
        f"stdout:\n{out}\nstderr:\n{err}"
    )
    return out


def _ghdl_elaborates(output, entity):
    """Return whether GHDL was asked to elaborate this exact entity."""
    for line in output.splitlines():
        if "ghdl -e " not in line:
            continue
        if re.search(
            r"(?<![A-Za-z0-9_])" + re.escape(entity) + r"(?![A-Za-z0-9_])",
            line,
        ):
            return True
    return False


def _vsim_selects(output, entity):
    """Return whether the entity is registered as a vsim regression test."""
    return re.search(
        r"^lappend\s+testcases\s+\[list\s+\S+\s+"
        + re.escape(entity)
        + r"(?:\s|\])",
        output,
        flags=re.MULTILINE,
    ) is not None


def _is_selected(backend, output, entity):
    if backend == "ghdl":
        return _ghdl_elaborates(output, entity)
    return _vsim_selects(output, entity)


def _assert_selected(backend, output, selected, unselected=()):
    for entity in selected:
        assert _is_selected(backend, output, entity), (
            f"{entity} was not selected by the {backend} backend; output was:\n"
            f"{output}"
        )

    for entity in unselected:
        assert not _is_selected(backend, output, entity), (
            f"{entity} should not have been selected by the {backend} backend; "
            f"output was:\n{output}"
        )


@pytest.mark.parametrize("backend", ["ghdl", "vsim"])
def test_backends_run_every_default_test_case_in_a_multi_entity_file(
    backend, multi_entity_project
):
    output = _run_backend(backend, multi_entity_project)

    _assert_selected(
        backend,
        output,
        selected=["alpha_tc", "beta_tc", "solo_tc"],
        unselected=["helper"],
    )


@pytest.mark.parametrize("backend", ["ghdl", "vsim"])
def test_explicit_pattern_can_select_entity_without_tc_suffix(
    backend, multi_entity_project
):
    # The *_tc suffix is only the default pattern. An explicit entity pattern
    # must not impose an additional, undocumented suffix restriction.
    output = _run_backend(backend, multi_entity_project, "helper")

    _assert_selected(
        backend,
        output,
        selected=["helper"],
        unselected=["alpha_tc", "beta_tc", "solo_tc"],
    )


def test_patterns_are_applied_to_each_entity_independently(multi_entity_project):
    output = _run_backend(
        "vsim", multi_entity_project, "*_tc", "!beta_tc"
    )

    _assert_selected(
        "vsim",
        output,
        selected=["alpha_tc", "solo_tc"],
        unselected=["beta_tc", "helper"],
    )


def test_filename_pattern_selects_all_matching_entities_in_file(
    multi_entity_project,
):
    # Filename patterns match the absolute filename, hence the leading '*'.
    # Since this is an explicit pattern, helper is a valid selection too.
    output = _run_backend("vsim", multi_entity_project, ":*multi.vhd")

    _assert_selected(
        "vsim",
        output,
        selected=["alpha_tc", "beta_tc", "helper"],
        unselected=["solo_tc"],
    )

"""Regression tests for numpy.take and unyt_array.take with scalar indices."""

import numpy as np
import pytest

from unyt import cm
from unyt.array import unyt_array, unyt_quantity
from unyt.testing import assert_array_equal_units


def _take(a, indices, use_numpy, **kwargs):
    if use_numpy:
        return np.take(a, indices, **kwargs)
    return a.take(indices, **kwargs)


def _assert_result(actual, expected):
    assert isinstance(actual, unyt_array)
    assert_array_equal_units(actual, expected)


def _assert_scalar_result(actual, value):
    # Scalar indexing elsewhere in unyt produces a unyt_quantity, rather than
    # either a NumPy scalar or a one-element array.
    assert isinstance(actual, unyt_quantity)
    assert actual.shape == ()
    _assert_result(actual, unyt_quantity(value, cm))


@pytest.mark.parametrize("use_numpy", [False, True], ids=["method", "numpy-function"])
@pytest.mark.parametrize(
    ("indices", "expected"),
    [
        pytest.param(0, 1, id="python-int"),
        pytest.param(np.int64(1), 2, id="numpy-scalar"),
        pytest.param(np.array(-1), 3, id="zero-dimensional-array"),
    ],
)
def test_take_scalar_index_preserves_units(use_numpy, indices, expected):
    a = [1, 2, 3] * cm

    result = _take(a, indices, use_numpy)

    _assert_scalar_result(result, expected)


