import inspect

import pytest

from oop_ext.interface import (
    DeclareClassImplements,
    ImplementsInterface,
    Interface,
    IsImplementation,
)


class IExample(Interface):
    def method(self, value):
        ...


@ImplementsInterface(IExample)
class DeclaredImplementation:
    def method(self, value):
        return value


class DuckImplementation:
    """Structurally implements IExample without declaring it."""

    def method(self, value):
        return value


class MissingMethodImplementation:
    pass


class WrongSignatureImplementation:
    def method(self):
        pass


@pytest.mark.parametrize("use_instance", [False, True])
def test_default_requires_declaration_for_classes_and_instances(use_instance):
    candidate = DuckImplementation() if use_instance else DuckImplementation

    # Merely having the same methods must not be enough by default.
    assert not IsImplementation(candidate, IExample)
    assert not IsImplementation(candidate, IExample, requires_declaration=True)

    # Duck typing remains available when explicitly requested.
    assert IsImplementation(candidate, IExample, requires_declaration=False)


@pytest.mark.parametrize("use_instance", [False, True])
def test_declared_implementations_are_accepted_by_default(use_instance):
    candidate = DeclaredImplementation() if use_instance else DeclaredImplementation

    assert IsImplementation(candidate, IExample)
    assert IsImplementation(candidate, IExample, requires_declaration=True)


def test_declaration_can_be_added_outside_the_class():
    class ExternalImplementation:
        def method(self, value):
            return value

    DeclareClassImplements(ExternalImplementation, IExample)

    assert IsImplementation(ExternalImplementation, IExample)
    assert IsImplementation(ExternalImplementation(), IExample)


@pytest.mark.parametrize(
    "candidate", [MissingMethodImplementation, WrongSignatureImplementation]
)
def test_disabling_declaration_requirement_still_checks_implementation(candidate):
    assert not IsImplementation(candidate, IExample, requires_declaration=False)
    assert not IsImplementation(candidate, IExample)


def test_requires_declaration_default_is_true_in_public_signature():
    parameter = inspect.signature(IsImplementation).parameters[
        "requires_declaration"
    ]
    assert parameter.default is True

"""Regression tests for preserving units in numpy.take and unyt_array.take."""

import numpy as np
import pytest

from unyt import cm, unyt_array, unyt_quantity
from unyt.testing import assert_array_equal_units


def _method_take(a, indices, **kwargs):
    return a.take(indices, **kwargs)


def _function_take(a, indices, **kwargs):
    return np.take(a, indices, **kwargs)


TAKE_CALLS = [
    pytest.param(_method_take, id="method"),
    pytest.param(_function_take, id="numpy-function"),
]


@pytest.mark.parametrize("take", TAKE_CALLS)
@pytest.mark.parametrize(
    ("index", "expected_value"),
    [
        (0, 1),
        (np.int64(1), 2),
        (-1, 3),
        (np.int32(-2), 2),
    ],
)
def test_take_scalar_index_preserves_units(take, index, expected_value):
    a = [1, 2, 3] * cm

    result = take(a, index)

    # A scalar result must still be a unyt object, rather than a NumPy scalar.
    assert isinstance(result, unyt_array)
    assert result.shape == ()
    assert_array_equal_units(result, unyt_quantity(expected_value, cm))


@pytest.mark.parametrize("take", TAKE_CALLS)
@pytest.mark.parametrize(
    ("axis", "index", "expected_values"),
    [
        (0, 1, [4, 5, 6]),
        (1, -1, [3, 6]),
        (-1, np.int64(0), [1, 4]),
    ],
)
def test_take_scalar_index_along_axis_preserves_units(
    take, axis, index, expected_values
):
    a = unyt_array([[1, 2, 3], [4, 5, 6]], cm)

    result = take(a, index, axis=axis)

    # Scalar indexing along an axis reduces the dimensionality but can still
    # produce an array. Units must be retained in this case as well.
    assert isinstance(result, unyt_array)
    expected_shape = (3,) if axis == 0 else (2,)
    assert result.shape == expected_shape
    assert_array_equal_units(result, unyt_array(expected_values, cm))


@pytest.mark.parametrize("take", TAKE_CALLS)
def test_take_array_like_indices_regression(take):
    a = [1, 2, 3] * cm

    result = take(a, [0, 2])

    assert type(result) is unyt_array
    assert_array_equal_units(result, [1, 3] * cm)

import json

import pytest
import yaml
from yaml.nodes import MappingNode, ScalarNode, SequenceNode

from cfn_flip import to_json, to_yaml


STRING_TAG = "tag:yaml.org,2002:str"
QUOTED_STYLES = {"'", '"'}


def find_values_for_key(node, wanted_key):
    """Find mapping values without depending on whether keys are quoted."""
    matches = []

    if isinstance(node, MappingNode):
        for key_node, value_node in node.value:
            if isinstance(key_node, ScalarNode) and key_node.value == wanted_key:
                matches.append(value_node)
            matches.extend(find_values_for_key(value_node, wanted_key))
    elif isinstance(node, SequenceNode):
        for child in node.value:
            matches.extend(find_values_for_key(child, wanted_key))

    return matches


def assert_quoted_string(node, expected_value):
    assert isinstance(node, ScalarNode)
    assert node.tag == STRING_TAG
    assert node.value == expected_value
    # Quoting is important here: some YAML/CloudFormation parsers interpret
    # unquoted digit-only values, including values with leading zeroes, as numbers.
    assert node.style in QUOTED_STYLES, (
        "String value {!r} was emitted without quotes".format(expected_value)
    )


def test_issue_elb_ids_are_consistently_emitted_as_quoted_strings():
    document = {
        "Mappings": {
            "Regions": {
                "us-east-1": {"ELBID": "127311923021", "Name": "ue1"},
                "us-east-2": {"ELBID": "033677994240", "Name": "ue2"},
                "us-west-1": {"ELBID": "027434742980", "Name": "uw1"},
                "us-west-2": {"ELBID": "797873946194", "Name": "uw2"},
            }
        }
    }

    rendered = to_yaml(json.dumps(document))
    root = yaml.compose(rendered)
    elbid_nodes = find_values_for_key(root, "ELBID")

    assert len(elbid_nodes) == 4
    expected_ids = {
        region["ELBID"]
        for region in document["Mappings"]["Regions"].values()
    }
    assert {node.value for node in elbid_nodes} == expected_ids

    for node in elbid_nodes:
        assert_quoted_string(node, node.value)

    # The generated YAML must also retain the original data and string types.
    assert yaml.safe_load(rendered) == document
    assert json.loads(to_json(rendered)) == document


@pytest.mark.parametrize(
    "value",
    [
        "0",
        "123",
        "797873946194",
        "0123",          # Valid YAML 1.1 octal-like syntax when unquoted.
        "033677994240",  # Leading zero from the reported issue.
        "027434742980",
        "-42",
        "+42",
        "-0123",
        "3.14159",
        ".5",
        "1e10",
        "0x2A",
        "0o17",
    ],
)
def test_numeric_looking_json_strings_remain_quoted_strings(value):
    document = {"Parameters": {"Identifier": value}}

    rendered = to_yaml(json.dumps(document))
    nodes = find_values_for_key(yaml.compose(rendered), "Identifier")

    assert len(nodes) == 1
    assert_quoted_string(nodes[0], value)
    assert yaml.safe_load(rendered) == document
    assert json.loads(to_json(rendered)) == document


def test_string_conversion_does_not_change_native_json_types_or_other_strings():
    document = {
        "Strings": {
            "plain": "hello world",
            "empty": "",
            "apostrophe": "it's a string",
            "boolean_like": "true",
            "null_like": "null",
            "multiline": "first line\nsecond line",
        },
        "NativeValues": {
            "integer": 123,
            "float": 1.25,
            "boolean": True,
            "null": None,
        },
    }

    rendered = to_yaml(json.dumps(document))

    assert yaml.safe_load(rendered) == document
    assert json.loads(to_json(rendered)) == document

"""Regression tests for the default declaration requirement of IsImplementation."""

from oop_ext.interface import (
    DeclareClassImplements,
    ImplementsInterface,
    Interface,
    IsImplementation,
)


def test_undeclared_duck_typing_is_rejected_by_default():
    class IWorker(Interface):
        def work(self, value):
            ...

    class Duck:
        def work(self, value):
            return value

    duck = Duck()

    # Matching methods alone must no longer make a class or instance an implementation.
    assert not IsImplementation(Duck, IWorker)
    assert not IsImplementation(duck, IWorker)

    # Duck typing remains available as an explicit opt-in, for classes and instances.
    assert IsImplementation(Duck, IWorker, requires_declaration=False)
    assert IsImplementation(duck, IWorker, requires_declaration=False)

    # Results for different declaration requirements must not contaminate each other.
    assert not IsImplementation(Duck, IWorker)
    assert not IsImplementation(Duck, IWorker, requires_declaration=True)


def test_explicitly_declared_implementations_are_accepted_by_default():
    class IWorker(Interface):
        def work(self, value):
            ...

    @ImplementsInterface(IWorker)
    class Worker:
        def work(self, value):
            return value

    assert IsImplementation(Worker, IWorker)
    assert IsImplementation(Worker(), IWorker)


def test_declaration_can_be_added_outside_the_class_after_an_earlier_check():
    class IWorker(Interface):
        def work(self, value):
            ...

    class ExternalWorker:
        def work(self, value):
            return value

    worker = ExternalWorker()
    assert not IsImplementation(worker, IWorker)

    DeclareClassImplements(ExternalWorker, IWorker)

    # This also verifies that the earlier negative, cached result is forgotten.
    assert IsImplementation(ExternalWorker, IWorker)
    assert IsImplementation(worker, IWorker)


def test_declaration_distinguishes_otherwise_identical_interfaces():
    class IFirst(Interface):
        def execute(self):
            ...

    class ISecond(Interface):
        def execute(self):
            ...

    @ImplementsInterface(IFirst)
    class Implementation:
        def execute(self):
            return "done"

    implementation = Implementation()

    # Structural compatibility with ISecond must not bypass its missing declaration.
    assert IsImplementation(implementation, IFirst)
    assert not IsImplementation(implementation, ISecond)
    assert IsImplementation(implementation, ISecond, requires_declaration=False)


def test_explicit_duck_typing_still_checks_the_interface_structure():
    class IWorker(Interface):
        def work(self, value):
            ...

    class MissingMethod:
        pass

    class WrongSignature:
        def work(self, value, extra):
            return value, extra

    assert not IsImplementation(MissingMethod, IWorker, requires_declaration=False)
    assert not IsImplementation(WrongSignature(), IWorker, requires_declaration=False)


def test_inherited_and_subinterface_declarations_remain_valid():
    class IBase(Interface):
        def base_method(self):
            ...

    class IExtended(IBase):
        def extended_method(self):
            ...

    @ImplementsInterface(IExtended)
    class Implementation:
        def base_method(self):
            pass

        def extended_method(self):
            pass

    class Child(Implementation):
        pass

    # Declaring a subinterface also declares its base interfaces.
    assert IsImplementation(Implementation, IExtended)
    assert IsImplementation(Implementation(), IBase)

    # Interface declarations are inherited by implementation subclasses.
    assert IsImplementation(Child, IExtended)
    assert IsImplementation(Child(), IBase)

import pytest

from vyper.exceptions import OverflowException


@pytest.mark.parametrize(
    "expression,expected",
    [
        pytest.param("(10**18)**2", 10**36, id="reported-issue"),
        pytest.param("1000000000000000000**2", 10**36, id="folded-base-literal"),
        pytest.param("(10**18)**1", 10**18, id="exponent-one"),
        pytest.param("(10**9)**4", 10**36, id="different-nesting"),
        pytest.param("((2**8)**4)**2", 2**64, id="three-levels"),
        pytest.param("(2**127)**2", 2**254, id="large-but-in-range"),
        pytest.param("(2**255)**1", 2**255, id="near-uint256-boundary"),
    ],
)
def test_nested_constant_exponentiation_in_range(get_contract, expression, expected):
    # Folding an inner exponentiation must not make the outer operation look
    # like an overflow when the final value still fits in uint256.
    code = f"""
@external
def foo() -> uint256:
    return {expression}
    """
    contract = get_contract(code)
    assert contract.foo() == expected


@pytest.mark.parametrize(
    "expression",
    [
        pytest.param("2**256", id="direct-overflow"),
        pytest.param("(2**128)**2", id="result-is-two-to-the-256"),
        pytest.param("(2**255)**2", id="large-nested-overflow"),
        pytest.param("(10**18)**5", id="decimal-nested-overflow"),
    ],
)
def test_nested_constant_exponentiation_real_overflow_is_rejected(
    assert_compile_failed, get_contract, expression
):
    # Fixing the false positive must not disable detection of expressions
    # whose folded result really is outside uint256.
    code = f"""
@external
def foo() -> uint256:
    return {expression}
    """
    assert_compile_failed(lambda: get_contract(code), OverflowException)

