from __future__ import annotations

import numpy as np
import pytest

from zarr import Array, AsyncArray, AsyncGroup, Group
from zarr.core.common import ZarrFormat
from zarr.core.sync import sync
from zarr.store import MemoryStore


# The name-first signatures are part of the v2-compatible Group API:
# Group.empty(name, shape, ...), Group.full(name, shape, fill_value, ...), and
# Group.empty_like(name, prototype, ...), etc.
BASIC_METHODS = [
    ("empty", None),
    ("zeros", 0),
    ("ones", 1),
    ("full", 7),
]
LIKE_METHODS = ["empty_like", "zeros_like", "ones_like", "full_like"]


def _sync_groups(zarr_format: ZarrFormat) -> tuple[Group, Group]:
    root = Group.create(MemoryStore(mode="w"), zarr_format=zarr_format)
    # A non-root group detects implementations that accidentally create arrays
    # directly in the underlying store rather than relative to the group.
    return root, root.create_group("parent")


def _async_groups(zarr_format: ZarrFormat) -> tuple[AsyncGroup, AsyncGroup]:
    root = sync(AsyncGroup.create(MemoryStore(mode="w"), zarr_format=zarr_format))
    return root, sync(root.create_group("parent"))


def _prototype_chunk_kwargs(zarr_format: ZarrFormat) -> dict[str, tuple[int, int]]:
    if zarr_format == 2:
        return {"chunks": (2, 3)}
    return {"chunk_shape": (2, 3)}


@pytest.mark.parametrize("zarr_format", [2, 3], ids=["zarr2", "zarr3"])
@pytest.mark.parametrize(("method", "expected_fill"), BASIC_METHODS)
def test_group_array_creation_methods(
    zarr_format: ZarrFormat, method: str, expected_fill: int | None
) -> None:
    root, group = _sync_groups(zarr_format)
    shape = (4, 6)
    kwargs = {"dtype": "int16", "chunks": (2, 3)}

    if method == "full":
        created = group.full("data", shape, 7, **kwargs)
    else:
        created = getattr(group, method)("data", shape, **kwargs)

    assert isinstance(created, Array)
    assert created.shape == shape
    assert created.dtype == np.dtype("int16")
    assert created.chunks == (2, 3)
    assert created.metadata.zarr_format == zarr_format
    assert created.path == "parent/data"

    # The array must be a child of this group, not an unrelated root array.
    assert group["data"] == created
    with pytest.raises(KeyError):
        root["data"]

    if expected_fill is not None:
        assert created.metadata.fill_value == expected_fill
        np.testing.assert_array_equal(
            created[:], np.full(shape, expected_fill, dtype="int16")
        )


@pytest.mark.parametrize("zarr_format", [2, 3], ids=["zarr2", "zarr3"])
@pytest.mark.parametrize("method", LIKE_METHODS)
def test_group_like_creation_methods(zarr_format: ZarrFormat, method: str) -> None:
    root, group = _sync_groups(zarr_format)
    prototype = group.create_array(
        "prototype",
        shape=(4, 6),
        dtype="int16",
        fill_value=5,
        **_prototype_chunk_kwargs(zarr_format),
    )

    # In particular, this must accept the synchronous Array returned by
    # Group.create_array, not only its private asynchronous counterpart.
    created = getattr(group, method)("copy", prototype)

    assert isinstance(created, Array)
    assert created.shape == prototype.shape
    assert created.dtype == prototype.dtype
    assert created.chunks == prototype.chunks
    assert created.metadata.zarr_format == zarr_format
    assert created.path == "parent/copy"
    assert group["copy"] == created
    with pytest.raises(KeyError):
        root["copy"]

    expected_fill = {
        "zeros_like": 0,
        "ones_like": 1,
        # full_like defaults to the prototype's fill value.
        "full_like": 5,
    }.get(method)
    if expected_fill is not None:
        assert created.metadata.fill_value == expected_fill
        np.testing.assert_array_equal(
            created[:], np.full(prototype.shape, expected_fill, dtype=prototype.dtype)
        )


@pytest.mark.parametrize("zarr_format", [2, 3], ids=["zarr2", "zarr3"])
@pytest.mark.parametrize(("method", "expected_fill"), BASIC_METHODS)
def test_async_group_array_creation_methods(
    zarr_format: ZarrFormat, method: str, expected_fill: int | None
) -> None:
    root, group = _async_groups(zarr_format)
    shape = (4, 6)
    kwargs = {"dtype": "int16", "chunks": (2, 3)}

    if method == "full":
        created = sync(group.full("data", shape, 7, **kwargs))
    else:
        created = sync(getattr(group, method)("data", shape, **kwargs))

    assert isinstance(created, AsyncArray)
    assert created.shape == shape
    assert created.dtype == np.dtype("int16")
    assert created.chunks == (2, 3)
    assert created.metadata.zarr_format == zarr_format
    assert created.path == "parent/data"
    assert sync(group.getitem("data")) == created
    with pytest.raises(KeyError):
        sync(root.getitem("data"))

    if expected_fill is not None:
        assert created.metadata.fill_value == expected_fill
        values = sync(created.getitem(slice(None)))
        np.testing.assert_array_equal(
            values, np.full(shape, expected_fill, dtype="int16")
        )


@pytest.mark.parametrize("zarr_format", [2, 3], ids=["zarr2", "zarr3"])
@pytest.mark.parametrize("method", LIKE_METHODS)
def test_async_group_like_creation_methods(zarr_format: ZarrFormat, method: str) -> None:
    root, group = _async_groups(zarr_format)
    prototype = sync(
        group.create_array(
            "prototype",
            shape=(4, 6),
            dtype="int16",
            fill_value=5,
            **_prototype_chunk_kwargs(zarr_format),
        )
    )

    created = sync(getattr(group, method)("copy", prototype))

    assert isinstance(created, AsyncArray)
    assert created.shape == prototype.shape
    assert created.dtype == prototype.dtype
    assert created.chunks == prototype.chunks
    assert created.metadata.zarr_format == zarr_format
    assert created.path == "parent/copy"
    assert sync(group.getitem("copy")) == created
    with pytest.raises(KeyError):
        sync(root.getitem("copy"))

    expected_fill = {
        "zeros_like": 0,
        "ones_like": 1,
        "full_like": 5,
    }.get(method)
    if expected_fill is not None:
        assert created.metadata.fill_value == expected_fill
        values = sync(created.getitem(slice(None)))
        np.testing.assert_array_equal(
            values, np.full(prototype.shape, expected_fill, dtype=prototype.dtype)
        )


@pytest.mark.parametrize("zarr_format", [2, 3], ids=["zarr2", "zarr3"])
@pytest.mark.parametrize("method", LIKE_METHODS)
def test_group_like_methods_accept_numpy_prototypes(
    zarr_format: ZarrFormat, method: str
) -> None:
    _, group = _sync_groups(zarr_format)
    prototype = np.arange(12, dtype="int32").reshape(3, 4)
    kwargs = {"fill_value": 9} if method == "full_like" else {}

    created = getattr(group, method)("numpy_copy", prototype, **kwargs)

    assert isinstance(created, Array)
    assert created.shape == prototype.shape
    assert created.dtype == prototype.dtype
    assert created.metadata.zarr_format == zarr_format
    assert created.path == "parent/numpy_copy"
    assert group["numpy_copy"] == created

    expected_fill = {
        "zeros_like": 0,
        "ones_like": 1,
        "full_like": 9,
    }.get(method)
    if expected_fill is not None:
        assert created.metadata.fill_value == expected_fill
        np.testing.assert_array_equal(
            created[:], np.full(prototype.shape, expected_fill, dtype=prototype.dtype)
        )

