def test_default_requires_declaration_for_classes_and_instances():
    class IService(Interface):
        def run(self, value):
            ...

    class Duck:
        def run(self, value):
            return value

    # Matching the interface's methods is not enough with the new default.
    assert IsImplementation(Duck, IService) is False
    assert IsImplementation(Duck(), IService) is False

    # Duck typing remains available as an explicit opt-in.
    assert IsImplementation(Duck, IService, requires_declaration=False) is True
    assert IsImplementation(Duck(), IService, requires_declaration=False) is True

    # Explicitly requiring a declaration has the same behavior as the default.
    assert IsImplementation(Duck, IService, requires_declaration=True) is False
    assert IsImplementation(Duck(), IService, requires_declaration=True) is False


def test_explicit_duck_typing_still_checks_interface_implementation():
