import json

import pytest
import yaml

from cfn_flip import to_json, to_yaml


STRING_TAG = "tag:yaml.org,2002:str"
QUOTED_STYLES = ("'", '"')


def _root_mapping(yaml_text):
    root = yaml.compose(yaml_text)
    assert isinstance(root, yaml.MappingNode)
    return root


def _mapping_value(node, key):
    assert isinstance(node, yaml.MappingNode)
    for key_node, value_node in node.value:
        if key_node.value == key:
            return value_node
    raise AssertionError("No mapping entry found for key {!r}".format(key))


def _assert_quoted_string(node, expected):
    assert node.value == expected
    assert node.tag == STRING_TAG
    assert node.style in QUOTED_STYLES, (
        "Numeric string {!r} must be explicitly quoted so that YAML consumers "
        "cannot interpret it as a number".format(expected)
    )


def test_issue_elb_ids_are_consistently_emitted_as_strings():
    template = {
        "Mappings": {
            "Regions": {
                "us-east-1": {
                    "ELBID": "127311923021",
                    "Name": "ue1",
                },
                "us-east-2": {
                    "ELBID": "033677994240",
                    "Name": "ue2",
                },
                "us-west-1": {
                    "ELBID": "027434742980",
                    "Name": "uw1",
                },
                "us-west-2": {
                    "ELBID": "797873946194",
                    "Name": "uw2",
                },
            }
        }
    }

    yaml_text = to_yaml(json.dumps(template))
    root = _root_mapping(yaml_text)
    regions = _mapping_value(_mapping_value(root, "Mappings"), "Regions")

    for region, values in template["Mappings"]["Regions"].items():
        region_node = _mapping_value(regions, region)
        _assert_quoted_string(
            _mapping_value(region_node, "ELBID"), values["ELBID"]
        )

    # Conversion back to JSON must preserve both the values and their types.
    assert json.loads(to_json(yaml_text)) == template


@pytest.mark.parametrize(
    "value",
    [
        "0",
        "000000",
        "01234567",
        "0789",
        "027434742980",
        "033677994240",
        "127311923021",
        "797873946194",
        "909090909090",
        "123456789012345678901234567890",
    ],
)
def test_digit_only_strings_are_quoted_including_leading_zero_edge_cases(value):
    document = {"ELBID": value}

    yaml_text = to_yaml(json.dumps(document))
    root = _root_mapping(yaml_text)

    _assert_quoted_string(_mapping_value(root, "ELBID"), value)
    assert json.loads(to_json(yaml_text)) == document


def test_numeric_strings_are_quoted_in_sequences_and_mapping_keys():
    document = {
        "IDs": ["033677994240", "127311923021", "0789"],
        "033677994240": "leading-zero key",
        "127311923021": "ordinary numeric key",
    }

    yaml_text = to_yaml(json.dumps(document))
    root = _root_mapping(yaml_text)

    ids_node = _mapping_value(root, "IDs")
    assert isinstance(ids_node, yaml.SequenceNode)
    assert len(ids_node.value) == len(document["IDs"])
    for node, expected in zip(ids_node.value, document["IDs"]):
        _assert_quoted_string(node, expected)

    numeric_keys = {"033677994240", "127311923021"}
    seen_keys = set()
    for key_node, _ in root.value:
        if key_node.value in numeric_keys:
            _assert_quoted_string(key_node, key_node.value)
            seen_keys.add(key_node.value)
    assert seen_keys == numeric_keys

    assert json.loads(to_json(yaml_text)) == document


def test_json_numbers_remain_numbers_and_unquoted():
    document = {
        "StringID": "033677994240",
        "NumericID": 33677994240,
        "Zero": 0,
        "Ratio": 1.25,
    }

    yaml_text = to_yaml(json.dumps(document))
    root = _root_mapping(yaml_text)

    _assert_quoted_string(_mapping_value(root, "StringID"), "033677994240")

    numeric_id = _mapping_value(root, "NumericID")
    assert numeric_id.tag == "tag:yaml.org,2002:int"
    assert numeric_id.style is None

    zero = _mapping_value(root, "Zero")
    assert zero.tag == "tag:yaml.org,2002:int"
    assert zero.style is None

    ratio = _mapping_value(root, "Ratio")
    assert ratio.tag == "tag:yaml.org,2002:float"
    assert ratio.style is None

    assert json.loads(to_json(yaml_text)) == document


def test_unambiguous_strings_retain_the_existing_plain_yaml_style():
    document = {
        "Name": "ue1",
        "Description": "Elastic Load Balancer",
        "Identifier": "server123",
    }

    yaml_text = to_yaml(json.dumps(document))
    root = _root_mapping(yaml_text)

    # The numeric-string fix should not quote every key and value in a template.
    for key_node, value_node in root.value:
        assert key_node.style is None
        assert value_node.style is None

    assert json.loads(to_json(yaml_text)) == document


def test_numeric_string_fix_does_not_change_multiline_string_handling():
    document = {"Description": "first line\nsecond line"}

    yaml_text = to_yaml(json.dumps(document))
    description = _mapping_value(_root_mapping(yaml_text), "Description")

    # This is the established CfnYamlDumper representation for multiline text.
    assert description.style == '"'
    assert description.tag == STRING_TAG
    assert json.loads(to_json(yaml_text)) == document

