def test_undeclared_duck_type_is_rejected_by_default():
    class IJob(Interface):
        def run(self, value, optional=None):
            pass

    class DuckJob:
        def run(self, value, optional=None):
            pass

    # Matching the interface structurally is no longer sufficient by default,
    # whether a class or an instance is checked.
    assert IsImplementation(DuckJob, IJob) is False
    assert IsImplementation(DuckJob(), IJob) is False

    # Duck typing remains available as an explicit opt-in. Results for one
    # requires_declaration value must not contaminate results for another.
    assert IsImplementation(DuckJob, IJob, requires_declaration=False) is True
    assert IsImplementation(DuckJob(), IJob, requires_declaration=False) is True
    assert IsImplementation(DuckJob, IJob, requires_declaration=True) is False
    assert IsImplementation(DuckJob, IJob) is False


def test_explicitly_declared_implementation_is_accepted_by_default():
    class IJob(Interface):
        def run(self):
            pass

    @ImplementsInterface(IJob)
    class Job:
        def run(self):
            pass

    class SpecializedJob(Job):
        pass

    assert IsImplementation(Job, IJob) is True
    assert IsImplementation(Job(), IJob) is True

    # Interface declarations inherited from a base class remain valid.
    assert IsImplementation(SpecializedJob, IJob) is True
    assert IsImplementation(SpecializedJob(), IJob) is True


def test_external_declaration_enables_default_check_after_previous_result():
    class IJob(Interface):
        def run(self):
            pass

    class ExternalJob:
        def run(self):
            pass

    # Populate the implementation cache before declaring the interface.
    assert IsImplementation(ExternalJob, IJob) is False

    DeclareClassImplements(ExternalJob, IJob)

    # Declaring the interface must invalidate a previously cached negative
    # result, including one produced using the new default.
    assert IsImplementation(ExternalJob, IJob) is True
    assert IsImplementation(ExternalJob(), IJob) is True


def test_declaration_does_not_bypass_structural_requirements():
    class IJob(Interface):
        def run(self):
            pass

    @ImplementsInterface(IJob, no_check=True)
    class IncompleteJob:
        pass

    # The new default requires both a declaration and an actual implementation;
    # a declaration alone must not turn an incomplete class into an implementation.
    assert IsImplementation(IncompleteJob, IJob) is False
    assert IsImplementation(IncompleteJob(), IJob) is False
    assert IsImplementation(IncompleteJob, IJob, requires_declaration=False) is False


def test_declaring_a_subinterface_also_declares_its_base_interface():
    class IBaseJob(Interface):
