import inspect

from oop_ext.interface import (
    DeclareClassImplements,
    ImplementsInterface,
    Interface,
    IsImplementation,
)


def test_requires_declaration_public_default_is_true():
    parameter = inspect.signature(IsImplementation).parameters[
        "requires_declaration"
    ]
    assert parameter.default is True


def test_undeclared_duck_typed_class_is_not_an_implementation_by_default():
    class IService(Interface):
        def run(self, value, option=None):
            pass

    class DuckTypedService:
        def run(self, value, option=None):
            return value

    # Matching methods alone must not make either a class or an instance an
    # implementation when the default arguments are used.
    assert IsImplementation(DuckTypedService, IService) is False
    assert IsImplementation(DuckTypedService(), IService) is False

    # Duck typing remains available as an explicit opt-in.
    assert (
        IsImplementation(
            DuckTypedService, IService, requires_declaration=False
        )
        is True
    )
    assert (
        IsImplementation(
            DuckTypedService(), IService, requires_declaration=False
        )
        is True
    )
    assert (
        IsImplementation(
            DuckTypedService, IService, requires_declaration=True
        )
        is False
    )


def test_explicitly_declared_implementations_work_with_the_default():
    class IService(Interface):
        def run(self, value, option=None):
            pass

    @ImplementsInterface(IService)
    class DeclaredService:
        def run(self, value, option=None):
            return value

    class InheritedDeclaredService(DeclaredService):
        pass

    assert IsImplementation(DeclaredService, IService) is True
    assert IsImplementation(DeclaredService(), IService) is True
    assert IsImplementation(InheritedDeclaredService, IService) is True
    assert IsImplementation(InheritedDeclaredService(), IService) is True


def test_external_declaration_is_honored_by_default():
    class IService(Interface):
        def run(self, value, option=None):
            pass

    class ExternalService:
        def run(self, value, option=None):
            return value

    # Declare the implementation before performing implementation checks, as
    # implementation checks are cached by the interface machinery.
    DeclareClassImplements(ExternalService, IService)

    assert IsImplementation(ExternalService, IService) is True
    assert IsImplementation(ExternalService(), IService) is True


def test_explicit_duck_typing_check_does_not_change_the_default():
    class IService(Interface):
        def run(self, value, option=None):
            pass

    class DuckTypedService:
        def run(self, value, option=None):
            return value

    assert (
        IsImplementation(DuckTypedService, IService, requires_declaration=False)
        is True
    )
    assert IsImplementation(DuckTypedService, IService) is False
    assert IsImplementation(DuckTypedService(), IService) is False


def test_declaration_requirement_does_not_weaken_structural_checks():
    class IService(Interface):
        def run(self, value, option=None):
            pass

    class WrongSignature:
        def run(self, value):
            return value

    class MissingMethod:
        pass

    candidates = (
        WrongSignature,
        WrongSignature(),
        MissingMethod,
        MissingMethod(),
    )
    for candidate in candidates:
        assert IsImplementation(candidate, IService) is False
        assert (
            IsImplementation(candidate, IService, requires_declaration=False)
            is False
        )

import httpx
import pytest


def _query_parts(url):
    query = url.query.decode("ascii")
    return query.split("&") if query else []


def test_issue_example_preserves_bare_parameter_when_merging_params():
    request = httpx.Request(
        "GET",
        "https://httpbin.org/get?foobar",
        params={"hello": "world"},
    )

    # Parameter ordering is not significant, but the originally bare parameter
    # must remain present and must not acquire an equals sign.
    assert sorted(_query_parts(request.url)) == ["foobar", "hello=world"]


def test_request_merge_preserves_multiple_bare_and_explicitly_empty_params():
    request = httpx.Request(
        "GET",
        "https://example.com/path?first&empty=&second&value=123",
        params={"added": "456"},
    )

    assert sorted(_query_parts(request.url)) == [
        "added=456",
        "empty=",
        "first",
        "second",
        "value=123",
    ]


def test_empty_params_mapping_does_not_discard_existing_query():
    request = httpx.Request(
        "GET", "https://example.com/path?first&empty=", params={}
    )

    assert sorted(_query_parts(request.url)) == ["empty=", "first"]


@pytest.mark.parametrize(
    ("source", "expected"),
    [
        ("flag", "flag"),
        ("flag=", "flag="),
        ("flag&other=1", "flag&other=1"),
        ("flag&flag", "flag&flag"),
        # Bareness belongs to each occurrence, not to the key as a whole.
        ("flag=&flag", "flag=&flag"),
        ("flag&flag=", "flag&flag="),
    ],
)
def test_queryparams_round_trip_distinguishes_bare_and_empty_values(
    source, expected
):
    assert str(httpx.QueryParams(source)) == expected


def test_percent_encoded_bare_parameter_name_remains_bare():
    rendered = str(httpx.QueryParams("spaced%20key"))

    # Either normal URL encoding or httpx's usual quote-plus encoding is valid,
    # but an equals sign must not be introduced.
    assert rendered in {"spaced+key", "spaced%20key"}


@pytest.mark.parametrize("value", ["", None])
def test_explicit_empty_mapping_values_are_not_rendered_as_bare(value):
    assert str(httpx.QueryParams({"flag": value})) == "flag="


@pytest.mark.parametrize(
    ("operation", "expected"),
    [
        pytest.param(
            lambda params: params.set("value", "2"),
            "flag&value=2",
            id="set",
        ),
        pytest.param(
            lambda params: params.add("value", "2"),
            "flag&value=1&value=2",
            id="add",
        ),
        pytest.param(
            lambda params: params.remove("value"),
            "flag",
            id="remove",
        ),
    ],
)
def test_queryparam_operations_preserve_unrelated_bare_parameters(
    operation, expected
):
    params = httpx.QueryParams("flag&value=1")

    assert str(operation(params)) == expected


def test_merge_override_replaces_bare_parameter_with_explicit_empty_value():
    original = httpx.QueryParams("flag&keep")
    merged = original.merge({"flag": ""})

    assert sorted(str(merged).split("&")) == ["flag=", "keep"]
    assert str(original) == "flag&keep"

import pytest

from vyper import compiler
from vyper.exceptions import InvalidLiteral, InvalidOperation, OverflowException


@pytest.mark.parametrize(
    "return_type,expression,expected",
    [
        # Regression test for the reported issue: the intermediate base and the
        # final result both fit in uint256.
        ("uint256", "(10**18)**2", 10**36),
        ("uint256", "10**36", 10**36),
        # Nested exponentiation must be checked using the folded result.
        ("uint256", "(2**127)**2", 2**254),
        # 10**77 is the largest power of ten which fits in a uint256.
        ("uint256", "10**77", 10**77),
        ("uint256", "(10**18)**0", 1),
        # The result must also be checked against narrower and signed types.
        ("uint8", "(2**3)**2", 64),
        ("int256", "(2**127)**2", 2**254),
        ("int256", "(-2)**255", -(2**255)),
    ],
)
def test_literal_exponentiation_accepts_results_in_bounds(
    get_contract, return_type, expression, expected
):
    source = f"""
@external
def foo() -> {return_type}:
    return {expression}
"""
    contract = get_contract(source)
    assert contract.foo() == expected


@pytest.mark.parametrize(
    "return_type,expression",
    [
        ("uint256", "2**256"),
        ("uint256", "10**78"),
        ("uint256", "(2**128)**2"),
        ("uint8", "(2**4)**2"),
        ("int256", "(2**128)**2"),
        ("int256", "(-2)**256"),
        # Exponentiation is right-associative, so this is 10**(18**2),
        # rather than the valid expression (10**18)**2.
        ("uint256", "10**18**2"),
    ],
)
def test_literal_exponentiation_still_rejects_overflow(
    assert_compile_failed, return_type, expression
):
    source = f"""
@external
def foo() -> {return_type}:
    return {expression}
"""
    # Depending on whether folding or literal validation detects the invalid
    # value first, either diagnostic is valid. An internal compiler error or
    # successful compilation is not.
    assert_compile_failed(
        lambda: compiler.compile_code(source), (OverflowException, InvalidLiteral)
    )


def test_negative_literal_exponent_still_rejected(assert_compile_failed):
    source = """
@external
def foo() -> uint256:
    return 2**(-1)
"""
    assert_compile_failed(lambda: compiler.compile_code(source), InvalidOperation)


def test_literal_base_with_runtime_exponent(get_contract):
    source = """
@external
def foo(exponent: uint256) -> uint256:
    return (10**18)**exponent
"""
    contract = get_contract(source)
    assert contract.foo(0) == 1
    assert contract.foo(2) == 10**36


@pytest.mark.parametrize(
    "integer_type,exponent",
    [
        # These exponents exceed the compile-time limit for a non-literal base
        # of the corresponding type. Fixing constant folding must not silently
        # relax validation of runtime exponentiation.
        ("uint8", 9),
        ("int8", 8),
        ("int256", 256),
    ],
)
def test_nonliteral_base_exponent_validation_is_unchanged(
    assert_compile_failed, integer_type, exponent
):
    source = f"""
@external
def foo(base: {integer_type}) -> {integer_type}:
    return base**{exponent}
"""
    assert_compile_failed(lambda: compiler.compile_code(source), OverflowException)

import pytest

from oop_ext.interface import (
    AssertImplements,
    DeclareClassImplements,
    ImplementsInterface,
    Interface,
    IsImplementation,
    IsImplementationOfAny,
)


def test_is_implementation_requires_declaration_by_default():
    class IFoo(Interface):
        def Foo(self):
            pass

    class DuckTypedFoo:
        def Foo(self):
            pass

    # Matching the interface's methods is not sufficient with the default.
    assert not IsImplementation(DuckTypedFoo, IFoo)
    assert not IsImplementation(DuckTypedFoo(), IFoo)

    # Duck typing remains available as an explicit opt-in, for classes and instances.
    assert IsImplementation(DuckTypedFoo, IFoo, requires_declaration=False)
    assert IsImplementation(DuckTypedFoo(), IFoo, requires_declaration=False)

    @ImplementsInterface(IFoo)
    class DeclaredFoo:
        def Foo(self):
            pass

    assert IsImplementation(DeclaredFoo, IFoo)
    assert IsImplementation(DeclaredFoo(), IFoo)


def test_default_checks_the_specific_declared_interface():
    class IFoo(Interface):
        def Operation(self):
            pass

    class IStructurallyIdentical(Interface):
        def Operation(self):
            pass

    @ImplementsInterface(IFoo)
    class Foo:
        def Operation(self):
            pass

    # Declaring one interface must not declare every interface with the same methods.
    assert IsImplementation(Foo, IFoo)
    assert not IsImplementation(Foo, IStructurallyIdentical)
    assert IsImplementation(Foo, IStructurallyIdentical, requires_declaration=False)


def test_is_implementation_of_any_requires_declaration_by_default():
    class IFoo(Interface):
        def Foo(self):
            pass

    class IBar(Interface):
        def Bar(self):
            pass

    class DuckTypedFoo:
        def Foo(self):
            pass

    assert not IsImplementationOfAny(DuckTypedFoo, [IFoo])
    assert not IsImplementationOfAny(DuckTypedFoo(), [IBar, IFoo])
    assert IsImplementationOfAny(
        DuckTypedFoo, [IBar, IFoo], requires_declaration=False
    )

    @ImplementsInterface(IFoo)
    class DeclaredFoo:
        def Foo(self):
            pass

    assert IsImplementationOfAny(DeclaredFoo, [IBar, IFoo])
    assert IsImplementationOfAny(DeclaredFoo(), [IBar, IFoo])
    assert not IsImplementationOfAny(DeclaredFoo, [IBar])
    assert not IsImplementationOfAny(DeclaredFoo, [])


def test_assert_implements_requires_declaration_by_default():
    class IFoo(Interface):
        def Foo(self):
            pass

    class DuckTypedFoo:
        def Foo(self):
            pass

    # Populate the duck-typing result first; the declaration-required check must
    # not reuse it as though declaration checking had been requested.
    AssertImplements(DuckTypedFoo, IFoo, requires_declaration=False)

    with pytest.raises(AssertionError):
        AssertImplements(DuckTypedFoo, IFoo)

    with pytest.raises(AssertionError):
        AssertImplements(DuckTypedFoo(), IFoo)

    @ImplementsInterface(IFoo)
    class DeclaredFoo:
        def Foo(self):
            pass

    AssertImplements(DeclaredFoo, IFoo)
    AssertImplements(DeclaredFoo(), IFoo)


def test_declare_class_implements_invalidates_both_cached_check_modes():
    class IFoo(Interface):
        def Foo(self):
            pass

    class ExternallyDeclaredFoo:
        def Foo(self):
            pass

    # Cache both the positive duck-typing result and the negative result for the
    # default declaration-required check before declaring the interface.
    assert IsImplementation(ExternallyDeclaredFoo, IFoo, requires_declaration=False)
    assert not IsImplementation(ExternallyDeclaredFoo, IFoo)
    with pytest.raises(AssertionError):
        AssertImplements(ExternallyDeclaredFoo, IFoo)

    DeclareClassImplements(ExternallyDeclaredFoo, IFoo)

    # A later declaration must be visible immediately rather than being hidden by
    # either cached result.
    assert IsImplementation(ExternallyDeclaredFoo, IFoo)
    assert IsImplementation(ExternallyDeclaredFoo(), IFoo)
    assert IsImplementationOfAny(ExternallyDeclaredFoo, [IFoo])
    AssertImplements(ExternallyDeclaredFoo, IFoo)
    assert IsImplementation(ExternallyDeclaredFoo, IFoo, requires_declaration=False)

"""Regression tests for replacing shows which use sync_ms."""

from mpf.tests.MpfTestCase import MpfTestCase


class TestSyncedShowReplacement(MpfTestCase):
    """Test that a synced replacement stops its predecessor when it starts."""

    def getConfigFile(self):
        return 'test_config_players.yaml'

    def getMachinePath(self):
        return 'tests/machine_files/config_players/'

    def setUp(self):
        # test_config_players.yaml uses this custom player.
        self.machine_config_patches['mpf']['config_players'] = {
            'banana': 'mpf.tests.test_ConfigPlayers.BananaPlayer'
        }
        self.add_to_config_validator(
            'banana_player', dict(__valid_in__='machine, mode'))

        self.machine_config_patches['shows'] = {
            'ttg_old_show': [
                {'duration': -1},
            ],
            'ttg_new_show': [
                {'duration': -1},
            ],
        }
        self.machine_config_patches['show_player'] = {
            'ttg_play_old': {
                'ttg_old_show': {
                    'key': 'ttg_shared',
                },
            },
            'ttg_play_new_synced': {
                'ttg_new_show': {
                    'key': 'ttg_shared',
                    'sync_ms': 1000,
                },
            },
            'ttg_play_new_unsynced': {
                'ttg_new_show': {
                    'key': 'ttg_shared',
                    'sync_ms': 0,
                },
            },
            'ttg_play_other_synced': {
                'ttg_new_show': {
                    'key': 'ttg_other',
                    'sync_ms': 1000,
                },
            },
        }
        super().setUp()

    def _running_show(self, key):
        return self.machine.show_player.instances[
            '_global']['show_player'][key]

    def _post_and_process(self, event):
        self.machine.events.post(event)
        # Process the event without advancing far enough to cross a sync
        # boundary.
        self.advance_time_and_run(0)

    def test_synced_replacement_stops_old_show_only_when_new_show_starts(self):
        self._post_and_process('ttg_play_old')
        old_show = self._running_show('ttg_shared')
        self.assertFalse(old_show.stopped)
        self.assertEqual(0, old_show.current_step_index)

        self._post_and_process('ttg_play_new_synced')
        new_show = self._running_show('ttg_shared')

        self.assertIsNot(old_show, new_show)
        self.assertIsNone(new_show.current_step_index)
        self.assertFalse(
            old_show.stopped,
            "The old show must keep running while the new show waits for "
            "its sync boundary.")

        time_until_start = (
            new_show.next_step_time - self.machine.clock.get_time())
        self.assertGreater(time_until_start, 0)

        # Waiting only part of the sync delay must not stop the old show or
        # start the new one early.
        self.advance_time_and_run(time_until_start / 2.0)
        self.assertFalse(old_show.stopped)
        self.assertIsNone(new_show.current_step_index)

        # Once the first step of the new show runs, the old show is stopped.
        remaining_time = (
            new_show.next_step_time - self.machine.clock.get_time())
        self.advance_time_and_run(remaining_time + 0.001)
        self.assertEqual(0, new_show.current_step_index)
        self.assertTrue(old_show.stopped)

    def test_unsynced_replacement_still_stops_old_show_immediately(self):
        self._post_and_process('ttg_play_old')
        old_show = self._running_show('ttg_shared')

        self._post_and_process('ttg_play_new_unsynced')
        new_show = self._running_show('ttg_shared')

        self.assertTrue(old_show.stopped)
        self.assertEqual(0, new_show.current_step_index)
        self.assertFalse(new_show.stopped)

    def test_synced_show_with_another_key_does_not_stop_old_show(self):
        self._post_and_process('ttg_play_old')
        old_show = self._running_show('ttg_shared')

        self._post_and_process('ttg_play_other_synced')
        other_show = self._running_show('ttg_other')
        self.assertFalse(old_show.stopped)

        time_until_start = (
            other_show.next_step_time - self.machine.clock.get_time())
        self.advance_time_and_run(time_until_start + 0.001)

        self.assertEqual(0, other_show.current_step_index)
        self.assertFalse(
            old_show.stopped,
            "Starting a show under a different key must not stop the old "
            "show, either immediately or at the sync boundary.")

import numpy as np
import pytest

from unyt import cm
from unyt.array import unyt_array, unyt_quantity


def _take(a, indices, via_numpy, **kwargs):
    if via_numpy:
        return np.take(a, indices, **kwargs)
    return a.take(indices, **kwargs)


@pytest.mark.parametrize("via_numpy", [False, True], ids=["method", "np.take"])
@pytest.mark.parametrize(
    ("index", "expected"),
    [
        (0, 1),
        (1, 2),
        (-1, 3),
        (np.int64(2), 3),
        (np.array(1), 2),
    ],
)
def test_take_scalar_index_preserves_units(via_numpy, index, expected):
    a = [1, 2, 3] * cm

    result = _take(a, index, via_numpy)

    assert type(result) is unyt_quantity
    assert result.units == cm
    assert result.value == expected
    assert result.shape == ()


@pytest.mark.parametrize("via_numpy", [False, True], ids=["method", "np.take"])
@pytest.mark.parametrize(
    ("indices", "expected"),
    [
        ([0], [1]),
        ([0, 2], [1, 3]),
        ((1,), [2]),
        (np.array([2, 0]), [3, 1]),
    ],
)
def test_take_array_indices_retain_array_behavior(via_numpy, indices, expected):
    a = [1, 2, 3] * cm

    result = _take(a, indices, via_numpy)

    assert type(result) is unyt_array
    assert result.units == cm
    assert result.shape == (len(expected),)
    np.testing.assert_array_equal(result.ndview, expected)


@pytest.mark.parametrize("via_numpy", [False, True], ids=["method", "np.take"])
def test_take_scalar_from_multidimensional_array_without_axis(via_numpy):
    a = [[1, 2, 3], [4, 5, 6]] * cm

    # With axis=None, NumPy takes from the flattened input.
    result = _take(a, 2, via_numpy)

    assert type(result) is unyt_quantity
    assert result.units == cm
    assert result.value == 3


@pytest.mark.parametrize("via_numpy", [False, True], ids=["method", "np.take"])
@pytest.mark.parametrize(
    ("axis", "index", "expected"),
    [
        (0, 1, [4, 5, 6]),
        (1, -1, [3, 6]),
    ],
)
def test_take_scalar_index_with_axis_returns_unit_array(
    via_numpy, axis, index, expected
):
    a = [[1, 2, 3], [4, 5, 6]] * cm

    # A scalar index does not imply a scalar result when an axis is supplied.
    result = _take(a, index, via_numpy, axis=axis)

    assert type(result) is unyt_array
    assert result.units == cm
    assert result.ndim == 1
    np.testing.assert_array_equal(result.ndview, expected)


@pytest.mark.parametrize("via_numpy", [False, True], ids=["method", "np.take"])
def test_take_array_indices_with_axis(via_numpy):
    a = [[1, 2, 3], [4, 5, 6]] * cm

    result = _take(a, [0], via_numpy, axis=1)

    assert type(result) is unyt_array
    assert result.units == cm
    assert result.shape == (2, 1)
    np.testing.assert_array_equal(result.ndview, [[1], [4]])


@pytest.mark.parametrize("via_numpy", [False, True], ids=["method", "np.take"])
@pytest.mark.parametrize(
    ("index", "mode", "expected"),
    [
        (99, "clip", 3),
        (-99, "clip", 1),
        (4, "wrap", 2),
        (-1, "wrap", 3),
    ],
)
def test_take_scalar_index_modes_preserve_units(via_numpy, index, mode, expected):
    a = [1, 2, 3] * cm

    result = _take(a, index, via_numpy, mode=mode)

    assert type(result) is unyt_quantity
    assert result.units == cm
    assert result.value == expected


@pytest.mark.parametrize("via_numpy", [False, True], ids=["method", "np.take"])
@pytest.mark.parametrize("index", [3, -4])
def test_take_invalid_scalar_index_still_raises(via_numpy, index):
    a = [1, 2, 3] * cm

    with pytest.raises(IndexError):
        _take(a, index, via_numpy)


@pytest.mark.parametrize("via_numpy", [False, True], ids=["method", "np.take"])
def test_take_with_unyt_out_does_not_change_or_square_units(via_numpy):
    a = [1, 2, 3] * cm
    out = unyt_array(np.empty(2, dtype=a.dtype), "cm")

    result = _take(a, [0, 2], via_numpy, out=out)

    # take only selects values; supplying an output that already has units
    # must not multiply its units by the input units a second time.
    assert out.units == cm
    assert result.units == cm
    assert np.shares_memory(result, out)
    np.testing.assert_array_equal(out.ndview, [1, 3])
    np.testing.assert_array_equal(result.ndview, [1, 3])

import pytest

from oop_ext.interface import (
    AssertImplements,
    DeclareClassImplements,
    ImplementsInterface,
    Interface,
    IsImplementation,
    IsImplementationOfAny,
)


def test_is_implementation_requires_declaration_by_default():
    class IPing(Interface):
        def ping(self):
            ...

    class DuckPing:
        def ping(self):
            ...

    # Matching the interface structurally is no longer sufficient by default,
    # for either classes or instances.
    assert IsImplementation(DuckPing, IPing) is False
    assert IsImplementation(DuckPing(), IPing) is False
    assert IsImplementation(DuckPing, IPing, requires_declaration=True) is False

    # Duck typing remains available as an explicit opt-in.
    assert IsImplementation(DuckPing, IPing, requires_declaration=False) is True
    assert IsImplementation(DuckPing(), IPing, requires_declaration=False) is True

    @ImplementsInterface(IPing)
    class DeclaredPing:
        def ping(self):
            ...

    class InheritedPing(DeclaredPing):
        pass

    assert IsImplementation(DeclaredPing, IPing) is True
    assert IsImplementation(DeclaredPing(), IPing) is True
    assert IsImplementation(InheritedPing, IPing) is True
    assert IsImplementation(InheritedPing(), IPing) is True


def test_declaration_is_specific_to_the_requested_interface():
    class IFirstIdentity(Interface):
        def identify(self):
            ...

    class ISecondIdentity(Interface):
        def identify(self):
            ...

    @ImplementsInterface(IFirstIdentity)
    class Implementation:
        def identify(self):
            ...

    # Structurally identical interfaces can be used as distinct IDs: declaring
    # one must not implicitly declare every other interface with the same API.
    assert IsImplementation(Implementation, IFirstIdentity) is True
    assert IsImplementation(Implementation, ISecondIdentity) is False
    assert IsImplementation(Implementation(), ISecondIdentity) is False

    assert (
        IsImplementation(
            Implementation, ISecondIdentity, requires_declaration=False
        )
        is True
    )


def test_is_implementation_of_any_requires_declaration_by_default():
    class IFirst(Interface):
        def first(self):
            ...

    class ISecond(Interface):
        def second(self):
            ...

    class DuckSecond:
        def second(self):
            ...

    assert IsImplementationOfAny(DuckSecond, [IFirst, ISecond]) is False
    assert IsImplementationOfAny(DuckSecond(), [IFirst, ISecond]) is False
    assert (
        IsImplementationOfAny(
            DuckSecond, [IFirst, ISecond], requires_declaration=False
        )
        is True
    )
    assert (
        IsImplementationOfAny(DuckSecond, [IFirst], requires_declaration=False)
        is False
    )

    @ImplementsInterface(ISecond)
    class DeclaredSecond:
        def second(self):
            ...

    assert IsImplementationOfAny(DeclaredSecond, [IFirst, ISecond]) is True
    assert IsImplementationOfAny(DeclaredSecond(), [IFirst, ISecond]) is True


def test_assert_implements_requires_declaration_by_default():
    class ICalculation(Interface):
        def calculate(self, value):
            ...

    class DuckCalculation:
        def calculate(self, value):
            return value

    # The implementation is structurally valid, so the default failure must be
    # specifically due to the missing declaration.
    with pytest.raises(AssertionError, match="requires_declaration"):
        AssertImplements(DuckCalculation(), ICalculation)

    AssertImplements(DuckCalculation(), ICalculation, requires_declaration=False)

    @ImplementsInterface(ICalculation)
    class DeclaredCalculation:
        def calculate(self, value):
            return value

    AssertImplements(DeclaredCalculation, ICalculation)
    AssertImplements(DeclaredCalculation(), ICalculation)


def test_declare_class_implements_invalidates_previous_default_checks():
    class IExternal(Interface):
        def execute(self):
            ...

    class ExternalImplementation:
        def execute(self):
            ...

    # Populate the implementation cache for both declaration modes before
    # adding the declaration externally.
    assert IsImplementation(ExternalImplementation, IExternal) is False
    assert (
        IsImplementation(
            ExternalImplementation, IExternal, requires_declaration=False
        )
        is True
    )

    DeclareClassImplements(ExternalImplementation, IExternal)

    # A previously cached negative result using the new default must not hide
    # the newly added declaration.
    assert IsImplementation(ExternalImplementation, IExternal) is True
    assert IsImplementation(ExternalImplementation(), IExternal) is True
    AssertImplements(ExternalImplementation, IExternal)


def test_disabling_declaration_requirement_still_checks_implementation():
    class IWorker(Interface):
        def work(self, value):
            ...

    class MissingMethod:
        pass

    class WrongSignature:
        def work(self):
            ...

    assert IsImplementation(MissingMethod, IWorker, requires_declaration=False) is False
    assert (
        IsImplementation(WrongSignature, IWorker, requires_declaration=False) is False
    )
    with pytest.raises(AssertionError):
        AssertImplements(WrongSignature, IWorker, requires_declaration=False)

