import pytest

from ansible_builder.introspect import process
from ansible_builder.requirements import sanitize_requirements


@pytest.mark.parametrize("package", ["yamllint", "ansible-lint"])
def test_sanitize_preserves_linting_tools(package):
    """Packages explicitly requested for an EE must survive sanitization."""
    assert sanitize_requirements({"user": [package]}) == [
        f"{package}  # from collection user"
    ]


def test_introspect_sanitize_preserves_versioned_user_requirements(tmp_path):
    """Exercise the user requirements path used by introspect --sanitize."""
    user_pip = tmp_path / "requirements.txt"
    user_pip.write_text(
        "# Tools needed inside the execution environment\n"
        "yamllint>=1.26.0\n"
        "ansible-lint>=5.0.0\n"
        "requests>=2.25.0\n"
    )

    files = process(str(tmp_path), user_pip=str(user_pip))
