import json

import pytest
import yaml

from cfn_flip import to_json, to_yaml


def _assert_quoted_mapping_value(output, key, value):
    """Accept either YAML quote style, but require the scalar to be quoted."""
    lines = {line.strip() for line in output.splitlines()}
    assert (
        "{}: '{}'".format(key, value) in lines
        or '{}: "{}"'.format(key, value) in lines
    ), output


@pytest.mark.parametrize(
    "value",
    [
        # Examples from the issue, including values PyYAML does not implicitly
        # recognize as integers because they contain 8 or 9 after a leading 0.
        "127311923021",
        "033677994240",
        "027434742980",
        "797873946194",
        # Boundary and related numeric-string cases.
        "0",
        "00",
        "000000000000",
        "01234567",
        "09876543210",
        "0000000000000000000000000000000000000001",
        "1234567890",
    ],
)
def test_to_yaml_quotes_numeric_strings(value):
    output = to_yaml(json.dumps({"ELBID": value}))

    _assert_quoted_mapping_value(output, "ELBID", value)

    loaded = yaml.safe_load(output)
    assert loaded["ELBID"] == value
    assert isinstance(loaded["ELBID"], str)


def test_issue_elb_mapping_ids_are_all_emitted_as_quoted_strings():
    source = {
        "Mappings": {
            "Regions": {
                "us-east-1": {
                    "ELBID": "127311923021",
                    "Name": "ue1",
                },
                "us-east-2": {
                    "ELBID": "033677994240",
                    "Name": "ue2",
                },
                "us-west-1": {
                    "ELBID": "027434742980",
                    "Name": "uw1",
                },
                "us-west-2": {
                    "ELBID": "797873946194",
                    "Name": "uw2",
                },
            }
        }
    }

    output = to_yaml(json.dumps(source))

    for region in source["Mappings"]["Regions"].values():
        _assert_quoted_mapping_value(output, "ELBID", region["ELBID"])

    # Conversion must not change any of the original JSON string values.
    assert json.loads(to_json(output)) == source


def test_to_yaml_still_distinguishes_numeric_strings_from_json_numbers():
    source = {
        "StringID": "033677994240",
        "IntegerID": 33677994240,
        "ZeroString": "0",
        "ZeroNumber": 0,
    }

    output = to_yaml(json.dumps(source))
    loaded = yaml.safe_load(output)

    assert loaded["StringID"] == "033677994240"
    assert isinstance(loaded["StringID"], str)
    assert loaded["ZeroString"] == "0"
    assert isinstance(loaded["ZeroString"], str)

    assert loaded["IntegerID"] == 33677994240
    assert type(loaded["IntegerID"]) is int
    assert loaded["ZeroNumber"] == 0
    assert type(loaded["ZeroNumber"]) is int

