        DuckTyped, [_IBar, _IFoo], requires_declaration=False
    )

    @ImplementsInterface(_IBar)
    class PartiallyDeclared:
        def foo(self):
            return "foo"

        def bar(self):
            return "bar"

    # Structurally implementing _IFoo must not make it count as a declared
    # implementation, while the explicitly declared _IBar still matches.
    assert not IsImplementationOfAny(PartiallyDeclared, [_IFoo])
    assert IsImplementationOfAny(PartiallyDeclared, [_IFoo, _IBar])
    assert IsImplementationOfAny(
        PartiallyDeclared, [_IFoo], requires_declaration=False
    )


def test_declaration_is_checked_for_the_requested_interface():
    @ImplementsInterface(_IIdentifierA)
    class Implementation:
        def operation(self):
            return "done"

    # The interfaces are structurally identical, but declaring one must not
    # implicitly declare every other interface with the same methods.
    assert IsImplementation(Implementation, _IIdentifierA)
    assert not IsImplementation(Implementation, _IIdentifierB)
    assert IsImplementation(
        Implementation, _IIdentifierB, requires_declaration=False
    )


def test_declare_class_implements_invalidates_previous_default_checks():
    class ExternallyDeclared:
        def foo(self):
            return "foo"

    # Populate both declaration-sensitive and structural-check cache entries
    # before declaring the interface from outside the class.
    assert not IsImplementation(ExternallyDeclared, _IFoo)
    assert IsImplementation(
        ExternallyDeclared, _IFoo, requires_declaration=False
    )

    DeclareClassImplements(ExternallyDeclared, _IFoo)

    assert IsImplementation(ExternallyDeclared, _IFoo)
    assert IsImplementation(ExternallyDeclared(), _IFoo)
    assert IsImplementation(
        ExternallyDeclared, _IFoo, requires_declaration=False
    )
    AssertImplements(ExternallyDeclared, _IFoo)


def test_declaration_alone_does_not_bypass_structural_validation():
    @ImplementsInterface(_IFoo, no_check=True)
    class DeclaredButIncomplete:
        pass

    # Declaration is necessary under the new default, but it is not sufficient:
    # the required methods and signatures must still be present.
    assert not IsImplementation(DeclaredButIncomplete, _IFoo)
    assert not IsImplementation(
        DeclaredButIncomplete, _IFoo, requires_declaration=False
    )

    with pytest.raises(AssertionError):
        AssertImplements(DeclaredButIncomplete, _IFoo)

import pytest

import sqlglot


def transpile_one(sql: str, read: str = "mysql", write: str = "duckdb") -> str:
    return sqlglot.transpile(sql, read=read, write=write)[0]


@pytest.mark.parametrize(
    "sql",
    [
        "insert into t(i) values (default)",
        "INSERT INTO t(i) VALUES (DEFAULT)",
        "INSERT INTO t(i) VALUES (DeFaUlT)",
    ],
)
def test_default_in_values_remains_a_keyword(sql):
    """Regression test for the MySQL -> DuckDB translation in the issue."""
    assert transpile_one(sql) == "INSERT INTO t (i) VALUES (DEFAULT)"


def test_default_is_preserved_with_other_values_and_multiple_rows():
    sql = """
        INSERT INTO test(col1, col2)
        VALUES (1, default), (DEFAULT, 'value'), (NULL, 2)
    """

    assert transpile_one(sql) == (
        "INSERT INTO test (col1, col2) "
        "VALUES (1, DEFAULT), (DEFAULT, 'value'), (NULL, 2)"
    )


@pytest.mark.parametrize("write", ["mysql", "duckdb", "postgres"])
def test_default_keyword_survives_translation_to_other_dialects(write):
