"""Regression tests for requiring interface declarations by default."""

import pytest

from oop_ext.interface import (
    AssertImplements,
    DeclareClassImplements,
    ImplementsInterface,
    Interface,
    IsImplementation,
    IsImplementationOfAny,
)


class _IFoo(Interface):
    def foo(self):
        ...


class _IBar(Interface):
    def bar(self):
        ...


def test_is_implementation_requires_declaration_by_default():
    class DuckFoo:
        def foo(self):
            return "foo"

    @ImplementsInterface(_IFoo)
    class DeclaredFoo:
        def foo(self):
            return "foo"

    # Matching the interface's methods is no longer sufficient by default,
    # whether checking a class or an instance.
    assert IsImplementation(DuckFoo, _IFoo) is False
    assert IsImplementation(DuckFoo(), _IFoo) is False

    # Duck typing remains available when explicitly requested.
    assert IsImplementation(DuckFoo, _IFoo, requires_declaration=False) is True
    assert IsImplementation(DuckFoo(), _IFoo, requires_declaration=False) is True

    # Explicitly declared implementations continue to work with the default.
    assert IsImplementation(DeclaredFoo, _IFoo) is True
    assert IsImplementation(DeclaredFoo(), _IFoo) is True


def test_assert_implements_requires_declaration_by_default():
    class DuckFoo:
        def foo(self):
            return "foo"

    @ImplementsInterface(_IFoo)
    class DeclaredFoo:
        def foo(self):
            return "foo"

    # Populate the duck-typing cache first; it must not affect the default check.
    AssertImplements(DuckFoo(), _IFoo, requires_declaration=False)

    with pytest.raises(AssertionError, match="requires_declaration"):
        AssertImplements(DuckFoo(), _IFoo)

    AssertImplements(DeclaredFoo, _IFoo)
    AssertImplements(DeclaredFoo(), _IFoo)


def test_is_implementation_of_any_requires_declaration_by_default():
    class DuckFoo:
        def foo(self):
            return "foo"

    @ImplementsInterface(_IBar)
    class DeclaredBarWithFooMethod:
        def foo(self):
            return "foo"

        def bar(self):
            return "bar"

    assert IsImplementationOfAny(DuckFoo, [_IFoo]) is False
    assert IsImplementationOfAny(DuckFoo(), [_IFoo, _IBar]) is False
    assert (
        IsImplementationOfAny(DuckFoo, [_IFoo], requires_declaration=False) is True
    )

    # Declaring one interface must not make other structurally compatible
    # interfaces count as declared.
    assert IsImplementation(DeclaredBarWithFooMethod, _IFoo) is False
    assert IsImplementationOfAny(DeclaredBarWithFooMethod, [_IFoo]) is False
    assert IsImplementationOfAny(DeclaredBarWithFooMethod(), [_IFoo, _IBar]) is True

    assert IsImplementationOfAny(DuckFoo, []) is False


def test_declare_class_implements_invalidates_previous_default_result():
    class DuckFoo:
        def foo(self):
            return "foo"

    # Cache both a negative declaration-requiring result and a positive
    # duck-typing result before declaring the interface externally.
    assert IsImplementation(DuckFoo, _IFoo) is False
    assert IsImplementation(DuckFoo, _IFoo, requires_declaration=False) is True

    DeclareClassImplements(DuckFoo, _IFoo)

    # The previously cached negative result must not hide the new declaration.
    assert IsImplementation(DuckFoo, _IFoo) is True
    assert IsImplementation(DuckFoo(), _IFoo) is True
    AssertImplements(DuckFoo(), _IFoo)


def test_declaration_does_not_replace_structural_checking():
    class MissingFoo:
        pass

    class WrongFooSignature:
        def foo(self, unexpected_argument):
            ...

    assert IsImplementation(MissingFoo, _IFoo, requires_declaration=False) is False
    assert (
        IsImplementation(WrongFooSignature, _IFoo, requires_declaration=False)
        is False
    )

    with pytest.raises(AssertionError, match="Method 'foo' is missing"):
        DeclareClassImplements(MissingFoo, _IFoo)

    # A failed declaration is rolled back and cannot turn an invalid class into
    # an implementation.
    assert IsImplementation(MissingFoo, _IFoo) is False
    assert IsImplementation(MissingFoo, _IFoo, requires_declaration=False) is False


def test_declared_interface_is_inherited_by_subclasses():
    @ImplementsInterface(_IFoo)
    class BaseFoo:
        def foo(self):
            return "foo"

    class ChildFoo(BaseFoo):
        pass

    assert IsImplementation(ChildFoo, _IFoo) is True
    assert IsImplementation(ChildFoo(), _IFoo) is True
    AssertImplements(ChildFoo(), _IFoo)

import json

import pytest
import yaml

from cfn_flip import to_yaml


ELB_IDS = {
    "us-east-1": "127311923021",
    "us-east-2": "033677994240",
    "us-west-1": "027434742980",
    "us-west-2": "797873946194",
}


def _mapping(node):
    """Return a YAML mapping node keyed by its scalar key values."""
    return {key.value: value for key, value in node.value}


def test_issue_elb_ids_are_all_emitted_as_quoted_strings():
    source = {
        "Mappings": {
            "Regions": {
                region: {
                    "ELBID": identifier,
                    "Name": name,
                }
                for (region, identifier), name in zip(
                    ELB_IDS.items(), ("ue1", "ue2", "uw1", "uw2")
                )
            }
        }
    }

    rendered = to_yaml(json.dumps(source))
    document = yaml.compose(rendered)
    regions = _mapping(_mapping(_mapping(document)["Mappings"])["Regions"])

    for region, expected_identifier in ELB_IDS.items():
        identifier_node = _mapping(regions[region])["ELBID"]

        assert identifier_node.value == expected_identifier
        assert identifier_node.tag == "tag:yaml.org,2002:str"
        # A plain digit-only scalar is not reliably a string to YAML and
        # CloudFormation consumers, even when PyYAML happens to load it as one.
        assert identifier_node.style in ("'", '"'), (
            "%s was emitted as a plain scalar instead of a quoted string"
            % expected_identifier
        )

    # Conversion must also preserve the complete document and every ID exactly.
    assert yaml.safe_load(rendered) == source


@pytest.mark.parametrize(
    "identifier",
    [
        "0",
        "1",
        "00",
        "000000000000",
        "01234567",          # Valid YAML 1.1 octal syntax if left plain.
        "033677994240",      # Leading zero with digits outside the octal range.
        "027434742980",
        "127311923021",
        "797873946194",
        "9007199254740993",
        "999999999999999999999999999999",
    ],
)
def test_digit_only_json_strings_are_consistently_quoted(identifier):
    rendered = to_yaml(json.dumps({"ID": identifier}))
    identifier_node = _mapping(yaml.compose(rendered))["ID"]

    assert identifier_node.value == identifier
    assert identifier_node.tag == "tag:yaml.org,2002:str"
    assert identifier_node.style in ("'", '"')
    assert yaml.safe_load(rendered) == {"ID": identifier}


def test_actual_json_numbers_remain_numbers():
    source = {
        "Integer": 127311923021,
        "Zero": 0,
        "Float": 0.25,
        "String": "127311923021",
    }

    result = yaml.safe_load(to_yaml(json.dumps(source)))

    assert result == source
    assert type(result["Integer"]) is int
    assert type(result["Zero"]) is int
    assert type(result["Float"]) is float
    assert type(result["String"]) is str

import pytest

from vyper.exceptions import InvalidLiteral, OverflowException


def _returning_uint256(expression):
    return f"""
@external
def foo() -> uint256:
    return {expression}
"""


def test_nested_literal_exponentiation_issue(get_contract):
    # 10**36 is well within the uint256 range. Neither the intermediate value
    # nor the final result should be checked against a smaller integer type.
    contract = get_contract(_returning_uint256("(10**18)**2"))
    assert contract.foo() == 10**36


@pytest.mark.parametrize(
    "expression,expected",
    [
        ("(10**18)**0", 1),
        ("(10**18)**1", 10**18),
        ("(2**127)**2", 2**254),
        ("(10**38)**2", 10**76),
        ("2**255", 2**255),
        ("10**77", 10**77),
    ],
)
def test_literal_exponentiation_within_uint256(get_contract, expression, expected):
    contract = get_contract(_returning_uint256(expression))
    assert contract.foo() == expected


@pytest.mark.parametrize(
    "expression",
    [
        "2**256",
        "10**78",
        "(2**128)**2",
        "(10**39)**2",
    ],
)
def test_literal_exponentiation_overflow_is_still_rejected(
    get_contract, assert_compile_failed, expression
):
    assert_compile_failed(
        lambda: get_contract(_returning_uint256(expression)),
        (OverflowException, InvalidLiteral),
    )


def test_large_exponent_with_nonoverflowing_literal_base(get_contract):
    # The exponent's size alone does not imply an overflow; folding 1**10001
    # is cheap and its result is representable.
    contract = get_contract(_returning_uint256("1**10001"))
    assert contract.foo() == 1


def test_nonliteral_base_exponent_limit_is_not_weakened(
    get_contract, assert_compile_failed
):
    # Keep the existing compile-time check for a non-literal base. The fix for
    # nested constant expressions must not permit exponents that the type's
    # exponentiation validation previously rejected.
    source = """
@external
def foo(x: uint8) -> uint8:
    return x**9
"""
    assert_compile_failed(lambda: get_contract(source), OverflowException)

