    IsImplementation,
    IsImplementationOfAny,
)


def test_is_implementation_requires_declaration_by_default():
    class IFoo(Interface):
        def foo(self, value):
            ...

    class Duck:
        def foo(self, value):
            return value

    # Matching the interface structurally is no longer sufficient by default,
    # for either classes or instances.
    for class_or_instance in (Duck, Duck()):
        assert not IsImplementation(class_or_instance, IFoo)

        # Duck typing remains available as an explicit opt-in.
        assert IsImplementation(
            class_or_instance, IFoo, requires_declaration=False
        )


def test_declared_implementations_are_accepted_by_default():
    class IFoo(Interface):
        def foo(self, value):
            ...

    @ImplementsInterface(IFoo)
    class Foo:
        def foo(self, value):
            return value

    class Child(Foo):
        pass

    for class_or_instance in (Foo, Foo(), Child, Child()):
        assert IsImplementation(class_or_instance, IFoo)
        AssertImplements(class_or_instance, IFoo)


def test_assert_implements_requires_declaration_by_default():
    class IFoo(Interface):
        def foo(self, value):
            ...

    class Duck:
        def foo(self, value):
            return value

    for class_or_instance in (Duck, Duck()):
        with pytest.raises(AssertionError, match="requires_declaration"):
            AssertImplements(class_or_instance, IFoo)

        # The same structurally valid object passes when duck typing is
        # explicitly requested.
        AssertImplements(class_or_instance, IFoo, requires_declaration=False)


def test_is_implementation_of_any_honors_declaration_default():
    class IFoo(Interface):
        def foo(self):
            ...

    class IBar(Interface):
        def bar(self):
            ...

    class Duck:
        def foo(self):
            pass

    # Duck structurally implements IFoo, but declares neither interface.
    assert not IsImplementationOfAny(Duck, [IBar, IFoo])
    assert not IsImplementationOfAny(Duck(), [IBar, IFoo])

    assert IsImplementationOfAny(
        Duck, [IBar, IFoo], requires_declaration=False
    )
    assert IsImplementationOfAny(
        Duck(), [IBar, IFoo], requires_declaration=False
    )

    @ImplementsInterface(IFoo)
    class Foo:
        def foo(self):
            pass

    # One explicitly declared implementation is enough for "any".
    assert IsImplementationOfAny(Foo, [IBar, IFoo])
    assert IsImplementationOfAny(Foo(), [IBar, IFoo])
