        def foo(self, value):
            return value

    # Populate both declaration-aware and structural-check caches before the
    # interface is declared externally.
    assert not IsImplementation(Duck, IFoo)
    assert IsImplementation(Duck, IFoo, requires_declaration=False)

    DeclareClassImplements(Duck, IFoo)

    assert IFoo in GetImplementedInterfaces(Duck)
    assert IsImplementation(Duck, IFoo)
    assert IsImplementation(Duck(), IFoo)
    AssertImplements(Duck, IFoo)


def test_declaration_does_not_replace_structural_checking():
    class IFoo(Interface):
        def foo(self):
            ...

    @ImplementsInterface(IFoo, no_check=True)
    class Incomplete:
        pass

    assert IFoo in GetImplementedInterfaces(Incomplete)

    # An explicit declaration alone must not turn an incomplete class into an
    # implementation, regardless of the requires_declaration setting.
    assert not IsImplementation(Incomplete, IFoo)
    assert not IsImplementation(
        Incomplete, IFoo, requires_declaration=False
    )

    with pytest.raises(AssertionError, match="Method 'foo' is missing"):
        AssertImplements(Incomplete, IFoo)

import json

import pytest

from cfn_flip import to_json, to_yaml


ISSUE_TEMPLATE = {
    "Mappings": {
        "Regions": {
            "us-east-1": {
                "ELBID": "127311923021",
                "Name": "ue1",
            },
            "us-east-2": {
                "ELBID": "033677994240",
                "Name": "ue2",
            },
            "us-west-1": {
                "ELBID": "027434742980",
                "Name": "uw1",
            },
            "us-west-2": {
                "ELBID": "797873946194",
                "Name": "uw2",
            },
        },
    },
}

ELB_IDS = [
    "127311923021",
    "033677994240",
    "027434742980",
    "797873946194",
]


def _dump(document, clean_up=False):
    return to_yaml(json.dumps(document), clean_up=clean_up)


def _round_trip(document, clean_up=False):
    yaml_text = _dump(document, clean_up=clean_up)
    restored = json.loads(to_json(yaml_text))
    return yaml_text, restored


def _scalars_for_key(yaml_text, key):
    prefix = key + ":"
    scalars = []

    for line in yaml_text.splitlines():
        stripped = line.strip()
        if stripped.startswith(prefix):
            scalars.append(stripped[len(prefix):].strip())

    return scalars


def _quoted_representations(value):
    return ("'{}'".format(value), '"{}"'.format(value))


@pytest.mark.parametrize("clean_up", [False, True])
def test_issue_elb_ids_are_consistently_emitted_as_strings(clean_up):
    yaml_text, restored = _round_trip(ISSUE_TEMPLATE, clean_up=clean_up)

    rendered_ids = _scalars_for_key(yaml_text, "ELBID")
    assert len(rendered_ids) == len(ELB_IDS)

    # In particular, IDs containing 8 or 9 must not be left plain merely
    # because PyYAML does not consider them valid YAML 1.1 octal integers.
    for elb_id in ELB_IDS:
        assert any(
            rendered == quoted
            for rendered in rendered_ids
            for quoted in _quoted_representations(elb_id)
        ), "ELB ID {!r} was not emitted as a quoted string:\n{}".format(
            elb_id, yaml_text
        )

    assert restored == ISSUE_TEMPLATE
    for region in restored["Mappings"]["Regions"].values():
        assert isinstance(region["ELBID"], str)


@pytest.mark.parametrize(
    "value",
    [
        "0",
        "00",
        "0000",
        "0123",
        "0777",
        "08",
        "09",
        "018",
        "0987654321",
        "033677994240",
        "027434742980",
        "123",
        "-123",
        "+123",
        "127311923021",
        "797873946194",
    ],
)
def test_integer_strings_are_quoted_and_preserve_their_value(value):
    document = {"Value": value}
    yaml_text, restored = _round_trip(document)

    scalars = _scalars_for_key(yaml_text, "Value")
    assert len(scalars) == 1
    assert scalars[0] in _quoted_representations(value), yaml_text

    assert restored == document
    assert isinstance(restored["Value"], str)


def test_leading_zero_strings_in_sequences_and_mapping_keys_are_preserved():
    document = {
        "Items": [
            "033677994240",
            {"Nested": "027434742980"},
        ],
        "Mappings": {
            "08": "zero eight",
            "123": "one two three",
        },
    }

    yaml_text, restored = _round_trip(document)

    assert "'033677994240'" in yaml_text or '"033677994240"' in yaml_text
    assert "'027434742980'" in yaml_text or '"027434742980"' in yaml_text
    assert "'08':" in yaml_text or '"08":' in yaml_text
    assert restored == document


def test_multiline_string_handling_is_not_changed():
    document = {"Value": "0first line\nsecond line"}

    yaml_text, restored = _round_trip(document)

    # Existing multiline strings use double quotes and escaped newlines. A
    # leading zero must not cause them to be emitted as literal block text.
    assert 'Value: "0first line\\nsecond line"' in yaml_text
    assert restored == document


def test_actual_json_numbers_remain_numbers():
    document = {
        "Integer": 123,
        "Zero": 0,
        "Negative": -7,
        "Float": 1.25,
        "String": "123",
    }

    yaml_text, restored = _round_trip(document)

    assert _scalars_for_key(yaml_text, "Integer") == ["123"]
    assert _scalars_for_key(yaml_text, "Zero") == ["0"]
    assert _scalars_for_key(yaml_text, "Negative") == ["-7"]
    assert _scalars_for_key(yaml_text, "Float") == ["1.25"]
    assert _scalars_for_key(yaml_text, "String")[0] in _quoted_representations(
        "123"
    )

    assert restored == document
    assert isinstance(restored["Integer"], int)
    assert isinstance(restored["Zero"], int)
    assert isinstance(restored["Negative"], int)
