import pytest

from unyt import cm
from unyt.array import unyt_array, unyt_quantity


def _take_with_method(a, indices, **kwargs):
    return a.take(indices, **kwargs)


def _take_with_numpy(a, indices, **kwargs):
    return np.take(a, indices, **kwargs)


TAKE_IMPLEMENTATIONS = [
    pytest.param(_take_with_method, id="array-method"),
    pytest.param(_take_with_numpy, id="numpy-function"),
]


def _assert_quantity(result, expected_value):
    assert type(result) is unyt_quantity
    assert result.units == cm
    assert result.ndim == 0
    assert result.value == expected_value


def _assert_array(result, expected_values):
    assert type(result) is unyt_array
    assert result.units == cm
    np.testing.assert_array_equal(np.asarray(result), expected_values)


@pytest.mark.parametrize("take", TAKE_IMPLEMENTATIONS)
@pytest.mark.parametrize(
    ("indices", "expected_value"),
    [
        (0, 1),
        (1, 2),
        (-1, 3),
        (np.int64(2), 3),
        (np.array(1), 2),
    ],
)
def test_take_scalar_index_preserves_units(take, indices, expected_value):
    a = [1, 2, 3] * cm

    result = take(a, indices)

    _assert_quantity(result, expected_value)


@pytest.mark.parametrize("take", TAKE_IMPLEMENTATIONS)
@pytest.mark.parametrize(
    ("indices", "expected_values"),
    [
        ([0], [1]),
        ([2, 0], [3, 1]),
        (np.array([1, 1]), [2, 2]),
    ],
)
def test_take_array_indices_remain_unyt_arrays(take, indices, expected_values):
    a = [1, 2, 3] * cm

    result = take(a, indices)

    _assert_array(result, expected_values)


