def mqtt_client_id(client: MqttClient) -> str:
    client_id = client._client_id
    if isinstance(client_id, bytes):
        return client_id.decode()
    return client_id


def assert_generated_client_id(client_id: str) -> None:
    # Preserve the identifier format previously supplied by Config:
    # six bytes represented as twelve uppercase hexadecimal characters.
    assert re.fullmatch(r"[0-9A-F]{12}", client_id) is not None


def test_config_does_not_generate_client_id() -> None:
    configs = [make_config(), make_config()]

    for config in configs:
        # Implementations may remove the field entirely or leave an empty
        # optional setting, but Config must no longer create an identifier.
        assert getattr(config, "client_id", None) in (None, "")


def test_each_app_mqtt_client_initialization_generates_a_unique_client_id() -> None:
    # Sharing one configuration must not result in sharing an MQTT identity.
    config = make_config()
    apps = [App(config) for _ in range(8)]
    client_ids = [mqtt_client_id(app.client) for app in apps]

    for client_id in client_ids:
        assert_generated_client_id(client_id)

