"""Regression tests for replacing shows which start on a sync_ms boundary."""

from mpf.tests.MpfTestCase import MpfTestCase


class TestSyncedShowReplacement(MpfTestCase):
    """A replaced show must remain active until its synced replacement starts."""

    def getConfigFile(self):
        return 'test_shows.yaml'

    def getMachinePath(self):
        return 'tests/machine_files/shows/'

    def setUp(self):
        # Use action-less shows so these tests exercise show lifecycle behavior
        # without depending on any particular light or LED hardware.
        self.machine_config_patches['shows'] = {
            'ttg_old': [
                {'duration': 1},
                {'duration': 1},
            ],
            'ttg_new': [
                {'duration': 1},
                {'duration': 1},
            ],
            'ttg_other': [
                {'duration': 1},
                {'duration': 1},
            ],
        }
        self.machine_config_patches['show_player'] = {
            'ttg_start_old': {
                'ttg_old': {
                    'key': 'ttg_shared',
                    'sync_ms': 0,
                },
            },
            'ttg_start_new_synced': {
                'ttg_new': {
                    'key': 'ttg_shared',
                    'sync_ms': 10000,
                },
            },
            'ttg_start_other_synced': {
                'ttg_other': {
                    'key': 'ttg_shared',
                    'sync_ms': 10000,
                },
            },
            'ttg_start_new_immediate': {
                'ttg_new': {
                    'key': 'ttg_shared',
                    'sync_ms': 0,
                },
            },
            'ttg_start_other_key': {
                'ttg_other': {
                    'key': 'ttg_unrelated',
                    'sync_ms': 10000,
                },
            },
        }
        super().setUp()

    def _play(self, event):
        self.machine.events.post(event)
        self.advance_time_and_run()

    def _instances(self):
        return self.machine.show_player.instances['_global']['show_player']

    def _advance_to_start(self, show):
        remaining = show.next_step_time - self.machine.clock.get_time()
        self.assertGreater(remaining, 0)
        self.advance_time_and_run(remaining + 0.05)

    def test_old_show_stops_when_synced_replacement_starts(self):
        self._play('ttg_start_old')
        old_show = self._instances()['ttg_shared']
        self.assertFalse(old_show.stopped)
        self.assertIsNotNone(old_show.current_step_index)

        self._play('ttg_start_new_synced')
        new_show = self._instances()['ttg_shared']
        self.assertIsNot(old_show, new_show)

        # Requesting the replacement must not immediately stop the old show.
        self.assertFalse(old_show.stopped)
        self.assertFalse(new_show.stopped)
        self.assertIsNone(new_show.current_step_index)

        # It must also remain running throughout the synchronization delay.
        remaining = new_show.next_step_time - self.machine.clock.get_time()
        self.advance_time_and_run(remaining - 0.05)
        self.assertFalse(old_show.stopped)
        self.assertIsNone(new_show.current_step_index)

        # Once the new show actually starts, the old show is stopped.
        self.advance_time_and_run(0.1)
        self.assertTrue(old_show.stopped)
        self.assertFalse(new_show.stopped)
        self.assertEqual(0, new_show.current_step_index)

    def test_unsynced_replacement_still_stops_old_show_immediately(self):
        self._play('ttg_start_old')
        old_show = self._instances()['ttg_shared']

        self._play('ttg_start_new_immediate')
        new_show = self._instances()['ttg_shared']

        self.assertTrue(old_show.stopped)
        self.assertFalse(new_show.stopped)
        self.assertIsNotNone(new_show.current_step_index)

    def test_synced_show_with_another_key_does_not_stop_old_show(self):
        self._play('ttg_start_old')
        old_show = self._instances()['ttg_shared']

        self._play('ttg_start_other_key')
        other_show = self._instances()['ttg_unrelated']
        self._advance_to_start(other_show)

        self.assertEqual(0, other_show.current_step_index)
        self.assertFalse(old_show.stopped)

    def test_successive_synced_replacements_do_not_orphan_original_show(self):
        """The latest replacement must not leave an earlier show running."""
        self._play('ttg_start_old')
        original_show = self._instances()['ttg_shared']

        self._play('ttg_start_new_synced')
        first_pending_show = self._instances()['ttg_shared']

        # Replace the pending show before its sync boundary arrives.
        self._play('ttg_start_other_synced')
        latest_show = self._instances()['ttg_shared']
        self.assertIsNone(latest_show.current_step_index)

        self._advance_to_start(latest_show)

        self.assertEqual(0, latest_show.current_step_index)
        self.assertFalse(latest_show.stopped)
        self.assertTrue(first_pending_show.stopped)
        self.assertTrue(original_show.stopped)

