def test_folded_base_with_variable_exponent(get_contract, tx_failed):
    source = """
@external
def foo(power: uint256) -> uint256:
    return (10**18)**power
    """
    contract = get_contract(source)

    assert contract.foo(0) == 1
    assert contract.foo(1) == 10**18
    assert contract.foo(2) == 10**36
    assert contract.foo(4) == 10**72

