def test_issue_tuple_coercion_dict_roundtrip() -> None:
    # This class definition used to raise SyntaxError while generating the
    # deserializer because data["loc"][0] was interpolated without escaping.
    @serde.serde(type_check=serde.coerce)
    class Foo:
        loc: tuple[float, float]

    foo = Foo(loc=(1, 2))
