from typing import Any, Optional

import serde
from serde.de import DeField, Renderer


def assert_float_pair(value: Any) -> None:
    assert type(value) is tuple
    assert len(value) == 2
    assert value == (1.0, 2.0)
    assert all(type(item) is float for item in value)


def test_issue_example_serializes_and_coerces_tuple_elements() -> None:
    @serde.serde(type_check=serde.coerce)
