    assert set(serialized) == {"loc"}
    assert_float_pair(serialized["loc"])

    serialized_tuple = serde.to_tuple(foo)
    assert len(serialized_tuple) == 1
    assert_float_pair(serialized_tuple[0])


def test_fixed_tuple_deserialization_coerces_elements() -> None:
    @serde.serde(type_check=serde.coerce)
    class Foo:
        loc: tuple[float, float]

    from_list = serde.from_dict(Foo, {"loc": [1, 2]})
    assert_float_pair(from_list.loc)

    from_tuple_value = serde.from_dict(Foo, {"loc": (1, 2)})
    assert_float_pair(from_tuple_value.loc)

    from_iter = serde.from_tuple(Foo, ((1, 2),))
    assert_float_pair(from_iter.loc)

    roundtrip = serde.from_dict(Foo, serde.to_dict(Foo(loc=(1, 2))))
