def test_renamed_tuple_field_with_coerce() -> None:
    @serde.serde(type_check=serde.coerce, rename_all="camelcase")
    class Renamed:
        location_in_space: tuple[float, float]

    serialized = serde.to_dict(Renamed(location_in_space=(1, 2)))
    assert set(serialized) == {"locationInSpace"}
    assert_float_pair(serialized["locationInSpace"])

    restored = serde.from_dict(Renamed, {"locationInSpace": [1, 2]})
    assert_float_pair(restored.location_in_space)


def test_tuple_renderer_produces_valid_python_and_preserves_field_path() -> None:
    expression = Renderer("from_dict", class_name="Foo").render(
        DeField(tuple[float, float], "loc", datavar="data")
    )

    calls: list[tuple[str, str, type[Any], Any]] = []

    def coerce_object(cls: str, name: str, typ: type[Any], value: Any) -> Any:
        calls.append((cls, name, typ, value))
        return typ(value)

    result = eval(
        expression,
        {
            "coerce_object": coerce_object,
            "data": {"loc": [1, 2]},
        },
    )

    assert_float_pair(result)
    assert calls == [
        ("Foo", 'data["loc"][0]', float, 1),
        ("Foo", 'data["loc"][1]', float, 2),
    ]

