"""Regression tests for tuple code generation with coercion enabled."""

from typing import Optional

import serde
from serde import field
from serde.de import DeField, Renderer


def test_issue_tuple_coercion_roundtrip() -> None:
    """The exact issue example must generate valid code and coerce tuple items."""

    @serde.serde(type_check=serde.coerce)
    class Foo:
        loc: tuple[float, float]

    foo = Foo(loc=(1, 2))

    assert serde.to_dict(foo) == {"loc": (1.0, 2.0)}
    assert serde.to_tuple(foo) == ((1.0, 2.0),)

    from_dict = serde.from_dict(Foo, {"loc": [3, 4]})
    assert from_dict.loc == (3.0, 4.0)
    assert all(type(value) is float for value in from_dict.loc)

    from_tuple = serde.from_tuple(Foo, ((5, 6),))
    assert from_tuple.loc == (5.0, 6.0)
    assert all(type(value) is float for value in from_tuple.loc)


def test_nested_and_mixed_tuples_with_coercion() -> None:
    """Every nested tuple accessor must be escaped, not just the first level."""

    @serde.serde(type_check=serde.coerce)
    class Nested:
        points: tuple[tuple[float, float], tuple[float, float]]
        metadata: tuple[str, int]

    value = Nested(points=((1, 2), (3, 4)), metadata=("answer", 42))
    assert serde.to_dict(value) == {
        "points": ((1.0, 2.0), (3.0, 4.0)),
        "metadata": ("answer", 42),
    }

    restored = serde.from_dict(
        Nested,
        {"points": [[5, 6], [7, 8]], "metadata": ("answer", 42)},
    )
    assert restored.points == ((5.0, 6.0), (7.0, 8.0))
    assert all(
        type(coordinate) is float
        for point in restored.points
        for coordinate in point
    )
    assert restored.metadata == ("answer", 42)


def test_tuple_coercion_with_apostrophe_in_renamed_field() -> None:
    """Using single quotes around the accessor is not a sufficient escaping fix."""

    @serde.serde(type_check=serde.coerce)
    class Renamed:
        loc: tuple[float, float] = field(rename="owner's")

    value = Renamed(loc=(1, 2))
    assert serde.to_dict(value) == {"owner's": (1.0, 2.0)}

    restored = serde.from_dict(Renamed, {"owner's": [3, 4]})
    assert restored.loc == (3.0, 4.0)
    assert all(type(coordinate) is float for coordinate in restored.loc)


def test_optional_tuple_with_coercion() -> None:
    """Optional tuples use the same tuple renderer and must remain supported."""

    @serde.serde(type_check=serde.coerce)
    class OptionalTuple:
        loc: Optional[tuple[float, float]] = None

    assert serde.to_dict(OptionalTuple()) == {"loc": None}
    assert serde.from_dict(OptionalTuple, {"loc": None}).loc is None

    restored = serde.from_dict(OptionalTuple, {"loc": [1, 2]})
    assert restored.loc == (1.0, 2.0)
    assert all(type(coordinate) is float for coordinate in restored.loc)


def test_variable_length_tuple_with_coercion() -> None:
    """The fixed-tuple escaping fix must not regress variable-length tuples."""

    @serde.serde(type_check=serde.coerce)
    class VariableTuple:
        values: tuple[int, ...]

    value = VariableTuple(values=(1, 2, 3, 4))
    assert serde.to_dict(value) == {"values": (1, 2, 3, 4)}
    assert serde.from_dict(VariableTuple, {"values": [1, 2, 3, 4]}).values == (
        1,
        2,
        3,
        4,
    )


def test_rendered_tuple_accessors_are_executable_and_preserved() -> None:
    """The generated expression must compile and retain useful accessor names."""

    rendered = Renderer("foo").render(
        DeField(tuple[float, float], "loc", datavar="data")
    )

    coerced_names = []

    def coerce_object(class_name, name, typ, value):
        coerced_names.append(name)
        return typ(value)

    result = eval(
        rendered,
        {
            "coerce_object": coerce_object,
            "data": {"loc": ("1.5", "2.5")},
        },
    )

    assert result == (1.5, 2.5)
    assert coerced_names == ['data["loc"][0]', 'data["loc"][1]']

