import pytest

from vyper import compiler
from vyper.exceptions import InvalidLiteral, OverflowException


def test_issue_nested_literal_pow(get_contract):
    # 10**36 is well within the uint256 range. In particular, validating the
    # intermediate 10**18 against narrower possible integer types must not
    # make compilation fail.
    contract = get_contract(
        """
@external
def foo() -> uint256:
    return (10**18)**2
"""
    )

    assert contract.foo() == 10**36


@pytest.mark.parametrize(
    ("expression", "expected"),
    [
        # A result just below the uint256 overflow boundary.
        ("(2**127)**2", 2**254),
        # The intermediate literal needs the full unsigned 256-bit range,
        # while exponentiation by one leaves the value unchanged.
        ("(2**255)**1", 2**255),
        # Decimal cases on both sides of the approximate 10**77 magnitude of
        # uint256's maximum, with results that still fit.
        ("(10**38)**2", 10**76),
        ("(10**77)**1", 10**77),
    ],
)
def test_valid_nested_literal_pow(get_contract, expression, expected):
    source = f"""
@external
def foo() -> uint256:
    return {expression}
"""
    contract = get_contract(source)
    assert contract.foo() == expected


@pytest.mark.parametrize(
    "expression",
    [
        # Exactly one greater than the largest uint256.
        "(2**128)**2",
        # 10**78 is greater than 2**256 - 1.
        "(10**39)**2",
    ],
)
def test_nested_literal_pow_real_overflow_still_rejected(expression, assert_compile_failed):
    source = f"""
@external
def foo() -> uint256:
    return {expression}
"""

    # Depending on whether folding or literal validation diagnoses it first,
    # an out-of-range integer literal can be reported as InvalidLiteral.
    assert_compile_failed(
        lambda: compiler.compile_code(source), (OverflowException, InvalidLiteral)
    )


def test_nonliteral_pow_exponent_limit_for_narrow_type(assert_compile_failed):
    # Fixing nested literals must not weaken the existing validation for a
    # non-literal base. Before the patch, uint8 rejected exponents greater
    # than its eight value bits with OverflowException. Allowing this through
    # semantic analysis instead leads to an internal TypeCheckFailure during
    # code generation, which is not a valid public compilation diagnostic.
    source = """
@external
def foo(x: uint8) -> uint8:
    return x**9
"""
    assert_compile_failed(lambda: compiler.compile_code(source), OverflowException)


def test_nonliteral_base_pow_behavior_unchanged(get_contract):
    contract = get_contract(
        """
@external
def foo(x: uint256) -> uint256:
    return x**2
"""
    )

    assert contract.foo(10**18) == 10**36
    assert contract.foo(0) == 0
    assert contract.foo(1) == 1

