import serde


def _assert_float_pair(value: tuple[float, float]) -> None:
    assert all(type(item) is float for item in value)


def test_tuple_coercion_issue_roundtrip() -> None:
    """The example in the issue must generate valid code and coerce both ways."""

    @serde.serde(type_check=serde.coerce)
    class Foo:
        loc: tuple[float, float]

    foo = Foo(loc=(1, 2))

    serialized = serde.to_dict(foo)
    assert serialized == {"loc": (1.0, 2.0)}
    _assert_float_pair(serialized["loc"])

    deserialized = serde.from_dict(Foo, serialized)
    assert deserialized.loc == (1.0, 2.0)
    _assert_float_pair(deserialized.loc)


def test_nested_tuple_coercion_roundtrip() -> None:
    """Tuple element expressions containing quotes must also work recursively."""

    @serde.serde(type_check=serde.coerce)
    class NestedTuples:
        matrix: tuple[tuple[float, float], tuple[float, float]]

    original = NestedTuples(matrix=((1, 2), (3, 4)))
    serialized = serde.to_dict(original)

    assert serialized == {"matrix": ((1.0, 2.0), (3.0, 4.0))}
    for pair in serialized["matrix"]:
        _assert_float_pair(pair)

    # Lists are representative of input produced by JSON decoders.
    deserialized = serde.from_dict(NestedTuples, {"matrix": [[1, 2], [3, 4]]})
    assert deserialized.matrix == ((1.0, 2.0), (3.0, 4.0))
    for pair in deserialized.matrix:
        _assert_float_pair(pair)


def test_tuple_coercion_with_iter_based_apis() -> None:
    """The tuple-based APIs must remain valid alongside the dict-based fix."""

    @serde.serde(type_check=serde.coerce)
    class IterBased:
        loc: tuple[float, float]
        count: int

    original = IterBased(loc=(1, 2), count=3)
    serialized = serde.to_tuple(original)

    assert serialized == ((1.0, 2.0), 3)
    _assert_float_pair(serialized[0])
    assert type(serialized[1]) is int

    deserialized = serde.from_tuple(IterBased, ((1, 2), 3))
    assert deserialized.loc == (1.0, 2.0)
    _assert_float_pair(deserialized.loc)
    assert deserialized.count == 3


def test_tuple_coercion_with_renamed_field() -> None:
    """Renaming changes the quoted data accessor used by generated tuple code."""

    @serde.serde(type_check=serde.coerce, rename_all="camelcase")
    class RenamedTuple:
        location_pair: tuple[float, float]

    original = RenamedTuple(location_pair=(4, 5))
    serialized = serde.to_dict(original)

    assert serialized == {"locationPair": (4.0, 5.0)}
    _assert_float_pair(serialized["locationPair"])

    deserialized = serde.from_dict(RenamedTuple, {"locationPair": [4, 5]})
    assert deserialized.location_pair == (4.0, 5.0)
    _assert_float_pair(deserialized.location_pair)

from ansible_builder.introspect import process
