import pytest

import sqlglot
from sqlglot import exp, parse_one


def transpile_from_mysql(sql: str, write: str = "duckdb", **opts) -> str:
    return sqlglot.transpile(sql, read="mysql", write=write, **opts)[0]


def first_insert_value(statement: exp.Expression) -> exp.Expression:
    values = statement.find(exp.Values)
    assert values is not None
    return values.expressions[0].expressions[0]


def test_reported_mysql_to_duckdb_regression():
    assert (
        transpile_from_mysql("insert into t(i) values (default)")
        == "INSERT INTO t (i) VALUES (DEFAULT)"
    )


@pytest.mark.parametrize("write", ["duckdb", "mysql", "postgres", "sqlite"])
def test_default_remains_an_unquoted_keyword_across_dialects(write):
    result = transpile_from_mysql("INSERT INTO t (i) VALUES (DEFAULT)", write=write)
    assert result == "INSERT INTO t (i) VALUES (DEFAULT)"
    assert '"default"' not in result.lower()


@pytest.mark.parametrize(
    ("sql", "expected"),
    [
        (
            "insert into t values (default)",
            "INSERT INTO t VALUES (DEFAULT)",
        ),
        (
            "insert into t(i,j) values (default, 1)",
            "INSERT INTO t (i, j) VALUES (DEFAULT, 1)",
        ),
        (
            "insert into t(i,j) values (1, default)",
            "INSERT INTO t (i, j) VALUES (1, DEFAULT)",
        ),
        (
            "insert into t(i,j,k) values (default, 1, default)",
            "INSERT INTO t (i, j, k) VALUES (DEFAULT, 1, DEFAULT)",
        ),
        (
            "insert into t(i) values (default), (1), (default)",
            "INSERT INTO t (i) VALUES (DEFAULT), (1), (DEFAULT)",
        ),
        (
            "insert into t(i,j,k) values (default, 'default', 2)",
            "INSERT INTO t (i, j, k) VALUES (DEFAULT, 'default', 2)",
        ),
    ],
)
def test_default_in_mixed_and_multiple_values(sql, expected):
    assert transpile_from_mysql(sql) == expected


@pytest.mark.parametrize("keyword", ["default", "DEFAULT", "Default", "dEfAuLt"])
def test_default_keyword_is_case_insensitive(keyword):
    assert (
        transpile_from_mysql(f"INSERT INTO t (i) VALUES ({keyword})")
        == "INSERT INTO t (i) VALUES (DEFAULT)"
    )


def test_default_is_represented_as_a_keyword_expression_not_an_identifier():
    statement = parse_one(
        "INSERT INTO t (i, j, k) VALUES (DEFAULT, 1, DEFAULT)", read="mysql"
    )

    value = first_insert_value(statement)
    assert isinstance(value, exp.Default)
    assert value.name == "DEFAULT"
    assert value.sql("duckdb") == "DEFAULT"
    assert len(list(statement.find_all(exp.Default))) == 2


def test_identifier_quoting_options_do_not_quote_default_keyword():
    assert (
        transpile_from_mysql("INSERT INTO t (i) VALUES (DEFAULT)", identify=True)
        == 'INSERT INTO "t" ("i") VALUES (DEFAULT)'
    )


@pytest.mark.parametrize("literal", ["default", "Default", "DEFAULT"])
def test_default_string_literals_are_not_converted_to_keywords(literal):
    statement = parse_one(f"INSERT INTO t (i) VALUES ('{literal}')", read="mysql")
    value = first_insert_value(statement)

    assert isinstance(value, exp.Literal)
    assert value.is_string
    assert statement.sql("duckdb") == f"INSERT INTO t (i) VALUES ('{literal}')"


def test_quoted_default_identifier_is_not_converted_to_keyword():
    statement = parse_one("INSERT INTO t (i) VALUES (`default`)", read="mysql")
    value = first_insert_value(statement)

    assert isinstance(value, exp.Column)
    assert value.name == "default"
    assert statement.sql("duckdb") == 'INSERT INTO t (i) VALUES ("default")'


@pytest.mark.parametrize(
    ("sql", "expected"),
    [
        (
            "CREATE TABLE t (id INT DEFAULT 0)",
            "CREATE TABLE t (id INT DEFAULT 0)",
        ),
        (
            "CREATE TABLE t (name VARCHAR(50) DEFAULT 'unknown')",
            "CREATE TABLE t (name TEXT(50) DEFAULT 'unknown')",
        ),
    ],
)
def test_default_column_constraints_are_unchanged(sql, expected):
    statement = parse_one(sql, read="mysql")
    constraint = statement.find(exp.DefaultColumnConstraint)

    assert constraint is not None
    assert isinstance(constraint.this, exp.Literal)
    assert statement.sql("duckdb") == expected

from typing import Optional

import serde


def test_coerce_tuple_field_reproduction() -> None:
    @serde.serde(type_check=serde.coerce)
    class Foo:
        loc: tuple[float, float]

    foo = Foo(loc=(1, 2))

    # Both serialization code paths should generate valid Python and coerce
    # each tuple element to the declared type.
    assert serde.to_dict(foo) == {"loc": (1.0, 2.0)}
    assert serde.to_tuple(foo) == ((1.0, 2.0),)

    restored = serde.from_dict(Foo, {"loc": ("3.5", 4)})
    assert restored.loc == (3.5, 4.0)
    assert all(type(value) is float for value in restored.loc)


def test_coerce_nested_tuple_fields_from_dict() -> None:
    @serde.serde(type_check=serde.coerce)
    class Container:
        values: tuple[str, tuple[int, float], list[int]]

    obj = serde.from_dict(
        Container,
        {"values": ("row", ("1", "2.5"), ["3", 4])},
    )

    assert obj.values == ("row", (1, 2.5), [3, 4])
    assert type(obj.values[1][0]) is int
    assert type(obj.values[1][1]) is float
    assert all(type(value) is int for value in obj.values[2])


def test_coerce_optional_tuple_field() -> None:
    @serde.serde(type_check=serde.coerce)
    class OptionalLocation:
        loc: Optional[tuple[float, float]]

    present = serde.from_dict(OptionalLocation, {"loc": [1, "2.25"]})
    assert present.loc == (1.0, 2.25)
    assert present.loc is not None
    assert all(type(value) is float for value in present.loc)

    missing_value = serde.from_dict(OptionalLocation, {"loc": None})
    assert missing_value.loc is None


def test_coerce_tuple_with_renamed_field_and_iterbased_input() -> None:
    @serde.serde(type_check=serde.coerce)
    class RenamedLocation:
        loc: tuple[int, float] = serde.field(rename="location")

    from_dict = serde.from_dict(
        RenamedLocation, {"location": ("1", "2.5")}
    )
    assert from_dict.loc == (1, 2.5)
    assert type(from_dict.loc[0]) is int
    assert type(from_dict.loc[1]) is float

    from_iter = serde.from_tuple(RenamedLocation, (("3", "4.5"),))
    assert from_iter.loc == (3, 4.5)

    assert serde.to_dict(from_iter) == {"location": (3, 4.5)}

import sys

import pytest

from treon import treon


def _make_notebook(path):
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text("{}", encoding="utf-8")
    return str(path)


def _run_main(monkeypatch, argv):
    """Run the real CLI parsing and collection code without executing notebooks."""
    calls = {}

    class FakeTask:
        def __init__(self, file_path):
            self.file_path = file_path
            self.is_successful = True

    def fake_trigger_tasks(tasks, thread_count):
        calls["tasks"] = tasks
        calls["thread_count"] = thread_count

    monkeypatch.setattr(sys, "argv", ["treon", *argv])
    monkeypatch.setattr(treon, "Task", FakeTask)
    monkeypatch.setattr(treon, "trigger_tasks", fake_trigger_tasks)

    treon.main()

    notebooks = [task.file_path for task in calls["tasks"]]
    return notebooks, calls["thread_count"]


def test_cli_accepts_multiple_individual_notebook_paths(tmp_path, monkeypatch):
    first = _make_notebook(tmp_path / "first.ipynb")
    second = _make_notebook(tmp_path / "second.ipynb")
    third = _make_notebook(tmp_path / "third.ipynb")

    notebooks, thread_count = _run_main(
        monkeypatch, [first, second, third, "--threads=2"]
    )

    assert set(notebooks) == {first, second, third}
    assert int(thread_count) == 2


def test_cli_combines_multiple_directories_and_files_recursively(
    tmp_path, monkeypatch
):
    first_dir = tmp_path / "first"
    second_dir = tmp_path / "second"
    empty_dir = tmp_path / "empty"
    empty_dir.mkdir()

    first = _make_notebook(first_dir / "first.ipynb")
    nested = _make_notebook(first_dir / "nested" / "nested.ipynb")
    second = _make_notebook(second_dir / "second.ipynb")
    explicit = _make_notebook(tmp_path / "explicit.ipynb")
    (second_dir / "not-a-notebook.txt").write_text("ignored", encoding="utf-8")

    notebooks, _ = _run_main(
        monkeypatch,
        [str(first_dir), str(empty_dir), str(second_dir), explicit],
    )

    assert set(notebooks) == {first, nested, second, explicit}


def test_exclude_applies_to_notebooks_from_all_supplied_paths(
    tmp_path, monkeypatch
):
    first = _make_notebook(tmp_path / "first.ipynb")
    excluded = _make_notebook(tmp_path / "excluded.ipynb")
    last = _make_notebook(tmp_path / "last.ipynb")

    notebooks, _ = _run_main(
        monkeypatch,
        [first, excluded, last, "--exclude={}".format(excluded)],
    )

    assert set(notebooks) == {first, last}


def test_single_path_remains_supported(tmp_path, monkeypatch):
    selected = _make_notebook(tmp_path / "selected.ipynb")
    _make_notebook(tmp_path / "not-selected.ipynb")

    notebooks, _ = _run_main(monkeypatch, [selected])

    assert set(notebooks) == {selected}


def test_no_path_still_searches_the_current_working_directory(
    tmp_path, monkeypatch
):
    notebook = _make_notebook(tmp_path / "nested" / "default.ipynb")
    monkeypatch.chdir(tmp_path)

    notebooks, _ = _run_main(monkeypatch, [])

    assert set(notebooks) == {notebook}


def test_invalid_path_among_multiple_paths_is_an_error(tmp_path):
    valid = _make_notebook(tmp_path / "valid.ipynb")
    missing = str(tmp_path / "missing")
    args = {"PATH": [valid, missing], "--exclude": []}

    with pytest.raises(SystemExit, match="is not a valid path"):
        treon.get_notebooks_to_test(args)


def test_non_notebook_file_among_multiple_paths_is_an_error(tmp_path):
    valid = _make_notebook(tmp_path / "valid.ipynb")
    text_file = tmp_path / "notes.txt"
    text_file.write_text("not a notebook", encoding="utf-8")
    args = {"PATH": [valid, str(text_file)], "--exclude": []}

    with pytest.raises(SystemExit, match="is not a Notebook"):
        treon.get_notebooks_to_test(args)


def test_no_notebooks_across_all_paths_is_an_error(tmp_path):
    first = tmp_path / "first"
    second = tmp_path / "second"
    first.mkdir()
    second.mkdir()
    (second / "notes.txt").write_text("not a notebook", encoding="utf-8")
    args = {"PATH": [str(first), str(second)], "--exclude": []}

    with pytest.raises(SystemExit, match="No notebooks to test"):
        treon.get_notebooks_to_test(args)

