import pytest

from vyper.exceptions import InvalidLiteral, InvalidOperation, OverflowException


def _literal_pow_source(expression: str) -> str:
    return f"""
@external
def foo() -> uint256:
    return {expression}
"""


@pytest.mark.parametrize(
    "expression, expected",
    [
        # Regression test for the reported spurious OverflowException.
        ("(10**18)**2", 10**36),
        ("10**36", 10**36),
        # Constant folding and overflow validation must also handle deeper nesting.
        ("((10**18)**2)**2", 10**72),
        ("(10**18)**0", 1),
        # Values close to, but still within, the uint256 upper bound are valid.
        ("2**255", 2**255),
        ("10**77", 10**77),
    ],
)
def test_literal_pow_result_within_uint256(get_contract, expression, expected):
    contract = get_contract(_literal_pow_source(expression))
    assert contract.foo() == expected


@pytest.mark.parametrize(
    "expression",
    [
        "2**256",
        "10**78",
        # Deferring to constant folding must not disable overflow validation.
        "(2**128)**2",
        "(10**39)**2",
    ],
)
def test_literal_pow_result_overflowing_uint256_is_rejected(
    get_contract, assert_compile_failed, expression
):
    # Depending on whether constant folding or literal validation detects the
    # value first, the source-level diagnostic may be an overflow or an invalid
    # literal. In either case, compilation must not succeed or panic internally.
    assert_compile_failed(
        lambda: get_contract(_literal_pow_source(expression)),
        (OverflowException, InvalidLiteral),
    )


def test_literal_pow_negative_exponent_is_rejected(get_contract, assert_compile_failed):
    assert_compile_failed(
        lambda: get_contract(_literal_pow_source("2**(-1)")), InvalidOperation
    )


def test_nonliteral_base_exponentiation_still_works(get_contract):
    contract = get_contract(
        """
@external
def foo(x: uint256) -> uint256:
    return x**2
"""
    )
    assert contract.foo(10**18) == 10**36


@pytest.mark.parametrize(
    "type_name, exponent",
    [
        ("uint8", 9),
        ("int8", 8),
        ("int256", 256),
    ],
)
def test_nonliteral_base_retains_type_specific_exponent_checks(
    get_contract, assert_compile_failed, type_name, exponent
):
    # Fixing literal folding must not replace these checks with a uint256-only
    # limit for narrower or signed integer types, nor allow them to reach code
    # generation and fail with an internal compiler error.
    source = f"""
@external
def foo(x: {type_name}) -> {type_name}:
    return x**{exponent}
"""
    assert_compile_failed(lambda: get_contract(source), OverflowException)

import asyncio
import time

import pytest

from anyio.to_thread import run_sync


CELL_TIMEOUT = 5


@pytest.fixture
def persistent_event_loop():
    """Provide one event loop for several independent top-level await cells."""
    loop = asyncio.new_event_loop()
    asyncio.set_event_loop(loop)
    try:
        yield loop
    finally:
        pending = asyncio.all_tasks(loop)
        for task in pending:
            task.cancel()
        if pending:
            loop.run_until_complete(
                asyncio.gather(*pending, return_exceptions=True)
            )
        loop.close()
        asyncio.set_event_loop(None)


def run_cell(loop, coro):
    """
    Run a coroutine as IPython runs a top-level await.

    Each call creates and completes a new root task while retaining the event
    loop. The watchdog turns a regression into a test failure rather than
    leaving the test suite blocked indefinitely.
    """
    task = loop.create_task(coro)
    watchdog = loop.call_later(CELL_TIMEOUT, task.cancel)
    try:
        return loop.run_until_complete(task)
    except asyncio.CancelledError:
        raise AssertionError(
            "top-level run_sync() call did not finish within {} seconds".format(
                CELL_TIMEOUT
            )
        ) from None
    finally:
        watchdog.cancel()


def test_run_sync_across_successive_top_level_awaits(persistent_event_loop):
    """Completing one top-level await must not break the next run_sync call."""
    calls = []

    def sync_func(value):
        calls.append(value)
        time.sleep(0.01)
        return "{}-done".format(value)

    assert run_cell(
        persistent_event_loop, run_sync(sync_func, "first")
    ) == "first-done"

    # This is the sequence from the issue: the first call succeeds, and the
    # second call must also finish instead of waiting on a stopped worker.
    assert run_cell(
        persistent_event_loop, run_sync(sync_func, "second")
    ) == "second-done"

    # Repeated cells cover continued reuse/cleanup, not just one recovery.
    assert run_cell(
        persistent_event_loop, run_sync(sync_func, "third")
    ) == "third-done"
    assert run_cell(
        persistent_event_loop, run_sync(sync_func, "fourth")
    ) == "fourth-done"
    assert calls == ["first", "second", "third", "fourth"]


def test_run_sync_in_top_level_await_after_previous_cell_failed(
    persistent_event_loop,
):
    """A failed top-level task must also clean up its worker thread."""

    def fail():
        raise ValueError("boom")

    with pytest.raises(ValueError, match="boom"):
        run_cell(persistent_event_loop, run_sync(fail))

    assert run_cell(
        persistent_event_loop, run_sync(lambda: "recovered")
    ) == "recovered"

from typing import Optional

import serde
from serde.json import from_json


def test_coerce_tuple_issue_reproduction() -> None:
    @serde.serde(type_check=serde.coerce)
    class Foo:
        loc: tuple[float, float]

    foo = Foo(loc=(1, 2))

    serialized = serde.to_dict(foo)
    assert serialized == {"loc": (1.0, 2.0)}
    assert all(type(value) is float for value in serialized["loc"])

    serialized_tuple = serde.to_tuple(foo)
    assert serialized_tuple == ((1.0, 2.0),)
    assert all(type(value) is float for value in serialized_tuple[0])

    deserialized = serde.from_dict(Foo, {"loc": ["1.25", "2.5"]})
    assert deserialized.loc == (1.25, 2.5)
    assert all(type(value) is float for value in deserialized.loc)

    deserialized_iter = serde.from_tuple(Foo, (["3.75", "4.5"],))
    assert deserialized_iter.loc == (3.75, 4.5)
    assert all(type(value) is float for value in deserialized_iter.loc)

    deserialized_json = from_json(Foo, '{"loc": ["5.25", 6]}')
    assert deserialized_json.loc == (5.25, 6.0)
    assert all(type(value) is float for value in deserialized_json.loc)


def test_coerce_nested_tuples_escape_all_generated_field_paths() -> None:
    @serde.serde(type_check=serde.coerce)
    class Matrix:
        values: tuple[tuple[int, int], tuple[float, float]]

    matrix = serde.from_dict(
        Matrix, {"values": [["1", "2"], ["3.5", 4]]}
    )
    assert matrix.values == ((1, 2), (3.5, 4.0))
    assert all(type(value) is int for value in matrix.values[0])
    assert all(type(value) is float for value in matrix.values[1])

    serialized = serde.to_dict(matrix)
    assert serialized == {"values": ((1, 2), (3.5, 4.0))}
    assert all(type(value) is int for value in serialized["values"][0])
    assert all(type(value) is float for value in serialized["values"][1])


def test_coerce_optional_tuple() -> None:
    @serde.serde(type_check=serde.coerce)
    class OptionalPoint:
        loc: Optional[tuple[int, int]]

    point = serde.from_dict(OptionalPoint, {"loc": ["7", "8"]})
    assert point.loc == (7, 8)
    assert point.loc is not None
    assert all(type(value) is int for value in point.loc)
    assert serde.to_dict(point) == {"loc": (7, 8)}

    empty = serde.from_dict(OptionalPoint, {"loc": None})
    assert empty.loc is None
    assert serde.to_dict(empty) == {"loc": None}

