"""Regression tests for positional arguments on Group array-creation methods."""

import warnings

import numpy as np
import pytest

import zarr


BASIC_METHODS = ("create", "empty", "zeros", "ones", "full", "array")
LIKE_METHODS = ("empty_like", "zeros_like", "ones_like", "full_like")


def _positional_warning_messages(caught):
    """Return FutureWarnings concerning positional argument usage."""
    return [
        str(warning.message)
        for warning in caught
        if issubclass(warning.category, FutureWarning)
        and "positional" in str(warning.message)
    ]


def _assert_positional_deprecation(caught, *, includes_data=False):
    """Positional v2-style calls must participate in the deprecation cycle."""
    messages = _positional_warning_messages(caught)
    assert messages, "No positional-argument FutureWarning was issued"

    combined_message = "\n".join(messages)
    assert "name" in combined_message, combined_message
    if includes_data:
        assert "data" in combined_message, combined_message


def _assert_no_positional_deprecation(caught):
    assert not _positional_warning_messages(caught)


def _call_basic_method(group, method_name, name, *, positional):
    kwargs = {"shape": (2, 3), "dtype": "i2"}
    if method_name == "full":
        kwargs["fill_value"] = 7

    args = (name,) if positional else ()
    if not positional:
        kwargs["name"] = name

    with warnings.catch_warnings(record=True) as caught:
        warnings.simplefilter("always")
        array = getattr(group, method_name)(*args, **kwargs)

    return array, caught


def _call_like_method(group, method_name, name, data, *, positional):
    kwargs = {}
    if method_name == "full_like":
        kwargs["fill_value"] = 7

    if positional:
        args = (name, data)
    else:
        args = ()
        kwargs.update(name=name, data=data)

    with warnings.catch_warnings(record=True) as caught:
        warnings.simplefilter("always")
        array = getattr(group, method_name)(*args, **kwargs)

    return array, caught


def test_issue_reproduction_nested_group():
    """The v2-style call from the report works, creates the right array, and warns."""
    root = zarr.group()
    bar = root.create_group("foo").create_group("bar")

    with warnings.catch_warnings(record=True) as caught:
        warnings.simplefilter("always")
        array = bar.zeros("baz", shape=(20, 10), chunks=(5, 5), dtype="i4")

    _assert_positional_deprecation(caught)
    assert array.path == "foo/bar/baz"
    assert array.shape == (20, 10)
    assert array.chunks == (5, 5)
    assert array.dtype == np.dtype("i4")
    np.testing.assert_array_equal(array[:], np.zeros((20, 10), dtype="i4"))


@pytest.mark.parametrize("method_name", BASIC_METHODS)
@pytest.mark.parametrize("positional", [True, False], ids=["positional", "keyword"])
def test_group_methods_accept_name_without_breaking_keyword_api(method_name, positional):
    group = zarr.group()
    name = f"{method_name}_{'positional' if positional else 'keyword'}"

    array, caught = _call_basic_method(group, method_name, name, positional=positional)

    if positional:
        _assert_positional_deprecation(caught)
    else:
        # Group.array/create may have their own DeprecationWarning, but using
        # keyword arguments must not trigger the positional-argument warning.
        _assert_no_positional_deprecation(caught)

    assert isinstance(array, zarr.Array)
    assert array.path == name
    assert array.shape == (2, 3)
    assert array.dtype == np.dtype("i2")

    expected = None
    if method_name == "zeros":
        expected = np.zeros((2, 3), dtype="i2")
    elif method_name == "ones":
        expected = np.ones((2, 3), dtype="i2")
    elif method_name == "full":
        expected = np.full((2, 3), 7, dtype="i2")

    if expected is not None:
        np.testing.assert_array_equal(array[:], expected)


@pytest.mark.parametrize("method_name", LIKE_METHODS)
@pytest.mark.parametrize("positional", [True, False], ids=["positional", "keyword"])
def test_like_methods_accept_name_and_data_without_breaking_keyword_api(
    method_name, positional
):
    group = zarr.group()
    data = np.arange(6, dtype="i4").reshape(2, 3)
    name = f"{method_name}_{'positional' if positional else 'keyword'}"

    array, caught = _call_like_method(
        group, method_name, name, data, positional=positional
    )

    if positional:
        _assert_positional_deprecation(caught, includes_data=True)
    else:
        _assert_no_positional_deprecation(caught)

    assert isinstance(array, zarr.Array)
    assert array.path == name
    assert array.shape == data.shape
    assert array.dtype == data.dtype

    expected = None
    if method_name == "zeros_like":
        expected = np.zeros_like(data)
    elif method_name == "ones_like":
        expected = np.ones_like(data)
    elif method_name == "full_like":
        expected = np.full_like(data, 7)

    if expected is not None:
        np.testing.assert_array_equal(array[:], expected)


@pytest.mark.parametrize("method_name", LIKE_METHODS)
def test_like_methods_allow_positional_name_with_keyword_data(method_name):
    """Passing only name positionally is also valid v2-style usage."""
    group = zarr.group()
    data = np.arange(4, dtype="i4")
    kwargs = {"fill_value": 7} if method_name == "full_like" else {}

    with warnings.catch_warnings(record=True) as caught:
        warnings.simplefilter("always")
        array = getattr(group, method_name)(method_name, data=data, **kwargs)

    _assert_positional_deprecation(caught)
    assert array.path == method_name
    assert array.shape == data.shape
    assert array.dtype == data.dtype

