from typing import Optional

import serde


def test_coerce_fixed_tuple_round_trip() -> None:
    """Regression test for the SyntaxError reported with tuple coercion."""

    @serde.serde(type_check=serde.coerce)
    class Foo:
        loc: tuple[float, float]

    foo = Foo(loc=(1, 2))

    as_dict = serde.to_dict(foo)
    assert as_dict == {"loc": (1.0, 2.0)}
    # Equality alone would also pass if the integers had not been coerced.
    assert tuple(type(value) for value in as_dict["loc"]) == (float, float)

    as_tuple = serde.to_tuple(foo)
    assert as_tuple == ((1.0, 2.0),)
    assert tuple(type(value) for value in as_tuple[0]) == (float, float)

    # Exercise the generated deserializer, including coercion of each element.
    from_mapping = serde.from_dict(Foo, {"loc": ("3.25", 4)})
    assert from_mapping.loc == (3.25, 4.0)
    assert tuple(type(value) for value in from_mapping.loc) == (float, float)

    # Iterator-based access uses different generated expressions and must keep
    # working alongside the dictionary-based path that contained the quotes.
    from_sequence = serde.from_tuple(Foo, (("5.25", 6),))
    assert from_sequence.loc == (5.25, 6.0)
    assert tuple(type(value) for value in from_sequence.loc) == (float, float)


def test_coerce_nested_and_heterogeneous_tuples() -> None:
    @serde.serde(type_check=serde.coerce)
    class Nested:
        values: tuple[tuple[int, int], tuple[float, float]]

    value = Nested(values=(("1", 2), (3, "4.5")))
    serialized = serde.to_dict(value)
    assert serialized == {"values": ((1, 2), (3.0, 4.5))}

    restored = serde.from_dict(
        Nested, {"values": [["5", "6"], ["7.25", 8]]}
    )
    assert restored.values == ((5, 6), (7.25, 8.0))
    assert tuple(type(item) for item in restored.values[0]) == (int, int)
    assert tuple(type(item) for item in restored.values[1]) == (float, float)

    @serde.serde(type_check=serde.coerce)
    class Mixed:
        values: tuple[int, float, str]

    mixed = Mixed(values=("10", "2.5", 30))
    assert serde.to_dict(mixed) == {"values": (10, 2.5, "30")}

    mixed_restored = serde.from_dict(Mixed, {"values": ["11", "3.5", 40]})
    assert mixed_restored.values == (11, 3.5, "40")
    assert tuple(type(item) for item in mixed_restored.values) == (
        int,
        float,
        str,
    )


def test_coerce_optional_tuple() -> None:
    @serde.serde(type_check=serde.coerce)
    class OptionalLocation:
        loc: Optional[tuple[int, int]]

    assert serde.to_dict(OptionalLocation(loc=None)) == {"loc": None}
    assert serde.from_dict(OptionalLocation, {"loc": None}).loc is None

    serialized = serde.to_dict(OptionalLocation(loc=("1", 2)))
    assert serialized == {"loc": (1, 2)}
    assert tuple(type(value) for value in serialized["loc"]) == (int, int)

    restored = serde.from_dict(OptionalLocation, {"loc": ["3", "4"]})
    assert restored.loc == (3, 4)
    assert tuple(type(value) for value in restored.loc) == (int, int)

"""Tests for SDO-specific handling of the optional/required ``labels`` property."""

import datetime as dt

import pytest

import stix2
from stix2.common import COMMON_PROPERTIES


LABELS_REQUIRED_SDOS = [
    (
        stix2.Indicator,
        {
            "name": "File hash for malware variant",
            "pattern": 'file:hashes.md5 = "d41d8cd98f00b204e9800998ecf8427e"',
        },
    ),
    (stix2.Malware, {"name": "Poison Ivy"}),
    (
        stix2.Report,
        {
            "name": "Example report",
            "published": dt.datetime(2017, 5, 5, tzinfo=dt.timezone.utc),
            "object_refs": [
                "indicator--63ce9068-b5ab-47fa-a2cf-a602ea01f21a"
            ],
        },
    ),
    (stix2.ThreatActor, {"name": "Example threat actor"}),
    (stix2.Tool, {"name": "Example tool"}),
]


def test_labels_is_defined_per_sdo_not_as_a_common_property():
    """Making labels universally optional would not express SDO requirements."""
    assert "labels" not in COMMON_PROPERTIES


@pytest.mark.parametrize("sdo_class, required_kwargs", LABELS_REQUIRED_SDOS)
def test_labels_is_required_for_sdos_that_require_it(sdo_class, required_kwargs):
    with pytest.raises(ValueError) as excinfo:
        sdo_class(**required_kwargs)

    assert "labels" in str(excinfo.value)


@pytest.mark.parametrize("sdo_class, required_kwargs", LABELS_REQUIRED_SDOS)
def test_empty_labels_does_not_satisfy_a_required_labels_property(
    sdo_class, required_kwargs
):
    """An empty list is equivalent to omitting this required property."""
    with pytest.raises(ValueError) as excinfo:
        sdo_class(labels=[], **required_kwargs)

    assert "labels" in str(excinfo.value)


@pytest.mark.parametrize("sdo_class, required_kwargs", LABELS_REQUIRED_SDOS)
def test_required_labels_accepts_and_preserves_nonempty_values(
    sdo_class, required_kwargs
):
    labels = ["malicious-activity", "second-label"]

    obj = sdo_class(labels=labels, **required_kwargs)

    assert obj.labels == labels
    assert obj["labels"] == labels


def test_labels_remains_optional_where_the_sdo_does_not_require_it():
