from typing import Optional

import serde


def test_coerce_tuple_field_roundtrip() -> None:
    """Regression test for quote escaping in generated tuple coercion code."""

    @serde.serde(type_check=serde.coerce)
    class Foo:
        loc: tuple[float, float]

    # Constructing and serializing the object is the example from the issue.
    foo = Foo(loc=(1, 2))
    assert serde.to_dict(foo) == {"loc": (1.0, 2.0)}
    assert serde.to_tuple(foo) == ((1.0, 2.0),)

    # Deserialization must not merely avoid the SyntaxError; tuple elements
    # must still be coerced to their declared types.
    from_mapping = serde.from_dict(Foo, {"loc": ("1.25", 2)})
    assert from_mapping.loc == (1.25, 2.0)
    assert all(type(value) is float for value in from_mapping.loc)

    # Iterator-based deserialization uses different generated expressions and
    # should continue to work as well.
    from_iter = serde.from_tuple(Foo, (("3.5", 4),))
    assert from_iter.loc == (3.5, 4.0)
    assert all(type(value) is float for value in from_iter.loc)


def test_coerce_nested_tuple_fields() -> None:
    """Every quoted data expression in nested tuples must be escaped."""

    @serde.serde(type_check=serde.coerce)
    class NestedTuples:
        matrix: tuple[tuple[int, int], tuple[int, int]]
        label_and_count: tuple[str, int]

    value = serde.from_dict(
        NestedTuples,
        {
            "matrix": [["1", "2"], ["3", 4]],
            "label_and_count": [5, "6"],
        },
    )

    assert value.matrix == ((1, 2), (3, 4))
    assert value.label_and_count == ("5", 6)
    assert serde.to_dict(value) == {
        "matrix": ((1, 2), (3, 4)),
        "label_and_count": ("5", 6),
    }


def test_coerce_optional_tuple_field() -> None:
    """Optional tuples use the same quoted dictionary-access expressions."""

    @serde.serde(type_check=serde.coerce)
    class OptionalLocation:
        loc: Optional[tuple[float, float]]

    present = serde.from_dict(OptionalLocation, {"loc": ["1.5", 2]})
    assert present.loc == (1.5, 2.0)
    assert all(type(value) is float for value in present.loc)
    assert serde.to_dict(present) == {"loc": (1.5, 2.0)}

    missing = serde.from_dict(OptionalLocation, {})
    assert missing.loc is None
    assert serde.to_dict(missing) == {"loc": None}

