sys.path.insert(0, str(PYDEVD_ROOT))

from _pydevd_bundle.pydevd_resolver import (  # noqa: E402
    MAX_ITEMS_TO_HANDLE,
    defaultResolver,
    tupleResolver,
)
from _pydevd_bundle.pydevd_xml import get_type  # noqa: E402


def _get_variables(value):
    _, _, resolver = get_type(value)
    return resolver, resolver.get_dictionary(value)


def _indexed_items(variables):
    return {
        int(key): value
        for key, value in variables.items()
        if isinstance(key, str) and key.isdigit()
    }


def test_ctypes_array_from_buffer_is_enumerated_like_the_issue_example():
    file_bytes = bytearray(b"\x01\x02\x03\x04\x05")
    array = (ctypes.c_uint8 * len(file_bytes)).from_buffer(file_bytes)

    resolver, variables = _get_variables(array)

    assert resolver is not defaultResolver
    assert variables["len()"] == len(file_bytes)
    assert _indexed_items(variables) == {
        0: 1,
        1: 2,
        2: 3,
        3: 4,
        4: 5,
    }

    # Enumerating children is not sufficient: the debugger must also be able
    # to retrieve an individual child using its displayed attribute name.
    for index, expected in enumerate(file_bytes):
        assert resolver.resolve(array, str(index)) == expected


@pytest.mark.parametrize(
    ("array", "expected"),
    [
        ((ctypes.c_int * 4)(10, -20, 30, -40), [10, -20, 30, -40]),
        ((ctypes.c_double * 3)(1.5, -2.25, 0.0), [1.5, -2.25, 0.0]),
        ((ctypes.c_char * 3)(b"a", b"b", b"c"), [b"a", b"b", b"c"]),
    ],
)
def test_different_ctypes_array_element_types_are_enumerated(array, expected):
    resolver, variables = _get_variables(array)

    assert resolver is not defaultResolver
    assert variables["len()"] == len(expected)
    assert _indexed_items(variables) == dict(enumerate(expected))


def test_empty_ctypes_array_has_zero_length_and_no_indexed_children():
    array = (ctypes.c_int * 0)()

    resolver, variables = _get_variables(array)

    assert resolver is not defaultResolver
    assert variables["len()"] == 0
    assert _indexed_items(variables) == {}


def test_user_defined_ctypes_array_subclass_is_enumerated():
    class CustomIntArray(ctypes.c_int * 3):
        pass

    array = CustomIntArray(7, 8, 9)

    resolver, variables = _get_variables(array)

    assert resolver is not defaultResolver
    assert variables["len()"] == 3
    assert _indexed_items(variables) == {0: 7, 1: 8, 2: 9}


def test_large_ctypes_array_reports_full_length_and_enumerates_a_bounded_prefix():
    size = MAX_ITEMS_TO_HANDLE + 25
    array = (ctypes.c_int * size)()
    for index in range(size):
        array[index] = index - 10

    resolver, variables = _get_variables(array)
    indexed = _indexed_items(variables)

    assert resolver is not defaultResolver
    assert variables["len()"] == size

    # The debugger may truncate a large container, but the entries it does
    # expose must be real, contiguous array elements rather than attributes.
    assert indexed
    assert len(indexed) < size
    assert set(indexed) == set(range(len(indexed)))
    assert all(value == index - 10 for index, value in indexed.items())


