    MAX_ITEMS_TO_HANDLE,
    TOO_LARGE_ATTR,
    TOO_LARGE_MSG,
)
from _pydevd_bundle.pydevd_xml import get_type


def _get_variables(value):
    """Return the resolver and children used to populate the variables view."""
    _type_object, _type_name, resolver = get_type(value)
    assert resolver is not None
    return resolver, resolver.get_dictionary(value)


def _indexed_elements(variables):
    return {
        name: value
        for name, value in variables.items()
        if isinstance(name, str) and name.isdigit()
    }


def test_ctypes_array_from_buffer_is_enumerated_like_the_issue_example():
    file_bytes = bytearray(b"\x00\x01\x7f\x80\xff")
    array = (ctypes.c_uint8 * len(file_bytes)).from_buffer(file_bytes)

    resolver, variables = _get_variables(array)

    expected = {str(index): value for index, value in enumerate(file_bytes)}
    assert _indexed_elements(variables) == expected
    assert variables["len()"] == len(file_bytes)

    # Enumerated children must also be retrievable when the debugger expands or
    # subsequently asks for an individual array element.
    for name, expected_value in expected.items():
        assert resolver.resolve(array, name) == expected_value


@pytest.mark.parametrize(
    ("array", "expected"),
    [
        pytest.param(
            (ctypes.c_int * 4)(-7, 0, 11, 42),
            [-7, 0, 11, 42],
            id="signed-integers",
        ),
        pytest.param(
            (ctypes.c_uint16 * 3)(0, 32768, 65535),
            [0, 32768, 65535],
            id="unsigned-integers",
        ),
        pytest.param(
            (ctypes.c_double * 3)(-1.25, 0.0, 3.5),
            [-1.25, 0.0, 3.5],
            id="floating-point",
        ),
        pytest.param(
            (ctypes.c_char * 3)(b"x", b"y", b"z"),
            [b"x", b"y", b"z"],
            id="characters",
        ),
    ],
)
def test_different_ctypes_array_element_types_are_enumerated(array, expected):
    _resolver, variables = _get_variables(array)

    assert variables["len()"] == len(expected)
    assert _indexed_elements(variables) == {
        str(index): value for index, value in enumerate(expected)
    }


def test_empty_ctypes_array_has_zero_length_and_no_indexed_children():
    array = (ctypes.c_int * 0)()

    _resolver, variables = _get_variables(array)

    assert variables["len()"] == 0
    assert _indexed_elements(variables) == {}


def test_user_defined_ctypes_array_subclass_is_enumerated():
    class CustomArray(ctypes.c_int * 3):
        pass

    array = CustomArray(8, 9, 10)

    _resolver, variables = _get_variables(array)

    assert variables["len()"] == 3
    assert _indexed_elements(variables) == {"0": 8, "1": 9, "2": 10}


def test_nested_ctypes_arrays_are_enumerated_recursively():
    inner_type = ctypes.c_int * 2
    outer_type = inner_type * 2
    array = outer_type()
    array[0][0], array[0][1] = 1, 2
    array[1][0], array[1][1] = 3, 4

    _resolver, outer_variables = _get_variables(array)
    outer_elements = _indexed_elements(outer_variables)

    assert outer_variables["len()"] == 2
    assert set(outer_elements) == {"0", "1"}

    for index, expected in enumerate(([1, 2], [3, 4])):
        inner_array = outer_elements[str(index)]
        assert isinstance(inner_array, ctypes.Array)

        _inner_resolver, inner_variables = _get_variables(inner_array)
        assert inner_variables["len()"] == 2
        assert _indexed_elements(inner_variables) == {
            "0": expected[0],
            "1": expected[1],
        }


def test_large_ctypes_array_reports_full_length_and_uses_debugger_limit():
    size = MAX_ITEMS_TO_HANDLE + 7
    array = (ctypes.c_int * size)()
    for index in range(size):
        array[index] = index

    _resolver, variables = _get_variables(array)

    # Match the established tuple/list debugger contract for oversized
    # containers: retain the real length and explicitly mark the contents as
    # too large instead of attempting to enumerate every child.
    assert variables["len()"] == size
    assert variables[TOO_LARGE_ATTR] == TOO_LARGE_MSG
    assert _indexed_elements(variables) == {}


def test_non_array_ctypes_objects_keep_normal_field_resolution():
    simple_int = ctypes.c_int(42)
    _resolver, simple_variables = _get_variables(simple_int)
    assert simple_variables["value"] == 42
    assert "len()" not in simple_variables
    assert _indexed_elements(simple_variables) == {}

    class Point(ctypes.Structure):
        _fields_ = [("x", ctypes.c_int), ("y", ctypes.c_int)]

    point = Point(3, 9)
    _resolver, point_variables = _get_variables(point)
    assert point_variables["x"] == 3
    assert point_variables["y"] == 9
    assert "len()" not in point_variables
    assert _indexed_elements(point_variables) == {}


def test_regular_python_containers_are_not_changed():
    regular_list = [4, 5, 6]
    list_resolver, list_variables = _get_variables(regular_list)
    assert list_resolver.__class__.__name__ != "CTypesArrayResolveProvider"
    assert list_variables["len()"] == 3
    assert _indexed_elements(list_variables) == {"0": 4, "1": 5, "2": 6}

    regular_dict = {"answer": 42}
    dict_resolver, dict_variables = _get_variables(regular_dict)
    assert dict_resolver.__class__.__name__ != "CTypesArrayResolveProvider"
    # Dictionary child names may be formatted for display; its contents must
    # nevertheless remain available rather than being treated as an array.
    assert 42 in dict_variables.values()
    assert _indexed_elements(dict_variables) == {}

import pytest

from ansible_builder.introspect import process
from ansible_builder.requirements import sanitize_requirements


def test_introspect_sanitize_preserves_user_pip_requirements(tmp_path):
    """The introspect --sanitize data path must not discard user lint tools."""
    requirements_file = tmp_path / "requirements.txt"
    requirements_file.write_text(
        "yamllint>=6.0\nansible-lint\n",
        encoding="utf-8",
    )

    introspected = process(str(tmp_path), user_pip=str(requirements_file))

    assert sanitize_requirements(introspected["python"]) == [
        "yamllint>=6.0  # from collection user",
        "ansible-lint  # from collection user",
    ]


def test_sanitize_preserves_excluded_packages_explicitly_requested_by_user():
    """User requirements bypass exclusions generally, not just for one package."""
    assert sanitize_requirements({
        "user": [
            "yamllint",
            "ansible-lint==6.8.0",
            "pytest>=7",
        ],
    }) == [
        "yamllint  # from collection user",
        "ansible-lint==6.8.0  # from collection user",
        "pytest>=7  # from collection user",
    ]


def test_sanitize_still_excludes_lint_tools_required_only_by_collections():
    """The fix must not disable dependency filtering for collection metadata."""
    assert sanitize_requirements({
        "foo.bar": [
            "yamllint",
            "ansible-lint",
            "requests>=2",
        ],
    }) == [
        "requests>=2  # from collection foo.bar",
    ]


@pytest.mark.parametrize(
    ("requirements_by_source", "expected"),
    [
        (
            {
                "foo.bar": ["yamllint>=6"],
                "user": ["yamllint<7"],
            },
            ["yamllint>=6,<7  # from collection foo.bar,user"],
        ),
        (
            {
                "user": ["ansible-lint>=6"],
                "foo.bar": ["ansible-lint<7"],
            },
            ["ansible-lint>=6,<7  # from collection user,foo.bar"],
        ),
    ],
)
def test_sanitize_retains_user_requirement_when_collection_also_requests_it(
    requirements_by_source,
    expected,
):
    """De-duplication must retain user provenance regardless of source order."""
    assert sanitize_requirements(requirements_by_source) == expected

import io
from pprint import pformat, pprint

import pytest

from baseclasses.utils import CaseInsensitiveDict, CaseInsensitiveSet


ISSUE_DATA = {
    "b-longstring": 2,
    "a-longstring": 1,
    "c-longstring": 3,
    "e-longstring": 5,
    "d-longstring": 4,
}

LONG_SET_ITEMS = {
    "b-long-string-that-forces-line-breaks",
    "a-long-string-that-forces-line-breaks",
    "c-long-string-that-forces-line-breaks",
    "e-long-string-that-forces-line-breaks",
    "d-long-string-that-forces-line-breaks",
}


def pprint_to_string(obj, **kwargs):
    stream = io.StringIO()
    pprint(obj, stream=stream, **kwargs)
    return stream.getvalue()


def test_issue_dict_example_has_exact_builtin_formatting():
    insensitive = CaseInsensitiveDict(ISSUE_DATA)

    expected = (
        "{'a-longstring': 1,\n"
        " 'b-longstring': 2,\n"
        " 'c-longstring': 3,\n"
        " 'd-longstring': 4,\n"
        " 'e-longstring': 5}\n"
    )

    assert pprint_to_string(ISSUE_DATA) == expected
    assert pprint_to_string(insensitive) == expected


@pytest.mark.parametrize(
    "printer_kwargs",
    [
        {"width": 80},
        {"width": 40},
        {"width": 45, "indent": 2},
        {"width": 60, "compact": True},
    ],
)
def test_dict_pformat_matches_builtin_when_wrapping(printer_kwargs):
    insensitive = CaseInsensitiveDict(ISSUE_DATA)

    expected = pformat(ISSUE_DATA, **printer_kwargs)
    actual = pformat(insensitive, **printer_kwargs)

    # These settings must exercise pprint's multiline formatter rather than
    # merely accepting the container's one-line repr.
    assert "\n" in expected
    assert actual == expected


@pytest.mark.parametrize("width", [20, 40, 80])
def test_set_pformat_matches_builtin_when_wrapping(width):
    insensitive = CaseInsensitiveSet(LONG_SET_ITEMS)

    expected = pformat(LONG_SET_ITEMS, width=width)
    actual = pformat(insensitive, width=width)

    assert "\n" in expected
    assert actual == expected
    # In particular, multiline output must not acquire a
    # "CaseInsensitiveSet(...)" wrapper that is absent from repr(insensitive).
    assert "CaseInsensitiveSet(" not in actual


def test_set_pprint_output_matches_builtin():
    insensitive = CaseInsensitiveSet(LONG_SET_ITEMS)

    expected = pprint_to_string(LONG_SET_ITEMS, width=40)
    actual = pprint_to_string(insensitive, width=40)

    assert "\n" in expected
    assert actual == expected


@pytest.mark.parametrize(
    "container_type,builtin,expected",
    [
        (CaseInsensitiveDict, {}, "{}"),
        (CaseInsensitiveSet, set(), "set()"),
    ],
)
def test_empty_containers_match_builtin(container_type, builtin, expected):
    container = container_type()

    assert pformat(container) == expected
    assert pformat(container) == pformat(builtin)


@pytest.mark.parametrize("width", [10, 80])
def test_single_element_containers_match_builtin(width):
    regular_dict = {"MiXeDCaseKey": "a value"}
    regular_set = {"MiXeDCaseElement"}

    assert pformat(CaseInsensitiveDict(regular_dict), width=width) == pformat(
        regular_dict, width=width
    )
    assert pformat(CaseInsensitiveSet(regular_set), width=width) == pformat(
        regular_set, width=width
    )


@pytest.mark.parametrize("width", [45, 80])
def test_nested_case_insensitive_containers_match_builtin(width):
    inner = {
        "BetaKey": 2,
        "AlphaKey": 1,
        "GammaKey": 3,
    }
    regular = {
        "OuterOptions": inner,
        "StringChoices": LONG_SET_ITEMS,
    }
    insensitive = CaseInsensitiveDict(
        {
            "OuterOptions": CaseInsensitiveDict(inner),
            "StringChoices": CaseInsensitiveSet(LONG_SET_ITEMS),
        }
    )

    expected = pformat(regular, width=width)
    actual = pformat(insensitive, width=width)

    assert "\n" in expected
    assert actual == expected
    # Formatting must preserve the original capitalization of keys and items.
    assert "OuterOptions" in actual
    assert "AlphaKey" in actual

import json

import pytest

import stix2
from stix2.exceptions import InvalidValueError, MissingFieldsError


OPTIONAL_LABEL_SDOS = [
    (stix2.AttackPattern, {"name": "Test Attack Pattern"}),
    (stix2.Campaign, {"name": "Test Campaign"}),
    (stix2.CourseOfAction, {"name": "Test Course of Action"}),
    (stix2.Identity, {"name": "Test Identity", "identity_class": "individual"}),
    (stix2.IntrusionSet, {"name": "Test Intrusion Set"}),
    (
        stix2.ObservedData,
        {
            "first_observed": "2016-04-06T20:06:37.000Z",
            "last_observed": "2016-04-06T20:06:37.000Z",
            "number_observed": 1,
            "objects": {},
        },
    ),
    (stix2.Vulnerability, {"name": "Test Vulnerability"}),
]

REQUIRED_LABEL_SDOS = [
    (
        stix2.Indicator,
        {"pattern": "[file:hashes.MD5 = 'd41d8cd98f00b204e9800998ecf8427e']"},
    ),
    (stix2.Malware, {"name": "Test Malware"}),
    (
        stix2.Report,
        {"name": "Test Report", "published": "2016-04-06T20:06:37.000Z"},
    ),
    (stix2.ThreatActor, {"name": "Test Threat Actor"}),
    (stix2.Tool, {"name": "Test Tool"}),
]


def _object_id(value):
    return getattr(value, "__name__", "")


@pytest.mark.parametrize(
    "cls,kwargs", OPTIONAL_LABEL_SDOS, ids=_object_id
)
def test_labels_are_optional_common_properties_on_sdos(cls, kwargs):
    """SDOs without a type-specific requirement may omit or supply labels."""
    without_labels = cls(**kwargs)
    assert "labels" not in without_labels
    assert "labels" not in json.loads(str(without_labels))

    labels = ["test-label", "another-label"]
    with_labels = cls(labels=labels, **kwargs)
    assert with_labels.labels == labels
    assert with_labels["labels"] == labels
    assert json.loads(str(with_labels))["labels"] == labels


@pytest.mark.parametrize(
    "cls,kwargs", REQUIRED_LABEL_SDOS, ids=_object_id
)
def test_type_specific_label_requirements_are_preserved(cls, kwargs):
    """Making labels a common property must not make them optional everywhere."""
    with pytest.raises(MissingFieldsError) as exc_info:
        cls(**kwargs)
    assert exc_info.value.fields == ["labels"]

    obj = cls(labels=["test-label"], **kwargs)
    assert obj.labels == ["test-label"]


@pytest.mark.parametrize(
    "cls,kwargs",
    [
        (
            stix2.Relationship,
            {
                "relationship_type": "indicates",
                "source_ref": "indicator--00000000-0000-0000-0000-000000000000",
                "target_ref": "attack-pattern--00000000-0000-0000-0000-000000000001",
            },
        ),
        (
            stix2.Sighting,
            {
                "sighting_of_ref": "indicator--00000000-0000-0000-0000-000000000000",
            },
        ),
    ],
    ids=_object_id,
)
def test_labels_are_optional_on_other_objects_using_common_properties(cls, kwargs):
    without_labels = cls(**kwargs)
    assert "labels" not in without_labels

    with_labels = cls(labels=["test-label"], **kwargs)
    assert with_labels.labels == ["test-label"]


@pytest.mark.parametrize("invalid_labels", ["not-a-list", [1]])
@pytest.mark.parametrize(
    "cls,kwargs",
    [
        (stix2.AttackPattern, {"name": "Test Attack Pattern"}),
        (
            stix2.Identity,
            {"name": "Test Identity", "identity_class": "individual"},
        ),
    ],
    ids=_object_id,
)
def test_optional_common_labels_are_validated_when_parsing(
    cls, kwargs, invalid_labels
):
    """Inherited labels must retain the normal list-of-strings validation."""
    data = json.loads(str(cls(**kwargs)))
    data["labels"] = invalid_labels

    with pytest.raises(InvalidValueError):
        stix2.parse(json.dumps(data))


def test_optional_labels_survive_serialization_and_parsing():
    attack_pattern = stix2.AttackPattern(
        name="Test Attack Pattern",
        labels=["test-label"],
    )

    parsed = stix2.parse(str(attack_pattern))

    assert isinstance(parsed, stix2.AttackPattern)
    assert parsed.labels == ["test-label"]

import asyncio
import time

import pytest

from anyio.to_thread import run_sync


def _echo(value):
    time.sleep(0.01)
    return value


def _fail():
    time.sleep(0.01)
    raise ValueError("worker failure")


def _run_top_level(loop, awaitable):
    """Run one top-level await, with a timeout so a regression cannot hang pytest."""
    return loop.run_until_complete(asyncio.wait_for(awaitable, timeout=3))


@pytest.fixture
def persistent_event_loop():
    loop = asyncio.new_event_loop()
    asyncio.set_event_loop(loop)
    try:
        yield loop
    finally:
        for task in asyncio.all_tasks(loop):
            task.cancel()
        loop.close()
        asyncio.set_event_loop(None)


def test_successive_top_level_run_sync_calls(persistent_event_loop):
    """Each run_until_complete() call represents a separate IPython input cell."""
    for value in range(4):
        result = _run_top_level(persistent_event_loop, run_sync(_echo, value))
        assert result == value


def test_top_level_run_sync_after_worker_exception(persistent_event_loop):
    with pytest.raises(ValueError, match="worker failure"):
        _run_top_level(persistent_event_loop, run_sync(_fail))

    # A failed top-level task must not leave a worker tied to that dead task for
    # subsequent top-level awaits.
    assert _run_top_level(
        persistent_event_loop, run_sync(_echo, "after exception")
    ) == "after exception"
    assert _run_top_level(
        persistent_event_loop, run_sync(_echo, "final call")
    ) == "final call"


def test_run_sync_reuse_within_one_top_level_task(persistent_event_loop):
    """Sequential and concurrent calls in a normal task must continue to work."""

    async def main():
        assert await run_sync(_echo, "first") == "first"
        assert await run_sync(_echo, "second") == "second"

        results = await asyncio.gather(
            *(run_sync(_echo, value) for value in range(4))
        )
        assert results == list(range(4))

    _run_top_level(persistent_event_loop, main())

import pandas as pd
import polars as pl
import pytest

import narwhals as nw


@pytest.fixture(params=["pandas", "polars"])
def backend(request):
    return request.param


def make_float_series(backend, values):
    if backend == "pandas":
        return pd.Series(values, dtype="float64")
    return pl.Series(values, dtype=pl.Float64)


def make_float_dataframe(backend, values):
    if backend == "pandas":
        return pd.DataFrame({"a": pd.Series(values, dtype="float64")})
    return pl.DataFrame({"a": pl.Series(values, dtype=pl.Float64)})


def first_row(native_df):
    if isinstance(native_df, pd.DataFrame):
        return native_df.iloc[0].to_dict()
