from __future__ import annotations

from typing import Any

import pandas as pd
import polars as pl
import pytest

import narwhals as nw


def make_series(backend: str, values: list[Any]) -> Any:
    if backend == "pandas":
        return pd.Series(values, dtype="float64")
    return pl.Series("a", values, dtype=pl.Float64)


def make_frame(backend: str, values: list[Any]) -> Any:
    series = make_series(
        "pandas" if backend == "pandas" else "polars", values
    )
    frame = (
        pd.DataFrame({"a": series})
        if backend == "pandas"
        else pl.DataFrame({"a": series})
    )
    if backend == "polars-lazy":
        return frame.lazy()
    return frame


def collect_scalar(result: Any, column: str = "a") -> Any:
    if isinstance(result, nw.LazyFrame):
        result = result.collect()
    return result[column][0]


@pytest.mark.parametrize("backend", ["pandas", "polars"])
@pytest.mark.parametrize(
    ("values", "expected"),
    [
        ([1.0, None, None, 2.0], 2),  # Reproduction from the issue.
        ([None, 1.0, 1.0, None, 2.0], 2),
        ([None, None, None], 0),
        ([], 0),
        ([1.0, 1.0, 2.0, 2.0], 2),  # Behavior without nulls must be unchanged.
    ],
)
def test_series_n_unique_excludes_nulls(
    backend: str, values: list[Any], expected: int
) -> None:
    series = nw.from_native(make_series(backend, values), series_only=True)

    assert series.n_unique() == expected


@pytest.mark.parametrize("backend", ["pandas", "polars", "polars-lazy"])
@pytest.mark.parametrize(
    ("values", "expected"),
    [
        ([1.0, None, None, 2.0], 2),
        ([None, 1.0, 1.0, None, 2.0], 2),
        ([None, None, None], 0),
        ([1.0, 1.0, 2.0, 2.0], 2),
    ],
)
def test_expression_n_unique_excludes_nulls(
    backend: str, values: list[Any], expected: int
) -> None:
    frame = nw.from_native(make_frame(backend, values))

    result = frame.select(nw.col("a").n_unique())

    assert collect_scalar(result) == expected


@pytest.mark.parametrize("backend", ["pandas", "polars", "polars-lazy"])
def test_expression_n_unique_handles_each_column_independently(
    backend: str,
) -> None:
    native_frame = make_frame(backend, [1.0, None, None, 2.0])
    if backend == "pandas":
        native_frame["b"] = pd.Series(
            [None, 1.0, 1.0, None], dtype="float64"
        )
        native_frame["c"] = pd.Series([None] * 4, dtype="float64")
    else:
        native_frame = native_frame.with_columns(
            pl.Series("b", [None, 1.0, 1.0, None], dtype=pl.Float64),
            pl.Series("c", [None] * 4, dtype=pl.Float64),
        )
    frame = nw.from_native(native_frame)

    result = frame.select(nw.col("a", "b", "c").n_unique())
    if isinstance(result, nw.LazyFrame):
        result = result.collect()

    assert result["a"][0] == 2
    assert result["b"][0] == 1
    assert result["c"][0] == 0


@pytest.mark.parametrize("backend", ["pandas", "polars", "polars-lazy"])
def test_n_unique_null_filtering_happens_after_earlier_expressions(
    backend: str,
) -> None:
    frame = nw.from_native(make_frame(backend, [1.0, None, None, 2.0]))

    # Filling nulls introduces a third distinct value, which must be counted.
    result = frame.select(nw.col("a").fill_null(3.0).n_unique())

    assert collect_scalar(result) == 3

import os
import warnings
from unittest import mock

import pytest

from lektor.context import Context
from lektor.imagetools import make_image_thumbnail
from lektor.imagetools import ThumbnailMode


SOURCE_URL_PATH = "test.jpg"
SOURCE_DIMENSIONS = (384, 512)


class DummyContext:
    def __init__(self):
        self.sub_artifacts = []

    def sub_artifact(self, **kwargs):
        def decorate(f):
            self.add_sub_artifact(build_func=f, **kwargs)
            return f

        return decorate

    def add_sub_artifact(self, **kwargs):
        self.sub_artifacts.append(kwargs)


@pytest.fixture
def ctx():
    return DummyContext()


@pytest.fixture
def test_jpg(project):
    return os.path.join(project.tree, "content", "test.jpg")


def make_thumbnail_without_warnings(ctx, source_image, **kwargs):
    with warnings.catch_warnings():
        warnings.simplefilter("error")
        return make_image_thumbnail(
            ctx, source_image, SOURCE_URL_PATH, **kwargs
        )


def test_image_thumbnail_rejects_removed_crop_argument(pad):
    image = pad.root.attachments.images.get("test.jpg")

    with mock.patch("lektor.db.make_image_thumbnail") as make_thumbnail:
        with Context(pad=pad):
            with pytest.raises(TypeError, match="crop"):
                image.thumbnail(width=100, crop=True)

    make_thumbnail.assert_not_called()


@pytest.mark.parametrize(
    "dimensions",
    [
        pytest.param({"width": 512}, id="width-only"),
        pytest.param({"height": 1024}, id="height-only"),
        pytest.param(
            {"width": 512, "height": 1024}, id="width-and-height"
        ),
    ],
)
def test_fit_thumbnail_does_not_upscale_by_default(
    ctx, test_jpg, dimensions
):
    thumbnail = make_thumbnail_without_warnings(
        ctx, test_jpg, **dimensions
    )

    # The original image is returned instead of scheduling an upscaled artifact.
    assert (thumbnail.width, thumbnail.height) == SOURCE_DIMENSIONS
    assert thumbnail.url_path == SOURCE_URL_PATH
    assert ctx.sub_artifacts == []


def test_fit_thumbnail_can_still_be_explicitly_upscaled(ctx, test_jpg):
    thumbnail = make_thumbnail_without_warnings(
        ctx, test_jpg, width=512, upscale=True
    )

    assert (thumbnail.width, thumbnail.height) == (512, 683)
    assert thumbnail.url_path == "test@512.jpg"
    assert len(ctx.sub_artifacts) == 1


@pytest.mark.parametrize(
    "width, expected_dimensions",
    [
        (192, (192, 256)),  # Ordinary downscaling is unaffected.
        (384, (384, 512)),  # Same-size output is not upscaling.
    ],
)
def test_fit_thumbnail_still_builds_non_upscaled_images(
    ctx, test_jpg, width, expected_dimensions
):
    thumbnail = make_thumbnail_without_warnings(ctx, test_jpg, width=width)

    assert (thumbnail.width, thumbnail.height) == expected_dimensions
    assert thumbnail.url_path == f"test@{width}.jpg"
    assert len(ctx.sub_artifacts) == 1


@pytest.mark.parametrize(
    "mode", [ThumbnailMode.CROP, ThumbnailMode.STRETCH]
)
def test_crop_and_stretch_modes_still_upscale_by_default(
    ctx, test_jpg, mode
):
    thumbnail = make_thumbnail_without_warnings(
        ctx, test_jpg, width=512, height=512, mode=mode
    )

    assert (thumbnail.width, thumbnail.height) == (512, 512)
    assert thumbnail.url_path == f"test@512x512_{mode.value}.jpg"
    assert len(ctx.sub_artifacts) == 1


@pytest.mark.parametrize("mode", list(ThumbnailMode))
def test_explicit_upscale_false_is_respected_for_every_mode(
    ctx, test_jpg, mode
):
    thumbnail = make_thumbnail_without_warnings(
        ctx,
        test_jpg,
        width=4096,
        height=4069,
        mode=mode,
        upscale=False,
    )

    assert (thumbnail.width, thumbnail.height) == SOURCE_DIMENSIONS
