from __future__ import annotations

from typing import Any

import pandas as pd
import polars as pl
import pytest

import narwhals as nw


N_UNIQUE_CASES = [
    pytest.param([1.0, None, None, 2.0], 2, id="issue-example"),
    pytest.param([None, 1.0, 1.0, None], 1, id="one-distinct-non-null"),
    pytest.param([None, None, None], 0, id="all-null"),
    pytest.param([1.0, 1.0, 2.0, 2.0], 2, id="no-nulls"),
    pytest.param([], 0, id="empty"),
]


def make_series(backend: str, values: list[Any]) -> Any:
    if backend == "pandas":
        return pd.Series(values, dtype="float64", name="a")
    if backend == "pandas-nullable":
        return pd.Series(values, dtype="Float64", name="a")
    if backend == "polars":
        return pl.Series("a", values)
    raise AssertionError(f"Unexpected backend: {backend}")


def make_frame(backend: str, values: list[Any]) -> Any:
    if backend == "pandas":
        return pd.DataFrame({"a": pd.Series(values, dtype="float64")})
    if backend == "pandas-nullable":
        return pd.DataFrame({"a": pd.Series(values, dtype="Float64")})
    if backend == "polars":
        return pl.DataFrame({"a": values})
    if backend == "polars-lazy":
        return pl.LazyFrame({"a": values})
    raise AssertionError(f"Unexpected backend: {backend}")


@pytest.mark.parametrize("backend", ["pandas", "pandas-nullable", "polars"])
@pytest.mark.parametrize(("values", "expected"), N_UNIQUE_CASES)
def test_series_n_unique_excludes_nulls(
    backend: str, values: list[Any], expected: int
) -> None:
    native = make_series(backend, values)
    series = nw.from_native(native, series_only=True)

    assert series.n_unique() == expected


@pytest.mark.parametrize(
    "backend", ["pandas", "pandas-nullable", "polars", "polars-lazy"]
)
@pytest.mark.parametrize(("values", "expected"), N_UNIQUE_CASES)
def test_expression_n_unique_excludes_nulls(
    backend: str, values: list[Any], expected: int
) -> None:
    if not values and backend in {"pandas", "pandas-nullable"}:
        # Selecting a scalar result on an empty pandas frame raises while trying
        # to broadcast the scalar to its zero-length index, independently of
        # n_unique's null-counting behavior.
        pytest.skip("Scalar selection on an empty pandas frame is unsupported")

    native = make_frame(backend, values)
    frame = nw.from_native(native)

    result = frame.select(nw.col("a").n_unique())
    if isinstance(result, nw.LazyFrame):
        result = result.collect()

    assert result["a"][0] == expected


@pytest.mark.parametrize("backend", ["pandas", "polars"])
def test_n_unique_excludes_nulls_for_non_numeric_values(backend: str) -> None:
    values = ["a", None, "a", "b", None]
    native_series = (
        pd.Series(values, name="a")
        if backend == "pandas"
        else pl.Series("a", values)
    )
    native_frame = (
        pd.DataFrame({"a": values})
        if backend == "pandas"
        else pl.DataFrame({"a": values})
    )

    series_result = nw.from_native(native_series, series_only=True).n_unique()
    frame_result = nw.from_native(native_frame).select(nw.col("a").n_unique())

    assert series_result == 2
    assert frame_result["a"][0] == 2

import os
import warnings

import pytest

from lektor.imagetools import make_image_thumbnail
from lektor.imagetools import ThumbnailMode


class DummyContext:
    """Records thumbnail artifacts without invoking ImageMagick."""

    def __init__(self):
        self.sub_artifacts = []

    def sub_artifact(self, **kwargs):
        def decorate(build_func):
            self.sub_artifacts.append({"build_func": build_func, **kwargs})
            return build_func

        return decorate


@pytest.fixture
def ctx():
    return DummyContext()


@pytest.fixture
def test_jpg(project):
    return os.path.join(project.tree, "content", "test.jpg")


@pytest.fixture
def source_url_path():
    return "test.jpg"


@pytest.mark.parametrize("crop", [True, False])
def test_image_thumbnail_rejects_removed_crop_argument(pad, crop):
    image = pad.root.attachments.images.get("test.jpg")
    assert image is not None

    with pytest.raises(TypeError, match="crop"):
        image.thumbnail(width=100, crop=crop)


@pytest.mark.parametrize(
    "dimensions",
    [
        pytest.param({"width": 512}, id="width-only"),
        pytest.param({"height": 1024}, id="height-only"),
        pytest.param({"width": 768, "height": 1024}, id="width-and-height"),
    ],
)
def test_oversized_fit_thumbnail_does_not_implicitly_upscale(
    ctx, test_jpg, source_url_path, dimensions
):
    # The source image is 384 x 512. An oversized request with no explicit
    # upscale argument must return the source image, without a warning or a
    # thumbnail artifact.
    with warnings.catch_warnings():
        warnings.simplefilter("error")
        thumbnail = make_image_thumbnail(
            ctx, test_jpg, source_url_path, **dimensions
        )

    assert (thumbnail.width, thumbnail.height) == (384, 512)
    assert thumbnail.url_path == source_url_path
    assert ctx.sub_artifacts == []


def test_explicit_upscale_true_still_creates_upscaled_thumbnail(
    ctx, test_jpg, source_url_path
):
    with warnings.catch_warnings():
        warnings.simplefilter("error")
        thumbnail = make_image_thumbnail(
            ctx, test_jpg, source_url_path, width=512, upscale=True
        )

    assert (thumbnail.width, thumbnail.height) == (512, 683)
    assert thumbnail.url_path == "test@512.jpg"
    assert len(ctx.sub_artifacts) == 1
    assert ctx.sub_artifacts[0]["artifact_name"] == "test@512.jpg"


@pytest.mark.parametrize("mode", list(ThumbnailMode))
def test_explicit_upscale_false_returns_source_for_every_mode(
    ctx, test_jpg, source_url_path, mode
):
    thumbnail = make_image_thumbnail(
        ctx,
        test_jpg,
        source_url_path,
        width=4096,
        height=4069,
        mode=mode,
        upscale=False,
    )

    assert (thumbnail.width, thumbnail.height) == (384, 512)
    assert thumbnail.url_path == source_url_path
    assert ctx.sub_artifacts == []


@pytest.mark.parametrize("mode", [ThumbnailMode.CROP, ThumbnailMode.STRETCH])
def test_crop_and_stretch_retain_their_explicit_size_behavior(
    ctx, test_jpg, source_url_path, mode
):
    # Crop and stretch require both dimensions and intentionally upscale by
    # default. Disabling deprecated implicit FIT upscaling must not break them.
    with warnings.catch_warnings():
        warnings.simplefilter("error")
        thumbnail = make_image_thumbnail(
            ctx,
            test_jpg,
            source_url_path,
            width=512,
            height=512,
            mode=mode,
        )

    expected_url = f"test@512x512_{mode.value}.jpg"
    assert (thumbnail.width, thumbnail.height) == (512, 512)
    assert thumbnail.url_path == expected_url
    assert len(ctx.sub_artifacts) == 1
    assert ctx.sub_artifacts[0]["artifact_name"] == expected_url


def test_regular_downscaling_is_unchanged(ctx, test_jpg, source_url_path):
    with warnings.catch_warnings():
        warnings.simplefilter("error")
        thumbnail = make_image_thumbnail(
            ctx, test_jpg, source_url_path, width=50
        )

    assert (thumbnail.width, thumbnail.height) == (50, 67)
    assert thumbnail.url_path == "test@50.jpg"
    assert len(ctx.sub_artifacts) == 1

import pytest

import sqlglot as sg
from sqlglot import exp


def duckdb_to_tsql(sql: str) -> str:
    return sg.parse_one(sql, read="duckdb").sql("tsql")


def test_nonliteral_strftime_format_is_not_rendered_as_none():
    expression = sg.parse_one("select strftime(a, concat('%Y', '%m'))", read="duckdb")

    assert expression.sql("tsql") == "SELECT FORMAT(a, CONCAT('%Y', '%m'))"


@pytest.mark.parametrize(
    ("source", "expected"),
    [
        (
            "select strftime(a, concat('%Y', '-', '%m'))",
            "SELECT FORMAT(a, CONCAT('%Y', '-', '%m'))",
        ),
        (
            "select strftime(a, upper('%y%m'))",
            "SELECT FORMAT(a, UPPER('%y%m'))",
        ),
        (
            "select strftime(a, lower(concat('ABC', '%Y')))",
            "SELECT FORMAT(a, LOWER(CONCAT('ABC', '%Y')))",
        ),
        (
            "select strftime(a, format_column)",
            "SELECT FORMAT(a, format_column)",
        ),
    ],
)
def test_other_dynamic_format_expressions_are_preserved(source, expected):
    assert duckdb_to_tsql(source) == expected


@pytest.mark.parametrize(
    ("source", "expected"),
    [
        ("select strftime(a, '%Y-%m-%d')", "SELECT FORMAT(a, 'yyyy-MM-dd')"),
        ("select strftime(a, '%H:%M:%S')", "SELECT FORMAT(a, 'HH:mm:ss')"),
        ("select strftime(a, 'abc')", "SELECT FORMAT(a, 'abc')"),
    ],
)
def test_literal_formats_still_use_tsql_format_mapping(source, expected):
    assert duckdb_to_tsql(source) == expected


@pytest.mark.parametrize(
    ("format_string", "datepart"),
    [("dw", "DW"), ("HOUR", "HOUR"), ("QUARTER", "QUARTER")],
)
def test_literal_datepart_only_formats_still_generate_datepart(format_string, datepart):
    assert duckdb_to_tsql(f"select strftime(a, '{format_string}')") == (
        f"SELECT DATEPART({datepart}, a)"
    )


def test_dynamic_format_does_not_trigger_datepart_special_case():
    assert duckdb_to_tsql("select strftime(a, concat('dw', ''))") == (
        "SELECT FORMAT(a, CONCAT('dw', ''))"
    )


def test_culture_is_preserved_with_dynamic_format():
    expression = sg.parse_one(
        "select strftime(a, concat('%Y', '%m'))", read="duckdb"
    )
    time_to_str = expression.find(exp.TimeToStr)
    assert time_to_str is not None
    time_to_str.set("culture", exp.Literal.string("en-US"))

    assert expression.sql("tsql") == (
        "SELECT FORMAT(a, CONCAT('%Y', '%m'), 'en-US')"
    )


def test_number_to_str_generation_is_unchanged():
    number_to_str = exp.NumberToStr(
        this=exp.column("a"),
        format=exp.Literal.string("N"),
        culture=exp.Literal.string("en-US"),
    )

    assert exp.select(number_to_str).sql("tsql") == (
        "SELECT FORMAT(a, 'N', 'en-US')"
    )

from __future__ import annotations

from typing import Any

import pandas as pd
import polars as pl
import pytest

import narwhals as nw


N_UNIQUE_CASES = [
    pytest.param([1.0, None, None, 2.0], 2, id="issue-example"),
    pytest.param([None, 7, 7, None], 1, id="nulls-and-duplicates"),
    pytest.param([None, None, None], 0, id="all-null"),
