]

# Scalar selection on an empty pandas DataFrame is unsupported independently of
# n_unique, so exercise empty input through the public Series API instead.
EXPRESSION_N_UNIQUE_CASES = N_UNIQUE_CASES[:-1]


def _pandas_series(values: list[Any]) -> pd.Series:
    return pd.Series(values)


def _polars_series(values: list[Any]) -> pl.Series:
