def _polars_frame(data: dict[str, list[Any]]) -> pl.DataFrame:
    return pl.DataFrame(data)


def _polars_lazy_frame(data: dict[str, list[Any]]) -> pl.LazyFrame:
    return pl.LazyFrame(data)


def _expression_n_unique(native_frame: Any, column: str = "a") -> Any:
    frame = nw.from_native(native_frame)
    result = frame.select(nw.col(column).n_unique())
    if isinstance(result, nw.LazyFrame):
        result = result.collect()
    return result[column][0]


