) -> None:
    series = nw.from_native(series_factory(list(values)), series_only=True)

    assert series.n_unique() == expected


@pytest.mark.parametrize(
    "frame_factory",
    [_pandas_frame, _polars_frame, _polars_lazy_frame],
    ids=["pandas", "polars", "polars-lazy"],
)
@pytest.mark.parametrize("values, expected", EXPRESSION_N_UNIQUE_CASES)
def test_expression_n_unique_excludes_nulls(
    frame_factory: Any, values: list[Any], expected: int
) -> None:
    native_frame = frame_factory({"a": list(values)})

    assert _expression_n_unique(native_frame) == expected


@pytest.mark.parametrize(
    "frame_factory",
    [_pandas_frame, _polars_frame, _polars_lazy_frame],
    ids=["pandas", "polars", "polars-lazy"],
)
def test_expression_n_unique_filters_nulls_per_column(frame_factory: Any) -> None:
    native_frame = frame_factory(
        {
            "a": [1.0, None, None, 2.0],
            "b": [None, "x", "x", "y"],
            "c": [1, 1, 2, 2],
            "d": [None, None, None, None],
        }
    )
    frame = nw.from_native(native_frame)

    result = frame.select(
        a=nw.col("a").n_unique(),
        b=nw.col("b").n_unique(),
        c=nw.col("c").n_unique(),
        d=nw.col("d").n_unique(),
    )
    if isinstance(result, nw.LazyFrame):
        result = result.collect()

    assert {name: result[name][0] for name in ("a", "b", "c", "d")} == {
        "a": 2,
        "b": 2,
        "c": 2,
        "d": 0,
    }

import pytest

from sqlglot import exp, parse_one


def _assert_computed_format_is_preserved(sql: str) -> None:
    """A computed format must be generated as an expression, not as a literal."""
    statement = parse_one(sql, read="duckdb")
    time_to_str = statement.selects[0]

    assert isinstance(time_to_str, exp.TimeToStr)

    # Generate the format expression independently so this expectation also covers
    # dialect-specific CONCAT generation without relying on TimeToStr itself.
    expected_format = time_to_str.args["format"].sql("tsql")
    expected = f"SELECT FORMAT(a, {expected_format})"

    output = statement.sql("tsql")
    assert output == expected
    assert "'None'" not in output


def test_tsql_time_to_str_with_concat_format_regression():
    # Regression test for strftime(a, concat('%Y', '%m')) producing FORMAT(a, 'None').
    _assert_computed_format_is_preserved(
        "SELECT STRFTIME(a, CONCAT('%Y', '%m'))"
    )


@pytest.mark.parametrize(
    "sql",
    [
        "SELECT STRFTIME(a, CONCAT('%Y', '-', '%m'))",
        "SELECT STRFTIME(a, UPPER('%y%m'))",
        "SELECT STRFTIME(a, LOWER(CONCAT('ABC', '%Y')))",
        "SELECT STRFTIME(a, format_string)",
    ],
)
def test_tsql_time_to_str_supports_computed_formats(sql):
    _assert_computed_format_is_preserved(sql)


def test_tsql_computed_format_is_not_mistaken_for_datepart():
    # A column named "quarter" is still an expression. Only a string literal whose
    # entire value is QUARTER should use the special DATEPART generation path.
    _assert_computed_format_is_preserved("SELECT STRFTIME(a, quarter)")


@pytest.mark.parametrize(
    ("source_format", "expected_format"),
