def test_tsql_computed_time_format_retains_culture():
    format_expression = exp.Concat(
        expressions=[exp.Literal.string("%Y"), exp.Literal.string("%m")]
    )
    time_to_str = exp.TimeToStr(
        this=exp.column("a"),
        format=format_expression,
        culture=exp.Literal.string("en-US"),
    )
    statement = exp.select(time_to_str)

    expected_format = format_expression.sql("tsql")
    assert statement.sql("tsql") == (
        f"SELECT FORMAT(a, {expected_format}, 'en-US')"
    )


