from __future__ import annotations

from typing import Any
from typing import Callable

import pandas as pd
import polars as pl
import pytest

import narwhals as nw


def pandas_frame(values: list[Any]) -> pd.DataFrame:
    return pd.DataFrame({"a": pd.Series(values, dtype="float64")})


def pandas_nullable_frame(values: list[Any]) -> pd.DataFrame:
    return pd.DataFrame({"a": pd.Series(values, dtype="Float64")})


def polars_frame(values: list[Any]) -> pl.DataFrame:
    return pl.DataFrame(
        {"a": pl.Series("a", values, dtype=pl.Float64)}
    )


FRAME_FACTORIES = [
    pytest.param(pandas_frame, id="pandas"),
    pytest.param(pandas_nullable_frame, id="pandas-nullable"),
    pytest.param(polars_frame, id="polars"),
]

N_UNIQUE_CASES = [
    pytest.param([1.0, None, None, 2.0], 2, id="issue-example"),
    pytest.param([3.0, None, 3.0, None], 1, id="one-non-null-value"),
    pytest.param([None, None, None], 0, id="all-null"),
    pytest.param([None], 0, id="single-null"),
    pytest.param([], 0, id="empty"),
    pytest.param([1.0, 1.0, 2.0, 3.0], 3, id="no-nulls"),
]

# Scalar selection on an empty pandas-backed frame is a separate, general
# reduction/selection limitation in this version. Empty input is therefore
# covered through Series for every backend and through expressions for Polars.
EXPRESSION_N_UNIQUE_CASES = [
    pytest.param([1.0, None, None, 2.0], 2, id="issue-example"),
    pytest.param([3.0, None, 3.0, None], 1, id="one-non-null-value"),
    pytest.param([None, None, None], 0, id="all-null"),
    pytest.param([None], 0, id="single-null"),
    pytest.param([1.0, 1.0, 2.0, 3.0], 3, id="no-nulls"),
]


@pytest.mark.parametrize("frame_factory", FRAME_FACTORIES)
@pytest.mark.parametrize(("values", "expected"), N_UNIQUE_CASES)
def test_series_n_unique_excludes_nulls(
    frame_factory: Callable[[list[Any]], Any],
    values: list[Any],
    expected: int,
) -> None:
    native_series = frame_factory(values)["a"]
    series = nw.from_native(native_series, series_only=True)

    assert series.n_unique() == expected


@pytest.mark.parametrize("frame_factory", FRAME_FACTORIES)
@pytest.mark.parametrize(("values", "expected"), EXPRESSION_N_UNIQUE_CASES)
def test_expression_n_unique_excludes_nulls_eager(
    frame_factory: Callable[[list[Any]], Any],
    values: list[Any],
    expected: int,
) -> None:
    frame = nw.from_native(frame_factory(values))

    result = frame.select(nw.col("a").n_unique())

    assert result["a"][0] == expected


@pytest.mark.parametrize("frame_factory", FRAME_FACTORIES)
@pytest.mark.parametrize(("values", "expected"), EXPRESSION_N_UNIQUE_CASES)
def test_expression_n_unique_excludes_nulls_lazy(
    frame_factory: Callable[[list[Any]], Any],
