@pytest.mark.parametrize("lazy", [False, True], ids=["eager", "lazy"])
def test_polars_expression_n_unique_empty(lazy: bool) -> None:
    native_frame = polars_frame([])
    expression = nw.col("a").n_unique()

    if lazy:
        result = nw.LazyFrame(native_frame).select(expression).collect()
    else:
