    assert result["a"][0] == 0


def multi_column_frame(backend: str) -> Any:
    data = {
        "a": [1.0, None, None, 2.0],
        "b": [None, None, None, None],
        "c": [4.0, 4.0, 5.0, 5.0],
    }
    if backend == "polars":
        return pl.DataFrame(
            {
                name: pl.Series(name, values, dtype=pl.Float64)
                for name, values in data.items()
            }
        )

    dtype = "Float64" if backend == "pandas-nullable" else "float64"
    return pd.DataFrame(
        {
            name: pd.Series(values, dtype=dtype)
            for name, values in data.items()
        }
    )


@pytest.mark.parametrize("backend", ["pandas", "pandas-nullable", "polars"])
@pytest.mark.parametrize("lazy", [False, True], ids=["eager", "lazy"])
