    backend: str,
    lazy: bool,
) -> None:
    native_frame = multi_column_frame(backend)
    expression = nw.col("a", "b", "c").n_unique()

    if lazy:
        result = nw.LazyFrame(native_frame).select(expression).collect()
    else:
        result = nw.from_native(native_frame).select(expression)

    assert {name: result[name][0] for name in ("a", "b", "c")} == {
        "a": 2,
        "b": 0,
        "c": 2,
    }

"""Regression tests for batch_run with non-iterable model parameter values."""

import pandas as pd

from mesa import Model
from mesa.batchrunner import batch_run
from mesa.datacollection import DataCollector
from mesa.time import BaseScheduler


class ExoticParameterModel(Model):
    """Small model accepting the parameter types described in the issue."""

    def __init__(
        self,
        scenario="baseline",
        input_data=None,
        social_network_parameters=None,
        year_period=30,
    ):
        super().__init__()
        self.scenario = scenario
        self.input_data = input_data
        self.social_network_parameters = social_network_parameters
        self.year_period = year_period

        self.schedule = BaseScheduler(self)
        self.datacollector = DataCollector(
            model_reporters={
                "model_scenario": lambda model: model.scenario,
                "model_year_period": lambda model: model.year_period,
            }
        )

    def step(self):
        self.schedule.step()
        self.datacollector.collect(self)
        self.running = False


def run_with_parameters(parameters):
    return batch_run(
        ExoticParameterModel,
        parameters,
        number_processes=1,
        iterations=1,
        max_steps=5,
        display_progress=False,
    )


def test_single_string_is_fixed_and_list_of_strings_is_swept():
    single = run_with_parameters({"scenario": "baseline"})

    assert len(single) == 1
    assert single[0]["scenario"] == "baseline"
    assert single[0]["model_scenario"] == "baseline"

    scenarios = ["baseline", "scenario1", "scenario2"]
    swept = run_with_parameters({"scenario": scenarios})

    assert len(swept) == len(scenarios)
    assert {row["scenario"] for row in swept} == set(scenarios)
    assert all(row["model_scenario"] == row["scenario"] for row in swept)


def test_issue_example_sweeps_scenarios_with_fixed_dict_and_dataframe():
    input_data = pd.DataFrame(
        {
            "baseline": [1.0, 2.0],
            "scenario1": [3.0, 4.0],
            "scenario2": [5.0, 6.0],
        }
    )
    network_parameters = {
        "average_degree": 10,
        "rewiring_probability": 0.1,
    }
    scenarios = ["baseline", "scenario1", "scenario2"]

    results = run_with_parameters(
        {
            "input_data": input_data,
            "scenario": scenarios,
            "social_network_parameters": network_parameters,
            "year_period": 30,
        }
    )

    # The DataFrame and dictionary are each one fixed value, not collections
    # of column names or keys over which batch_run should iterate.
    assert len(results) == 3
    assert {row["scenario"] for row in results} == set(scenarios)

    for row in results:
        assert row["model_scenario"] == row["scenario"]
        assert row["year_period"] == 30
        assert row["model_year_period"] == 30
        assert row["social_network_parameters"] == network_parameters
        pd.testing.assert_frame_equal(row["input_data"], input_data)


def test_fixed_dictionary_is_passed_as_one_value():
    network_parameters = {
        "average_degree": 10,
        "rewiring_probability": 0.1,
    }

    results = run_with_parameters(
        {
            "scenario": ["baseline", "scenario1"],
            "social_network_parameters": network_parameters,
        }
    )

    assert len(results) == 2
    assert {row["scenario"] for row in results} == {"baseline", "scenario1"}
    assert all(
        row["social_network_parameters"] == network_parameters for row in results
    )


def test_empty_dict_and_empty_dataframe_are_still_single_values():
    empty_data = pd.DataFrame()

    results = run_with_parameters(
        {
            "input_data": empty_data,
            "social_network_parameters": {},
            "scenario": "baseline",
        }
    )

    # Empty complex values must not accidentally produce zero parameter
    # combinations; they are valid fixed inputs to one model run.
    assert len(results) == 1
    assert results[0]["social_network_parameters"] == {}
    pd.testing.assert_frame_equal(results[0]["input_data"], empty_data)


def test_scalar_and_conventional_parameter_iterables_still_work():
    results = run_with_parameters(
        {
            "scenario": ("baseline", "scenario1"),
            "year_period": range(30, 32),
            "input_data": None,
        }
    )

    expected = {
        ("baseline", 30, None),
        ("baseline", 31, None),
        ("scenario1", 30, None),
        ("scenario1", 31, None),
    }
    assert len(results) == len(expected)
    assert {
        (row["scenario"], row["year_period"], row["input_data"])
        for row in results
    } == expected

