from __future__ import annotations

from typing import Any

import pandas as pd
import polars as pl
import pytest

import narwhals as nw


ISSUE_VALUES = [1.0, None, None, 2.0]


def select_and_collect(native: Any, *exprs: nw.Expr) -> Any:
    df = nw.from_native(native)
    result = df.select(*exprs)
    if isinstance(result, nw.LazyFrame):
        result = result.collect()
    return result


@pytest.mark.parametrize(
    "native_series",
    [
        pytest.param(pd.Series(ISSUE_VALUES), id="pandas"),
        pytest.param(pl.Series(ISSUE_VALUES), id="polars"),
        pytest.param(
            pd.Series([1, pd.NA, pd.NA, 2], dtype="Int64"),
            id="pandas-nullable",
        ),
    ],
)
def test_series_n_unique_excludes_nulls(native_series: Any) -> None:
    series = nw.from_native(native_series, series_only=True)

    assert series.n_unique() == 2


@pytest.mark.parametrize("backend", ["pandas", "polars"])
@pytest.mark.parametrize(
    ("values", "expected"),
    [
        ([], 0),
        ([None, None], 0),
        ([None, 7.0, None], 1),
        ([1.0, 1.0, 2.0, 2.0], 2),
    ],
)
def test_series_n_unique_null_edge_cases(
    backend: str, values: list[Any], expected: int
) -> None:
    if backend == "pandas":
        native = pd.Series(values, dtype="float64")
    else:
        native = pl.Series(values, dtype=pl.Float64)

    series = nw.from_native(native, series_only=True)

    assert series.n_unique() == expected


@pytest.mark.parametrize(
    "native_series",
    [
        pytest.param(pd.Series(["a", None, "a", "b"]), id="pandas"),
        pytest.param(pl.Series(["a", None, "a", "b"]), id="polars"),
    ],
)
def test_series_n_unique_excludes_nulls_for_strings(native_series: Any) -> None:
    series = nw.from_native(native_series, series_only=True)

    assert series.n_unique() == 2


@pytest.mark.parametrize(
    "native_frame",
    [
        pytest.param(pd.DataFrame({"a": ISSUE_VALUES}), id="pandas"),
        pytest.param(pl.DataFrame({"a": ISSUE_VALUES}), id="polars-eager"),
        pytest.param(pl.LazyFrame({"a": ISSUE_VALUES}), id="polars-lazy"),
    ],
)
def test_expression_n_unique_excludes_nulls(native_frame: Any) -> None:
    result = select_and_collect(
        native_frame, nw.col("a").n_unique().alias("a_n_unique")
    )

    assert result["a_n_unique"][0] == 2


@pytest.mark.parametrize("constructor", [pd.DataFrame, pl.DataFrame])
def test_expression_n_unique_handles_no_nulls_and_all_nulls(
    constructor: Any,
) -> None:
    native = constructor(
        {
            "without_nulls": [1, 1, 2, 2],
            "all_nulls": [None, None, None, None],
        }
    )

    result = select_and_collect(
        native,
        nw.col("without_nulls").n_unique(),
        nw.col("all_nulls").n_unique(),
    )

    # No null should be subtracted when the column contains no nulls.
    assert result["without_nulls"][0] == 2
    # An all-null column contains no non-null unique values.
    assert result["all_nulls"][0] == 0

"""Regression tests for batch_run with non-standard model parameter values."""

import pandas as pd

from mesa import Model
from mesa.batchrunner import batch_run
from mesa.datacollection import DataCollector
from mesa.time import BaseScheduler


class ParameterRecordingModel(Model):
    """Minimal model that records the parameter values it actually receives."""

    def __init__(
        self,
        scenario="baseline",
        input_data=None,
        social_network_parameters=None,
        year_period=30,
    ):
        super().__init__()
        self.schedule = BaseScheduler(self)
        self.scenario = scenario
        self.input_data = input_data
        self.social_network_parameters = social_network_parameters
        self.year_period = year_period
        self.running = True
        self.datacollector = DataCollector(
            model_reporters={
                "received_scenario": lambda model: model.scenario,
                "received_input_data": lambda model: model.input_data,
                "received_social_network_parameters": (
                    lambda model: model.social_network_parameters
                ),
                "received_year_period": lambda model: model.year_period,
            }
        )

    def step(self):
        self.datacollector.collect(self)
        self.schedule.step()
        self.running = False


def run_batch(parameters, iterations=1):
    return batch_run(
        ParameterRecordingModel,
        parameters=parameters,
        number_processes=1,
        iterations=iterations,
        max_steps=1,
        display_progress=False,
    )


def test_batch_run_sweeps_a_list_of_scenario_strings():
    scenarios = ["baseline", "scenario1", "scenario2"]

    results = run_batch({"scenario": scenarios, "year_period": 30})

    assert len(results) == len(scenarios)
    assert [row["scenario"] for row in results] == scenarios
    assert [row["received_scenario"] for row in results] == scenarios


def test_batch_run_treats_a_single_string_as_one_fixed_value():
    results = run_batch({"scenario": "baseline", "year_period": [30, 60]})

    assert len(results) == 2
    assert {row["year_period"] for row in results} == {30, 60}
    for row in results:
        assert row["scenario"] == "baseline"
        assert row["received_scenario"] == "baseline"


def test_batch_run_passes_a_dictionary_as_one_fixed_parameter():
    scenarios = ["baseline", "scenario1"]
    network_parameters = {
        "average_degree": 10,
        "rewiring_probability": 0.1,
    }

    results = run_batch(
        {
            "scenario": scenarios,
            "social_network_parameters": network_parameters,
            "year_period": 30,
        },
        iterations=2,
    )

    # Two scenarios, two iterations each; dictionary keys must not be swept.
    assert len(results) == 4
    for scenario in scenarios:
        scenario_rows = [row for row in results if row["scenario"] == scenario]
        assert len(scenario_rows) == 2
        assert sorted(row["iteration"] for row in scenario_rows) == [0, 1]

    for row in results:
        assert row["social_network_parameters"] == network_parameters
        assert row["received_social_network_parameters"] == network_parameters


def test_batch_run_passes_a_dataframe_as_one_fixed_parameter():
    scenarios = ["baseline", "scenario1", "scenario2"]
    input_data = pd.DataFrame(
        {
            "scenario": ["baseline", "scenario1", "scenario2"],
            "value": [1.0, 2.0, 3.0],
        }
    )

    results = run_batch(
        {
            "scenario": scenarios,
            "input_data": input_data,
            "year_period": 30,
        }
    )

    # DataFrame column names are not separate parameter values.
    assert len(results) == len(scenarios)
    assert [row["scenario"] for row in results] == scenarios
    for row in results:
        pd.testing.assert_frame_equal(row["input_data"], input_data)
        pd.testing.assert_frame_equal(row["received_input_data"], input_data)


def test_batch_run_can_sweep_a_list_of_dictionaries():
    parameter_sets = [
        {"average_degree": 10, "rewiring_probability": 0.1},
        {"average_degree": 20, "rewiring_probability": 0.2},
    ]

    results = run_batch(
        {
            "scenario": "baseline",
            "social_network_parameters": parameter_sets,
        }
    )

    assert len(results) == 2
    for row, expected in zip(results, parameter_sets):
        assert row["social_network_parameters"] == expected
        assert row["received_social_network_parameters"] == expected


def test_empty_dictionary_and_dataframe_are_still_single_values():
    input_data = pd.DataFrame()

    results = run_batch(
        {
            "scenario": "baseline",
            "input_data": input_data,
            "social_network_parameters": {},
        }
    )

    # Empty exotic values must not silently produce an empty parameter sweep.
    assert len(results) == 1
    row = results[0]
    assert row["social_network_parameters"] == {}
    assert row["received_social_network_parameters"] == {}
    pd.testing.assert_frame_equal(row["input_data"], input_data)
    pd.testing.assert_frame_equal(row["received_input_data"], input_data)

from __future__ import annotations

from typing import Any

import pandas as pd
import polars as pl
import pytest

import narwhals as nw


BACKENDS = ["pandas", "polars"]


def _make_series(backend: str, values: list[Any]) -> Any:
    if backend == "pandas":
        if not values:
            return pd.Series(values, dtype="float64")
        return pd.Series(values)
    if not values:
        return pl.Series(values, dtype=pl.Float64)
    return pl.Series(values)


@pytest.mark.parametrize("backend", BACKENDS)
@pytest.mark.parametrize(
    ("values", "expected"),
    [
        # The example from the issue: repeated nulls count as one unique value.
        ([1.0, None, None, 2.0], 3),
        ([None, 1, None, 1, 2, None], 3),
        (["a", None, "a", "b", None], 3),
        # A series consisting entirely of nulls still has one unique value.
        ([None, None, None], 1),
        # Existing behavior without nulls must remain unchanged.
        ([1, 2, 2, 3], 3),
        ([1, 1, 1], 1),
        # Empty input has no unique values.
        ([], 0),
    ],
)
def test_series_n_unique_counts_nulls_consistently(
    backend: str, values: list[Any], expected: int
) -> None:
    native_series = _make_series(backend, values)
    series = nw.from_native(native_series, series_only=True)

    assert series.n_unique() == expected


@pytest.mark.parametrize("backend", BACKENDS)
def test_n_unique_expression_counts_nulls(backend: str) -> None:
    data = {"value": [1.0, None, None, 2.0, 1.0]}
    native_frame = pd.DataFrame(data) if backend == "pandas" else pl.DataFrame(data)

    result = nw.from_native(native_frame).select(nw.col("value").n_unique())

    assert result["value"][0] == 3


@pytest.mark.parametrize(
    ("dtype", "missing"),
    [
        ("float64", None),
        ("Float64", pd.NA),
    ],
)
def test_pandas_n_unique_counts_missing_values_in_numeric_dtypes(
    dtype: str, missing: Any
) -> None:
    native_series = pd.Series([1.0, missing, missing, 2.0], dtype=dtype)
    series = nw.from_native(native_series, series_only=True)

    assert series.n_unique() == 3

import pytest

import sqlglot as sg
from sqlglot import exp


def duckdb_to_tsql(sql: str) -> str:
    return sg.parse_one(sql, read="duckdb").sql("tsql")


def test_tsql_time_to_str_with_concat_format():
    """Regression test for the reported DuckDB strftime -> TSQL transpilation."""
    expression = sg.parse_one("select strftime(a, concat('%Y', '%m'))", read="duckdb")

    assert expression.sql("tsql") == "SELECT FORMAT(a, CONCAT('%Y', '%m'))"


@pytest.mark.parametrize(
    ("source", "expected"),
    [
        (
            "SELECT STRFTIME(a, format_string)",
            "SELECT FORMAT(a, format_string)",
        ),
        (
            "SELECT STRFTIME(a, CONCAT('%Y', '-', '%m'))",
            "SELECT FORMAT(a, CONCAT('%Y', '-', '%m'))",
        ),
        (
            "SELECT STRFTIME(a, UPPER(format_string))",
            "SELECT FORMAT(a, UPPER(format_string))",
        ),
        (
            "SELECT STRFTIME(a, LOWER(CONCAT('ABC', '%Y')))",
            "SELECT FORMAT(a, LOWER(CONCAT('ABC', '%Y')))",
        ),
    ],
)
def test_tsql_time_to_str_preserves_non_literal_formats(source, expected):
    """Any computed format must be rendered as an expression, not as 'None'."""
    assert duckdb_to_tsql(source) == expected


@pytest.mark.parametrize(
    ("source", "expected"),
    [
        (
            "SELECT STRFTIME(a, '%Y-%m-%d')",
            "SELECT FORMAT(a, 'yyyy-MM-dd')",
        ),
        (
            "SELECT STRFTIME(a, '%H:%M:%S')",
            "SELECT FORMAT(a, 'HH:mm:ss')",
        ),
        (
            "SELECT STRFTIME(a, 'abc')",
            "SELECT FORMAT(a, 'abc')",
        ),
    ],
)
def test_tsql_time_to_str_still_converts_literal_formats(source, expected):
    """The non-literal fix must not bypass the existing literal format mapping."""
    assert duckdb_to_tsql(source) == expected


@pytest.mark.parametrize("format_name", ["dw", "HOUR", "QUARTER"])
def test_tsql_datepart_only_formats_are_unchanged(format_name):
    assert duckdb_to_tsql(f"SELECT STRFTIME(a, '{format_name}')") == (
        f"SELECT DATEPART({format_name.upper()}, a)"
    )


def test_tsql_computed_time_format_retains_culture():
    time_to_str = exp.TimeToStr(
        this=exp.column("a"),
        format=exp.Concat(
            expressions=[exp.Literal.string("%Y"), exp.Literal.string("%m")]
        ),
        culture=exp.Literal.string("en-US"),
    )

    assert exp.select(time_to_str).sql("tsql") == (
        "SELECT FORMAT(a, CONCAT('%Y', '%m'), 'en-US')"
    )


def test_tsql_number_to_str_is_unchanged():
    expression = sg.parse_one("SELECT FORMAT(amount, 'N', 'en-US')", read="tsql")

    assert expression.sql("tsql") == "SELECT FORMAT(amount, 'N', 'en-US')"

from __future__ import annotations

from typing import Any
from typing import Callable

import pandas as pd
import polars as pl
import pytest

import narwhals as nw
from narwhals.utils import parse_version


SeriesConstructor = Callable[[list[Any]], Any]


def pandas_series(values: list[Any]) -> pd.Series:
    return pd.Series(values, dtype="float64")


def pandas_nullable_series(values: list[Any]) -> pd.Series:
    return pd.Series(values, dtype="Float64")


def pandas_pyarrow_series(values: list[Any]) -> pd.Series:
    pytest.importorskip("pyarrow")
    if parse_version(pd.__version__) < parse_version("1.5.0"):
        pytest.skip("pandas pyarrow dtypes require pandas 1.5 or later")
    return pd.Series(values, dtype="Float64[pyarrow]")


def polars_series(values: list[Any]) -> pl.Series:
    return pl.Series(values)


BACKENDS = [
    pytest.param(pandas_series, id="pandas"),
    pytest.param(pandas_nullable_series, id="pandas-nullable"),
    pytest.param(pandas_pyarrow_series, id="pandas-pyarrow"),
    pytest.param(polars_series, id="polars"),
]

SERIES_CASES = [
    # The example from the issue: repeated nulls form one additional unique value.
    pytest.param([1.0, None, None, 2.0], 3, id="repeated-nulls"),
    pytest.param([None, None, None], 1, id="all-nulls"),
    pytest.param([], 0, id="empty"),
    # Existing behavior without nulls must remain unchanged.
    pytest.param([1.0, 2.0, 2.0, 3.0], 3, id="no-nulls"),
]

EXPRESSION_CASES = [
    pytest.param([1.0, None, None, 2.0], 3, id="repeated-nulls"),
    pytest.param([None, None, None], 1, id="all-nulls"),
    pytest.param([1.0, 2.0, 2.0, 3.0], 3, id="no-nulls"),
]


@pytest.mark.parametrize("constructor", BACKENDS)
@pytest.mark.parametrize(("values", "expected"), SERIES_CASES)
def test_series_n_unique_counts_nulls_consistently(
    constructor: SeriesConstructor, values: list[Any], expected: int
) -> None:
    series = nw.from_native(constructor(values), series_only=True)

    assert series.n_unique() == expected


@pytest.mark.parametrize("constructor", BACKENDS)
@pytest.mark.parametrize(("values", "expected"), EXPRESSION_CASES)
def test_expression_n_unique_counts_nulls_consistently(
    constructor: SeriesConstructor, values: list[Any], expected: int
) -> None:
    native_series = constructor(values).rename("a")
    frame = nw.from_native(native_series.to_frame())

    result = frame.select(nw.col("a").n_unique())

    assert result["a"][0] == expected

import pytest

from sqlglot import exp, parse_one


def test_reported_non_literal_format_is_not_rendered_as_none():
    expr = parse_one("SELECT STRFTIME(a, CONCAT('%Y', '%m'))", read="duckdb")

    # The format is an expression, not a string literal. It must survive T-SQL
    # generation instead of being converted through Expression.text("format"),
    # which used to produce the bogus format string 'None'.
    assert expr.sql("tsql") == "SELECT FORMAT(a, CONCAT('%Y', '%m'))"

    # Generation for T-SQL must not interfere with the already-working dialects.
    assert expr.sql("snowflake") == (
        "SELECT TO_CHAR(CAST(a AS TIMESTAMPNTZ), "
        "CONCAT(COALESCE('yyyy', ''), COALESCE('mm', '')))"
    )


@pytest.mark.parametrize(
    ("duckdb_sql", "expected_tsql"),
    [
        (
            "SELECT STRFTIME(a, CONCAT('%Y', '-', '%m'))",
            "SELECT FORMAT(a, CONCAT('%Y', '-', '%m'))",
        ),
        (
            "SELECT STRFTIME(a, UPPER('%y%m'))",
            "SELECT FORMAT(a, UPPER('%y%m'))",
        ),
        (
            "SELECT STRFTIME(a, LOWER(CONCAT('ABC', '%Y')))",
            "SELECT FORMAT(a, LOWER(CONCAT('ABC', '%Y')))",
        ),
    ],
)
def test_other_non_literal_format_expressions(duckdb_sql, expected_tsql):
    assert parse_one(duckdb_sql, read="duckdb").sql("tsql") == expected_tsql


@pytest.mark.parametrize(
    ("duckdb_sql", "expected_tsql"),
    [
        ("SELECT STRFTIME(a, '%Y-%m-%d')", "SELECT FORMAT(a, 'yyyy-MM-dd')"),
        ("SELECT STRFTIME(a, '%H:%M:%S')", "SELECT FORMAT(a, 'HH:mm:ss')"),
        ("SELECT STRFTIME(a, 'abc')", "SELECT FORMAT(a, 'abc')"),
    ],
)
def test_literal_formats_still_use_tsql_time_mapping(duckdb_sql, expected_tsql):
    """The non-literal fallback must not bypass normal literal conversion."""
    assert parse_one(duckdb_sql, read="duckdb").sql("tsql") == expected_tsql


@pytest.mark.parametrize(
    ("format_string", "datepart"),
    [
        ("dw", "DW"),
        ("HOUR", "HOUR"),
        ("QUARTER", "QUARTER"),
    ],
)
def test_datepart_only_literal_formats_are_preserved(format_string, datepart):
    expr = parse_one(f"SELECT STRFTIME(a, '{format_string}')", read="duckdb")
    assert expr.sql("tsql") == f"SELECT DATEPART({datepart}, a)"


def test_dynamic_format_column_is_emitted_as_an_expression():
    time_to_str = exp.TimeToStr(this=exp.column("a"), format=exp.column("fmt"))

    assert exp.select(time_to_str).sql("tsql") == "SELECT FORMAT(a, fmt)"


def test_non_literal_format_and_culture_are_both_preserved():
    time_to_str = exp.TimeToStr(
        this=exp.column("a"),
        format=exp.Concat(
            expressions=[exp.Literal.string("%Y"), exp.Literal.string("%m")]
        ),
        culture=exp.Literal.string("en-US"),
    )

    assert exp.select(time_to_str).sql("tsql") == (
        "SELECT FORMAT(a, CONCAT('%Y', '%m'), 'en-US')"
    )


@pytest.mark.parametrize(
    "sql",
    [
        "SELECT FORMAT(a, 'N')",
        "SELECT FORMAT(a, 'C')",
        "SELECT FORMAT(a, 'N', 'en-US')",
    ],
)
def test_number_to_str_generation_is_unchanged(sql):
    """NumberToStr shares this generator but needs no time-format conversion."""
    assert parse_one(sql, read="tsql").sql("tsql") == sql


def test_literal_time_format_with_culture_still_roundtrips():
    sql = "SELECT FORMAT(a, 'yyyy-MM-dd', 'en-US')"
    assert parse_one(sql, read="tsql").sql("tsql") == sql

"""Regression tests for batch runs with non-sequence model parameters."""

import pandas as pd

from mesa.batchrunner import _make_model_kwargs, batch_run
from mesa.datacollection import DataCollector
from mesa.model import Model
from mesa.time import BaseScheduler


def test_make_model_kwargs_keeps_single_exotic_values_intact():
    input_data = pd.DataFrame({"baseline": [1, 2], "scenario1": [3, 4]})
    network_parameters = {
        "average_degree": 10,
        "rewiring_probability": 0.1,
    }

    kwargs_list = _make_model_kwargs(
        {
            "seed": 0,
            "input_data": input_data,
            "scenario": "baseline",
            "social_network_parameters": network_parameters,
            "year_period": 30,
        }
    )

    assert len(kwargs_list) == 1
    kwargs = kwargs_list[0]
    assert kwargs["seed"] == 0
    assert kwargs["scenario"] == "baseline"
    assert kwargs["year_period"] == 30
    assert kwargs["social_network_parameters"] == network_parameters
    pd.testing.assert_frame_equal(kwargs["input_data"], input_data)


def test_make_model_kwargs_sweeps_strings_without_splitting_fixed_values():
    scenarios = ["baseline", "scenario1", "scenario2"]
    input_data = pd.DataFrame(
        {"baseline": [1], "scenario1": [2], "scenario2": [3]}
    )
    network_parameters = {
        "average_degree": 10,
        "rewiring_probability": 0.1,
    }

    kwargs_list = _make_model_kwargs(
        {
            "input_data": input_data,
            "scenario": scenarios,
            "social_network_parameters": network_parameters,
            "year_period": 30,
        }
    )

    assert len(kwargs_list) == len(scenarios)
    assert [kwargs["scenario"] for kwargs in kwargs_list] == scenarios
    for kwargs in kwargs_list:
        assert kwargs["year_period"] == 30
        assert kwargs["social_network_parameters"] == network_parameters
        pd.testing.assert_frame_equal(kwargs["input_data"], input_data)


def test_make_model_kwargs_treats_empty_dict_and_dataframe_as_values():
    """Empty complex values are still values, not empty parameter sweeps."""
    input_data = pd.DataFrame()

    kwargs_list = _make_model_kwargs(
        {
            "input_data": input_data,
            "social_network_parameters": {},
            "scenario": "baseline",
        }
    )

    assert len(kwargs_list) == 1
    assert kwargs_list[0]["social_network_parameters"] == {}
    assert kwargs_list[0]["scenario"] == "baseline"
    pd.testing.assert_frame_equal(kwargs_list[0]["input_data"], input_data)


def test_make_model_kwargs_can_sweep_a_list_of_dictionaries():
    networks = [
        {"average_degree": 5, "rewiring_probability": 0.0},
        {"average_degree": 20, "rewiring_probability": 0.5},
    ]

    kwargs_list = _make_model_kwargs(
        {
            "scenario": ["baseline", "scenario1"],
            "social_network_parameters": networks,
        }
    )

    assert len(kwargs_list) == 4
    assert [kwargs["scenario"] for kwargs in kwargs_list] == [
        "baseline",
        "baseline",
        "scenario1",
        "scenario1",
    ]
    assert [
        kwargs["social_network_parameters"] for kwargs in kwargs_list
    ] == [networks[0], networks[1], networks[0], networks[1]]


def test_make_model_kwargs_still_expands_regular_parameter_iterables():
    kwargs_list = _make_model_kwargs(
        {
            "scenario": ("baseline", "scenario1"),
            "year_period": range(30, 32),
        }
    )

    assert kwargs_list == [
        {"scenario": "baseline", "year_period": 30},
        {"scenario": "baseline", "year_period": 31},
        {"scenario": "scenario1", "year_period": 30},
        {"scenario": "scenario1", "year_period": 31},
    ]


class ExoticParameterModel(Model):
    """Minimal model exercising the parameter types from the issue."""

    def __init__(
        self,
        input_data,
        scenario,
        social_network_parameters,
        year_period=30,
    ):
        super().__init__()
        self.input_data = input_data
        self.scenario = scenario
        self.social_network_parameters = social_network_parameters
        self.year_period = year_period
        self.schedule = BaseScheduler(self)
        self.running = True
        self.datacollector = DataCollector(
            model_reporters={
                # This both uses the complete scenario string and verifies that
                # input_data arrived as a DataFrame rather than as column names.
                "selected_input": lambda model: model.input_data.loc[
                    0, model.scenario
                ],
                "average_degree": lambda model: (
                    model.social_network_parameters["average_degree"]
                ),
                "year_period": lambda model: model.year_period,
            }
        )

    def step(self):
        self.datacollector.collect(self)
        self.schedule.step()
        self.running = False


def test_batch_run_accepts_dataframe_and_dict_with_scenario_sweep():
    """The public API must handle unhashable fixed values throughout the run."""
    scenarios = ["baseline", "scenario1", "scenario2"]
    input_data = pd.DataFrame(
        {"baseline": [1], "scenario1": [2], "scenario2": [3]}
    )
    network_parameters = {
        "average_degree": 10,
        "rewiring_probability": 0.1,
    }

    results = batch_run(
        ExoticParameterModel,
        parameters={
            "input_data": input_data,
            "scenario": scenarios,
            "social_network_parameters": network_parameters,
            "year_period": 30,
        },
        number_processes=1,
        iterations=1,
        max_steps=1,
        display_progress=False,
    )

    assert len(results) == 3
    assert [row["scenario"] for row in results] == scenarios
    assert [row["selected_input"] for row in results] == [1, 2, 3]

    for row in results:
        assert row["average_degree"] == 10
        assert row["year_period"] == 30
        assert row["social_network_parameters"] == network_parameters
        pd.testing.assert_frame_equal(row["input_data"], input_data)

import dimod
import pytest

from dwave.system import EmbeddingComposite
from dwave.system.warnings import WarningAction


def _sampler_with_embedding(embedding, target_edgelist):
    """Build an offline sampler that returns a deterministic embedding."""
    target_nodelist = sorted({
        qubit for chain in embedding.values() for qubit in chain
    })
    child = dimod.StructureComposite(
        dimod.ExactSolver(),
        nodelist=target_nodelist,
        edgelist=target_edgelist,
    )

    def find_embedding(source_edgelist, target_edgelist, **kwargs):
        return {variable: list(chain) for variable, chain in embedding.items()}

    return EmbeddingComposite(child, find_embedding=find_embedding)


def _get_saved_warnings(sampler, bqm, chain_strength=1.0):
    sampleset = sampler.sample(
        bqm,
        chain_strength=chain_strength,
        warnings=WarningAction.SAVE,
    )
    return sampleset.info.get("warnings", [])


@pytest.mark.parametrize("quadratic_bias", [-2.0, 2.0, -20.0, 20.0])
def test_no_chain_strength_warning_when_embedding_has_no_chains(quadratic_bias):
    # The -2 case is the two-variable problem from the issue. Larger biases
    # must behave identically: chain strength is irrelevant without chains.
    bqm = dimod.BinaryQuadraticModel.from_qubo({
        (0, 0): 1,
        (1, 1): 1,
        (0, 1): quadratic_bias,
    })
    sampler = _sampler_with_embedding(
        embedding={0: [0], 1: [1]},
        target_edgelist=[(0, 1)],
    )

    assert _get_saved_warnings(sampler, bqm) == []


def test_chain_strength_warning_is_still_issued_when_a_chain_exists():
    bqm = dimod.BinaryQuadraticModel.from_qubo({
        (0, 0): 1,
        (1, 1): 1,
        (0, 1): -2,
    })
    sampler = _sampler_with_embedding(
        embedding={0: [0, 1], 1: [2]},
        target_edgelist=[(0, 1), (0, 2), (1, 2)],
    )

    saved_warnings = _get_saved_warnings(sampler, bqm, chain_strength=1.0)

    assert len(saved_warnings) == 1
    assert "quadratic biases" in str(saved_warnings[0])


def test_no_chain_strength_warning_when_chain_strength_is_sufficient():
    bqm = dimod.BinaryQuadraticModel.from_qubo({
        (0, 0): 1,
        (1, 1): 1,
        (0, 1): -0.5,
    })
    sampler = _sampler_with_embedding(
        embedding={0: [0, 1], 1: [2]},
        target_edgelist=[(0, 1), (0, 2), (1, 2)],
    )

    assert _get_saved_warnings(sampler, bqm, chain_strength=1.0) == []

