import asyncio
import time

import pytest

from anyio.to_thread import run_sync


def _echo_after_delay(value):
    time.sleep(0.01)
    return value


def _raise_value_error():
    raise ValueError("worker failure")


def _run_top_level(loop, awaitable, timeout=2):
    """
    Run one top-level await as IPython does, but with a timeout so that a
    regression results in a test failure rather than a hung test suite.
    """
    async def bounded():
        return await asyncio.wait_for(awaitable, timeout)

    return loop.run_until_complete(bounded())


@pytest.fixture
def ipython_loop():
    loop = asyncio.new_event_loop()
    asyncio.set_event_loop(loop)
    try:
        yield loop
    finally:
        pending = [task for task in asyncio.all_tasks(loop) if not task.done()]
        for task in pending:
            task.cancel()

        if pending:
            loop.run_until_complete(asyncio.gather(*pending, return_exceptions=True))

        loop.close()
        asyncio.set_event_loop(None)


def test_run_sync_across_successive_top_level_awaits(ipython_loop):
    """Each run_until_complete() call must be able to use a worker thread."""
    results = [
        _run_top_level(ipython_loop, run_sync(_echo_after_delay, value))
        for value in ("first", "second", "third")
    ]

    assert results == ["first", "second", "third"]


def test_run_sync_top_level_await_after_worker_exception(ipython_loop):
    """A failed top-level call must not prevent later calls from running."""
    with pytest.raises(ValueError, match="worker failure"):
        _run_top_level(ipython_loop, run_sync(_raise_value_error))

    assert _run_top_level(
        ipython_loop, run_sync(_echo_after_delay, "after exception")
    ) == "after exception"


def test_concurrent_run_sync_calls_after_earlier_top_level_await(ipython_loop):
    """Worker cleanup from one top-level await must not break a later gather()."""
    assert _run_top_level(
        ipython_loop, run_sync(_echo_after_delay, "initial")
    ) == "initial"

    async def concurrent_calls():
        return await asyncio.gather(
            run_sync(_echo_after_delay, "first"),
            run_sync(_echo_after_delay, "second"),
            run_sync(_echo_after_delay, "third"),
        )

    assert _run_top_level(ipython_loop, concurrent_calls()) == [
        "first",
        "second",
        "third",
    ]


def test_run_sync_repeated_within_one_root_task():
    """The top-level-await fix must not disturb ordinary asyncio.run() usage."""
    async def main():
        first = await run_sync(_echo_after_delay, "first")
        second = await run_sync(_echo_after_delay, "second")
        return first, second

    assert asyncio.run(main()) == ("first", "second")

