import narwhals as nw


def _make_series(backend: str, data: list[Any]) -> Any:
    # Give empty inputs an explicit dtype to avoid backend-specific inference
    # warnings; dtype inference is not what these tests are exercising.
    if backend == "pandas":
        return pd.Series(data, dtype="float64" if not data else None)
    return pl.Series(data, dtype=pl.Float64 if not data else None)


@pytest.mark.parametrize("backend", ["pandas", "polars"])
@pytest.mark.parametrize(
    ("data", "expected"),
    [
        pytest.param([1.0, None, None, 2.0], 3, id="nulls-counted-once"),
        pytest.param([1, 2, 2, 3], 3, id="without-nulls"),
        pytest.param([None, None, None], 1, id="all-nulls"),
        pytest.param([], 0, id="empty"),
        pytest.param(["a", None, None, "b", "a"], 3, id="strings-with-nulls"),
    ],
)
def test_series_n_unique_counts_nulls_consistently(
    backend: str, data: list[Any], expected: int
) -> None:
    native_series = _make_series(backend, data)

    result = nw.from_native(native_series, series_only=True).n_unique()

    # Narwhals follows the Polars API: null is a distinct value, and repeated
    # nulls contribute only one to the count.
    assert result == expected


