    with pytest.raises(UnicodeEncodeError) as exc_info:
        profile.enforce(value)
    assert exc_info.value.reason == INVALID_WHITE_SPACE


def assert_compatibility_strip_or_diagnostic(value, expected):
    """Allow the explicitly permitted tab/LF/CR compatibility behavior."""
    try:
        result = NICKNAME.enforce(value)
    except UnicodeEncodeError as exc:
        # A strict strip(' ') implementation is also valid, but rejection
        # must use the new diagnostic rather than a generic base-class error.
        assert exc.reason == INVALID_WHITE_SPACE
    else:
        assert result == expected


@pytest.mark.parametrize(
    "value",
    [
        "  nickname  ",
        "  two   spaces  ",
        "\u00a0nickname\u00a0",
        " \u2003nickname\u3000 ",
        "\u00a0  nickname \u202f ",
    ],
)
def test_ascii_and_nonascii_spaces_are_still_mapped_and_stripped(value):
    expected = "two spaces" if "two" in value else "nickname"
    assert NICKNAME.enforce(value) == expected


def test_nonascii_spaces_are_mapped_before_interior_space_collapsing():
    assert NICKNAME.enforce("\u00a0one\u2003\u202ftwo\u3000") == "one two"


@pytest.mark.parametrize(
    "character",
    [
        "\v",       # U+000B
        "\f",       # U+000C
        "\x1c",     # U+001C
        "\x1d",     # U+001D
        "\x1e",     # U+001E
        "\x1f",     # U+001F
        "\x85",     # U+0085
        "\u2028",   # U+2028
        "\u2029",   # U+2029
    ],
)
def test_extra_python_whitespace_is_not_silently_stripped(character):
    # Unlike tab, LF, and CR, these were not part of the Nickname profile's
    # established compatibility stripping set. They require the new error.
    assert_invalid_white_space(character + "nick" + character)


@pytest.mark.parametrize(
    "value",
    [
        "\x1fb\x1f",
        "\u2028nick",
        "nick\u2029",
        "\x85nick\x85",
    ],
)
def test_issue_examples_report_the_new_diagnostic(value):
    assert_invalid_white_space(value)


@pytest.mark.parametrize(
    "value,expected",
    [
        ("\tc\r\n", "c"),
        (" \t nick \r ", "nick"),
        (" a\n", "a"),
        ("\na", "a"),
        ("\n a \n", "a"),
    ],
)
def test_tab_lf_and_cr_may_be_retained_for_compatibility(value, expected):
    assert_compatibility_strip_or_diagnostic(value, expected)


@pytest.mark.parametrize(
    "value",
    ["\v", "\f", "\x1c", "\x1d", "\x1e", "\x1f", "\x85", "\u2028", "\u2029"],
)
def test_invalid_whitespace_only_input_reports_diagnostic_before_empty(value):
    assert_invalid_white_space(value)


@pytest.mark.parametrize("value", ["\t", "\n", "\r", "\t\r\n"])
def test_compatibility_whitespace_only_input_has_appropriate_diagnostic(value):
    # Compatibility stripping produces an empty nickname; strict rejection
    # instead reports invalid_white_space. Neither may leak controls/other.
    with pytest.raises(UnicodeEncodeError) as exc_info:
        NICKNAME.enforce(value)
    assert exc_info.value.reason in {EMPTY, INVALID_WHITE_SPACE}


@pytest.mark.parametrize(
    "profile_name", ["NicknameCasePreserved", "NicknameCaseMapped"]
)
def test_new_diagnostic_is_used_by_both_nickname_variants(profile_name):
    assert_invalid_white_space("\x1fnick\x1f", get_profile(profile_name))


def test_new_diagnostic_also_applies_to_utf8_bytes_input():
    assert_invalid_white_space(b"\x1fnick\x1f")

from textwrap import dedent

import pytest

from wemake_python_styleguide.violations.refactoring import (
    UselessReturningElseViolation,
)
from wemake_python_styleguide.visitors.ast.conditions import UselessElseVisitor


def _run_visitor(parse_ast_tree, default_options, code):
    tree = parse_ast_tree(dedent(code))
    visitor = UselessElseVisitor(default_options, tree=tree)
    visitor.run()
    return visitor


@pytest.mark.parametrize(
    'code',
    [
        pytest.param(
            """
            def resolve_path(search_paths, relative_path):
                for search_path in search_paths:
                    template_relative_path = search_path / relative_path
                    if template_relative_path.exists():
                        break
                else:
                    raise UserMessageError(relative_path)
            """,
            id='issue-search-pattern',
        ),
        pytest.param(
            """
            def find(items):
                for item in items:
                    if item:
                        break
                else:
                    return None
                return item
            """,
            id='returning-else',
        ),
        pytest.param(
            """
            async def find(items):
                async for item in items:
                    if item:
                        break
                else:
                    raise ValueError
            """,
            id='async-for',
        ),
        pytest.param(
            """
            def find(items):
                while items:
                    if items.pop():
                        break
                else:
                    raise ValueError
            """,
            id='while',
        ),
        pytest.param(
            """
            def find(items, resource):
                for item in items:
                    with resource:
                        if item:
                            break
                else:
                    raise ValueError
            """,
            id='break-not-directly-inside-top-level-if',
        ),
    ],
)
def test_loop_else_with_break_is_meaningful(
    assert_errors,
    parse_ast_tree,
    default_options,
    code,
):
    """A loop ``else`` handles the case where its ``break`` was not run."""
    visitor = _run_visitor(parse_ast_tree, default_options, code)

    assert_errors(visitor, [])


@pytest.mark.parametrize(
    'code',
    [
        pytest.param(
            """
            def choose(items):
                for item in items:
                    return item
                else:
                    return None
            """,
            id='for-return',
        ),
        pytest.param(
            """
            async def choose(items):
                async for item in items:
                    return item
                else:
                    return None
            """,
            id='async-for-return',
        ),
        pytest.param(
            """
            def choose(items):
                while items:
                    return items.pop()
                else:
                    return None
            """,
            id='while-return',
        ),
        pytest.param(
            """
            def find(items):
                for item in items:
                    if item:
                        continue
                else:
                    raise ValueError
            """,
            id='continue-does-not-make-else-meaningful',
        ),
    ],
)
def test_useless_loop_else_is_still_reported(
    assert_errors,
    parse_ast_tree,
    default_options,
    code,
):
    """Loops without a ``break`` retain the original WPS503 behavior."""
    visitor = _run_visitor(parse_ast_tree, default_options, code)

    assert_errors(visitor, [UselessReturningElseViolation])


def test_nested_loop_break_does_not_exempt_outer_loop(
    assert_errors,
    parse_ast_tree,
    default_options,
):
    """Only a break belonging to the loop makes that loop's else useful."""
    code = """
    def choose(groups):
        for group in groups:
            if group:
                for item in group:
                    break
            return group
        else:
            return None
    """
    visitor = _run_visitor(parse_ast_tree, default_options, code)

    assert_errors(visitor, [UselessReturningElseViolation])

from __future__ import annotations

from typing import Any

import pandas as pd
import polars as pl
import pytest

import narwhals as nw


ISSUE_VALUES = [1.0, None, None, 2.0]


def _series_n_unique(native_series: Any) -> int:
    return nw.from_native(native_series, series_only=True).n_unique()


@pytest.mark.parametrize(
    "native_series",
    [
        pytest.param(pd.Series(ISSUE_VALUES), id="pandas"),
        pytest.param(
            pd.Series(ISSUE_VALUES, dtype="Float64"), id="pandas-nullable"
        ),
        pytest.param(
            pd.Series(ISSUE_VALUES, dtype="Float64[pyarrow]"),
            id="pandas-pyarrow",
        ),
        pytest.param(pl.Series(ISSUE_VALUES), id="polars"),
    ],
)
def test_n_unique_counts_null_as_a_unique_value(native_series: Any) -> None:
    """The two nulls form one additional unique value, as in Polars."""
    assert _series_n_unique(native_series) == 3


@pytest.mark.parametrize("backend", ["pandas", "polars"])
@pytest.mark.parametrize(
    ("values", "expected"),
    [
        pytest.param([1.0, 2.0, 2.0, 3.0], 3, id="without-nulls"),
        pytest.param([None, None, None], 1, id="all-nulls"),
        pytest.param([None], 1, id="single-null"),
        pytest.param([], 0, id="empty"),
    ],
)
def test_n_unique_null_edge_cases(
    backend: str, values: list[Any], expected: int
) -> None:
    if backend == "pandas":
        native_series = pd.Series(values, dtype="float64")
    else:
        native_series = pl.Series(values, dtype=pl.Float64)

    assert _series_n_unique(native_series) == expected


@pytest.mark.parametrize("backend", ["pandas", "polars"])
def test_n_unique_counts_repeated_nulls_once_for_strings(backend: str) -> None:
    values = ["a", None, "b", None, "a"]
    native_series = pd.Series(values) if backend == "pandas" else pl.Series(values)

    # The unique values are "a", "b", and null.
    assert _series_n_unique(native_series) == 3


@pytest.mark.parametrize(
    "native_df",
    [
        pytest.param(
            pd.DataFrame({"values": [1.0, None, None, 2.0, 1.0]}),
            id="pandas",
        ),
        pytest.param(
            pl.DataFrame({"values": [1.0, None, None, 2.0, 1.0]}),
            id="polars",
        ),
    ],
)
def test_n_unique_expression_counts_nulls(native_df: Any) -> None:
    result = nw.from_native(native_df).select(nw.col("values").n_unique())

    assert result["values"][0] == 3

"""Regression tests for batch_run with strings and exotic parameter values."""

import pandas as pd
import pytest

from mesa import Model
from mesa.batchrunner import batch_run
from mesa.datacollection import DataCollector
from mesa.time import BaseScheduler


class BatchRunModel(Model):
    """Minimal model that records the arguments it actually receives."""

    def __init__(self, **kwargs):
        super().__init__()
        self.received_kwargs = kwargs
        self.schedule = BaseScheduler(self)
        self.datacollector = DataCollector(
            model_reporters={
                "received_kwargs": lambda model: model.received_kwargs,
            }
        )
        self.running = True

    def step(self):
        self.datacollector.collect(self)
        self.schedule.step()
        self.running = False


def run_batch(parameters, iterations=1):
    return batch_run(
        BatchRunModel,
        parameters=parameters,
        number_processes=1,
        iterations=iterations,
        data_collection_period=1,
        max_steps=0,
        display_progress=False,
    )


def test_string_sweep_with_fixed_dataframe_and_dictionary():
    """A list of scenarios is swept while other exotic arguments stay intact."""
    input_data = pd.DataFrame(
        {"first_column": [1, 2], "second_column": [3, 4]}
    )
    network_parameters = {
        "average_degree": 10,
        "rewiring_probability": 0.1,
    }
    scenarios = ["baseline", "scenario1", "scenario2"]

    results = run_batch(
        {
            "input_data": input_data,
            "scenario": scenarios,
            "social_network_parameters": network_parameters,
            "year_period": 30,
        }
    )

    assert len(results) == len(scenarios)
    assert sorted(row["scenario"] for row in results) == sorted(scenarios)

    for row in results:
        # Check both the reported parameters and those received by the model.
        received = row["received_kwargs"]
        assert received["scenario"] == row["scenario"]
        assert received["year_period"] == 30
        assert received["social_network_parameters"] == network_parameters
        pd.testing.assert_frame_equal(received["input_data"], input_data)

        pd.testing.assert_frame_equal(row["input_data"], input_data)
        assert row["social_network_parameters"] == network_parameters
        assert row["year_period"] == 30


def test_single_string_is_not_split_into_characters():
    results = run_batch({"scenario": "baseline"})

    assert len(results) == 1
    assert results[0]["scenario"] == "baseline"
    assert results[0]["received_kwargs"]["scenario"] == "baseline"


@pytest.mark.parametrize(
    "value",
    [{}, pd.DataFrame()],
    ids=["empty-dictionary", "empty-dataframe"],
)
def test_empty_exotic_values_still_produce_one_run(value):
    """Empty dictionaries and DataFrames are values, not empty sweeps."""
    results = run_batch({"value": value})

    assert len(results) == 1
    if isinstance(value, pd.DataFrame):
        pd.testing.assert_frame_equal(results[0]["value"], value)
        pd.testing.assert_frame_equal(
            results[0]["received_kwargs"]["value"], value
        )
    else:
        assert results[0]["value"] == value
        assert results[0]["received_kwargs"]["value"] == value


def test_list_of_dictionaries_sweeps_whole_dictionary_values():
    configurations = [
        {"average_degree": 10, "rewiring_probability": 0.1},
        {"average_degree": 20, "rewiring_probability": 0.2},
    ]

    results = run_batch({"social_network_parameters": configurations})

    assert len(results) == 2
    observed = [row["social_network_parameters"] for row in results]
    assert all(isinstance(item, dict) for item in observed)
    for configuration in configurations:
        assert any(item == configuration for item in observed)
    for row in results:
        assert (
            row["received_kwargs"]["social_network_parameters"]
            == row["social_network_parameters"]
        )


def test_tuple_and_range_parameters_remain_iterable_sweeps():
    scenarios = ("baseline", "scenario1")
    years = range(2)

    results = run_batch({"scenario": scenarios, "year_period": years})

    expected = {(scenario, year) for scenario in scenarios for year in years}
    observed = {(row["scenario"], row["year_period"]) for row in results}
    assert len(results) == 4
    assert observed == expected


def test_iterations_work_with_unhashable_fixed_parameters():
    """Iteration bookkeeping must also support dictionaries and DataFrames."""
    network_parameters = {"average_degree": 10}

    results = run_batch(
        {"social_network_parameters": network_parameters}, iterations=3
    )

    assert len(results) == 3
    assert sorted(row["iteration"] for row in results) == [0, 1, 2]
    assert len({row["RunId"] for row in results}) == 3
    for row in results:
        assert row["social_network_parameters"] == network_parameters
        assert (
            row["received_kwargs"]["social_network_parameters"]
            == network_parameters
        )

import os
from pathlib import Path

import pytest

from compress_pickle import dump, load
from compress_pickle.compressers import (
    get_default_compression_mapping,
    get_registered_extensions,
)


PAYLOAD = {"message": "preserve the supplied path", "values": [1, 2, 3]}


def _expected_default_path(path, compression):
    """Reproduce the documented extension replacement for an invalid suffix."""
    root, _ = os.path.splitext(os.fspath(path))
    default_extension = get_default_compression_mapping()[compression]
    return Path(root + default_extension)


def _registered_extension_cases():
    registered = get_registered_extensions()
    return [
        pytest.param(compression, extension, id=f"{compression}-{extension}")
        for compression in ("gzip", "bz2", "lzma", "zipfile")
        for extension, extension_compression in registered.items()
        if extension_compression == compression
    ]


@pytest.mark.parametrize("path_kind", ["pathlib", "str", "bytes"])
def test_pkl_gz_path_is_preserved_with_inferred_compression(tmp_path, path_kind):
    """The reported path must be used verbatim for both writing and reading."""
    path = tmp_path / "object.pkl.gz"
    if path_kind == "str":
        supplied_path = str(path)
    elif path_kind == "bytes":
        supplied_path = os.fsencode(path)
    else:
        supplied_path = path

    dump(PAYLOAD, supplied_path, compression="infer")

    assert path.is_file()
    assert not (tmp_path / "object.pklgz").exists()
    assert {entry.name for entry in tmp_path.iterdir()} == {"object.pkl.gz"}
    assert load(supplied_path, compression="infer") == PAYLOAD


@pytest.mark.parametrize("compression,extension", _registered_extension_cases())
def test_compound_path_with_registered_extension_is_preserved(
    tmp_path, compression, extension
):
    """Compound suffixes must work for every standard compression and alias."""
    path = tmp_path / f"object.pkl.{extension}"

    dump(PAYLOAD, path, compression=compression)

    assert path.is_file()
    assert {entry.name for entry in tmp_path.iterdir()} == {path.name}
    assert load(path, compression=compression) == PAYLOAD


def test_unrecognized_extension_still_receives_the_default(tmp_path):
    """Fixing valid paths must not disable set_default_extension altogether."""
    requested_path = tmp_path / "object.unregistered"
    expected_path = _expected_default_path(requested_path, "gzip")

    dump(PAYLOAD, requested_path, compression="gzip")

    assert expected_path != requested_path
    assert expected_path.is_file()
    assert not requested_path.exists()
    assert load(requested_path, compression="gzip") == PAYLOAD


def test_extension_for_another_compression_is_not_preserved(tmp_path):
    """A gzip suffix is not a valid bz2 suffix when bz2 is explicitly requested."""
    requested_path = tmp_path / "object.pkl.gz"
    expected_path = _expected_default_path(requested_path, "bz2")

    dump(PAYLOAD, requested_path, compression="bz2")

    assert expected_path != requested_path
    assert expected_path.is_file()
    assert not requested_path.exists()
    assert load(requested_path, compression="bz2") == PAYLOAD


def test_set_default_extension_false_uses_path_verbatim(tmp_path):
    """The existing opt-out must continue to support arbitrary user paths."""
    path = tmp_path / "object.custom"

    dump(PAYLOAD, path, compression="gzip", set_default_extension=False)

    assert path.is_file()
    assert {entry.name for entry in tmp_path.iterdir()} == {path.name}
    assert (
        load(path, compression="gzip", set_default_extension=False) == PAYLOAD
    )

"""Regression tests for chain-strength warnings without using a QPU."""

import dimod
import pytest

from dwave.system import EmbeddingComposite
from dwave.system.warnings import ChainStrengthWarning


def _sample_with_embedding(bqm, embedding, target_edgelist, chain_strength):
    """Sample through EmbeddingComposite using a deterministic embedding."""
    target_nodelist = sorted({
        qubit for chain in embedding.values() for qubit in chain
    })
    child = dimod.StructureComposite(
        dimod.ExactSolver(), target_nodelist, target_edgelist
    )

    def find_embedding(source_edgelist, target_edgelist, **kwargs):
        return {v: tuple(chain) for v, chain in embedding.items()}

    sampler = EmbeddingComposite(child, find_embedding=find_embedding)
    return sampler.sample(
        bqm, chain_strength=chain_strength, warnings="SAVE"
    )


def _chain_strength_warnings(sampleset):
    return [
        warning for warning in sampleset.info.get("warnings", [])
        if issubclass(warning["type"], ChainStrengthWarning)
    ]


def test_issue_example_does_not_warn_without_chains():
    """The two-variable QUBO from the issue needs only singleton chains."""
    bqm = dimod.BinaryQuadraticModel.from_qubo(
        {(0, 0): 1, (1, 1): 1, (0, 1): -2}
    )

    sampleset = _sample_with_embedding(
        bqm,
        embedding={0: (0,), 1: (1,)},
        target_edgelist=[(0, 1)],
        chain_strength=1.0,
    )

    assert _chain_strength_warnings(sampleset) == []


@pytest.mark.parametrize("bias", [10.0, 100.0, -1000.0])
def test_strong_quadratic_bias_does_not_warn_without_chains(bias):
    """Bias magnitude is irrelevant to chain strength when no chains exist."""
    bqm = dimod.BinaryQuadraticModel.from_ising({}, {(0, 1): bias})

    sampleset = _sample_with_embedding(
        bqm,
        embedding={0: (0,), 1: (1,)},
        target_edgelist=[(0, 1)],
        chain_strength=1.0,
    )

    assert _chain_strength_warnings(sampleset) == []


def test_strong_quadratic_bias_still_warns_when_a_chain_exists():
    """Suppressing the chainless case must not disable the useful warning."""
    bqm = dimod.BinaryQuadraticModel.from_ising({}, {("a", "b"): 4.0})

    sampleset = _sample_with_embedding(
        bqm,
        embedding={"a": (0, 1), "b": (2,)},
        target_edgelist=[(0, 1), (1, 2)],
        chain_strength=1.0,
    )

    assert len(_chain_strength_warnings(sampleset)) == 1


def test_no_warning_when_chain_strength_is_sufficient():
    bqm = dimod.BinaryQuadraticModel.from_ising({}, {("a", "b"): 4.0})

    sampleset = _sample_with_embedding(
        bqm,
        embedding={"a": (0, 1), "b": (2,)},
        target_edgelist=[(0, 1), (1, 2)],
        chain_strength=5.0,
    )

    assert _chain_strength_warnings(sampleset) == []

