        continue
else:
    raise LookupError('No valid item found')
"""


@pytest.mark.parametrize('code', [
    reported_search_pattern,
    async_search_pattern,
    while_search_pattern,
    nested_conditional_break_pattern,
], ids=[
    'reported-for-search',
    'async-for-search',
    'while-search',
    'break-nested-in-try',
])
def test_loop_else_with_conditional_break_is_meaningful(
    code,
    assert_errors,
    parse_ast_tree,
    default_options,
):
    """A break belonging to a loop makes its ``else`` clause meaningful."""
    tree = parse_ast_tree(code)

    visitor = UselessElseVisitor(default_options, tree=tree)
    visitor.run()

    assert_errors(visitor, [])


loop_else_without_break = """
for item in items:
    if item:
        raise ValueError(item)
else:
    raise LookupError('No items were processed')
"""

inner_loop_break_only = """
for outer in items:
    if outer:
        for inner in outer:
            break
else:
    raise LookupError('No outer items were processed')
"""


@pytest.mark.parametrize('code', [
    loop_else_without_break,
    inner_loop_break_only,
], ids=[
    'no-break',
    'break-belongs-to-inner-loop',
])
def test_still_reports_useless_loop_else(
    code,
    assert_errors,
    parse_ast_tree,
    default_options,
):
    """Only a break of the loop itself should exempt its ``else`` clause."""
    tree = parse_ast_tree(code)

    visitor = UselessElseVisitor(default_options, tree=tree)
    visitor.run()

    assert_errors(visitor, [UselessReturningElseViolation])

"""Regression tests for chain-strength warnings during embedding."""

import dimod
import pytest

from dwave.system import EmbeddingComposite
from dwave.system.warnings import WarningAction


CHAIN_STRENGTH_MESSAGE = (
    "Some quadratic biases are stronger than the given chain strength"
)


def _composite_with_embedding(nodelist, edgelist, embedding):
    """Build an EmbeddingComposite with a deterministic embedding."""
    child = dimod.StructureComposite(
        dimod.ExactSolver(), nodelist=nodelist, edgelist=edgelist
    )

    def find_embedding(source_edgelist, target_edgelist, **kwargs):
        return embedding

    return EmbeddingComposite(child, find_embedding=find_embedding)


def _saved_warning_messages(sampleset):
    messages = []
    for warning in sampleset.info.get("warnings", []):
        if isinstance(warning, dict):
            messages.append(str(warning.get("message", warning)))
        else:
            messages.append(str(getattr(warning, "message", warning)))
    return messages


@pytest.mark.parametrize("quadratic_bias", [-2.0, -10.0, -50.0])
def test_no_chain_strength_warning_when_embedding_has_no_chains(quadratic_bias):
    """Chain strength is irrelevant when every chain contains one node.

    The first bias reproduces the issue's two-variable QUBO. The stronger
    biases ensure that the absence of the warning does not depend on the
    magnitude of the problem's interactions.
    """
    bqm = dimod.BinaryQuadraticModel.from_qubo(
        {(0, 0): 1, (1, 1): 1, (0, 1): quadratic_bias}
    )
    sampler = _composite_with_embedding(
        nodelist=[0, 1],
        edgelist=[(0, 1)],
        embedding={0: [0], 1: [1]},
    )

    # The default chain_strength=1.0 is weaker than each quadratic bias, but
    # no chain-strength warning should be saved because there are no chains.
    sampleset = sampler.sample(bqm, warnings=WarningAction.SAVE)

    assert not any(
        CHAIN_STRENGTH_MESSAGE in message
        for message in _saved_warning_messages(sampleset)
    )


def test_chain_strength_warning_is_still_saved_for_real_chains():
    """Removing the spurious warning must not hide useful chain warnings."""
    bqm = dimod.BinaryQuadraticModel.from_qubo(
        {("a", "a"): 1, ("b", "b"): 1, ("a", "b"): -2}
    )
    sampler = _composite_with_embedding(
        nodelist=[0, 1, 2],
        edgelist=[(0, 1), (0, 2), (1, 2)],
        embedding={"a": [0, 1], "b": [2]},
    )

    # Variable "a" is represented by a two-node chain, and the default chain
    # strength of 1.0 is weaker than the quadratic bias of magnitude 2.0.
    sampleset = sampler.sample(bqm, warnings=WarningAction.SAVE)

    assert any(
        CHAIN_STRENGTH_MESSAGE in message
        for message in _saved_warning_messages(sampleset)
    )


def test_no_chain_strength_warning_when_real_chains_are_strong_enough():
    """A real chain alone should not cause a warning."""
    bqm = dimod.BinaryQuadraticModel.from_qubo(
        {("a", "a"): 1, ("b", "b"): 1, ("a", "b"): -2}
    )
    sampler = _composite_with_embedding(
        nodelist=[0, 1, 2],
        edgelist=[(0, 1), (0, 2), (1, 2)],
        embedding={"a": [0, 1], "b": [2]},
    )

    sampleset = sampler.sample(
        bqm, chain_strength=3.0, warnings=WarningAction.SAVE
    )

    assert not any(
        CHAIN_STRENGTH_MESSAGE in message
        for message in _saved_warning_messages(sampleset)
    )

import dimod

from dwave.system import EmbeddingComposite
