import pytest

from wemake_python_styleguide.violations.refactoring import (
    UselessReturningElseViolation,
)
from wemake_python_styleguide.visitors.ast.conditions import UselessElseVisitor


issue_example = """
def resolve_template(self, relative_path):
    for search_path in self.environment.loader.searchpath:
        template_relative_path = Path(search_path) / relative_path
        if template_relative_path.exists():
            break
    else:
        raise UserMessageError(
            f"Could not resolve path to local extension module "
            f"'{relative_path}'",
        )
"""

returning_search = """
def find_item(items):
    for item in items:
        if item.is_valid():
            break
    else:
        return None
    return item
"""

async_search = """
async def find_item(items):
    async for item in items:
        if item.is_valid():
            break
    else:
        raise LookupError()
"""

break_inside_try = """
def find_path(paths):
    for path in paths:
        try:
            if path.exists():
                break
        except OSError:
            continue
    else:
        raise LookupError()
"""


@pytest.mark.parametrize('code', [
    issue_example,
    returning_search,
    async_search,
    break_inside_try,
], ids=[
    'issue-example',
    'return-not-found',
    'async-for',
    'conditional-break-inside-try',
])
def test_conditional_break_makes_loop_else_meaningful(
    assert_errors,
    parse_ast_tree,
    default_options,
    code,
):
    """A loop ``else`` handles the case where no ``break`` happened."""
    tree = parse_ast_tree(code)

    visitor = UselessElseVisitor(default_options, tree=tree)
    visitor.run()

    assert_errors(visitor, [])


returning_loop = """
def find_item(items):
    for item in items:
        if item.is_valid():
            return item
    else:
        return None
"""

continuing_loop = """
def find_item(items):
    for item in items:
        if item.is_valid():
            continue
    else:
        raise LookupError()
"""


@pytest.mark.parametrize('code', [
    returning_loop,
    continuing_loop,
], ids=['returning-body', 'continuing-body'])
def test_removable_for_else_is_still_reported(
    assert_errors,
    parse_ast_tree,
    default_options,
    code,
):
    """The exception for searches must not disable other WPS503 cases."""
    tree = parse_ast_tree(code)

    visitor = UselessElseVisitor(default_options, tree=tree)
    visitor.run()

    assert_errors(visitor, [UselessReturningElseViolation])


nested_loop_break = """
def find_item(items):
    for item in items:
        if item:
            for child in item:
                break
    else:
        raise LookupError()
"""


def test_nested_loop_break_does_not_exempt_outer_loop(
    assert_errors,
    parse_ast_tree,
    default_options,
):
    """A ``break`` belonging to an inner loop does not affect outer ``else``."""
    tree = parse_ast_tree(nested_loop_break)

    visitor = UselessElseVisitor(default_options, tree=tree)
    visitor.run()

    assert_errors(visitor, [UselessReturningElseViolation])

"""Regression tests for chain-strength warnings without hardware access."""

import dimod
import pytest

from dwave.system import EmbeddingComposite
from dwave.system.warnings import ChainStrengthWarning


def _sample_with_embedding(bqm, embedding, target_edgelist, chain_strength=1.0):
    """Sample using a deterministic embedding so chain usage is unambiguous."""
    target_nodelist = {
        qubit for chain in embedding.values() for qubit in chain
    }
    target_nodelist.update(
        qubit for edge in target_edgelist for qubit in edge
    )

    child = dimod.StructureComposite(
        dimod.RandomSampler(), sorted(target_nodelist), target_edgelist
    )

    def find_embedding(source_edgelist, target_edgelist, **kwargs):
        return {v: list(chain) for v, chain in embedding.items()}

    sampler = EmbeddingComposite(child, find_embedding=find_embedding)
    sampleset = sampler.sample(
        bqm,
        chain_strength=chain_strength,
        warnings="SAVE",
        return_embedding=True,
        num_reads=8,
    )

    # Ensure the problem was actually sampled and unembedded successfully.
    assert set(sampleset.variables) == set(bqm.variables)
    assert len(sampleset) > 0
    return sampleset


def _chain_strength_warnings(sampleset):
    return [
        warning
        for warning in sampleset.info.get("warnings", [])
        if issubclass(warning["type"], ChainStrengthWarning)
    ]


def _returned_embedding(sampleset):
    return sampleset.info["embedding_context"]["embedding"]


@pytest.mark.parametrize("bias", [-2.0, -1.0, 1.0, 2.0])
def test_no_chain_strength_warning_when_embedding_has_no_chains(bias):
    """Strong source couplings are irrelevant when every chain is one qubit."""
    # This is the issue's two-variable QUBO, including biases both stronger
    # than and equal to the default chain strength.
    bqm = dimod.BinaryQuadraticModel.from_qubo(
        {(0, 0): 1, (1, 1): 1, (0, 1): bias}
    )

    sampleset = _sample_with_embedding(
        bqm,
        embedding={0: [0], 1: [1]},
        # Extra target connectivity must not itself count as a chain.
        target_edgelist=[(0, 1), (1, 2)],
    )

    assert all(
        len(chain) == 1 for chain in _returned_embedding(sampleset).values()
    )
    assert _chain_strength_warnings(sampleset) == []


def test_no_chain_strength_warning_for_larger_chain_free_embedding():
    """The suppression is based on chain usage, not on having two variables."""
    bqm = dimod.BinaryQuadraticModel.from_ising(
        {}, {(0, 1): -2.0, (1, 2): 3.0, (0, 2): 1.0}
    )

    sampleset = _sample_with_embedding(
        bqm,
        embedding={0: [0], 1: [1], 2: [2]},
        target_edgelist=[(0, 1), (1, 2), (0, 2)],
    )

    assert all(
        len(chain) == 1 for chain in _returned_embedding(sampleset).values()
    )
    assert _chain_strength_warnings(sampleset) == []


@pytest.mark.parametrize("bias", [-2.0, 1.0])
def test_chain_strength_warning_is_retained_when_chains_exist(bias):
    """The fix must not disable the useful warning for actual chains."""
    bqm = dimod.BinaryQuadraticModel.from_qubo(
        {(0, 0): 1, (1, 1): 1, (0, 1): bias}
    )

    sampleset = _sample_with_embedding(
        bqm,
        embedding={0: [0, 1], 1: [2]},
        target_edgelist=[(0, 1), (1, 2)],
    )

    assert any(
        len(chain) > 1 for chain in _returned_embedding(sampleset).values()
    )

    warnings = _chain_strength_warnings(sampleset)
    assert len(warnings) == 1
    assert {
        tuple(sorted(interaction))
        for interaction in warnings[0]["data"]["source_interactions"]
    } == {(0, 1)}


def test_weak_couplings_do_not_warn_even_when_chains_exist():
    bqm = dimod.BinaryQuadraticModel.from_qubo(
        {(0, 0): 1, (1, 1): 1, (0, 1): -0.5}
    )

    sampleset = _sample_with_embedding(
        bqm,
        embedding={0: [0, 1], 1: [2]},
        target_edgelist=[(0, 1), (1, 2)],
        chain_strength=1.0,
    )

    assert any(
        len(chain) > 1 for chain in _returned_embedding(sampleset).values()
    )
    assert _chain_strength_warnings(sampleset) == []

import os

from pre_commit.meta_hooks import check_useless_excludes
from pre_commit.util import cmd_output
from testing.fixtures import add_config_to_repo


def test_exclude_matching_broken_symlink_is_useful(capsys, in_git_dir):
    # A symlink into a deinitialized submodule is still a tracked filesystem
    # entry, even though its target cannot be followed.
    os.symlink('submodule/some_file.txt', 'link-to-submodule')
    assert os.path.lexists('link-to-submodule')
    assert not os.path.exists('link-to-submodule')
    cmd_output('git', 'add', 'link-to-submodule')

    config = {
        'repos': [
            {
                'repo': 'meta',
                'hooks': [
                    {
                        'id': 'check-useless-excludes',
                        'types': ['symlink'],
                        'exclude': '^link-to-submodule$',
                    },
                ],
            },
        ],
    }
    add_config_to_repo(in_git_dir.strpath, config)

    assert check_useless_excludes.main(()) == 0
    out, _ = capsys.readouterr()
    assert out == ''


def test_broken_symlink_exclude_still_respects_type_filters(
        capsys, in_git_dir,
):
    os.symlink('missing-target', 'broken-link')
    cmd_output('git', 'add', 'broken-link')

    # The default file type does not select symlinks.  Merely retaining broken
    # symlinks in the classifier must not make every matching exclude useful.
    config = {
        'repos': [
            {
                'repo': 'meta',
                'hooks': [
                    {
                        'id': 'check-useless-excludes',
                        'exclude': '^broken-link$',
                    },
                ],
            },
        ],
    }
    add_config_to_repo(in_git_dir.strpath, config)

    assert check_useless_excludes.main(()) == 1
    out, _ = capsys.readouterr()
    assert out.strip() == (
        "The exclude pattern '^broken-link$' for check-useless-excludes "
        'does not match any files'
    )


def test_exclude_for_file_rejected_by_types_is_useless(capsys, in_git_dir):
    config = {
        'repos': [
            {
                'repo': 'meta',
                'hooks': [
                    {
                        'id': 'check-useless-excludes',
                        'types': ['python'],
                        'exclude': '.pre-commit-config.yaml',
                    },
                ],
            },
        ],
    }
    add_config_to_repo(in_git_dir.strpath, config)

    # The exclude matches the config filename, but the hook would never run on
    # that file because it is not Python, so the exclude is still useless.
    assert check_useless_excludes.main(()) == 1
    out, _ = capsys.readouterr()
    assert out.strip() == (
        "The exclude pattern '.pre-commit-config.yaml' for "
        'check-useless-excludes does not match any files'
    )

import dimod
import pytest

from dwave.system import EmbeddingComposite, FixedEmbeddingComposite
from dwave.system.warnings import ChainStrengthWarning


def _chain_strength_warnings(sampleset):
    return [
        warning
        for warning in sampleset.info.get("warnings", [])
        if issubclass(warning["type"], ChainStrengthWarning)
    ]


def _fixed_embedding_sampler(embedding, nodelist, edgelist):
    child = dimod.StructureComposite(
        dimod.RandomSampler(), nodelist=nodelist, edgelist=edgelist
    )
    return FixedEmbeddingComposite(child, embedding)


def test_issue_qubo_without_chains_has_no_chain_strength_warning():
    """The two-variable QUBO from the issue fits without any chains."""
    child = dimod.StructureComposite(
        dimod.RandomSampler(), nodelist=[0, 1], edgelist=[(0, 1)]
    )

    # Make the no-chain embedding deterministic rather than relying on the
    # heuristic embedding algorithm to choose one.
    def find_embedding(source_edgelist, target_edgelist, **kwargs):
        return {0: [0], 1: [1]}

    sampler = EmbeddingComposite(child, find_embedding=find_embedding)
    bqm = dimod.BinaryQuadraticModel.from_qubo(
        {(0, 0): 1, (1, 1): 1, (0, 1): -2}
    )

    sampleset = sampler.sample(
        bqm,
        num_reads=10,
        warnings="SAVE",
        return_embedding=True,
    )

    embedding = sampleset.info["embedding_context"]["embedding"]
    assert embedding
    assert all(len(chain) == 1 for chain in embedding.values())
    assert _chain_strength_warnings(sampleset) == []


def test_no_chain_strength_warning_for_any_strong_couplings_without_chains():
    """Suppressing the warning must depend on chains, not problem size."""
    sampler = _fixed_embedding_sampler(
        embedding={0: [0], 1: [1], 2: [2]},
        nodelist=[0, 1, 2],
        edgelist=[(0, 1), (1, 2)],
    )

    # Include positive and negative biases, and one exactly equal to the
    # chain strength. All would have triggered the old warning.
    sampleset = sampler.sample_ising(
        {},
        {(0, 1): 5.0, (1, 2): -1.0},
        chain_strength=1.0,
        warnings="SAVE",
        num_reads=10,
        return_embedding=True,
    )

    embedding = sampleset.info["embedding_context"]["embedding"]
    assert all(len(chain) == 1 for chain in embedding.values())
    assert _chain_strength_warnings(sampleset) == []


@pytest.mark.parametrize(
    "bias, expected_warning_count",
    [
        (-2.0, 1),
        (-1.0, 1),  # equality retains the existing warning threshold
        (1.0, 1),
        (2.0, 1),
        (-0.5, 0),
        (0.5, 0),
    ],
)
def test_chain_strength_warning_is_preserved_when_a_chain_exists(
    bias, expected_warning_count
):
    sampler = _fixed_embedding_sampler(
        embedding={"a": [0, 1], "b": [2]},
        nodelist=[0, 1, 2],
        edgelist=[(0, 1), (1, 2)],
    )
    assert any(len(chain) > 1 for chain in sampler.embedding.values())

    sampleset = sampler.sample_ising(
        {},
        {("a", "b"): bias},
        chain_strength=1.0,
        warnings="SAVE",
        num_reads=10,
    )

    warnings = _chain_strength_warnings(sampleset)
    assert len(warnings) == expected_warning_count

    if warnings:
        assert warnings[0]["message"] == (
            "Some quadratic biases are stronger than the given chain strength"
        )
        reported = {
            frozenset(interaction)
            for interaction in warnings[0]["data"]["source_interactions"]
        }
        assert reported == {frozenset(("a", "b"))}


def test_chain_strength_warning_reports_only_strong_interactions():
    sampler = _fixed_embedding_sampler(
        embedding={"a": [0, 1], "b": [2], "c": [3]},
        nodelist=[0, 1, 2, 3],
        edgelist=[(0, 1), (1, 2), (2, 3)],
    )

    sampleset = sampler.sample_ising(
        {},
        {("a", "b"): -2.0, ("b", "c"): 0.25},
        chain_strength=1.0,
        warnings="SAVE",
        num_reads=10,
    )

    warnings = _chain_strength_warnings(sampleset)
    assert len(warnings) == 1
    reported = {
        frozenset(interaction)
        for interaction in warnings[0]["data"]["source_interactions"]
    }
    assert reported == {frozenset(("a", "b"))}

import os

import pytest

from compress_pickle import dump, load


PAYLOAD = {"message": "preserve the filename", "values": [1, 2, 3]}


@pytest.mark.parametrize("path_kind", ["pathlib", "str", "bytes"])
@pytest.mark.parametrize("compression", ["infer", "gzip"])
def test_pkl_gz_path_is_stored_exactly_as_requested(
    tmp_path, path_kind, compression
):
    """The reported path must not lose the dot before its gzip extension."""
    directory = tmp_path / "directory.with.dots"
    directory.mkdir()
    expected_path = directory / "data.pkl.gz"

    if path_kind == "pathlib":
        supplied_path = expected_path
    elif path_kind == "str":
        supplied_path = str(expected_path)
    else:
        supplied_path = os.fsencode(str(expected_path))

    dump(PAYLOAD, supplied_path, compression=compression)

    assert expected_path.is_file()
    assert {path.name for path in directory.iterdir()} == {"data.pkl.gz"}
    assert not (directory / "data.pklgz").exists()
    assert load(supplied_path, compression=compression) == PAYLOAD


@pytest.mark.parametrize(
    ("compression", "filename"),
    [
        ("bz2", "data.pkl.bz"),
        ("lzma", "data.pkl.lzma"),
        ("zipfile", "data.pkl.zip"),
        (None, "data.pkl"),
        ("pickle", "data.pkl"),
