import pytest

from wemake_python_styleguide.violations.refactoring import (
    UselessReturningElseViolation,
)
from wemake_python_styleguide.visitors.ast.conditions import UselessElseVisitor


issue_example = """
def resolve_template_path(search_paths, relative_path):
    for search_path in search_paths:
        template_relative_path = search_path / relative_path
        if template_relative_path.exists():
            break
    else:
        raise UserMessageError(
            'Could not resolve path to local extension module',
        )
"""

async_for_else = """
async def find_item(items, target):
    async for item in items:
        if item == target:
            break
    else:
        raise LookupError(target)
"""

for_else_with_break_in_try = """
def find_item(items, target):
    for item in items:
        try:
            if item == target:
                break
        except ValueError:
            pass
    else:
        raise LookupError(target)
"""

for_else_with_break_in_with = """
def find_item(items, target, context):
    for item in items:
        with context:
            if item == target:
                break
    else:
        raise LookupError(target)
"""

for_else_without_break = """
def find_item(items, target):
    for item in items:
        if item == target:
            return item
    else:
        raise LookupError(target)
"""

for_else_with_unconditional_break = """
def find_item(items):
    for item in items:
        break
    else:
        raise LookupError(item)
"""

for_else_with_break_in_nested_loop_only = """
def find_item(rows, target):
    for row in rows:
        if row:
            for cell in row:
                if cell == target:
                    break
    else:
        raise LookupError(target)
"""


def test_for_else_search_pattern_is_not_useless(
    assert_errors,
    parse_ast_tree,
    default_options,
):
    """A conditional ``break`` makes the ``for``'s ``else`` meaningful."""
    tree = parse_ast_tree(issue_example)

    visitor = UselessElseVisitor(default_options, tree=tree)
    visitor.run()

    assert_errors(visitor, [])


@pytest.mark.parametrize('code', [
    pytest.param(async_for_else, id='async-for'),
    pytest.param(for_else_with_break_in_try, id='break-inside-try'),
    pytest.param(for_else_with_break_in_with, id='break-inside-with'),
])
def test_for_else_search_pattern_variations_are_not_useless(
    assert_errors,
    parse_ast_tree,
    default_options,
    code,
):
    """Async loops and nested statements have the same ``else`` semantics."""
    tree = parse_ast_tree(code)

    visitor = UselessElseVisitor(default_options, tree=tree)
    visitor.run()

    assert_errors(visitor, [])


@pytest.mark.parametrize('code', [
    pytest.param(for_else_without_break, id='no-break'),
    pytest.param(for_else_with_unconditional_break, id='unconditional-break'),
    pytest.param(
        for_else_with_break_in_nested_loop_only,
        id='break-belongs-to-nested-loop',
    ),
])
def test_actually_useless_for_else_is_still_reported(
    assert_errors,
    parse_ast_tree,
    default_options,
    code,
):
    """Only a ``break`` belonging to the loop makes its ``else`` useful."""
    tree = parse_ast_tree(code)

    visitor = UselessElseVisitor(default_options, tree=tree)
    visitor.run()

    assert_errors(visitor, [UselessReturningElseViolation])

