"""Regression tests for chain-strength warnings without using QPU hardware."""

import dimod
import pytest

from dwave.system import EmbeddingComposite
from dwave.system.warnings import ChainStrengthWarning


def _sample_with_embedding(bqm, embedding, chain_strength=1.0):
    """Sample using a deterministic embedding on a three-qubit path."""
    child = dimod.StructureComposite(
        dimod.RandomSampler(),
        nodelist=[0, 1, 2],
        edgelist=[(0, 1), (1, 2)],
    )

    def find_embedding(*args, **kwargs):
        return embedding

    sampler = EmbeddingComposite(child, find_embedding=find_embedding)
    return sampler.sample(
        bqm,
        chain_strength=chain_strength,
        warnings="SAVE",
        return_embedding=True,
        num_reads=5,
    )


def _chain_strength_warnings(sampleset):
    return [
        warning
        for warning in sampleset.info.get("warnings", [])
        if issubclass(warning["type"], ChainStrengthWarning)
    ]


def test_issue_example_has_no_chain_strength_warning_without_chains():
    """The strong QUBO coupling is irrelevant when every chain is a singleton."""
    bqm = dimod.BinaryQuadraticModel.from_qubo(
        {(0, 0): 1, (1, 1): 1, (0, 1): -2}
    )
    embedding = {0: [0], 1: [1]}

    sampleset = _sample_with_embedding(bqm, embedding, chain_strength=1.0)

    returned_embedding = sampleset.info["embedding_context"]["embedding"]
    assert all(len(chain) == 1 for chain in returned_embedding.values())
    assert _chain_strength_warnings(sampleset) == []


def test_no_chain_strength_warning_for_larger_embedding_without_chains():
    """Suppression is based on the absence of chains, not the problem size."""
    bqm = dimod.BinaryQuadraticModel.from_ising(
        {}, {(0, 1): -5.0, (1, 2): 3.0}
    )
    embedding = {0: [0], 1: [1], 2: [2]}

    sampleset = _sample_with_embedding(bqm, embedding, chain_strength=1.0)

    assert all(len(chain) == 1 for chain in embedding.values())
    assert _chain_strength_warnings(sampleset) == []


@pytest.mark.parametrize("bias", [-2.0, 2.0, -1.0])
def test_chain_strength_warning_is_retained_when_chains_exist(bias):
    """Strong couplings still warn with chains, including at the threshold."""
    bqm = dimod.BinaryQuadraticModel.from_ising({}, {("a", "b"): bias})
    # The a-chain uses target edge (0, 1); the source coupling uses (1, 2).
    embedding = {"a": [0, 1], "b": [2]}

    sampleset = _sample_with_embedding(bqm, embedding, chain_strength=1.0)

    assert any(len(chain) > 1 for chain in embedding.values())
    warnings = _chain_strength_warnings(sampleset)
    assert len(warnings) == 1
    assert set(warnings[0]["data"]["source_interactions"]) == {("a", "b")}


@pytest.mark.parametrize("bias", [-0.5, 0.5])
def test_no_chain_strength_warning_for_weak_couplings_with_chains(bias):
    """The presence of a chain alone must not produce the warning."""
    bqm = dimod.BinaryQuadraticModel.from_ising({}, {("a", "b"): bias})
    embedding = {"a": [0, 1], "b": [2]}

    sampleset = _sample_with_embedding(bqm, embedding, chain_strength=1.0)

    assert any(len(chain) > 1 for chain in embedding.values())
    assert _chain_strength_warnings(sampleset) == []

