import dimod
import pytest

from dwave.system import EmbeddingComposite
from dwave.system.warnings import ChainStrengthWarning


def _sampler_with_embedding(embedding, edgelist):
    """Build an EmbeddingComposite with a deterministic, valid embedding."""
    nodelist = sorted({qubit for chain in embedding.values() for qubit in chain})
    child = dimod.StructureComposite(
        dimod.RandomSampler(), nodelist=nodelist, edgelist=edgelist
    )

    def find_embedding(source_edgelist, target_edgelist, **kwargs):
        # Return a copy so sampling cannot mutate the test's embedding.
        return {v: list(chain) for v, chain in embedding.items()}

    return EmbeddingComposite(child, find_embedding=find_embedding)


def _sample(bqm, embedding, edgelist, chain_strength=1.0):
    sampler = _sampler_with_embedding(embedding, edgelist)
    return sampler.sample(
        bqm,
        chain_strength=chain_strength,
        warnings="SAVE",
        return_embedding=True,
        num_reads=1,
    )


def _chain_strength_warnings(sampleset):
    return [
        warning
        for warning in sampleset.info.get("warnings", [])
        if issubclass(warning["type"], ChainStrengthWarning)
    ]


def test_issue_example_has_no_chain_strength_warning_without_chains():
    """The two-variable QUBO from the issue embeds without any chains."""
    bqm = dimod.BinaryQuadraticModel.from_qubo(
        {(0, 0): 1, (1, 1): 1, (0, 1): -2}
    )
    embedding = {0: [0], 1: [1]}

    sampleset = _sample(bqm, embedding, edgelist=[(0, 1)])

    returned_embedding = sampleset.info["embedding_context"]["embedding"]
    assert all(len(chain) == 1 for chain in returned_embedding.values())
    assert _chain_strength_warnings(sampleset) == []


@pytest.mark.parametrize("bias", [1.0, -1.0, 2.0, -100.0])
def test_strong_quadratic_bias_does_not_warn_when_all_chains_are_singletons(bias):
    """Strong problem couplings are irrelevant to chain strength without chains."""
    bqm = dimod.BinaryQuadraticModel.from_ising({}, {("a", "b"): bias})
    embedding = {"a": [0], "b": [1]}

    sampleset = _sample(bqm, embedding, edgelist=[(0, 1)])

    assert _chain_strength_warnings(sampleset) == []


@pytest.mark.parametrize("bias", [1.0, -1.0, 2.0, -100.0])
def test_strong_quadratic_bias_still_warns_when_a_chain_exists(bias):
    """Suppressing the false positive must not disable legitimate warnings."""
    bqm = dimod.BinaryQuadraticModel.from_ising({}, {("a", "b"): bias})
    embedding = {"a": [0, 1], "b": [2]}

    sampleset = _sample(
