    assert set(warnings[0]["data"]["source_interactions"]) == {("a", "b")}


@pytest.mark.parametrize("bias", [0.5, -0.5, 0.999, -0.999])
def test_weak_quadratic_bias_does_not_warn_even_when_a_chain_exists(bias):
    bqm = dimod.BinaryQuadraticModel.from_ising({}, {("a", "b"): bias})
    embedding = {"a": [0, 1], "b": [2]}

