import pytest

from wemake_python_styleguide.violations.refactoring import (
    UselessReturningElseViolation,
)
from wemake_python_styleguide.visitors.ast.conditions import UselessElseVisitor


issue_example = """
class TemplateExtension:
    def resolve(self, relative_path):
        for search_path in self.environment.loader.searchpath:
            template_relative_path = Path(search_path) / relative_path
            if template_relative_path.exists():
                break
        else:
            raise UserMessageError(
                "Could not resolve path to local extension module "
                "'{0}'".format(relative_path),
            )
"""

for_search_with_return = """
def find_item(items, target):
    for item in items:
        if item == target:
            break
    else:
        return None
    return item
"""

async_for_search = """
async def find_item(items, target):
    async for item in items:
        if item == target:
            break
    else:
        raise LookupError(target)
    return item
"""

for_with_empty_collection_check = """
def first_item(items):
    for item in items:
        break
    else:
        raise ValueError('The collection must not be empty')
    return item
"""

for_with_break_inside_try = """
def find_existing_path(paths):
    for path in paths:
        try:
            if path.exists():
                break
        except OSError:
            continue
    else:
        raise LookupError('No existing path was found')
    return path
"""

for_with_break_inside_with = """
def find_nonempty_file(paths):
    for path in paths:
        with path.open() as stream:
            if stream.read():
                break
    else:
        raise LookupError('No non-empty file was found')
    return path
"""


@pytest.mark.parametrize('code', [
    issue_example,
    for_search_with_return,
    async_for_search,
    for_with_empty_collection_check,
    for_with_break_inside_try,
    for_with_break_inside_with,
])
def test_loop_else_with_break_is_not_useless(
    code,
    assert_errors,
    parse_ast_tree,
    default_options,
):
    """A loop ``else`` skipped by its own ``break`` is meaningful."""
    tree = parse_ast_tree(code)

    visitor = UselessElseVisitor(default_options, tree=tree)
    visitor.run()

    assert_errors(visitor, [])


@pytest.mark.parametrize('code', [
    """
def choose(items):
    for item in items:
        return item
    else:
        return None
""",
    """
def choose(items):
    for item in items:
        if item:
            return item
    else:
        raise LookupError()
""",
    """
def process(items):
    for item in items:
        if item:
            continue
    else:
        raise ValueError()
""",
])
def test_loop_else_without_break_can_still_be_useless(
    code,
    assert_errors,
    parse_ast_tree,
    default_options,
):
    """The fix must not disable WPS503 for every loop."""
    tree = parse_ast_tree(code)

    visitor = UselessElseVisitor(default_options, tree=tree)
    visitor.run()

    assert_errors(visitor, [UselessReturningElseViolation])


def test_nested_loop_break_does_not_make_outer_else_meaningful(
    assert_errors,
    parse_ast_tree,
    default_options,
):
    """Only a break belonging to the loop can skip that loop's ``else``."""
    tree = parse_ast_tree("""
def process(items):
    for item in items:
        if item:
            for value in item:
                break
    else:
        raise LookupError()
""")

    visitor = UselessElseVisitor(default_options, tree=tree)
    visitor.run()

    assert_errors(visitor, [UselessReturningElseViolation])


@pytest.mark.parametrize('code', [
    """
def choose(value):
    if value:
        return value
    else:
        raise ValueError()
""",
    """
def convert(value):
    try:
        return int(value)
    except ValueError:
        raise TypeError()
    else:
        return value
""",
])
def test_other_useless_else_checks_are_preserved(
    code,
    assert_errors,
    parse_ast_tree,
    default_options,
):
    """Allowing meaningful loop ``else`` clauses must not disable WPS503."""
    tree = parse_ast_tree(code)

    visitor = UselessElseVisitor(default_options, tree=tree)
    visitor.run()

    assert_errors(visitor, [UselessReturningElseViolation])

"""Regression tests for chain-strength warnings without actual chains."""

import dimod
import pytest

from dwave.system.composites import EmbeddingComposite, FixedEmbeddingComposite
from dwave.system.warnings import ChainStrengthWarning


def _structured_child(nodelist, edgelist):
    return dimod.StructureComposite(
        dimod.RandomSampler(), nodelist, edgelist
    )


def _chain_strength_warnings(sampleset):
    return [
        warning
        for warning in sampleset.info.get("warnings", [])
        if issubclass(warning["type"], ChainStrengthWarning)
    ]


@pytest.mark.parametrize("coupling", [-2.0, 2.0])
def test_no_chain_strength_warning_when_embedding_has_no_chains(coupling):
    """Strong problem couplings alone must not cause the warning.

    The negative-coupling case is the two-variable QUBO from the issue. The
    embedding is deterministic so the test cannot accidentally use a chain.
    """
    child = _structured_child([0, 1], [(0, 1)])

    def find_embedding(source_edgelist, target_edgelist, **kwargs):
        return {0: [0], 1: [1]}

    sampler = EmbeddingComposite(child, find_embedding=find_embedding)
    bqm = dimod.BinaryQuadraticModel.from_qubo(
        {(0, 0): 1, (1, 1): 1, (0, 1): coupling}
    )

    sampleset = sampler.sample(
        bqm,
        chain_strength=1.0,
        warnings="SAVE",
        return_embedding=True,
        num_reads=16,
    )

    embedding = sampleset.info["embedding_context"]["embedding"]
    assert embedding
    assert all(len(chain) == 1 for chain in embedding.values())
    assert _chain_strength_warnings(sampleset) == []


@pytest.mark.parametrize("coupling", [-2.0, 2.0])
def test_chain_strength_warning_is_retained_when_a_chain_exists(coupling):
    """Suppressing the no-chain false positive must not disable the warning."""
    child = _structured_child([0, 1, 2], [(0, 1), (1, 2)])
    sampler = FixedEmbeddingComposite(
        child, {"a": [0, 1], "b": [2]}
    )
    bqm = dimod.BinaryQuadraticModel.from_ising(
        {}, {("a", "b"): coupling}
    )

    sampleset = sampler.sample(
        bqm,
        chain_strength=1.0,
        warnings="SAVE",
        return_embedding=True,
        num_reads=16,
    )

    embedding = sampleset.info["embedding_context"]["embedding"]
    assert any(len(chain) > 1 for chain in embedding.values())

    warnings = _chain_strength_warnings(sampleset)
    assert len(warnings) == 1

    interactions = warnings[0]["data"]["source_interactions"]
    assert len(interactions) == 1
    assert set(interactions[0]) == {"a", "b"}


@pytest.mark.parametrize("coupling", [-0.5, 0.5])
def test_no_chain_strength_warning_for_weak_couplings_with_chains(coupling):
    """Having a chain is not sufficient; a coupling must exceed its strength."""
    child = _structured_child([0, 1, 2], [(0, 1), (1, 2)])
    sampler = FixedEmbeddingComposite(
        child, {"a": [0, 1], "b": [2]}
    )
    bqm = dimod.BinaryQuadraticModel.from_ising(
        {}, {("a", "b"): coupling}
    )

    sampleset = sampler.sample(
        bqm,
        chain_strength=1.0,
        warnings="SAVE",
        return_embedding=True,
        num_reads=16,
    )

    assert any(
        len(chain) > 1
        for chain in sampleset.info["embedding_context"]["embedding"].values()
    )
    assert _chain_strength_warnings(sampleset) == []


def test_warning_reports_only_strong_interactions_when_chains_exist():
    """A mixture of weak and strong couplings retains the useful warning data."""
    child = _structured_child(
        [0, 1, 2, 3], [(0, 1), (1, 2), (2, 3)]
    )
    sampler = FixedEmbeddingComposite(
        child, {"a": [0, 1], "b": [2], "c": [3]}
    )
    bqm = dimod.BinaryQuadraticModel.from_ising(
        {}, {("a", "b"): 0.25, ("b", "c"): -3.0}
    )

    sampleset = sampler.sample(
        bqm,
        chain_strength=1.0,
        warnings="SAVE",
        chain_break_fraction=False,
        num_reads=16,
    )

    warnings = _chain_strength_warnings(sampleset)
    assert len(warnings) == 1

    interactions = warnings[0]["data"]["source_interactions"]
    assert len(interactions) == 1
    assert set(interactions[0]) == {"b", "c"}

"""Regression tests for element-wise powers with array exponents."""

import operator

import numpy as np
import pytest

from unyt import cm, unyt_array, unyt_quantity
from unyt.exceptions import UnitOperationError


POWER_OPERATIONS = [
    pytest.param(operator.pow, id="operator"),
    pytest.param(np.power, id="numpy-ufunc"),
]


def assert_dimensionless_power_result(result, expected):
    """Check values without discarding the unit metadata being tested."""
    assert isinstance(result, unyt_array)
    assert result.units.is_dimensionless
    np.testing.assert_array_equal(result.d, np.asarray(expected))


@pytest.mark.parametrize("power_operation", POWER_OPERATIONS)
def test_dimensionless_unyt_array_exponent(power_operation):
    # Reproduction from the issue: this used to fail while evaluating p == 0.0.
    base = unyt_array([1, 2, 3, 4])
    exponent = unyt_array([1, 2, 3, 4])

    result = power_operation(base, exponent)

    assert_dimensionless_power_result(result, [1, 4, 27, 256])


@pytest.mark.parametrize("power_operation", POWER_OPERATIONS)
@pytest.mark.parametrize("numpy_operand", ["base", "exponent"])
def test_dimensionless_array_power_with_plain_numpy_operand(
    power_operation, numpy_operand
):
    values = np.array([2.0, 3.0, 4.0])
    exponents = np.array([1.0, 2.0, 3.0])

    if numpy_operand == "base":
        base = values
        exponent = unyt_array(exponents)
    else:
        base = unyt_array(values)
        exponent = exponents

    result = power_operation(base, exponent)

    assert_dimensionless_power_result(result, [2.0, 9.0, 64.0])


@pytest.mark.parametrize("power_operation", POWER_OPERATIONS)
def test_dimensionless_array_exponent_broadcasting(power_operation):
    base = unyt_array([[2.0], [3.0]])
    exponent = unyt_array([2.0, 3.0])

    result = power_operation(base, exponent)

    assert_dimensionless_power_result(result, [[4.0, 8.0], [9.0, 27.0]])


@pytest.mark.parametrize("power_operation", POWER_OPERATIONS)
def test_dimensionless_array_exponent_containing_zero(power_operation):
    base = unyt_array([2.0, 3.0, 4.0])
    exponent = unyt_array([0.0, 1.0, 2.0])

    result = power_operation(base, exponent)

    assert_dimensionless_power_result(result, [1.0, 3.0, 16.0])


@pytest.mark.parametrize("power_operation", POWER_OPERATIONS)
def test_dimensionless_scalar_base_with_array_exponent(power_operation):
    base = unyt_quantity(2.0)
    exponent = unyt_array([1.0, 2.0, 3.0])

    result = power_operation(base, exponent)

    assert_dimensionless_power_result(result, [2.0, 4.0, 8.0])


@pytest.mark.parametrize("power_operation", POWER_OPERATIONS)
@pytest.mark.parametrize("exponent_kind", ["unyt", "numpy"])
def test_unitful_array_base_with_array_exponent_is_rejected(
    power_operation, exponent_kind
):
    # Different elements would require different powers of the base unit.
    base = unyt_array([2.0, 3.0], "cm")
    if exponent_kind == "unyt":
        exponent = unyt_array([1.0, 2.0])
    else:
        exponent = np.array([1.0, 2.0])

    with pytest.raises(UnitOperationError):
        power_operation(base, exponent)


@pytest.mark.parametrize("power_operation", POWER_OPERATIONS)
def test_unitful_scalar_base_with_array_exponent_is_rejected(power_operation):
    # Broadcasting the scalar base does not make element-wise units well-defined.
    base = unyt_quantity(2.0, "cm")
    exponent = unyt_array([1.0, 2.0])

    with pytest.raises(UnitOperationError):
        power_operation(base, exponent)


@pytest.mark.parametrize("power_operation", POWER_OPERATIONS)
def test_unitful_array_exponent_is_rejected(power_operation):
    base = unyt_array([2.0, 3.0])
    exponent = unyt_array([1.0, 2.0], "cm")

    with pytest.raises(UnitOperationError):
        power_operation(base, exponent)


def test_scalar_exponent_behavior_is_unchanged():
    base = unyt_array([2.0, 3.0], "cm")

    squared = base**2
    assert squared.units == cm**2
    np.testing.assert_array_equal(squared.d, [4.0, 9.0])

    zeroth_power = base**0.0
    assert zeroth_power.units.is_dimensionless
    np.testing.assert_array_equal(zeroth_power.d, [1.0, 1.0])

import os
import subprocess

import pytest

from pre_commit.meta_hooks import check_useless_excludes
from testing.fixtures import add_config_to_repo


def _add_broken_submodule_symlink():
    # A missing submodule checkout leaves the symlink itself in the worktree,
    # even though its target cannot be resolved.
    os.symlink('submodule/file.txt', 'link-to-submodule')
    assert os.path.lexists('link-to-submodule')
    assert not os.path.exists('link-to-submodule')
    subprocess.run(
        ('git', 'add', '--', 'link-to-submodule'),
        check=True,
        capture_output=True,
    )


def test_exclude_for_broken_symlink_is_useful(capsys, in_git_dir):
    _add_broken_submodule_symlink()
    config = {
        'repos': [
            {
                # Loading the config for this meta hook does not clone the repo.
                'repo': 'https://github.com/pre-commit/pre-commit-hooks',
                'rev': 'v4.0.1',
                'hooks': [
                    {
                        'id': 'check-symlinks',
                        'exclude': '^link-to-submodule$',
                    },
                ],
            },
        ],
    }
    add_config_to_repo(in_git_dir.strpath, config)

    assert check_useless_excludes.main(()) == 0
    out, _ = capsys.readouterr()
    assert out == ''


@pytest.mark.parametrize(
    'type_filter',
    (
        {'types': ['python']},
        {'types_or': ['python']},
        {'exclude_types': ['file']},
    ),
)
def test_type_filters_do_not_make_matching_exclude_useless(
        capsys, in_git_dir, type_filter,
):
    # The configured hook does not necessarily contain the types from its
    # manifest.  File-pattern usefulness therefore must not be decided by
    # discarding files through the default or configured type filters.
    hook = {
        'id': 'check-useless-excludes',
        'exclude': r'^\.pre-commit-config\.yaml$',
        **type_filter,
    }
    config = {'repos': [{'repo': 'meta', 'hooks': [hook]}]}
    add_config_to_repo(in_git_dir.strpath, config)

    assert check_useless_excludes.main(()) == 0
    out, _ = capsys.readouterr()
    assert out == ''


def test_broken_symlink_exclude_must_still_match_files_pattern(
        capsys, in_git_dir,
):
    _add_broken_submodule_symlink()
    config = {
        'repos': [
            {
                'repo': 'meta',
                'hooks': [
                    {
                        'id': 'check-useless-excludes',
                        'files': '^src/',
                        'exclude': '^link-to-submodule$',
                    },
                ],
            },
        ],
    }
    add_config_to_repo(in_git_dir.strpath, config)

    assert check_useless_excludes.main(()) == 1
    out, _ = capsys.readouterr()
    assert out.strip() == (
        "The exclude pattern '^link-to-submodule$' for "
        'check-useless-excludes does not match any files'
    )

