    'async-for-loop',
    'while-loop',
    'conditional-break-inside-try',
])
def test_loop_else_with_conditional_break_is_meaningful(
    assert_errors,
    parse_ast_tree,
    default_options,
    code,
):
    """A break that exits the loop makes its ``else`` clause meaningful."""
    tree = parse_ast_tree(code)

    visitor = UselessElseVisitor(default_options, tree=tree)
    visitor.run()

    assert_errors(visitor, [])


