])
def test_genuinely_useless_loop_else_is_still_reported(
    assert_errors,
    parse_ast_tree,
    default_options,
    code,
):
    """The fix must not disable WPS503 or confuse nested and outer breaks."""
    tree = parse_ast_tree(code)

    visitor = UselessElseVisitor(default_options, tree=tree)
    visitor.run()

