import os

from pre_commit.meta_hooks import check_useless_excludes
from pre_commit.util import cmd_output
from testing.fixtures import add_config_to_repo


def _config_with_hook(hook):
    return {
        'repos': [
            {
                'repo': 'meta',
                'hooks': [{'id': 'check-useless-excludes', **hook}],
            },
        ],
    }


def _add_broken_symlink(filename):
    # Simulate a link into a submodule which has not been initialized.  The
    # link itself is tracked even though its target does not exist.
    os.symlink(os.path.join('missing-submodule', 'file'), filename)
    assert not os.path.exists(filename)
    assert os.path.islink(filename)
    cmd_output('git', 'add', filename)


def test_exclude_matching_broken_symlink_is_useful(capsys, in_git_dir):
    _add_broken_symlink('broken-symlink')
    config = _config_with_hook({'exclude': '^broken-symlink$'})
    add_config_to_repo(in_git_dir.strpath, config)

    assert check_useless_excludes.main(()) == 0

    out, _ = capsys.readouterr()
    assert out == ''


def test_exclude_matching_explicitly_typed_broken_symlink_is_useful(
        capsys, in_git_dir,
):
    # check-symlinks itself uses types: [symlink].  Keep this case explicit as
    # well as testing the manifest defaults applied by the meta hook above.
    _add_broken_symlink('broken-symlink')
    config = _config_with_hook({
        'types': ['symlink'],
        'exclude': '^broken-symlink$',
    })
    add_config_to_repo(in_git_dir.strpath, config)

    assert check_useless_excludes.main(()) == 0

