"""Regression tests for WPS503 on loops with meaningful ``else`` clauses."""

from textwrap import dedent

import pytest

from wemake_python_styleguide.violations.refactoring import (
    UselessReturningElseViolation,
)
from wemake_python_styleguide.visitors.ast.conditions import UselessElseVisitor


@pytest.mark.parametrize('code', [
    # The example from the issue: without ``else``, the exception would be
    # raised even when the loop found a path and executed ``break``.
    '''
    def resolve_template_path(environment, relative_path):
        for search_path in environment.loader.searchpath:
            template_relative_path = Path(search_path) / relative_path
            if template_relative_path.exists():
                break
        else:
            raise UserMessageError(
                "Could not resolve path to local extension module "
                "'{0}'".format(relative_path),
            )
    ''',
    # ``while ... else`` has the same break-sensitive semantics.
    '''
    def wait_for_result():
        while has_work():
            if finished():
                break
        else:
            return None
    ''',
    # Async loops must receive the same exemption as regular loops.
    '''
    async def find_item(items):
        async for item in items:
            if item.is_valid:
                break
        else:
            raise LookupError("Item not found")
    ''',
    # A break does not have to be a direct child of the loop body.
    '''
    def process_items(items):
        for item in items:
            try:
                if process(item):
                    break
            except ValueError:
                continue
        else:
            raise RuntimeError("No item could be processed")
    ''',
])
def test_loop_else_with_break_is_meaningful(
    code,
    assert_errors,
    parse_ast_tree,
    default_options,
):
    """A loop's own ``break`` makes its ``else`` conditionally executed."""
    tree = parse_ast_tree(dedent(code))

    visitor = UselessElseVisitor(default_options, tree=tree)
    visitor.run()

    assert_errors(visitor, [])


@pytest.mark.parametrize('code', [
    '''
    def find_item(items):
        for item in items:
            if item.is_valid:
                return item
        else:
            return None
    ''',
    '''
    def wait_for_result():
        while has_work():
            if finished():
                return True
        else:
            return False
    ''',
    '''
    async def find_item(items):
        async for item in items:
            if item.is_valid:
                return item
        else:
            return None
    ''',
    '''
    def find_item(items):
        for item in items:
            if item.should_be_skipped:
                continue
        else:
            return None
    ''',
])
def test_returning_loop_else_without_break_is_still_reported(
    code,
    assert_errors,
    parse_ast_tree,
    default_options,
):
    """The fix must not disable WPS503 for every loop with an ``else``."""
    tree = parse_ast_tree(dedent(code))

    visitor = UselessElseVisitor(default_options, tree=tree)
    visitor.run()

    assert_errors(visitor, [UselessReturningElseViolation])


def test_break_in_nested_loop_does_not_exempt_outer_loop(
    assert_errors,
    parse_ast_tree,
    default_options,
):
    """Only a break belonging to the loop makes that loop's else useful."""
    tree = parse_ast_tree(dedent('''
    def find_item(items):
        for item in items:
            for subitem in item.children:
                if subitem.is_valid:
                    break

            if item.is_valid:
                return item
        else:
            return None
    '''))

    visitor = UselessElseVisitor(default_options, tree=tree)
    visitor.run()

    # The inner break cannot prevent the outer else from running. The outer
    # else can therefore still be replaced by a return after the outer loop.
    assert_errors(visitor, [UselessReturningElseViolation])


def test_only_returning_else_is_not_wps503(
    assert_errors,
    parse_ast_tree,
    default_options,
):
    """WPS503 still requires returning nodes in both loop and else bodies."""
    tree = parse_ast_tree(dedent('''
    def process_items(items):
        for item in items:
            process(item)
        else:
            raise RuntimeError("Processing finished")
    '''))

    visitor = UselessElseVisitor(default_options, tree=tree)
    visitor.run()

    assert_errors(visitor, [])

