def find(items):
    while items:
        if items.pop():
            break
    else:
        raise LookupError
"""

async_for_with_break = """
async def find(items):
    async for item in items:
        if item:
            break
    else:
        return None
"""

break_inside_try = """
def find(items):
    for item in items:
        try:
            if item:
                break
        except ValueError:
            continue
    else:
        raise LookupError
"""


@pytest.mark.parametrize('code', [
    issue_example,
    while_with_break,
    async_for_with_break,
    break_inside_try,
])
def test_loop_else_with_break_is_not_reported(
    code,
    assert_errors,
    parse_ast_tree,
    default_options,
):
