import pytest

from wemake_python_styleguide.violations.refactoring import (
    UselessReturningElseViolation,
)
from wemake_python_styleguide.visitors.ast.conditions import UselessElseVisitor


issue_example = """
def resolve_template_path(self, relative_path):
    for search_path in self.environment.loader.searchpath:
        template_relative_path = Path(search_path) / relative_path
        if template_relative_path.exists():
            break
    else:
        raise UserMessageError(
            "Could not resolve path to local extension module "
            "'{0}'".format(relative_path),
        )
"""

for_with_break = """
def find_item(items):
    for item in items:
        if item.is_valid:
            break
    else:
        raise LookupError('Item not found')
    return item
"""

while_with_break = """
def find_item(items):
    while items:
        item = items.pop()
        if item.is_valid:
            break
    else:
        return None
    return item
"""

async_for_with_break = """
async def find_item(items):
    async for item in items:
        if item.is_valid:
            break
    else:
        raise LookupError('Item not found')
    return item
"""

unconditional_break = """
def find_first(items):
    for item in items:
        break
    else:
        return None
    return item
"""

break_after_try = """
def process_items(items):
    for item in items:
        try:
            process(item)
        except ValueError:
            continue
        break
    else:
        raise RuntimeError('No item could be processed')
"""


@pytest.mark.parametrize('code', [
    issue_example,
    for_with_break,
    while_with_break,
    async_for_with_break,
    unconditional_break,
    break_after_try,
])
def test_loop_else_with_break_is_not_useless(
    code,
    assert_errors,
    parse_ast_tree,
    default_options,
):
    """A loop ``else`` is meaningful when the loop can be exited by break."""
    tree = parse_ast_tree(code)

    visitor = UselessElseVisitor(default_options, tree=tree)
    visitor.run()

    assert_errors(visitor, [])


for_without_break = """
def find_item(items):
    for item in items:
        if item.is_valid:
            return item
    else:
        return None
"""

while_without_break = """
def validate(condition):
    while condition:
        if condition.failed:
            raise ValueError('Invalid condition')
    else:
        raise ValueError('Condition was not entered')
"""

async_for_without_break = """
async def consume(items):
    async for item in items:
        if item.skip:
            continue
    else:
        return None
"""

for_with_returning_branches = """
def find_item(items):
    for item in items:
        if item.is_valid:
            return item
        raise ValueError('Invalid item')
    else:
        raise LookupError('Item not found')
"""


@pytest.mark.parametrize('code', [
    for_without_break,
    while_without_break,
    async_for_without_break,
    for_with_returning_branches,
])
def test_returning_loop_else_without_break_is_still_reported(
    code,
    assert_errors,
    parse_ast_tree,
    default_options,
):
    """The fix must not disable WPS503 for genuinely useless loop elses."""
    tree = parse_ast_tree(code)

    visitor = UselessElseVisitor(default_options, tree=tree)
    visitor.run()

    assert_errors(visitor, [UselessReturningElseViolation])


only_else_returns = """
def consume(items):
    for item in items:
        print(item)
    else:
        return None
"""

only_body_returns = """
def find_item(items):
    for item in items:
        if item.is_valid:
            return item
    else:
        print('Item was not found')
"""

loop_without_else = """
def find_item(items):
    for item in items:
        if item.is_valid:
            return item
"""


@pytest.mark.parametrize('code', [
    only_else_returns,
    only_body_returns,
    loop_without_else,
])
def test_other_loop_else_shapes_remain_allowed(
    code,
    assert_errors,
