    visitor.run()

    assert_errors(visitor, [])


returning_if_else = """
def choose(condition):
    if condition:
        return 1
    else:
        return 2
"""

returning_try_else = """
def convert(value):
    try:
        converted = int(value)
    except ValueError:
        raise
    else:
        return converted
"""


@pytest.mark.parametrize('code', [
    returning_if_else,
    returning_try_else,
])
def test_non_loop_useless_else_checks_are_unchanged(
    code,
    assert_errors,
    parse_ast_tree,
    default_options,
):
    """Handling loop breaks must not suppress if/else or try/else checks."""
    tree = parse_ast_tree(code)

    visitor = UselessElseVisitor(default_options, tree=tree)
    visitor.run()

    assert_errors(visitor, [UselessReturningElseViolation])

import bibtexparser
import pytest


def _parse_entry(fields: str, strings: str = ""):
    """Parse one entry using the public, default parsing stack."""
    source = f"\n{strings}\n@article{{test,\n{fields}\n}}\n"
    library = bibtexparser.parse_string(source)
    assert len(library.entries) == 1, "The entry could not be parsed"
    return library.entries[0]


def test_issue_example_number_quoted_string_and_macro():
    source = '''
@STRING{ jan = "Jan." }

@INBOOK{inbook-full,
   month = 10 # "~" # jan,
}
'''
    library = bibtexparser.parse_string(source)

    assert len(library.entries) == 1
    assert library.entries[0].fields_dict["month"].value == "10~Jan."


@pytest.mark.parametrize(
    ("expression", "expected"),
    [
        # Numbers are string-like tokens, including their original digits.
        ('123 # "--" # 456', "123--456"),
        ('007 # "~" # jan', "007~Jan."),
        # Every token kind may occur at the beginning or end of an expression.
        ('jan # "~" # 10', "Jan.~10"),
        ('"~" # 10 # jan', "~10Jan."),
        ("{~} # 10 # jan", "~10Jan."),
        # Whitespace around the concatenation operator is optional.
        ('10#jan#"~"', "10Jan.~"),
        ('10\n      # "~"\n      # jan', "10~Jan."),
    ],
)
def test_concatenation_supports_all_field_token_kinds(expression, expected):
    entry = _parse_entry(
        f"  value = {expression},",
        strings='@string{jan = "Jan."}',
    )

    assert entry.fields_dict["value"].value == expected


def test_concatenation_resolves_braced_macro_values():
    entry = _parse_entry(
        "  value = jan # sep # 0,",
        strings='@string{jan = {Jan.}}\n@string{sep = "~"}',
    )

    assert entry.fields_dict["value"].value == "Jan.~0"


@pytest.mark.parametrize(
    ("expression", "expected"),
    [
        ('"C# is a language"', "C# is a language"),
        ("{C# is a language}", "C# is a language"),
        ('"a # b"', "a # b"),
        ("{a # b}", "a # b"),
    ],
)
def test_hash_inside_a_single_string_token_is_not_concatenation(
    expression, expected
):
    entry = _parse_entry(f"  value = {expression},")

    assert entry.fields_dict["value"].value == expected


@pytest.mark.parametrize(
    ("expression", "expected"),
    [
        ('10 # "a#b" # jan', "10a#bJan."),
        ("10 # {a#b} # jan", "10a#bJan."),
        ('10 # "a # b" # jan', "10a # bJan."),
    ],
)
def test_hash_inside_literals_of_a_concatenation_is_preserved(
    expression, expected
):
    entry = _parse_entry(
        f"  value = {expression},",
        strings='@string{jan = "Jan."}',
    )

    assert entry.fields_dict["value"].value == expected


@pytest.mark.parametrize(
    "expression",
    [
        '10 # ", " # jan',
        "10 # {, } # jan",
    ],
)
def test_field_delimiters_inside_concatenated_literals_are_ignored(expression):
    entry = _parse_entry(
        f"  value = {expression},",
        strings='@string{jan = "Jan."}',
    )

    assert entry.fields_dict["value"].value == "10, Jan."


def test_concatenation_accepts_brace_balanced_strings():
    entry = _parse_entry(
        '  value = {A {nested} title} # ": " # 2024,',
    )

    assert entry.fields_dict["value"].value == "A {nested} title: 2024"


def test_multiple_concatenated_fields_and_no_final_comma():
    entry = _parse_entry(
        '  first = 1 # "a",\n'
        '  second = "b" # 2,\n'
        "  third = jan # 3",
        strings='@string{jan = "Jan."}',
    )

    assert set(entry.fields_dict) == {"first", "second", "third"}
    assert entry.fields_dict["first"].value == "1a"
    assert entry.fields_dict["second"].value == "b2"
    assert entry.fields_dict["third"].value == "Jan.3"


def test_hash_introduced_by_macro_expansion_remains_literal():
    entry = _parse_entry(
        '  title = sharp,\n  note = sharp # "!",',
        strings='@string{sharp = "C#"}',
    )

    assert entry.fields_dict["title"].value == "C#"
    assert entry.fields_dict["note"].value == "C#!"

import datetime

import pytz

from temba_client.serialization import (
    DatetimeField,
    ObjectField,
    ObjectListField,
    TembaObject,
)


class DatetimeOnly(TembaObject):
    at = DatetimeField()


class NestedDatetime(TembaObject):
    at = DatetimeField()


class DatetimeContainer(TembaObject):
    at = DatetimeField()
    child = ObjectField(NestedDatetime)
    children = ObjectListField(NestedDatetime)


def test_datetimefield_serializes_none_as_none():
    assert DatetimeField().serialize(None) is None


def test_unset_datetime_attribute_serializes_as_null():
    obj = DatetimeOnly.create()

    assert obj.at is None
    assert obj.serialize() == {"at": None}


def test_null_datetimes_survive_deserialize_serialize_roundtrip():
    payload = {
        "at": None,
        "child": {"at": None},
        "children": [{"at": None}, {"at": None}],
    }

    obj = DatetimeContainer.deserialize(payload)

    assert obj.at is None
    assert obj.child.at is None
    assert [child.at for child in obj.children] == [None, None]
    assert obj.serialize() == payload


def test_non_null_datetime_serialization_is_unchanged():
    value = datetime.datetime(2014, 1, 2, 3, 4, 5, 123456, tzinfo=pytz.UTC)
    obj = DatetimeOnly.create(at=value)

    serialized = obj.serialize()

    assert serialized == {"at": "2014-01-02T03:04:05.123456"}
    assert DatetimeOnly.deserialize(serialized).at == value

import pytest

from sqlglot import exp, transpile


def _transpile_one(sql, read, write="duckdb"):
    return transpile(sql, read=read, write=write)[0]


def _assert_default_day_date_diff(actual, expected_template):
    # DuckDB date parts are case-insensitive. Both the issue's 'Day' and the
    # conventional 'day' are valid; the regression is the literal 'None'.
    assert actual in {
        expected_template.format(unit="Day"),
        expected_template.format(unit="day"),
    }
    assert "'None'" not in actual


@pytest.mark.parametrize(
    "spark_sql, expected_template",
    [
        (
            "SELECT DATEDIFF('2020-01-05', '2020-01-01') AS diff",
            "SELECT DATE_DIFF('{unit}', CAST('2020-01-01' AS DATE), "
            "CAST('2020-01-05' AS DATE)) AS diff",
        ),
        (
            "SELECT DATEDIFF(end_date, start_date) FROM transactions",
            "SELECT DATE_DIFF('{unit}', CAST(start_date AS DATE), "
            "CAST(end_date AS DATE)) FROM transactions",
        ),
        (
            "SELECT DATEDIFF(CURRENT_DATE(), hire_date) FROM employees",
            "SELECT DATE_DIFF('{unit}', CAST(hire_date AS DATE), "
            "CAST(CURRENT_DATE AS DATE)) FROM employees",
        ),
    ],
)
def test_spark_datediff_without_unit_defaults_to_day(spark_sql, expected_template):
    # Spark's two-argument form is DATEDIFF(end, start), whereas DuckDB's
    # DATE_DIFF takes (unit, start, end).
    duckdb_sql = _transpile_one(spark_sql, read="spark")
    _assert_default_day_date_diff(duckdb_sql, expected_template)


@pytest.mark.parametrize("unit", ["day", "month", "year"])
def test_spark_datediff_explicit_unit_is_preserved(unit):
    # Spark's three-argument form is DATEDIFF(unit, start, end), so its date
    # arguments retain their order when translated to DuckDB.
    duckdb_sql = _transpile_one(
        f"SELECT DATEDIFF({unit}, start_date, end_date)", read="spark"
    )

    assert duckdb_sql == (
        f"SELECT DATE_DIFF('{unit}', CAST(start_date AS DATE), "
        "CAST(end_date AS DATE))"
    )


def test_duckdb_date_diff_explicit_unit_is_not_replaced_by_default():
    sql = "SELECT DATE_DIFF('week', start_date, end_date)"
    assert _transpile_one(sql, read="duckdb") == sql


@pytest.mark.parametrize("date_diff_args", [{}, {"unit": None}])
def test_duckdb_date_diff_defaults_for_missing_or_none_unit(date_diff_args):
    # Cover both an absent unit key and Spark's explicitly stored unit=None.
    expression = exp.DateDiff(
        this=exp.column("end_date"),
        expression=exp.column("start_date"),
        **date_diff_args,
    )

    _assert_default_day_date_diff(
        expression.sql(dialect="duckdb"),
        "DATE_DIFF('{unit}', start_date, end_date)",
    )

