import pytest

from wemake_python_styleguide.violations.refactoring import (
    UselessReturningElseViolation,
)
from wemake_python_styleguide.visitors.ast.conditions import UselessElseVisitor


for_with_break = """
def resolve_path(search_paths, relative_path):
    for search_path in search_paths:
        template_relative_path = make_path(search_path, relative_path)
        if template_relative_path.exists():
            break
    else:
        raise UserMessageError('Could not resolve path')
"""

while_with_break = """
def wait_for_result():
    while is_pending():
        if is_ready():
            break
    else:
        return default_result
"""

async_for_with_break = """
async def find_item(items):
    async for item in items:
        if item.is_valid:
            break
    else:
        raise LookupError('Item not found')
"""

break_inside_try = """
def process_items(items):
    for item in items:
        try:
            process(item)
        except ExpectedError:
            continue
        break
    else:
        raise ProcessingError('No item could be processed')
"""

deeply_nested_break = """
def find_item(items):
    for item in items:
        if item.is_valid:
            if item.is_enabled:
                if item.matches():
                    break
    else:
        raise LookupError('No matching item')
"""


@pytest.mark.parametrize('code', [
    for_with_break,
    while_with_break,
    async_for_with_break,
    break_inside_try,
    deeply_nested_break,
])
def test_loop_else_with_break_is_not_reported(
    assert_errors,
    parse_ast_tree,
    default_options,
    code,
):
    """A loop ``else`` is meaningful when its loop can be terminated by break."""
    tree = parse_ast_tree(code)

    visitor = UselessElseVisitor(default_options, tree=tree)
    visitor.run()

    assert_errors(visitor, [])


for_without_break = """
def find_item(items):
    for item in items:
        if item.is_valid:
            return item
    else:
        raise LookupError('Item not found')
"""

while_without_break = """
def wait_for_result():
    while is_pending():
        if has_failed():
            raise ProcessingError()
    else:
        return default_result
"""

async_for_without_break = """
async def find_item(items):
    async for item in items:
        if item.is_valid:
            return item
    else:
        raise LookupError('Item not found')
"""

loop_with_only_continue = """
def validate_items(items):
    for item in items:
        if not item.is_valid:
            continue
    else:
        raise ValueError('No valid items')
"""


@pytest.mark.parametrize('code', [
    for_without_break,
    while_without_break,
    async_for_without_break,
    loop_with_only_continue,
])
def test_returning_loop_else_without_break_is_still_reported(
    assert_errors,
    parse_ast_tree,
    default_options,
    code,
):
    """The exemption for break must not disable WPS503 for other loops."""
    tree = parse_ast_tree(code)

    visitor = UselessElseVisitor(default_options, tree=tree)
    visitor.run()

    assert_errors(visitor, [UselessReturningElseViolation])


nested_for_break = """
def find_item(items):
    for item in items:
        for subitem in item:
            if subitem.is_valid:
                break
    else:
        raise LookupError('Item not found')
"""

nested_while_break = """
def find_item(items):
    while should_continue():
        for item in items:
            if item.is_valid:
                break
    else:
        raise LookupError('Item not found')
"""


@pytest.mark.parametrize('code', [
    nested_for_break,
    nested_while_break,
])
def test_break_in_nested_loop_does_not_exempt_outer_loop(
    assert_errors,
    parse_ast_tree,
    default_options,
    code,
):
    """Only a break belonging to the loop with ``else`` makes it meaningful."""
    tree = parse_ast_tree(code)

    visitor = UselessElseVisitor(default_options, tree=tree)
    visitor.run()

    assert_errors(visitor, [UselessReturningElseViolation])

import datetime

import pytz

from temba_client.serialization import (
    DatetimeField,
    ObjectField,
    ObjectListField,
    SimpleField,
    TembaObject,
)


class _RunLikeObject(TembaObject):
    name = SimpleField()
    started_on = DatetimeField()
    ended_on = DatetimeField(optional=True)


class _StepLikeObject(TembaObject):
    exited_on = DatetimeField()


class _NestedRunLikeObject(TembaObject):
    current_step = ObjectField(_StepLikeObject)
    steps = ObjectListField(_StepLikeObject)


def test_datetime_field_serializes_none_as_none():
    field = DatetimeField()

    assert field.deserialize(None) is None
    assert field.serialize(None) is None


def test_datetime_field_still_serializes_and_normalizes_real_datetimes():
    field = DatetimeField()
    value = datetime.datetime(
        2014, 1, 2, 5, 4, 5, 123456, tzinfo=pytz.FixedOffset(120)
    )

    assert field.serialize(value) == "2014-01-02T03:04:05.123456"


def test_deserialized_null_datetime_can_be_serialized_back_to_null():
    # An optional datetime may also be absent from the server response.
    fetched = {"name": "run-1", "started_on": None}

    run = _RunLikeObject.deserialize(fetched)

    assert run.started_on is None
    assert run.ended_on is None
    assert run.serialize() == {
        "name": "run-1",
        "started_on": None,
        "ended_on": None,
    }


def test_unset_datetime_attributes_on_created_objects_serialize_as_null():
    run = _RunLikeObject.create(name="created-locally")

    serialized = run.serialize()

    assert serialized["started_on"] is None
    assert serialized["ended_on"] is None
    assert serialized == {
        "name": "created-locally",
        "started_on": None,
        "ended_on": None,
    }


def test_null_datetimes_survive_nested_object_round_trips():
    # This mirrors the issue's traceback, where serialization reaches a
    # DatetimeField through nested objects and an object list.
    fetched = {
        "current_step": {"exited_on": None},
        "steps": [
            {"exited_on": None},
            {"exited_on": "2014-01-02T03:04:05.000000"},
        ],
    }

    run = _NestedRunLikeObject.deserialize(fetched)

    assert run.current_step.exited_on is None
    assert run.steps[0].exited_on is None
    assert run.serialize() == fetched

"""Regression tests for the editor used by ``towncrier create --edit``."""

from pathlib import Path
from unittest import mock

import pytest
from click.testing import CliRunner

from towncrier.create import _main
from towncrier.test.helpers import setup_simple_project


def _invoke_create_with_editor(*, extra_config="", args=None, cli_input=None):
    """Run create with a mocked editor and return its call and created files."""
    runner = CliRunner()

    with runner.isolated_filesystem():
        setup_simple_project(extra_config=extra_config)
        with mock.patch("click.edit", return_value="Edited content") as mock_edit:
            result = runner.invoke(
                _main,
                args=["123.feature", "--edit"] if args is None else args,
                input=cli_input,
            )

        assert result.exit_code == 0, result.output or repr(result.exception)
        fragments = {
            path.name: path.read_text(encoding="utf-8")
            for path in Path("foo", "newsfragments").iterdir()
        }

    return mock_edit, fragments


def _editor_suffix(mock_edit):
    """Get the effective suffix, allowing either click.edit filename mechanism."""
    assert mock_edit.call_count == 1
    kwargs = mock_edit.call_args.kwargs

    filename = kwargs.get("filename")
    if filename and Path(filename).suffix:
        return Path(filename).suffix.lower()

    extension = kwargs.get("extension")
    if extension:
        extension = extension.lower()
        return extension if extension.startswith(".") else f".{extension}"

    if filename:
        return Path(filename).suffix.lower()

    # This is click.edit's default when neither argument is supplied.
    return ".txt"


def test_explicit_edit_uses_rst_by_default():
    """The default reStructuredText configuration must not open a .txt file."""
    mock_edit, fragments = _invoke_create_with_editor()

    assert _editor_suffix(mock_edit) == ".rst"
    assert fragments == {"123.feature.rst": "Edited content\n"}


def test_explicit_edit_uses_markdown_extension_from_configuration():
    """A Markdown news file means the fragment should be edited as Markdown."""
    mock_edit, fragments = _invoke_create_with_editor(
        extra_config='filename = "NEWS.md"'
    )

    assert _editor_suffix(mock_edit) == ".md"
    assert fragments == {"123.feature.md": "Edited content\n"}


def test_interactive_create_also_uses_markup_extension():
    """Interactive creation enables editing implicitly and needs the same suffix."""
    mock_edit, fragments = _invoke_create_with_editor(
        extra_config='filename = "NEWS.md"',
        args=[],
        cli_input="42\nfeature\n",
    )

    assert _editor_suffix(mock_edit) == ".md"
    assert fragments == {"42.feature.md": "Edited content\n"}


def test_edit_with_initial_content_still_uses_markup_extension():
    """Supplying draft content with --edit must not revert the editor to .txt."""
    mock_edit, fragments = _invoke_create_with_editor(
        args=["123.feature", "--edit", "--content", "Draft content"]
    )

    assert _editor_suffix(mock_edit) == ".rst"
    assert mock_edit.call_args.args[0].startswith("Draft content\n")
    assert fragments == {"123.feature.rst": "Edited content\n"}


@pytest.mark.parametrize(
    ("news_filename", "expected_suffix"),
    [("NEWS.rst", ".rst"), ("NEWS.md", ".md")],
)
def test_editor_suffix_is_independent_of_fragment_filename_extension(
    news_filename, expected_suffix
):
    """
    create_add_extension controls the created fragment's name, not its markup.

    Even when fragments themselves have no suffix, their contents still use the
    syntax selected by the configured news filename. Disabling automatic filename
    extensions must therefore not make the editor fall back to a .txt file.
    """
    mock_edit, fragments = _invoke_create_with_editor(
        extra_config=(
            f'filename = "{news_filename}"\n'
            "create_add_extension = false"
        )
    )

    assert _editor_suffix(mock_edit) == expected_suffix
    assert fragments == {"123.feature": "Edited content\n"}

import datetime

import pytz

from temba_client.serialization import (
    DatetimeField,
    ObjectField,
    ObjectListField,
    SimpleField,
    TembaObject,
)


class SampleEvent(TembaObject):
    name = SimpleField()
    occurred_at = DatetimeField()


class SampleOptionalEvent(TembaObject):
    name = SimpleField()
    occurred_at = DatetimeField(optional=True)


class SampleEnvelope(TembaObject):
    primary = ObjectField(SampleEvent)
    history = ObjectListField(SampleEvent)


def test_datetimefield_serializes_none_as_null():
    field = DatetimeField()

    assert field.deserialize(None) is None
    assert field.serialize(None) is None


def test_deserialized_null_datetime_can_be_serialized_again():
    payload = {"name": "unfinished", "occurred_at": None}

    event = SampleEvent.deserialize(payload)

    assert event.occurred_at is None
    assert event.serialize() == payload
    assert event.serialize()["occurred_at"] is None


def test_unset_datetime_attributes_serialize_as_null():
    created = SampleEvent.create(name="created without a date")
    assert created.occurred_at is None
    assert created.serialize() == {
        "name": "created without a date",
        "occurred_at": None,
    }

    deserialized = SampleOptionalEvent.deserialize({"name": "missing optional date"})
    assert deserialized.occurred_at is None
    assert deserialized.serialize() == {
        "name": "missing optional date",
        "occurred_at": None,
    }


def test_null_datetimes_round_trip_inside_nested_objects_and_lists():
    payload = {
        "primary": {"name": "primary", "occurred_at": None},
        "history": [
            {"name": "pending", "occurred_at": None},
            {"name": "completed", "occurred_at": "2014-01-02T03:04:05.000000"},
        ],
    }

    envelope = SampleEnvelope.deserialize(payload)

    assert envelope.primary.occurred_at is None
    assert envelope.history[0].occurred_at is None
    assert envelope.serialize() == payload


def test_non_null_datetime_serialization_is_unchanged():
    field = DatetimeField()
    value = datetime.datetime(2014, 1, 2, 3, 4, 5, 123456, tzinfo=pytz.UTC)

    serialized = field.serialize(value)

    assert serialized == "2014-01-02T03:04:05.123456"
    assert field.deserialize(serialized) == value

    event = SampleEvent.create(name="completed", occurred_at=value)
    assert event.serialize() == {
        "name": "completed",
        "occurred_at": "2014-01-02T03:04:05.123456",
    }

import pytest

from sqlglot import exp, transpile


def test_spark_datediff_defaults_to_day_when_transpiled_to_duckdb():
    """Spark's two-argument DATEDIFF must not produce a 'None' unit."""
    assert transpile(
        "SELECT DATEDIFF(end_date, start_date) AS elapsed_days",
        read="spark",
        write="duckdb",
    ) == [
        "SELECT DATE_DIFF('day', CAST(start_date AS DATE), CAST(end_date AS DATE)) AS elapsed_days"
    ]


@pytest.mark.parametrize("unit_args", [{}, {"unit": None}])
def test_duckdb_date_diff_defaults_missing_unit_to_day(unit_args):
    """Both an omitted unit and an explicitly empty unit need the default."""
    expression = exp.DateDiff(
        this=exp.column("end_date"),
        expression=exp.column("start_date"),
        **unit_args,
    )

    assert expression.sql(dialect="duckdb") == (
        "DATE_DIFF('day', start_date, end_date)"
    )


@pytest.mark.parametrize("unit", ["day", "week", "month", "year"])
def test_duckdb_date_diff_preserves_an_explicit_unit(unit):
    """Supplying the default must not discard units already on the expression."""
    expression = exp.DateDiff(
        this=exp.column("end_date"),
        expression=exp.column("start_date"),
        unit=exp.var(unit),
    )

    assert expression.sql(dialect="duckdb") == (
        f"DATE_DIFF('{unit}', start_date, end_date)"
    )

