"""Regression tests for WPS503 on loops with meaningful ``else`` clauses."""

import pytest

from wemake_python_styleguide.violations.refactoring import (
    UselessReturningElseViolation,
)
from wemake_python_styleguide.visitors.ast.conditions import UselessElseVisitor


issue_example = """
def resolve_template_path(self, relative_path):
    for search_path in self.environment.loader.searchpath:
        template_relative_path = Path(search_path) / relative_path
        if template_relative_path.exists():
            break
    else:
        raise UserMessageError(
            'Could not resolve path to local extension module',
        )
"""

while_with_break = """
def find_value():
    while values:
        value = values.pop()
        if value.is_valid:
            break
    else:
        return None
    return value
"""

async_for_with_break = """
async def find_value(values):
    async for value in values:
        if value.is_valid:
            break
    else:
        raise ValueError('No valid value')
    return value
"""

unconditional_break = """
def find_value(values):
    for value in values:
        break
    else:
        return None
    return value
"""

break_after_try_except = """
def process_all(items):
    for item in items:
        try:
            process(item)
        except Exception:
            continue
        break
    else:
        raise ValueError('No item could be processed')
"""

deeply_nested_break = """
def find_value(items):
    for item in items:
        if item.is_valid:
            try:
                if item.ready:
                    break
            except Exception:
                continue
    else:
        raise ValueError('No ready item')
"""


@pytest.mark.parametrize('code', [
    issue_example,
    while_with_break,
    async_for_with_break,
    unconditional_break,
    break_after_try_except,
    deeply_nested_break,
])
def test_loop_else_with_break_is_not_reported(
    assert_errors,
    parse_ast_tree,
    default_options,
    code,
):
    """A loop ``else`` is meaningful when its loop can be exited by ``break``."""
    tree = parse_ast_tree(code)

    visitor = UselessElseVisitor(default_options, tree=tree)
    visitor.run()

    assert_errors(visitor, [])


for_with_return = """
def find_value(values):
    for value in values:
        if value.is_valid:
            return value
    else:
        raise ValueError('No valid value')
"""

while_with_raise = """
def find_value(values):
    while values:
        if values.invalid:
            raise ValueError('Invalid values')
    else:
        return None
"""

async_for_with_return = """
async def find_value(values):
    async for value in values:
        if value.is_valid:
            return value
    else:
        raise ValueError('No valid value')
"""

for_with_continue = """
def find_value(values):
    for value in values:
        if not value.is_valid:
            continue
    else:
        return None
"""


@pytest.mark.parametrize('code', [
    for_with_return,
    while_with_raise,
    async_for_with_return,
    for_with_continue,
])
def test_returning_loop_else_without_break_is_reported(
    assert_errors,
    parse_ast_tree,
    default_options,
    code,
):
    """The fix must preserve WPS503 when no ``break`` makes ``else`` useful."""
    tree = parse_ast_tree(code)

    visitor = UselessElseVisitor(default_options, tree=tree)
    visitor.run()

    assert_errors(visitor, [UselessReturningElseViolation])


only_else_returns = """
def find_value(values):
    for value in values:
        consume(value)
    else:
        raise ValueError('No values')
"""

only_body_returns = """
def find_value(values):
    for value in values:
        if value.is_valid:
            return value
    else:
        consume(values)
"""

loop_without_else = """
def consume_all(values):
    for value in values:
        if value.is_valid:
            return value
"""


@pytest.mark.parametrize('code', [
    only_else_returns,
    only_body_returns,
    loop_without_else,
])
def test_loop_else_still_requires_returning_nodes_on_both_sides(
    assert_errors,
    parse_ast_tree,
    default_options,
    code,
):
    """WPS503 must not be broadened to every loop with an ``else`` clause."""
    tree = parse_ast_tree(code)

    visitor = UselessElseVisitor(default_options, tree=tree)
    visitor.run()

    assert_errors(visitor, [])


nested_loop_break = """
def find_value(items):
    for item in items:
        for part in item.parts:
            if part.is_valid:
                break
        if item.is_valid:
            return item
    else:
        raise ValueError('No valid item')
"""


def test_inner_loop_break_does_not_excuse_outer_loop_else(
    assert_errors,
    parse_ast_tree,
    default_options,
):
    """A ``break`` only gives meaning to the ``else`` of its own loop.

    The inner ``break`` cannot prevent the outer loop from completing
    normally. Moving the outer ``else`` body's ``raise`` after the outer loop
    therefore preserves behavior, so WPS503 still applies to that ``else``.
    """
    tree = parse_ast_tree(nested_loop_break)

    visitor = UselessElseVisitor(default_options, tree=tree)
    visitor.run()

    assert_errors(visitor, [UselessReturningElseViolation])

import datetime

import pytz

from temba_client.serialization import (
    DatetimeField,
    ObjectField,
    ObjectListField,
    SimpleField,
    TembaObject,
)


class SampleChild(TembaObject):
    name = SimpleField()
    happened_on = DatetimeField(optional=True)


class SampleParent(TembaObject):
    name = SimpleField()
    happened_on = DatetimeField(optional=True)
    child = ObjectField(SampleChild, optional=True)
    children = ObjectListField(SampleChild, optional=True)


def test_datetime_field_serializes_none_as_none():
    field = DatetimeField()

    assert field.serialize(None) is None
    assert field.deserialize(None) is None


def test_datetime_field_still_serializes_real_datetimes():
    field = DatetimeField()
    value = datetime.datetime(2014, 1, 2, 3, 4, 5, 123456, tzinfo=pytz.UTC)

    serialized = field.serialize(value)

    assert serialized == "2014-01-02T03:04:05.123456"
    assert field.deserialize(serialized) == value


def test_deserialized_null_datetimes_can_be_reserialized_at_every_depth():
    # This mirrors fetching JSON, deserializing it into Temba objects, and then
    # feeding those objects back to the serializer. Nulls occur both directly
    # on an object and inside nested objects and object lists.
    payload = {
        "name": "parent",
        "happened_on": None,
        "child": {
            "name": "nested",
            "happened_on": None,
        },
        "children": [
            {
                "name": "null date",
                "happened_on": None,
            },
            {
                "name": "actual date",
                "happened_on": "2014-01-02T03:04:05.123456",
            },
        ],
    }

    instance = SampleParent.deserialize(payload)

    assert instance.happened_on is None
    assert instance.child.happened_on is None
    assert instance.children[0].happened_on is None
    assert instance.serialize() == payload


def test_unset_and_missing_optional_datetimes_serialize_as_null():
    # TembaObject.create assigns None to fields which were not supplied.
    created = SampleChild.create(name="created")
    assert created.serialize() == {
        "name": "created",
        "happened_on": None,
    }

    # An optional datetime omitted from deserialized input must be equally
    # safe to serialize afterwards.
    deserialized = SampleChild.deserialize({"name": "deserialized"})
    assert deserialized.happened_on is None
    assert deserialized.serialize() == {
        "name": "deserialized",
        "happened_on": None,
    }

"""Tests for BibTeX field-value concatenation with ``#``."""

from textwrap import dedent

import pytest

import bibtexparser


def _only_entry(library):
    """Return the sole entry, with useful assertions for parse failures."""
    assert not library.failed_blocks
    assert len(library.entries) == 1
    return library.entries[0]


def _parse_month(expression: str, macro_value: str = '"Jan."') -> str:
    """Parse a single month field and return its fully processed value."""
    bibtex_str = (
        f"@string{{jan = {macro_value}}}\n\n"
        "@inbook{inbook-full,\n"
        f"    month = {expression},\n"
        "}\n"
    )
    library = bibtexparser.parse_string(bibtex_str)
    entry = _only_entry(library)
    return entry.fields_dict["month"].value


@pytest.mark.parametrize(
    "expression,expected",
    [
        pytest.param('10 # "~" # jan', "10~Jan.", id="issue-example"),
        pytest.param('10#"~"#jan', "10~Jan.", id="without-whitespace"),
        pytest.param(
            '10\n      # "~"\n      # jan',
            "10~Jan.",
            id="across-lines",
        ),
        pytest.param(
            '"Vol. " # 10 # "~" # jan',
            "Vol. 10~Jan.",
            id="quoted-string-first",
        ),
        pytest.param(
            '{Vol. } # 10 # "~" # jan',
            "Vol. 10~Jan.",
            id="braced-string-first",
        ),
        pytest.param('jan # " " # 2024', "Jan. 2024", id="macro-first"),
        pytest.param('123 # "--" # 456', "123--456", id="multiple-numbers"),
        pytest.param('001 # "~" # 02', "001~02", id="numbers-remain-strings"),
        pytest.param('jan # "~" # jan', "Jan.~Jan.", id="repeated-macro"),
    ],
)
def test_concatenates_all_field_token_types(expression, expected):
    """Numbers, macros, and quoted/braced strings can occur in any position."""
    assert _parse_month(expression) == expected


@pytest.mark.parametrize("macro_value", ['"Jan."', "{Jan.}"])
def test_concatenation_resolves_macro_with_either_enclosing(macro_value):
    assert _parse_month('10 # "~" # jan', macro_value=macro_value) == "10~Jan."


@pytest.mark.parametrize(
    "expression,expected",
    [
        pytest.param('"C#C"', "C#C", id="hash-in-ordinary-quoted-value"),
        pytest.param("{C#C}", "C#C", id="hash-in-ordinary-braced-value"),
        pytest.param(
            '10 # "C#C" # jan',
            "10C#CJan.",
            id="hash-inside-concatenated-quoted-token",
        ),
        pytest.param(
            '"C#C" # jan',
            "C#CJan.",
            id="quoted-token-with-hash-first",
        ),
        pytest.param(
            "{C#C} # jan",
            "C#CJan.",
            id="braced-token-with-hash-first",
        ),
    ],
)
def test_hash_inside_string_tokens_is_literal(expression, expected):
    """Only separators between field tokens are concatenation operators."""
    assert _parse_month(expression) == expected


def test_hash_in_macro_value_is_literal():
    """Macro expansion must not turn a literal hash into an operator."""
    library = bibtexparser.parse_string(
        dedent(
            """
            @string{sharp = "C#C"}

            @article{test,
                plain = sharp,
                concatenated = sharp # "!",
            }
            """
        )
    )

    fields = _only_entry(library).fields_dict
    assert fields["plain"].value == "C#C"
    assert fields["concatenated"].value == "C#C!"


def test_delimiters_and_nested_braces_inside_tokens():
    """Commas and braces inside a token must not terminate the field value."""
    assert (
        _parse_month('10 # ", " # {a {b} c} # jan')
        == "10, a {b} cJan."
    )


def test_concatenation_does_not_affect_following_fields():
    library = bibtexparser.parse_string(
        dedent(
            """
            @string{jan = "Jan."}

            @inbook{inbook-full,
                month = 10 # "~" # jan,
                year = 2024,
                title = "A title",
            }
            """
        )
    )

    fields = _only_entry(library).fields_dict
    assert fields["month"].value == "10~Jan."
    assert fields["year"].value == "2024"
    assert fields["title"].value == "A title"


def test_concatenation_as_last_field_without_trailing_comma():
    """The entry-closing brace must not become part of the expression."""
    library = bibtexparser.parse_string(
        dedent(
            """
            @string{jan = "Jan."}

            @article{first,
                note = jan # "!"
            }

            @article{second,
                note = 10 # jan
            }
            """
        )
    )

    assert not library.failed_blocks
    assert len(library.entries) == 2
    assert library.entries_dict["first"].fields_dict["note"].value == "Jan.!"
    assert library.entries_dict["second"].fields_dict["note"].value == "10Jan."

import datetime
import json

import pytz

from temba_client.serialization import (
    DatetimeField,
