    expression = exp.DateDiff(
        this=exp.column("end_date"),
        expression=exp.column("start_date"),
        **date_diff_kwargs,
    )

    assert expression.sql(dialect="duckdb") == "DATE_DIFF('day', start_date, end_date)"


@pytest.mark.parametrize("function_name", ["DATE_DIFF", "DATEDIFF"])
def test_duckdb_date_diff_preserves_an_explicit_unit(function_name):
    """The default must only apply when no unit was supplied."""
    source = f"SELECT {function_name}('month', start_date, end_date)"

    assert transpile(source, read="duckdb", write="duckdb") == [
        "SELECT DATE_DIFF('month', start_date, end_date)"
    ]

