import pytest

from wemake_python_styleguide.violations.refactoring import (
    UselessReturningElseViolation,
)
from wemake_python_styleguide.visitors.ast.conditions import UselessElseVisitor


issue_example = """
def resolve_template_path(self, relative_path):
    for search_path in self.environment.loader.searchpath:
        template_relative_path = Path(search_path) / relative_path
        if template_relative_path.exists():
            break
    else:
        raise UserMessageError(
            'Could not resolve path to local extension module',
        )
"""

while_with_break = """
def find_item(items):
    while items:
        item = items.pop()
        if item.is_valid:
            break
    else:
        raise ValueError('Item not found')
"""

async_for_with_break = """
async def find_item(items):
    async for item in items:
        if item.is_valid:
            break
    else:
        raise ValueError('Item not found')
"""

break_after_try_except = """
def process_items(items):
    for item in items:
        try:
            process(item)
        except Exception:
            continue
        break
    else:
        raise ValueError('No item could be processed')
"""

deeply_nested_break = """
def find_item(items):
    for item in items:
        if item.is_valid:
            if item.is_ready:
                break
    else:
        return None
"""


@pytest.mark.parametrize('code', [
    issue_example,
    while_with_break,
    async_for_with_break,
    break_after_try_except,
    deeply_nested_break,
])
def test_loop_else_with_break_is_not_reported(
    code,
    assert_errors,
    parse_ast_tree,
    default_options,
):
    """A loop ``else`` is meaningful when its own loop can be broken."""
    tree = parse_ast_tree(code)

    visitor = UselessElseVisitor(default_options, tree=tree)
    visitor.run()

    assert_errors(visitor, [])


for_without_break = """
def find_item(items):
    for item in items:
        if item.is_valid:
            return item
    else:
        raise ValueError('Item not found')
"""

while_without_break = """
def find_item(items):
    while items:
        if items.pop().is_valid:
            return True
    else:
        return False
"""

async_for_without_break = """
async def find_item(items):
    async for item in items:
        if item.is_valid:
            return item
    else:
        raise ValueError('Item not found')
"""

continue_without_break = """
def find_item(items):
    for item in items:
        if not item.is_valid:
            continue
    else:
        return None
"""


@pytest.mark.parametrize('code', [
    for_without_break,
    while_without_break,
    async_for_without_break,
    continue_without_break,
])
def test_returning_loop_else_without_break_is_still_reported(
    code,
    assert_errors,
    parse_ast_tree,
    default_options,
):
    """The fix must not disable WPS503 for genuinely useless loop elses."""
    tree = parse_ast_tree(code)

    visitor = UselessElseVisitor(default_options, tree=tree)
    visitor.run()

    assert_errors(visitor, [UselessReturningElseViolation])


def test_inner_loop_break_does_not_make_outer_else_meaningful(
    assert_errors,
    parse_ast_tree,
    default_options,
):
    """A break in a nested loop must not suppress WPS503 on the outer loop."""
    tree = parse_ast_tree("""
def find_group(groups):
    for group in groups:
        for item in group:
            if item.is_valid:
                break
        if not group:
            return None
    else:
        return False
""")

    visitor = UselessElseVisitor(default_options, tree=tree)
    visitor.run()

    assert_errors(visitor, [UselessReturningElseViolation])


def test_non_returning_loop_body_does_not_trigger_wps503(
    assert_errors,
    parse_ast_tree,
    default_options,
):
    """A returning ``else`` alone is not a WPS503 violation."""
    tree = parse_ast_tree("""
def log_items(items):
    for item in items:
        print(item)
    else:
        raise ValueError('No items')
""")

    visitor = UselessElseVisitor(default_options, tree=tree)
    visitor.run()

    assert_errors(visitor, [])

from textwrap import dedent

import pytest

import bibtexparser


def _parse_without_errors(source):
    library = bibtexparser.parse_string(dedent(source))
    assert library.failed_blocks == []
    return library


def test_issue_number_quoted_string_and_macro_are_concatenated():
    library = _parse_without_errors(
        '''
        @STRING{ jan = "Jan." }

        @INBOOK{inbook-full,
           month = 10 # "~" # jan,
        }
        '''
    )

    assert len(library.entries) == 1
    assert library.entries[0].fields_dict["month"].value == "10~Jan."


@pytest.mark.parametrize(
    "expression,expected",
    [
        pytest.param(
            '"Volume" # sep # 5 # sep # "Issue" # 2',
            "Volume-5-Issue2",
            id="quoted-string-first",
        ),
        pytest.param(
            "{Volume} # sep # 5 # sep # {Issue} # \"2\"",
            "Volume-5-Issue2",
            id="braced-string-first",
        ),
        pytest.param("jan # \"~\" # 10", "Jan.~10", id="macro-first"),
        pytest.param(
            "{Vol {X}} # sep # 5",
            "Vol {X}-5",
            id="nested-brace-balanced-string",
        ),
        pytest.param('10#"~"#jan', "10~Jan.", id="without-whitespace"),
    ],
)
def test_all_field_token_types_can_be_concatenated(expression, expected):
    source = (
        '@string{jan = "Jan."}\n'
        '@string{sep = "-"}\n'
        "@article{test,\n"
        f"  note = {expression},\n"
        "  year = 2024\n"
        "}\n"
    )

    library = _parse_without_errors(source)

    assert len(library.entries) == 1
    entry = library.entries[0]
    assert entry.fields_dict["note"].value == expected
    # The expression must end at the field delimiter, not consume the next field.
    assert entry.fields_dict["year"].value == "2024"


@pytest.mark.parametrize("token", ['"A # B"', "{A # B}", '"#"', "{#}"])
def test_hash_inside_a_single_string_token_is_literal(token):
    source = (
        "@article{test,\n"
        f"  title = {token},\n"
        "  year = 2024\n"
        "}\n"
    )

    library = _parse_without_errors(source)

    entry = library.entries[0]
    assert entry.fields_dict["title"].value == token[1:-1]
    assert entry.fields_dict["year"].value == "2024"


@pytest.mark.parametrize("middle_token", ['"a#b"', "{a#b}"])
def test_hash_inside_a_concatenated_string_token_is_not_an_operator(middle_token):
    source = (
        '@string{jan = "Jan."}\n'
        "@article{test,\n"
        f"  note = 10 # {middle_token} # jan\n"
        "}\n"
    )

    library = _parse_without_errors(source)

    assert library.entries[0].fields_dict["note"].value == "10a#bJan."


def test_hash_introduced_by_a_macro_value_remains_literal():
    library = _parse_without_errors(
        '''
        @string{hash = "a#b"}
        @string{jan = {Jan.}}

        @article{test,
          note = 10 # hash # jan
        }
        '''
    )

    assert library.entries[0].fields_dict["note"].value == "10a#bJan."


def test_concatenation_at_entry_end_does_not_consume_the_next_entry():
    library = _parse_without_errors(
        '''
        @string{jan = "Jan."}

        @article{first,
          month = 10 # "~" # jan
        }

        @article{second,
          title = {Later entry}
        }
        '''
    )

    assert len(library.entries) == 2
    assert library.entries_dict["first"].fields_dict["month"].value == "10~Jan."
    assert library.entries_dict["second"].fields_dict["title"].value == "Later entry"

from __future__ import absolute_import, unicode_literals

import datetime
import json

import pytz

from temba_client.serialization import DatetimeField, ObjectListField, TembaObject
from temba_client.utils import format_iso8601


class _Event(TembaObject):
    created_on = DatetimeField()
    modified_on = DatetimeField()


class _Step(TembaObject):
    arrived_on = DatetimeField()
    left_on = DatetimeField()


class _Run(TembaObject):
    steps = ObjectListField(item_class=_Step)


def test_format_iso8601_returns_none_for_none():
    assert format_iso8601(None) is None


def test_datetime_field_serializes_none_as_json_null():
    field = DatetimeField()

    serialized = field.serialize(None)

    assert serialized is None
    assert json.dumps(serialized) == "null"


def test_null_datetimes_survive_deserialize_serialize_round_trip():
    payload = {"created_on": None, "modified_on": None}

    event = _Event.deserialize(payload)

    assert event.created_on is None
    assert event.modified_on is None
    assert _Event.serialize(event) == payload


def test_null_datetimes_serialize_inside_nested_object_lists():
    # This mirrors the Run -> steps -> DatetimeField path in the issue.
    payload = {
        "steps": [
            {"arrived_on": None, "left_on": None},
            {"arrived_on": "2016-02-03T04:05:06.123456Z", "left_on": None},
        ]
    }

    run = _Run.deserialize(payload)
    serialized = _Run.serialize(run)

    assert serialized == {
        "steps": [
            {"arrived_on": None, "left_on": None},
            {"arrived_on": "2016-02-03T04:05:06.123456", "left_on": None},
        ]
    }


def test_non_null_datetime_formatting_is_unchanged():
    # UTC+2 must still be converted to UTC, retaining microseconds.
    value = datetime.datetime(
        2016, 2, 3, 6, 5, 6, 123456, tzinfo=pytz.FixedOffset(120)
    )

    assert format_iso8601(value) == "2016-02-03T04:05:06.123456"

from textwrap import dedent

import pytest

import bibtexparser


def _parse_single_entry(bibtex_string):
