        ),
        pytest.param(
            '10 # "a#b" # jan',
            "10a#bJan.",
            id="hash-inside-quoted-token",
        ),
        pytest.param(
            "10 # {left#right} # jan",
            "10left#rightJan.",
            id="hash-inside-braced-token",
        ),
        pytest.param(
            "{A {nested} value} # jan",
            "A {nested} valueJan.",
