        ),
        pytest.param(
            '10 # ", " # jan',
            "10, Jan.",
            id="comma-inside-quoted-token",
        ),
        pytest.param(
            '10\n    # "~"\n    # jan',
            "10~Jan.",
            id="multiline-expression",
        ),
    ],
)
def test_concatenation_supports_all_field_token_types(expression, expected):
    entry = _parse_single_entry(
        f'''
        @string{{ jan = "Jan." }}
        @string{{ sep = "-" }}

        @inbook{{item,
