        ("{10#~#jan}", "10#~#jan"),
        ('"a # b"', "a # b"),
        ("{a {#} b}", "a {#} b"),
        ('"#"', "#"),
    ],
)
def test_hash_inside_a_single_string_literal_is_not_concatenation(
    literal, expected
):
    entry = _parse_single_entry(
        f"""
        @article{{item,
            value = {literal},
        }}
        """
    )

    assert entry.fields_dict["value"].value == expected


def test_concatenation_resolves_brace_enclosed_macro_definitions():
    entry = _parse_single_entry(
        """
        @string{jan = {Jan.}}

        @inbook{item,
            month = 10 # {~} # jan,
        }
        """
    )

    assert entry.fields_dict["month"].value == "10~Jan."


def test_concatenation_at_end_of_entry_without_trailing_comma():
