        """
        @string{jan = "Jan."}

        @inbook{item,
            month = 10 # "~" # jan
        }
        """
    )

    assert entry.fields_dict["month"].value == "10~Jan."


def test_concatenation_preserves_field_and_entry_boundaries():
    library = bibtexparser.parse_string(
        dedent(
            '''
            @string{jan = "Jan."}

            @inbook{first,
                month = 10 # "~" # jan,
