def test_original_number_string_macro_concatenation_issue():
    source = '''
    @STRING{ jan = "Jan." }

    @INBOOK{inbook-full,
       month = 10 # "~" # jan,
    }
    '''
    assert _parse_field(source, "month") == "10~Jan."


@pytest.mark.parametrize(
    ("expression", "expected"),
    [
        # All three field-token types, with different enclosing styles.
        ('"10" # "~" # jan', "10~Jan."),
        ("{10} # {~} # jan", "10~Jan."),
        # Whitespace around the concatenation operator is optional.
        ('10#"~"#jan', "10~Jan."),
        # A macro may occur anywhere in the expression.
        ('jan # 10 # "~"', "Jan.10~"),
        # Number tokens are strings, so leading zeroes must be retained.
        ('0010 # "~"', "0010~"),
        # Expressions may span lines.
        ('10\n       # "~"\n       # jan', "10~Jan."),
    ],
)
def test_concatenation_token_types_and_layout(expression, expected):
    source = f'''
    @STRING{{ jan = "Jan." }}
    @ARTICLE{{key,
        month = {expression}
    }}
    '''
    assert _parse_field(source, "month") == expected


def test_concatenation_does_not_consume_following_fields():
    source = '''
    @ARTICLE{key,
        title = "Hello" # ", " # {world},
        year = 2024,
        note = {unchanged}
    }
    '''
    library = bibtexparser.parse_string(textwrap.dedent(source))
    assert len(library.entries) == 1
    fields = library.entries[0].fields_dict
    assert fields["title"].value == "Hello, world"
    assert fields["year"].value == "2024"
    assert fields["note"].value == "unchanged"


def test_hashes_and_commas_inside_string_tokens_are_literal():
    source = '''
    @STRING{ suffix = "done" }
    @ARTICLE{key,
        title = {A {nested} # value} # ", " # suffix,
        year = 2024
    }
    '''
    library = bibtexparser.parse_string(textwrap.dedent(source))
    assert len(library.entries) == 1
    fields = library.entries[0].fields_dict
    assert fields["title"].value == "A {nested} # value, done"
    assert fields["year"].value == "2024"


def test_macro_expansion_preserves_literal_hash():
    source = '''
    @STRING{ sharp = "C#" }
    @ARTICLE{key, title = sharp # "!"}
    '''
    assert _parse_field(source, "title") == "C#!"


def test_concatenation_in_referenced_string_definition():
    """A macro token denotes its complete value, not its raw expression."""
    source = '''
    @STRING{ jan = "Jan" # "." }
    @INBOOK{key,
        month = 10 # "~" # jan
    }
    '''
    assert _parse_field(source, "month") == "10~Jan."


@pytest.mark.parametrize(
    "expression",
    [
        "{{foo}}",
        '"{foo}"',
        # Concatenating an empty string must not remove a content brace level.
        '{{foo}} # ""',
        '"{foo}" # ""',
    ],
)
def test_concatenation_removes_only_syntax_enclosing(expression):
    source = f'''
    @ARTICLE{{key,
        title = {expression}
    }}
    '''
    assert _parse_field(source, "title") == "{foo}"


@pytest.mark.parametrize(
    ("expression", "expected"),
    [
        ('"Simple Title"', "Simple Title"),
        ("{Simple Title}", "Simple Title"),
        ("2024", "2024"),
        # A hash inside a single string token is not a concatenation operator.
        ('"C#"', "C#"),
        ('"a # b"', "a # b"),
        ("{C#}", "C#"),
        ("{a # b}", "a # b"),
    ],
)
def test_non_concatenated_values_regressions(expression, expected):
    source = f'''
    @ARTICLE{{key,
        title = {expression}
    }}
    '''
    assert _parse_field(source, "title") == expected


def test_plain_macro_reference_regression():
    source = '''
    @STRING{ jan = "January" }
    @ARTICLE{key, month = jan}
    '''
    assert _parse_field(source, "month") == "January"

import pytest

import bibtexparser
from bibtexparser.middlewares.interpolate import ResolveStringReferencesMiddleware
from bibtexparser.splitter import Splitter


ISSUE_BIBTEX = '''
@STRING{ jan = "Jan." }

@INBOOK{inbook-full,
   month = 10 # "~" # jan,
}
'''


def _only_field_value(library, field_key="value"):
    assert not library.failed_blocks
    assert len(library.entries) == 1
    return library.entries[0].fields_dict[field_key].value


def test_splitter_preserves_the_complete_concatenation_expression():
    """The splitter must not drop tokens following a quoted token."""
    library = Splitter(ISSUE_BIBTEX).split()

    assert _only_field_value(library, "month") == '10 # "~" # jan'


def test_original_issue_example():
    library = bibtexparser.parse_string(ISSUE_BIBTEX)

    assert _only_field_value(library, "month") == "10~Jan."


@pytest.mark.parametrize(
    "expression,expected",
    [
        # Whitespace around the concatenation operator is optional.
        ('10#"~"#jan', "10~Jan."),
        # Braced strings, quoted strings, numbers, and macros are all tokens.
        ('{10} # "~" # jan', "10~Jan."),
        ('jan # " " # edition', "Jan. Edition"),
        # Numbers are concatenated as text, not added numerically.
        ("10 # 20 # 30", "102030"),
        # Delimiters and whitespace inside tokens must be preserved.
        ('"Hello, " # {world}', "Hello, world"),
        ('{Hello {World}} # "!"', "Hello {World}!"),
        # A hash inside a string token is literal, not an operator.
        ('"C#" # "!"', "C#!"),
        ('"a # b" # {c}', "a # bc"),
        # Empty string tokens still participate in concatenation.
        ('"" # {x} # ""', "x"),
    ],
)
def test_concatenation_of_field_tokens(expression, expected):
    bibtex = f'''
@string{{jan = "Jan."}}
@string{{edition = {{Edition}}}}
@article{{test,
  value = {expression}
}}
'''

    library = bibtexparser.parse_string(bibtex)

    assert _only_field_value(library) == expected


def test_concatenation_does_not_consume_following_fields_or_entries():
    bibtex = '''
@string{jan = "Jan."}
@article{test,
  title = "Hello, " # {world},
  note = jan # "!",
  publisher = {ACME}
}
@article{following,
  title = {Following}
}
'''

    library = bibtexparser.parse_string(bibtex)

    assert not library.failed_blocks
    assert len(library.entries) == 2
    fields = library.entries[0].fields_dict
    assert fields["title"].value == "Hello, world"
    assert fields["note"].value == "Jan.!"
    assert fields["publisher"].value == "ACME"
    assert library.entries[1].fields_dict["title"].value == "Following"


@pytest.mark.parametrize(
    "raw_value,expected_after_enclosing_removal",
    [
        ('"C#"', "C#"),
        ('"a # b"', "a # b"),
        ("{a # b}", "a # b"),
        ('{10 # "~" # jan}', '10 # "~" # jan'),
    ],
)
def test_hash_inside_a_single_string_token_is_not_concatenation(
    raw_value, expected_after_enclosing_removal
):
    """A hash without a concatenation operator must not change middleware behavior.

    Each input above is one enclosed string token. ResolveStringReferencesMiddleware
    therefore has nothing to resolve and must leave its enclosing intact; removing
    that enclosing remains the responsibility of RemoveEnclosingMiddleware.
    """
    bibtex = f"@article{{test, value = {raw_value}}}"
    original = Splitter(bibtex).split()
    assert _only_field_value(original) == raw_value

    resolved = ResolveStringReferencesMiddleware(
        allow_inplace_modification=False
    ).transform(original)

    assert _only_field_value(resolved) == raw_value
    assert _only_field_value(original) == raw_value

    parsed = bibtexparser.parse_string(bibtex)
    assert _only_field_value(parsed) == expected_after_enclosing_removal

from textwrap import dedent

import pytest

import bibtexparser
from bibtexparser.middlewares.interpolate import ResolveStringReferencesMiddleware
from bibtexparser.splitter import Splitter


def _parsed_field(bibtex: str, field_key: str = "result") -> str:
    """Parse one valid entry and return one of its field values."""
    library = bibtexparser.parse_string(dedent(bibtex))
    assert not library.failed_blocks
    assert len(library.entries) == 1
    return library.entries[0].fields_dict[field_key].value


def test_original_issue_number_string_and_macro_are_concatenated():
    bibtex_str = """
    @STRING{ jan = "Jan." }

    @INBOOK{inbook-full,
       month = 10 # "~" # jan,
    }
    """
    library = bibtexparser.parse_string(dedent(bibtex_str))

    assert not library.failed_blocks
    month = library.entries[0].fields_dict["month"].value
    assert month == "10~Jan."


@pytest.mark.parametrize(
    "expression,expected",
    [
        pytest.param('"10" # "~"', "10~", id="quoted-strings"),
        pytest.param('{10} # "~"', "10~", id="braced-and-quoted-strings"),
        pytest.param('10#"~"#jan', "10~Jan.", id="without-whitespace"),
        pytest.param('jan # 10 # "~"', "Jan.10~", id="macro-first"),
        pytest.param(
            '007 # 10 # " pages"',
            "00710 pages",
            id="numbers-are-strings-and-keep-leading-zeroes",
        ),
        pytest.param(
            '{Hello {World}} # "!"',
            "Hello {World}!",
            id="nested-braces",
        ),
        pytest.param(
            '10\n          # "~"\n          # jan',
            "10~Jan.",
            id="multiline-expression",
        ),
    ],
)
def test_concatenation_supports_all_field_token_types(expression, expected):
    value = _parsed_field(
        f"""
        @string{{jan = "Jan."}}
        @article{{test,
          result = {expression},
        }}
        """
    )
    assert value == expected


def test_multiple_macros_and_braced_macro_values():
    value = _parsed_field(
        """
        @string{conf = "Conference"}
        @string{proc = {Proceedings}}
        @article{test,
          result = "Proc." # " of " # conf # " " # proc,
        }
        """
    )
    assert value == "Proc. of Conference Proceedings"


def test_concatenation_in_string_definition_is_resolved_when_macro_is_used():
    """The RHS of @string uses the same token and concatenation syntax."""
    value = _parsed_field(
        """
        @string{jan = "Jan" # "."}
        @inbook{test,
          result = 10 # "~" # jan,
        }
        """,
    )
    assert value == "10~Jan."


@pytest.mark.parametrize(
    "expression,expected",
    [
        pytest.param('"C # sharp"', "C # sharp", id="quoted-literal-hash"),
        pytest.param("{C # sharp}", "C # sharp", id="braced-literal-hash"),
        pytest.param(
            "{A {nested # value}}",
            "A {nested # value}",
            id="nested-braced-literal-hash",
        ),
        pytest.param(
            r'"See Figure \#1"',
            r"See Figure \#1",
            id="escaped-hash",
        ),
        pytest.param(
            '{hash #1} # " and " # {table #2}',
            "hash #1 and table #2",
            id="literal-hashes-inside-concatenated-tokens",
        ),
    ],
)
def test_hash_inside_a_string_token_is_not_a_concatenation_operator(
    expression, expected
):
    value = _parsed_field(
        f"""
        @article{{test,
          result = {expression},
        }}
        """
    )
    assert value == expected


@pytest.mark.parametrize(
    "raw_value",
    [
        '"C # sharp"',
        "{C # sharp}",
        "{A {nested # value}}",
    ],
)
def test_string_reference_middleware_does_not_remove_enclosing_from_literal_hash(
    raw_value,
):
    """A literal hash must not make an enclosed value look like concatenation."""
    library = Splitter(f"@article{{test, note = {raw_value}}}").split()
    transformed = ResolveStringReferencesMiddleware(
        allow_inplace_modification=False
    ).transform(library)

    assert transformed.entries[0].fields_dict["note"].value == raw_value


def test_splitter_keeps_complete_expression_and_resumes_at_following_fields():
    bibtex = dedent(
        """
        @article{test,
          title = {A, B} # ", " # "C",
          year = 2024,
          note = "D, E"
        }
        """
    )
    library = Splitter(bibtex).split()

    assert not library.failed_blocks
    assert len(library.entries) == 1
    fields = library.entries[0].fields_dict
    assert fields["title"].value == '{A, B} # ", " # "C"'
    assert fields["year"].value == "2024"
    assert fields["note"].value == '"D, E"'

    parsed = bibtexparser.parse_string(bibtex)
    assert not parsed.failed_blocks
    parsed_fields = parsed.entries[0].fields_dict
    assert parsed_fields["title"].value == "A, B, C"
    assert parsed_fields["year"].value == "2024"
    assert parsed_fields["note"].value == "D, E"

import threading

import anyio
import pytest

from starlette.applications import Starlette
from starlette.background import BackgroundTask, BackgroundTasks
from starlette.middleware.base import BaseHTTPMiddleware
from starlette.responses import JSONResponse, PlainTextResponse
from starlette.testclient import TestClient


class TransparentMiddleware(BaseHTTPMiddleware):
    async def dispatch(self, request, call_next):
        return await call_next(request)


@pytest.mark.parametrize("task_kind", ["async", "sync"])
def test_background_task_runs_to_completion_exactly_once(
    test_client_factory, task_kind
):
    calls = []

    if task_kind == "async":

        async def background_task():
            calls.append("started")
            # Check completion, rather than only checking that the background
            # callable was entered before being cancelled.
            await anyio.sleep(0)
            calls.append("finished")

    else:

        def background_task():
            calls.append("started")
            calls.append("finished")

    app = Starlette()
    app.add_middleware(TransparentMiddleware)

    @app.route("/")
    async def homepage(request):
        return JSONResponse(
            {"message": "hello"}, background=BackgroundTask(background_task)
        )

    client = test_client_factory(app)
    response = client.get("/")

    assert response.status_code == 200
    assert response.json() == {"message": "hello"}
    assert calls == ["started", "finished"]


def test_multiple_background_tasks_run_once_and_in_order(test_client_factory):
    calls = []

    def sync_task():
        calls.append("sync")

    async def async_task():
        calls.append("async")

    tasks = BackgroundTasks()
    tasks.add_task(sync_task)
    tasks.add_task(async_task)

    app = Starlette()
    app.add_middleware(TransparentMiddleware)

    @app.route("/")
    async def homepage(request):
        return JSONResponse({"message": "hello"}, background=tasks)

    client = test_client_factory(app)
    response = client.get("/")

    assert response.status_code == 200
    assert calls == ["sync", "async"]


def test_background_on_response_returned_by_middleware_runs_once(
    test_client_factory,
):
    calls = []

    async def background_task():
        calls.append("called")

    class DirectResponseMiddleware(BaseHTTPMiddleware):
        async def dispatch(self, request, call_next):
            return PlainTextResponse(
                "direct response", background=BackgroundTask(background_task)
            )

    app = Starlette()
    app.add_middleware(DirectResponseMiddleware)

    client = test_client_factory(app)
    response = client.get("/")

    assert response.status_code == 200
    assert response.text == "direct response"
    assert calls == ["called"]


@pytest.mark.parametrize("task_kind", ["async", "sync"])
def test_background_task_does_not_block_another_request(task_kind):
    background_started = threading.Event()
    release_background = threading.Event()
    background_finished = threading.Event()
    second_endpoint_started = threading.Event()

    if task_kind == "async":

        async def background_task():
            background_started.set()
            while not release_background.is_set():
                await anyio.sleep(0.01)
            background_finished.set()

    else:

        def background_task():
            background_started.set()
            release_background.wait(5)
            background_finished.set()

    app = Starlette()
    app.add_middleware(TransparentMiddleware)

    @app.route("/first")
    async def first(request):
        return JSONResponse(
            {"request": "first"}, background=BackgroundTask(background_task)
        )

    @app.route("/second")
    async def second(request):
        second_endpoint_started.set()
        return JSONResponse({"request": "second"})

    responses = {}
    errors = []

    with TestClient(app) as client:

        def make_request(path):
            try:
                responses[path] = client.get(path)
            except BaseException as exc:
                errors.append(exc)

        first_thread = threading.Thread(
            target=make_request, args=("/first",), daemon=True
        )
        second_thread = None
        first_thread.start()

        try:
            started = background_started.wait(2)
            second_processed_before_release = False

            if started:
                second_thread = threading.Thread(
                    target=make_request, args=("/second",), daemon=True
                )
                second_thread.start()
                # The first background task is still blocked at this point. The
                # second request must not have to wait for it to be released.
                second_processed_before_release = second_endpoint_started.wait(2)
        finally:
            release_background.set()

        first_thread.join(5)
        if second_thread is not None:
            second_thread.join(5)
        finished = background_finished.wait(2)

    assert started, "The background task did not start"
    assert second_processed_before_release, (
        "The second request was not processed until the first request's "
        "background task was released"
    )
    assert finished, "The background task did not run to completion"
    assert not first_thread.is_alive()
    assert second_thread is not None and not second_thread.is_alive()
    assert not errors
    assert responses["/first"].json() == {"request": "first"}
    assert responses["/second"].json() == {"request": "second"}
